const QUESTIONS_DATA = [{"id": "pdf1-001", "question": "\u201cWorkers should receive orders from only one manager\u201d , this principle is termed as", "options": ["Unity of command", "Unity of direction", "Unity of group", "Unity of management"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Unity of command is Fayol's principle stating each employee should report to and receive orders from only one superior, avoiding conflicting instructions.", "topic": "Management"}, {"id": "pdf1-002", "question": "\u201cThe Hawthorne Experiments\u201d are related to", "options": ["Scientific Management", "Administrative Management", "Human Relations School", "Bureaucratic Organization"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "The Hawthorne Experiments (Elton Mayo, Western Electric) showed social and psychological factors affect productivity, founding the Human Relations School of management.", "topic": "Management"}, {"id": "pdf1-003", "question": "\u201cManagers have long realised that there is no one best way to do things\u201d. This statement is suitable for which management approach?", "options": ["Systems Theory", "Contingency Theory", "Organizational Humanism", "Management Science"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Contingency Theory holds that there is no single best way to manage; the right approach depends on the specific situation and environment.", "topic": "Management"}, {"id": "pdf1-004", "question": "\u201cg(n) is an upper bound for f(n) that is not asymptotically tight\u201d, statement holds true for", "options": ["Big oh", "Big theta", "Big omega", "Amortized"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "Strictly, an upper bound that is NOT asymptotically tight is little-o notation (o-notation), while Big-O allows the bound to be tight or loose; since little-o isn't offered as a choice, the exam intends Big-O as the general 'upper bound' answer, making this question technically imprecise.", "topic": "DSA"}, {"id": "pdf1-005", "question": "\u201cFunctional foremanship\u201d is related to", "options": ["Scientific Management", "Administrative Management", "Human Relations School", "Bureaucratic Organization"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Functional foremanship, where multiple specialist foremen each supervise one aspect of work, is part of F.W. Taylor's Scientific Management approach.", "topic": "Management"}, {"id": "pdf1-006", "question": "\u201cFayol\u2019s principles\u201d are related to", "options": ["Scientific Management", "Administrative Management", "Human Relations School", "Bureaucratic Organization"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Henri Fayol's 14 principles of management (unity of command, division of work, etc.) form the basis of Administrative Management theory.", "topic": "Management"}, {"id": "pdf1-007", "question": "X.25 standards covers how many layers?", "options": ["Two", "Three", "Seven", "Six"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "X.25 defines three layers corresponding to the physical, data link (LAPB), and network/packet layers of the OSI model.", "topic": "CN"}, {"id": "pdf1-008", "question": "Working set model for page replacement is based on the assumption of ____________", "options": ["Modularity of references", "Working Set Size", "Locality of references", "Random access"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "The working set model assumes locality of reference: a process references a bounded, slowly-changing set of pages within any given time window.", "topic": "OS"}, {"id": "pdf1-009", "question": "Within an organisation, leadership influence will be dependent upon the type of ________ that the leader can exercise over the followers.", "options": ["knowledge", "power", "delegation", "friendship"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A leader's influence over followers stems from the type of power (legitimate, expert, referent, reward, coercive) they hold within the organisation.", "topic": "Management"}, {"id": "pdf1-010", "question": "Why, according to stakeholder theory, is it in companies' best interests to pay attention to their stakeholders?", "options": ["If firms only act in their own self-interest, employees may feel exploited.", "If firms only act in their own self-interest, the government might put more regulation on them.", "If firms only act in their own self-interest, customers might not like the image that the company portrays.", "If firms only act in their own self-interest and inflict harm on stakeholders, then society might withdraw its support"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Stakeholder theory argues firms need a broad social license to operate; ignoring stakeholders and causing harm can cause society at large to withdraw support, threatening the firm's legitimacy and survival.", "topic": "Business Ethics"}, {"id": "pdf1-011", "question": "Why is it necessary for all employees to sign the Confidentiality and Security Agreement each year?", "options": ["To check if you still work there.", "No reason, they just like paperwork.", "To remind everyone of what their responsibilities are.", "Will be used for moving to a higher position."], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Annual re-signing of a Confidentiality and Security Agreement serves to refresh employees' awareness of their ongoing data-protection obligations, not as a formality or promotion tool.", "topic": "Information Security"}, {"id": "pdf1-012", "question": "Why is autocratic leadership considered negative?", "options": ["people are uninformed, insecure and afraid of the leader", "leader is extra friendly", "too much confusion arises", "it is very participative"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Autocratic leadership is viewed negatively because followers are kept uninformed and excluded from decisions, leaving them insecure and fearful of the leader.", "topic": "Management"}, {"id": "pdf1-013", "question": "Who suggested a system of cards?", "options": ["Henry Metcalfe", "Henry Robinson Towne", "Peter Drucker", "Robert Owen"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Captain Henry Metcalfe devised a card system for recording shop orders and production data at Frankford Arsenal in the 1880s, an early contribution to scientific management's record-keeping methods.", "topic": "Management"}, {"id": "pdf1-014", "question": "Who published the famous book \"The Cost of Manufacture and Administration of Workshop: Public and private\"?", "options": ["Henry Metcalfe", "Henry Robinson Towne", "Peter Drucker", "Robert Owen"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Henry Metcalfe documented his card-based shop-order system in his 1885 book on the cost and administration of workshops, an early scientific-management text.", "topic": "Management"}, {"id": "pdf1-015", "question": "Who presented the paper \u201cEngineer as an Economist\u201d?", "options": ["F W Taylor", "Henry Robinson Towne", "Peter Drucker", "Robert Owen"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Henry Robinson Towne presented 'The Engineer as an Economist' to the ASME in 1886, a landmark paper urging engineers to treat management as an economic, systematic discipline; it is said to have influenced a young F.W. Taylor.", "topic": "Management"}, {"id": "pdf1-016", "question": "Who plays an important role in the success of products and services and in increasing the marketing share of the firm in business?", "options": ["Functional level Managers", "Corporate level Managers", "Business level Managers", "All of the above"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Product/service success and market share depend on contributions at every level -- functional managers execute specialized tasks, business-unit managers set competitive strategy, and corporate managers align the portfolio -- so all of the above is the most defensible answer.", "topic": "Management"}, {"id": "pdf1-017", "question": "Who is the father of scientific management?", "options": ["F W Taylor", "Henry Fayol", "Peter Drucker", "None of these"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "F.W. Taylor is universally credited as the father of Scientific Management for his work on efficiency, time studies, and standardized workflows.", "topic": "Management"}, {"id": "pdf1-018", "question": "Who is the father of Personnel Management?", "options": ["F W Taylor", "Henry Fayol", "Peter Drucker", "Robert Owen"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Robert Owen is called the father of Personnel Management for his welfare reforms at New Lanark mills, including shorter hours, worker housing, and education for workers' children.", "topic": "Management"}, {"id": "pdf1-019", "question": "Who is the father of modern management?", "options": ["F W Taylor", "Henry Fayol", "Peter Drucker", "None of these"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Peter Drucker is widely regarded as the father of modern management for founding management as a formal discipline through works like 'The Practice of Management'.", "topic": "Management"}, {"id": "pdf1-020", "question": "Who developed the force-field analysis theory?", "options": ["Carl Rogers", "B.F.Skinner", "Kurt Lewin", "James Johnson"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Kurt Lewin developed force-field analysis, a framework for identifying driving and restraining forces around organisational change.", "topic": "Management"}, {"id": "pdf1-021", "question": "Who believed that workers performance was influenced by the total environment?", "options": ["F W Taylor", "Henry Fayol", "Peter Drucker", "Robert Owen"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Robert Owen believed worker productivity was shaped by their overall working conditions and treatment, leading him to improve housing, hours, and welfare at his mills.", "topic": "Management"}, {"id": "pdf1-022", "question": "Who are the organisational stakeholders?", "options": ["Government", "Employees", "Customers", "All the other answers are correct."], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Organisational stakeholders include any group with an interest in the firm's outcomes -- government, employees, and customers are all valid examples.", "topic": "Business Ethics"}, {"id": "pdf1-023", "question": "White Box techniques are also classified as_________________?", "options": ["Design based testing", "Structural testing", "Error guessing technique", "None of the mentioned"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "White box testing examines a program's internal code paths and logic, so it is also called structural testing (as opposed to black-box/functional testing).", "topic": "Software Engineering"}, {"id": "pdf1-024", "question": "While selecting a string w such that w belongs to L, where L is a regular language, and w=mno. Which of the following parts cannot be an empty string?", "options": ["m", "n", "o", "no"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "In the pumping lemma decomposition w = xyz (here m,n,o), the middle part y (n) must have length greater than zero and cannot be empty.", "topic": "TOC"}, {"id": "pdf1-025", "question": "While applying Pumping lemma over a regular language, we consider a string w that belong to L and separate it into _________ components.", "options": ["3", "4", "2", "5"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The pumping lemma splits a sufficiently long string w into exactly three parts, x, y, and z, where xy^iz remains in the language for all i >= 0.", "topic": "TOC"}, {"id": "pdf1-026", "question": "Which type of software can be used to merge data of two files in one file ?", "options": ["System software", "Networking software", "Documenting software", "Utility Software"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Utility software (e.g. merge/sort utilities, disk tools) performs specific maintenance tasks like merging two files into one; system software (like the OS) manages hardware but doesn't do this directly.", "topic": "OS"}, {"id": "pdf1-027", "question": "Which type of attack requires multiple handler on various system?", "options": ["Man in the Middle Attack", "DoS", "DDoS", "Backdoor Attack"], "correct": 3, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "A DDoS attack is coordinated through a hierarchy of 'handler' (master) systems that control many compromised 'agent' machines spread across various systems; a plain DoS comes from a single source, so the PDF's marked answer (DoS) is wrong.", "topic": "Information Security"}, {"id": "pdf1-028", "question": "Which transmission media has the highest transmission speed in the network.", "options": ["Coaxial cable", "Twisted pair cable", "Optical fibre cable", "Electrical cable"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Optical fibre cable transmits data as light pulses with far higher bandwidth and speed than copper-based coaxial, twisted pair, or electrical cables.", "topic": "CN"}, {"id": "pdf1-029", "question": "Which term refers to a systematic assessment of a company's activities in terms of social impact?", "options": ["managerial appraisal", "social audit", "social responsibility metric", "ethics audit"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A social audit is a formal, systematic review of a company's social and environmental impact and performance, as opposed to financial or managerial audits.", "topic": "Business Ethics"}, {"id": "pdf1-030", "question": "which technique was introduced because a single job could not keep both the CPU and the I/O devices busy?", "options": ["Time-sharing", "SPOOLing", "Preemptive scheduling", "Multiprogramming"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Multiprogramming keeps multiple jobs in memory so the CPU can switch to another job whenever the current one is waiting on I/O, maximizing utilization of both CPU and I/O devices.", "topic": "OS"}, {"id": "pdf1-031", "question": "Which sublayer of the data link layer performs data link functions that depend upon the type of medium?", "options": ["logical link control sublayer", "media access control sublayer", "network interface control sublayer", "none of the mentioned"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The MAC (Media Access Control) sublayer handles medium-specific access (e.g. Ethernet vs Wi-Fi framing/addressing), while the LLC sublayer above it is medium-independent.", "topic": "CN"}, {"id": "pdf1-032", "question": "Which style of leadership focuses on goals, standards, and organization?", "options": ["task leadership", "social leadership", "semantic leadership", "transformational leadership"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Task leadership is the style oriented around getting the job done \u2014 setting goals, standards, and organizing work \u2014 in contrast to social/relationship leadership which focuses on people and morale.", "topic": "Management"}, {"id": "pdf1-033", "question": "Which statement is CORRECT", "options": ["The internal data model represents the data\u2019s physical storage details", "To communicate with the business user, mainly, the logical data model is used", "The logical data model is implementation-independent", "A database state contains the description of the database data and is stored in the catalogue"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "In the three-schema architecture, the internal schema is the physical-storage-level description of the data (file organization, indexes, storage structures), which is exactly what the internal data model represents.", "topic": "DBMS"}, {"id": "pdf1-034", "question": "Which server translates the alphanumeric name into numeric addresses?", "options": ["Network server", "Protocols", "DNS", "System server"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "DNS (Domain Name System) resolves human-readable domain names into numeric IP addresses so machines can route traffic.", "topic": "CN"}, {"id": "pdf1-035", "question": "Which process model deals with understanding of the problem domain and architecture framework and developing the project plan with identification of risks?", "options": ["Agile Process Model", "Iterative Process Model", "Incremental Process Model", "Spiral Model"], "correct": 4, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "This describes the early quadrants of the Spiral Model \u2014 a communication/planning step to understand the problem and architecture, plus an explicit risk-identification step \u2014 which is the model's signature risk-driven feature; 'Iterative' as marked doesn't specifically emphasize risk analysis.", "topic": "Software Engineering"}, {"id": "pdf1-036", "question": "Which process model deals with review of project and a decision is made whether to continue with a further loop or not in the planning phase?", "options": ["Agile Process Model", "Waterfall Process Model", "Incremental Process Model", "Spiral Model"], "correct": 4, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "Each loop ('spiral') of the Spiral Model ends with a planning/review phase where the team explicitly decides whether to continue into another loop \u2014 this go/no-go-per-loop review is unique to the Spiral Model, not the strictly sequential Waterfall model marked in the source.", "topic": "Software Engineering"}, {"id": "pdf1-037", "question": "Which principle of general management advocates that \u201cEmployee turnover should be minimized to maintain organizational efficiency.\u201d?", "options": ["Stability of personnel", "Remuneration of employees", "Equity", "Esprit de Corps"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Fayol's principle of 'Stability of Tenure of Personnel' states that high employee turnover is inefficient and costly, so organizations should aim to retain staff.", "topic": "Management"}, {"id": "pdf1-038", "question": "Which organisation structure is generally followed by big steel plants?", "options": ["Line organisation", "Line and staff organisation", "Functional organisation", "All the other answers are correct"], "correct": 2, "original_marked": 3, "matches_original": false, "confidence": "high", "reasoning": "Large, complex operations like big steel plants typically use Line and Staff organisation, combining direct line authority with specialist staff departments (engineering, quality, HR) for advice \u2014 pure functional organisation (marked in the source) is less commonly cited for this case in management textbooks.", "topic": "Management"}, {"id": "pdf1-039", "question": "Which option is incorrect. Monitors can contain", "options": ["multiple (user) procedures.", "only a single user procedure.", "only one procedure will be active in the monitor at any one time.", "multiple procedures can share variables."], "correct": 2, "original_marked": 3, "matches_original": false, "confidence": "high", "reasoning": "Monitors are defined as containing multiple procedures that share local data, with mutual exclusion ensuring only one procedure executes at a time \u2014 so 'only a single user procedure' is the false statement, not the mutual-exclusion property marked in the source.", "topic": "OS"}, {"id": "pdf1-040", "question": "Which one of these scenarios are ethical issues? (i) A company is thinking of employing a robot that will make most of the workforce redundant (ii) Someone creates an AI (iii) A judge decides to give someone a prison sentence (iv) Someone hacks a computer", "options": ["(i) and (ii)", "(i) and (iii)", "(ii) and (iii)", "(iii) and (iv)"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "This question is subjective/ambiguous \u2014 what counts as an 'ethical issue' versus a routine legal action depends on framing (e.g. a judge sentencing under law or someone illegally hacking could also be argued as ethical matters), so the source's marked answer is kept without independent verification.", "topic": "Business Ethics"}, {"id": "pdf1-041", "question": "Which one of the following would be classified as sensitive personal data?", "options": ["Address", "Religion", "CCTV Video", "Name"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Under data protection frameworks like GDPR, religion is explicitly classified as 'special category' (sensitive) personal data, unlike ordinary identifiers such as name, address, or generic CCTV footage.", "topic": "Privacy & Compliance"}, {"id": "pdf1-042", "question": "Which one of the following regular expressions over {0,1} denotes the set of all strings not containing 100 as a substring?", "options": ["0*(10+1)*", "0*(11*0)*", "0*1010*", "0*1*01"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "0*(10+1)* generates a leading run of 0s followed only by blocks '1' or '10', so any 0 after the prefix is always a lone 0 immediately after a 1 \u2014 this exactly captures all strings that never contain '100'.", "topic": "TOC"}, {"id": "pdf1-043", "question": "Which one of the following regular expressions over {0,1} denotes the set of all strings not containing 100 as a substring?", "options": ["0*(11*0)*", "0*1010*", "0*(10+1)*", "0*1*01"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "This is the same question as pdf1-042 with options reshuffled; '0*(10+1)*' (option 3 here) is the regex that correctly denotes all strings avoiding '100' as a substring.", "topic": "TOC"}, {"id": "pdf1-044", "question": "Which one of the following languages over the alphabet {a,b} is described by the regular expression: (a+b)*a(a+b)*a(a+b)*?", "options": ["The set of all strings containing the substring aa.", "The set of all strings containing at most two a\u2019s.", "The set of all strings containing at least two a\u2019s.", "The set of all strings that begin and end with either a or b."], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "(a+b)*a(a+b)*a(a+b)* forces at least two occurrences of 'a' somewhere in the string, with any symbols around and between them, so it denotes strings containing at least two a's.", "topic": "TOC"}, {"id": "pdf1-045", "question": "Which one of the following is not a \u2018hygiene factor\u2019 of Herzberg\u2019s Two Factor theory ?", "options": ["Interpersonal relations", "Working conditions", "Responsibility", "Job security"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "In Herzberg's Two-Factor theory, 'Responsibility' is a motivator (satisfier) tied to the work itself, whereas interpersonal relations, working conditions, and job security are all hygiene (dissatisfier) factors.", "topic": "Management"}, {"id": "pdf1-046", "question": "Which one of the following is not a transmission medium.", "options": ["Coaxial cable", "Telephone Lines", "Modems", "Microwave systems"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "A modem is an end-device that modulates/demodulates signals for transmission \u2014 it is not itself a transmission medium, unlike coaxial cable, telephone lines, or microwave links.", "topic": "CN"}, {"id": "pdf1-047", "question": "Which one of the following is not a responsibility of the government?", "options": ["Enacting the pollution laws.", "Establishment of norms for the industrial undertakings.", "Providing after sales service.", "None of the other answers is correct."], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Providing after-sales service is a business/company obligation to its customers, not a governmental function like law-making or setting industrial norms.", "topic": "Business Ethics"}, {"id": "pdf1-048", "question": "Which one of the following is correct?", "options": ["A relationship can have one or more attributes directly linked to it", "All relationships attributes may be attached to one of the participating entities", "All relationships may be converted to 1:1 relationships", "All relationships may be converted to binary relationships"], "correct": 1, "original_marked": 3, "matches_original": false, "confidence": "high", "reasoning": "Relationships in the ER model can legitimately carry their own attributes (e.g. a 'works_on' relationship having an 'hours' attribute) \u2014 this is unconditionally true, whereas the other options make sweeping 'all relationships can be converted to...' claims that fail for many-to-many relationships, making the source's marked option (1:1 conversion) incorrect.", "topic": "DBMS"}, {"id": "pdf1-049", "question": "Which one of the following is an element of motivation according to Vroom\u2019s Vector Valence theory ?", "options": ["Involvement", "Equity", "Instrumentality", "Existence"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Vroom's Expectancy Theory (Valence-Instrumentality-Expectancy) names Instrumentality \u2014 the belief that performance leads to a reward \u2014 as one of its three core elements; 'Existence' belongs to Alderfer's ERG theory instead.", "topic": "Management"}, {"id": "pdf1-050", "question": "Which one of the following is an application of Stack Data Structure?", "options": ["Managing function calls", "The stock span problem", "Arithmetic expression evaluation", "All of these"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Stacks (LIFO structures) are used for managing function call returns, solving the stock span problem, and evaluating arithmetic expressions \u2014 all three are classic stack applications.", "topic": "DSA"}, {"id": "pdf1-051", "question": "Which one of the following is a synchronization tool?", "options": ["Thread", "Pipe", "Semaphore", "Socket"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "A semaphore is a classic synchronization primitive used to control access to shared resources between threads/processes; threads, pipes, and sockets are not synchronization mechanisms themselves.", "topic": "OS"}, {"id": "pdf1-052", "question": "Which one of the following describes the leadership style in which the leader generally gives the group complete freedom to make decisions and complete the work in whatever way it sees fit?", "options": ["facilitative style", "delegative style", "democratic style", "laissez-faire style"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Laissez-faire leadership is defined as giving the group complete freedom to make decisions and do the work however they see fit, with minimal leader involvement.", "topic": "Management"}, {"id": "pdf1-053", "question": "Which one of the following describes the leadership style in which a leader tends to centralize authority, dictate work methods, make unilateral decisions, and limit employee participation?", "options": ["authoritarian style", "autocratic style", "democratic style", "laissez-faire style"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The autocratic style is defined by centralized authority, leader-dictated work methods, unilateral decision-making, and limited employee participation - the standard management-textbook definition.", "topic": "Management"}, {"id": "pdf1-054", "question": "Which one of the following communication lines is best suitable for interactive process applications.", "options": ["Narrow band channel", "Half-duplex", "Full-duplex", "Simplex"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Full-duplex allows simultaneous two-way transmission, which is required for real-time interactive applications like voice calls or interactive terminal sessions.", "topic": "CN"}, {"id": "pdf1-055", "question": "Which one of the below is not a file infecting virus?", "options": ["Cavity Virus", "Prepending Virus", "Appending Virus", "Stealth Virus"], "correct": 4, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "Cavity, prepending, and appending viruses are classified by how they insert their code into a host file (all are file-infection techniques); stealth is a detection-evasion behavior, not a file-infection method, so it's the odd one out.", "topic": "Information Security"}, {"id": "pdf1-056", "question": "Which of these statements concerning Weber\u2019s concept of Bureaucracy is not correct?", "options": ["It is based on rules and procedures rather than personal preference and judgment.", "It is still a relevant concept in today\u2019s organization.", "It has acquired a negative reputation for inefficiency and rigidity.", "It rejects rational approaches to managing organizations"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Weber's bureaucracy is explicitly built on rational-legal authority and rule-based procedures, so saying it 'rejects rational approaches' is the incorrect statement among the four.", "topic": "Management"}, {"id": "pdf1-057", "question": "Which of these is an application of linked lists?", "options": ["To implement file systems", "For separate chaining in hash-tables", "To implement non-binary trees", "All of these"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Linked lists underlie file-system block chaining, separate chaining in hash tables, and representations of non-binary (generalized) trees, so all three uses are valid applications.", "topic": "DSA"}, {"id": "pdf1-058", "question": "Which of these expresses the specific number of entity occurrences associated with one occurrence of the related entity?", "options": ["Degree of relationship", "Connectivity of relationship", "Cardinality of relationship", "None of these"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Cardinality specifies the exact number of entity instances that can be associated with a single instance of the related entity (e.g., 1:1, 1:N, M:N), distinct from connectivity, which just names the relationship type.", "topic": "DBMS"}, {"id": "pdf1-059", "question": "Which of the two features match each other", "options": ["Inheritance and Encapsulation", "Encapsulation and Polymorphism", "Encapsulation and Abstraction", "Abstraction and Polymorphism"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Abstraction and encapsulation are the two OOP concepts most often paired and confused, since both are fundamentally about hiding detail - abstraction hides implementation complexity, encapsulation hides internal data via access control.", "topic": "OOPS"}, {"id": "pdf1-060", "question": "Which of the three pillars of digital privacy does not apply?", "options": ["Information privacy", "Individual privacy", "Communication privacy", "Family privacy"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "The commonly cited pillars of digital privacy are information privacy, communication privacy, and individual (personal) privacy - 'family privacy' is not one of the standard three.", "topic": "Privacy & Compliance"}, {"id": "pdf1-061", "question": "Which of the statement is true regarding the dequeue operation?", "options": ["Element are deleted at both end", "any element beside the last one", "Designing of the operation is simple", "All of these"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A dequeue (double-ended queue) by definition allows insertion and deletion of elements at both the front and rear ends.", "topic": "DSA"}, {"id": "pdf1-062", "question": "Which of the statement is false as part of asymptotic notation?", "options": ["Discuss about rate of growth of the function", "Asymptotically weakly bound based on the function", "Functions that are dependent are non-negative", "Bigoh notation speaks on defined constant"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "low", "reasoning": "The option wording is garbled/ambiguous (likely OCR damage from the source PDF), so this defers to the original marked answer rather than a confidently re-derived one.", "topic": "DSA"}, {"id": "pdf1-063", "question": "Which of the following ways should organizations use to protect personal information?", "options": ["Security clearances and access restrictions on a \"need-to-know\" basis are examples of organizational measures.", "Technological measures, for example, the use of passwords and encryption.", "Physical measures, for example, shredding documents and locking desk drawers.", "All of the these"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Organizational, technological, and physical safeguards (access restrictions, encryption/passwords, and shredding/locking) are all standard categories of measures used to protect personal information.", "topic": "Privacy & Compliance"}, {"id": "pdf1-064", "question": "Which of the following true about FILE *fp", "options": ["FILE is a keyword in C for representing files and fp is a variable of FILE type.", "FILE is a stream", "FILE is a buffered stream", "FILE is a structure and fp is a pointer to the structure of FILE type"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "In the C standard library, FILE is defined as a struct type, and fp declared as FILE* is a pointer to that structure used to track the stream's state.", "topic": "C/C++"}, {"id": "pdf1-065", "question": "Which of the following technique is used for fragment?", "options": ["a technique used in best-effort delivery systems to avoid endlessly looping packets", "a technique used by protocols in which a lower level protocol accepts a message from a higher level protocol and places it in the data portion of the low level frame", "one of the pieces that results when an IP gateway divides an IP datagram into smaller pieces for transmission across a network that cannot handle the original datagram size", "Compaction technique"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "A fragment is one of the pieces an IP gateway creates when it splits a datagram that is too large for the next network's MTU.", "topic": "CN"}, {"id": "pdf1-066", "question": "Which of the following TCP/IP protocol is used for transferring electronic mail messages from one machine to another?", "options": ["FTP", "SNMP", "SMTP", "RPC"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "SMTP (Simple Mail Transfer Protocol) is the TCP/IP protocol used to transfer email between mail servers.", "topic": "CN"}, {"id": "pdf1-067", "question": "Which of the following statements are true? I. Shortest remaining time first scheduling may cause starvation II. Preemptive scheduling may cause starvation III. Round robin is better than FCFS in terms of response time", "options": ["I only", "I and III only", "II and III only", "I II and III only"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "SRTF can starve long jobs, preemptive scheduling in general can starve low-priority processes, and round robin's time-slicing gives noticeably better response time than FCFS's run-to-completion order - all three statements hold.", "topic": "OS"}, {"id": "pdf1-068", "question": "Which of the following statements about the Privacy Data Breach Incident is correct?", "options": ["A Privacy incident is a theft of an asset", "A privacy event occurs when personal information is lost in any way. Both suspected and confirmed occurrences involving PII that provide a reasonable risk of harm are covered by this term.", "A Privacy Incident is one that may not cause serious injury or harm to the individual and/or involves a few numbers of affected individuals", "A Privacy incident is an attack on an asset"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A privacy incident/breach is broadly defined as any loss of personal information, covering both suspected and confirmed occurrences that pose a reasonable risk of harm - the standard compliance definition.", "topic": "Privacy & Compliance"}, {"id": "pdf1-069", "question": "Which of the following statements about leadership is false?", "options": ["Leadership does not necessarily take place within a hierarchical structure of an organisation", "Not every leader is a manager", "When people operate as leaders their role is always clearly established and defined.", "All the other answers are correct."], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Leadership roles are frequently informal and not always clearly defined within an organization's structure, so claiming they are 'always clearly established' is the false statement.", "topic": "Management"}, {"id": "pdf1-070", "question": "Which of the following statement(s) is/are correct? S1: When Bjarne stroustrup designed C++, there is no such concept of exception handling. S2: Exception handling is a new feature added to ANSI C++; not available in earlier compilers.", "options": ["Only S1", "Only S2", "Neither S1 nor S2", "Both S1 and S2"], "correct": 4, "original_marked": 3, "matches_original": false, "confidence": "high", "reasoning": "Historically both statements are accurate: Stroustrup's original C++ design had no exception-handling mechanism, and it was only added later as the language was standardized, so it was absent from earlier compilers - making 'Both S1 and S2' the correct choice rather than 'neither'.", "topic": "C/C++"}, {"id": "pdf1-071", "question": "Which of the following statement is true?", "options": ["DFA is more powerful than NFA", "NFA and DFA have equal power", "NFA is more powerful than DFA", "All options are true"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "NFAs and DFAs are equivalent in expressive power - both recognize exactly the regular languages - even though NFAs can be more compact to describe.", "topic": "TOC"}, {"id": "pdf1-072", "question": "Which of the following standard algorithms is not a Greedy algorithm?", "options": ["Dijkstra's shortest path algorithm", "Prim's algorithm", "Kruskal algorithm", "Bellmen Ford Shortest path algorithm"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Bellman-Ford is a dynamic-programming style algorithm (it relaxes all edges repeatedly), unlike Dijkstra's, Prim's, and Kruskal's algorithms, which are all classic greedy algorithms.", "topic": "DSA"}, {"id": "pdf1-073", "question": "Which of the following risk is the failure of a purchased component to perform as expected?", "options": ["Product risk", "Project risk", "Process risk", "Program risk"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A purchased or reused component failing to meet its spec is a product risk - a risk tied to the quality or characteristics of the deliverable itself, as classified in software risk management.", "topic": "Software Engineering"}, {"id": "pdf1-074", "question": "Which of the following represents the rights inherent in a managerial position to give orders and expect them to be obeyed ?", "options": ["Power", "Authority", "Influence", "Responsibility"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Authority is the formal right that comes with a managerial position to give orders and expect compliance, distinct from power (broader ability to influence) or responsibility.", "topic": "Management"}, {"id": "pdf1-075", "question": "Which of the following regular expression identity is true?", "options": ["r(*) =r*", "(r * s*)*= (r+s) *", "(r+s) *=r*+s*", "r*s*=r*+s*"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "(r*s*)* = (r+s)* is a well-known true regular-expression identity, since both sides generate all strings over the alphabet {r,s}; the other listed identities are false in general.", "topic": "TOC"}, {"id": "pdf1-076", "question": "Which of the following regular expression denotes a language comprising of all possible strings over {a,b} of length n where n is a multiple of 3?", "options": ["((a+b) (a+b) (a+b))*", "(aaa+ab+a)+(bbb+bb+a)", "(aaa+bbb)*", "(a+b+aa+bb+aba+bba)*"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "((a+b)(a+b)(a+b))* generates every possible string built from 3-character blocks over {a,b}, so it produces exactly the strings whose length is a multiple of 3.", "topic": "TOC"}, {"id": "pdf1-077", "question": "Which of the following regular expression denotes a language comprising of all possible strings over {a,b} of length n where n is a multiple of 3?", "options": ["(a+b+aa+bb+aba+bba)*", "(aaa+bbb)*", "((a+b) (a+b) (a+b))*", "(aaa+ab+a)+(bbb+bb+a)"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Same question with the options reshuffled; ((a+b)(a+b)(a+b))* is still the regex that matches all strings whose length is a multiple of 3.", "topic": "TOC"}, {"id": "pdf1-078", "question": "Which of the following properties is associated with a queue?", "options": ["First In Last Out", "First In First Out", "Last In First Out", "None"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A queue removes elements in the same order they were inserted, i.e. First In First Out.", "topic": "DSA"}, {"id": "pdf1-079", "question": "Which of the following properties are necessary for an Algorithm?", "options": ["Definiteness", "Correctness", "Effectiveness", "A and C"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "low", "reasoning": "Standard textbook lists of algorithm properties emphasize Definiteness (each step unambiguous) and Effectiveness (each step must be basically executable) alongside finiteness/input/output; correctness is usually treated as a design goal rather than a defining property, but this framing is genuinely debatable so treat the answer with some caution.", "topic": "DSA"}, {"id": "pdf1-080", "question": "Which of the following pair is correctly matched ? A. F.W. Taylor \u2013 Human Relations Approach B. Henry Fayol \u2013 Universality of Management C. Elton Mayo \u2013 Psychological Approach D. M. Parker Follet \u2013 Scientific Management", "options": ["A", "B", "C", "D"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Henry Fayol's 14 principles of management were proposed as universally applicable to any organization, which is exactly why he is tied to 'Universality of Management'.", "topic": "Management"}, {"id": "pdf1-081", "question": "Which of the following options are correct for the given question? The usage of \u201cvirtual\u201d keyword before the member function is to achieve\u2026\u2026\u2026\u2026 (i). Inheritance (ii). Compile time Polymorphism (iii). Runtime Polymorphism (iv). Static binding", "options": ["(i) only", "(ii) and (iv) only", "(ii) and (iii) only", "(iii) only"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "The 'virtual' keyword enables late (runtime) binding so the actual overriding function is resolved at execution time, which is the definition of runtime polymorphism.", "topic": "OOPS"}, {"id": "pdf1-082", "question": "Which of the following operation take worst-case linear time in the array implementation of the stack?", "options": ["Push", "Pop", "IsEmpty", "None"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "In a plain array-based stack, push, pop, and isEmpty all just read/update the top index, so each runs in O(1) worst-case time, not linear.", "topic": "DSA"}, {"id": "pdf1-083", "question": "Which of the following one can relate to the statement: If x items are put into y containers, with x>y, then at least one container must contain more than one item.", "options": ["Pumping Lemma", "Pigeon Hole Principle", "Counting principle", "None"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "This is the textbook statement of the Pigeonhole Principle: distributing more items than containers forces at least one container to hold more than one item.", "topic": "TOC"}, {"id": "pdf1-084", "question": "Which of the following must you do if a laptop holding client account information is stolen?", "options": ["Log the breach immediately with the DPO", "Notify the individuals concerned if their rights or freedoms are at risk", "Notify your manager", "Notify the regulators"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Under data-protection frameworks like GDPR, every breach must be logged/documented with the DPO regardless of its severity; notifying individuals or regulators only kicks in once a risk assessment says it's warranted.", "topic": "Privacy & Compliance"}, {"id": "pdf1-085", "question": "Which of the following keys in a table can uniquely identify a row in a table?", "options": ["Candidate key", "Alternate key", "Primary key", "All of these"], "correct": 4, "original_marked": 3, "matches_original": false, "confidence": "high", "reasoning": "Candidate keys, alternate keys, and primary keys are all, by definition, minimal attribute sets that uniquely identify a row \u2014 a primary key is simply the candidate key chosen for that role, and alternate keys are the ones not chosen, so 'All of these' is correct rather than primary key alone.", "topic": "DBMS"}, {"id": "pdf1-086", "question": "Which of the following is/are White box technique ?", "options": ["Statement Testing", "Decision Testing", "Condition Coverage", "All of the mentioned"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Statement testing, decision/branch testing, and condition coverage all require looking at the code's internal logic, which is exactly what defines white-box testing techniques.", "topic": "Software Engineering"}, {"id": "pdf1-087", "question": "Which of the following is/are not shared by the threads of the same process? Program counter (b) Logical Address space (c) Stack (d) Registers (e) Virtual Address space (f) File descriptor table (g) Message queue (h) Code", "options": ["(a), (b) and (e)", "(a), (c) and (f)", "(a), (c) and (h)", "(a), (c) and (d)"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Each thread keeps its own program counter, stack, and register set so it can execute independently, while address space, code, and file descriptor table remain shared across the process's threads.", "topic": "OS"}, {"id": "pdf1-088", "question": "Which of the following is TRUE?", "options": ["Every finite subset of a non-regular set is regular", "Every subset of a regular set is regular", "Infinite union of finite sets is regular", "The union of two non-regular sets is not regular"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Every finite set of strings is automatically regular (you can write it out as a finite union in a regex), so any finite subset of a non-regular language is still regular.", "topic": "TOC"}, {"id": "pdf1-089", "question": "Which of the following is true", "options": ["P is a subset of NP", "NP is a subset of P", "P and NP are equal", "NP is a subset of NP-hard"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Any problem solvable in polynomial time can also have its solution verified in polynomial time, so P is always a subset of NP; whether NP equals P remains an open problem.", "topic": "TOC"}, {"id": "pdf1-090", "question": "Which of the following is true of a divisional structure?", "options": ["It is also known as chain of command.", "It is also called a U-form (unitary) structure.", "It is a centralized structural form.", "It is used to promote flexibility and change."], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Divisional (M-form) structures push decision authority down to each division so it can respond quickly to its own market, which is exactly how they promote flexibility and change.", "topic": "Management"}, {"id": "pdf1-091", "question": "Which of the following is true of effective information sharing in an organization?", "options": ["Information should be shared vertically, but not horizontally.", "Vertical linkages are designed primarily for coordination and collaboration.", "The structure should fit the information requirements of the organization.", "It is not possible to give people a lot of information."], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Good organizational design means the structure and its information linkages are built to match what the organization actually needs to coordinate, not forced into one fixed pattern.", "topic": "Management"}, {"id": "pdf1-092", "question": "Which of the following is the most accurate description of an access control method that allows the data owner to develop and manage access control?", "options": ["MACs (Mandatory Access Control)", "RBACs (Role-Based Access Control)", "LBACs (List Based Access Control)", "DACs (Discretionary Access Control)"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "DAC (Discretionary Access Control) is defined by letting the resource/data owner decide and manage who else gets access, unlike MAC or RBAC which are set centrally or by role.", "topic": "Information Security"}, {"id": "pdf1-093", "question": "Which of the following is referred as part of restricted data structure?", "options": ["Stack", "Queue", "Linked list", "All of these"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "Stack and queue are both commonly labeled 'restricted' data structures because insertion/deletion is limited to specific ends, unlike a linked list which allows access anywhere; since queue fits this description just as well as stack, the single 'correct' option here is genuinely ambiguous, so the original marking is kept as-is.", "topic": "DSA"}, {"id": "pdf1-094", "question": "Which of the following is odd one out?", "options": ["Evaluating a postfix expression", "Matching Balancing Parentheses", "Luggage checking in airports", "Depth first search of graphs"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Postfix evaluation, parenthesis matching, and DFS are all classic stack (LIFO) applications, while airport luggage check-in is a first-come-first-served process, i.e. a queue, making it the odd one out.", "topic": "DSA"}, {"id": "pdf1-095", "question": "Which of the following is NOT a valid access control mechanism?", "options": ["DAC (Discretionary Access Control) list.", "SAC (Subjective Access Control) list.", "MAC (Mandatory Access Control) list.", "RBAC (Role-Based Access Control) list."], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "'SAC (Subjective Access Control)' is not a real, recognized access-control model \u2014 DAC, MAC, and RBAC are the standard, well-defined mechanisms.", "topic": "Information Security"}, {"id": "pdf1-096", "question": "Which of the following is NOT a key concept associated with scientific management?", "options": ["One best way", "Formalization", "Time-and-motion studies.", "Systematic selection"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Scientific management is built around finding the 'one best way' through time-and-motion studies and scientifically selecting/training workers; 'formalization' is a general organizational-structure concept, not a core Taylorist idea.", "topic": "Management"}, {"id": "pdf1-097", "question": "Which of the following is not a good way to protect one's privacy?", "options": ["Use privacy-focused SE", "Use private Browser-window", "Disable cookies", "Uninstall Antivirus"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Uninstalling antivirus removes a security safeguard rather than protecting privacy \u2014 it actually increases exposure to malware/spyware that could steal personal data.", "topic": "Privacy & Compliance"}, {"id": "pdf1-098", "question": "Which of the following is element of the database?", "options": ["Constraints and schema", "Relationships", "Data", "All of these"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A database is made up of the raw data itself plus the schema, constraints, and relationships that structure and govern it, so all of these are elements of a database.", "topic": "DBMS"}, {"id": "pdf1-099", "question": "Which of the following is an example of the implementation of an access control policy for a bank teller?", "options": ["Rule-based policy", "Identity-based policy", "User-based policy", "Role-based policy"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A bank teller's access is granted based on their job role rather than their individual identity, which is exactly what Role-Based Access Control implements.", "topic": "Information Security"}, {"id": "pdf1-100", "question": "Which of the following is an ethical behaviour?", "options": ["Giving less remuneration to the employees.", "Selling inferior goods.", "Honest behaviour with the customer.", "Polluting the environment."], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Being honest with customers is straightforward ethical conduct, unlike underpaying staff, selling defective goods, or polluting the environment, which are all unethical practices.", "topic": "Business Ethics"}, {"id": "pdf1-101", "question": "Which of the following is a vulnerability in a network environment with discretionary access controls?", "options": ["SYN flood", "Impersonation", "Denial of service", "Birthday attack"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "DAC grants access based on user identity/ownership, so its main weakness is that an attacker who successfully impersonates an authorized user inherits that user's access rights.", "topic": "Information Security"}, {"id": "pdf1-102", "question": "Which of the following is a project scheduling method that can be applied to software development?", "options": ["EPM", "CPM", "CMM", "NONE OF THE ABOVE"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "CPM (Critical Path Method) identifies the longest sequence of dependent tasks and is a standard scheduling technique applied to software projects; CMM is a process-maturity model, not a scheduling method.", "topic": "Software Engineering"}, {"id": "pdf1-103", "question": "Which of the following is a MAC (Mandatory Access Control) feature?", "options": ["Uses levels of security to classify users and data.", "Allows owners of documents to determine who has access to specific documents.", "Uses access control lists that specify a list of authorized users.", "Uses access control lists that specify a list of unauthorized users."], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "MAC assigns security classification levels (e.g., top secret, secret, confidential) to both users and data and grants access by comparing clearance to classification, unlike DAC which is owner-based.", "topic": "Information Security"}, {"id": "pdf1-104", "question": "Which of the following is a leadership trait?", "options": ["Dominance", "energy", "cognitive ability", "All the other answers are correct"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "low", "reasoning": "Trait theory literature (e.g., Kirkpatrick & Locke, Mann, Stogdill) lists dominance, energy, and cognitive ability as leadership traits, so all three options are individually defensible, making 'All the other answers are correct' arguably just as valid as picking 'energy' alone; deferring to the source's marked answer.", "topic": "Management"}, {"id": "pdf1-105", "question": "Which of the following does not require additional temporary space?", "options": ["Stack", "Queue", "Linked list", "All of these"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "low", "reasoning": "The question lacks context on which operation is meant (e.g., insertion, traversal, reversal), so it's not possible to confidently verify against a single correct data structure; deferring to the source's marked answer.", "topic": "DSA"}, {"id": "pdf1-106", "question": "Which of the following condition is used to transmit two packets over a medium at the same time?", "options": ["Contention", "Collision", "Synchronous", "Asynchronous"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A collision occurs when two devices on a shared medium transmit simultaneously and their signals overlap/interfere, which is exactly this scenario.", "topic": "CN"}, {"id": "pdf1-107", "question": "Which of the following claims about DAC (Discretionary Access Control) is correct?", "options": ["Files that don't have an owner CANNOT be modified.", "The administrator of the system is the owner of each object.", "The operating system is the owner of each object.", "Each object has an owner, which has full control over the object."], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "The defining feature of DAC is that every object has an owner who has full discretion to grant or revoke access to that object.", "topic": "Information Security"}, {"id": "pdf1-108", "question": "Which of the following are objectives of an information systems security program", "options": ["Threats, vulnerabilities, and risks", "Security, information value, and threats", "Integrity, confidentiality, and availability", "Authenticity, vulnerabilities, and costs"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Integrity, confidentiality, and availability (the CIA triad) are the core objectives of any information security program.", "topic": "Information Security"}, {"id": "pdf1-109", "question": "Which of the following are components of a database except?", "options": ["User data", "Metadata", "Reports", "Indexes"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "A database's structural components are user data, metadata (schema), and indexes; reports are generated outputs produced by applications querying the database, not a stored component of the database itself.", "topic": "DBMS"}, {"id": "pdf1-110", "question": "Which of the following application generally use a stack?", "options": ["Parenthesis balancing program", "Syntax analyzer in compiler", "Keeping track of local variables at run time", "All of the above"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Stacks underlie parenthesis matching, compiler syntax analysis (parsing), and the function call stack that tracks local variables at runtime, so all three are valid stack applications.", "topic": "DSA"}, {"id": "pdf1-111", "question": "Which of the below statement(s) is/are true? (i). By using pure virtual function, it is possible to achieve a pointer to base class points to refer derived class objects. (ii). By using pure virtual function, it is possible to achieve a pointer to derived class points to refer base class objects.", "options": ["Both (i) and (ii)", "Neither (i) nor (ii)", "only (i)", "only (ii)"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Virtual functions enable a base-class pointer to reference a derived-class object and invoke the derived override (runtime polymorphism, statement i); a derived-class pointer pointing to a base-class object (statement ii) is not something virtual functions provide and isn't valid without an explicit downcast.", "topic": "OOPS"}, {"id": "pdf1-112", "question": "Which of the below is used for designing real time networking capabilities?", "options": ["Packet Tracer", "WireShark", "Network Simulator 2", "TinyOS"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "Packet Tracer has a distinct 'Realtime mode' where the simulated network behaves as it would with real hardware, which fits 'real time networking capabilities', but NS2 is also widely used for real-time network protocol simulation, so the intended distinction is not fully certain; deferring to the source's marked answer.", "topic": "CN"}, {"id": "pdf1-113", "question": "Which of the below is not a business continuity disaster?", "options": ["Flooding", "Covid19", "Earth Quake", "Tsunami"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "low", "reasoning": "COVID-19, flooding, earthquakes, and tsunamis are all real triggers for business continuity plans, so the question only makes sense if it's distinguishing a biological/pandemic disaster from geophysical/natural disasters (flood, earthquake, tsunami); the question wording itself is ambiguous, so deferring to the source's marked answer.", "topic": "Management"}, {"id": "pdf1-114", "question": "Which of the below is an inline device?", "options": ["Switch", "Router", "VPN", "Host"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "low", "reasoning": "An inline device sits directly in the traffic path processing all passing packets; routers fit this well, though switches are also commonly classified as inline devices, making the single-answer choice somewhat ambiguous, so deferring to the source's marked answer.", "topic": "CN"}, {"id": "pdf1-115", "question": "Which of the below is a network sniffer tool?", "options": ["Packet Tracer", "WireShark", "Network Simulator 2", "TinyOS"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "WireShark is the industry-standard packet sniffer/protocol analyzer used to capture and inspect live network traffic.", "topic": "CN"}, {"id": "pdf1-116", "question": "Which of the following would LEAST likely be a source of ethical guidance?", "options": ["holy books", "laws", "tests", "friends"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Recognized sources of ethical guidance include religion/holy books, laws, and personal relationships like friends and family; 'tests' is not a recognized source of ethical values.", "topic": "Business Ethics"}, {"id": "pdf1-117", "question": "Which of the following term is the practice of hiding data in graphic, audio, or other text file?", "options": ["Masking", "Steganography", "Cryptography", "None of the choices"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Steganography is defined as concealing a message within another file (image, audio, text) so its existence is hidden, distinct from cryptography which scrambles content but doesn't hide its existence.", "topic": "Information Security"}, {"id": "pdf1-118", "question": "Which of the following statement(s) is/are NOT true? (i). Virtual function help to achieve a pointer to base class points to refer base class objects only. (ii). Virtual function help to achieve a pointer to base class points to refer derived class objects. (iii). Virtual function has no role in supporting a pointer to achieve polymorphism. (iv). Virtual functions are not member functions of a class.", "options": ["(i) and (iv) only", "(i), (ii) and (iv) only", "(i), (iii) and (iv) only", "(ii) only"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Statement (ii) is true (virtual functions let a base pointer reference derived objects), while (i) is false (a base pointer can reference derived objects, not just base ones), (iii) is false (virtual functions are the core mechanism for runtime polymorphism), and (iv) is false (virtual functions must be declared as class members), so the NOT-true set is (i), (iii), (iv).", "topic": "OOPS"}, {"id": "pdf1-119", "question": "Which of the following relations is correct, when comparing the best-case complexity?", "options": ["insertion<merge<selec tion", "merge <insertion<selection", "insertion<selection<m erge", "none of the above"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Best-case complexity: insertion sort is O(n) on an already-sorted array, merge sort is always O(n log n) regardless of input order, and selection sort is always O(n^2), giving insertion < merge < selection.", "topic": "DSA"}, {"id": "pdf1-120", "question": "Which of the following principles of management was not given by Fayol?", "options": ["Unity of direction", "Subordination of individual interest to common interest", "Stability of tenure", "Standardisation"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Fayol's 14 principles include unity of direction, subordination of individual interest, and stability of tenure, but 'standardisation' is not among them\u2014it's more associated with Taylor's scientific management.", "topic": "Management"}, {"id": "pdf1-121", "question": "Which of the following is true of a functional structure?", "options": ["It reacts quickly to environmental changes.", "It has a strong horizontal coordination.", "It often results in hierarchy overload.", "It cannot work in small organizations."], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Functional structures group employees by specialty with strong vertical (not horizontal) coordination, and decisions tend to funnel up to top management, causing hierarchy overload and slow response to change.", "topic": "Management"}, {"id": "pdf1-122", "question": "Which of the following is the encryption/decryption key known only to the party or parties that exchange secret messages?", "options": ["E-Signature", "Digital Signature", "Private key", "Security token"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "A private (secret) key in symmetric cryptography is known only to the communicating parties, unlike a digital signature or security token which serve authentication/verification roles.", "topic": "Information Security"}, {"id": "pdf1-123", "question": "Which of the following is NOT one of the triple bottom line factors of corporate social responsibility?", "options": ["society", "environment", "economy", "culture"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "The triple bottom line consists of people/society, planet/environment, and profit/economy\u2014'culture' is not one of the three pillars.", "topic": "Business Ethics"}, {"id": "pdf1-124", "question": "Which of the following is NOT a topic included in the social responsibility audit focus?", "options": ["open communication", "treatment of employees", "leadership", "management structure"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "low", "reasoning": "Social responsibility audits typically focus on employee treatment, community involvement, environmental practices, and open communication/stakeholder engagement; 'management structure' is more of an organizational design topic than a CSR audit focus area, though the exact source list couldn't be confirmed, so deferring to the source's marked answer.", "topic": "Business Ethics"}, {"id": "pdf1-125", "question": "Which of the following is an advantage of a peer-to-peer network?", "options": ["Files and folders cannot be centrally backed up", "Does not need an expensive server as individual workstations are used to access files", "The server is expensive to purchase", "Network security can be carried out centrally"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The classic advantage of peer-to-peer networks is that they avoid the cost of a dedicated server since individual workstations directly share files with each other; centralized backup and security are disadvantages of P2P, not advantages.", "topic": "CN"}, {"id": "pdf1-126", "question": "Which of the following is an advantage of a client-server network?", "options": ["If one computer fails it will not disrupt the network", "There is little or no security", "Users can access shared data which is centrally controlled", "If any part of the network fails, a lot of disruption can occur"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "In a client-server network, data and resources are stored centrally on the server and shared out to clients under central control, which is the classic advantage of this architecture over peer-to-peer.", "topic": "CN"}, {"id": "pdf1-127", "question": "Which of the following firms has NOT been exposed for ethical abuses and corrupt conduct?", "options": ["Satyam Computers", "Lehman Brothers", "Enron", "General Electric(GE)"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Satyam, Lehman Brothers, and Enron are all textbook examples of major corporate fraud/collapse scandals; GE is the outlier in this list and is the standard 'none of the above' answer in this kind of question.", "topic": "Business Ethics"}, {"id": "pdf1-128", "question": "Which of following linked list has the feature of its elimination of the need for a pointer to a node's predecessor to delete the node?", "options": ["Singly", "Doubly", "Circular", "All of these"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A doubly linked list stores a prev pointer in every node, so deletion can use the node's own prev field directly instead of having to search for or separately track a pointer to its predecessor.", "topic": "DSA"}, {"id": "pdf1-129", "question": "Which of the given option is correct? #include<stdio.h> main(){ int a[4]={1,2,3,4}; int *b[4]; int *(c[4]); printf(\"%d %d %d\",a,b,c); }", "options": ["a. a is an integer array, b is an array of pointers, c is an array of pointers", "a. a is an integer array, b is an array of pointers, c is a pointer to an array", "a. a is an array of pointers, b is a pointer to an array, c is an array of pointers", "a. a is an array of pointers, b is a pointer to an array, c is a pointer to an array"], "correct": 1, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "The PDF's marked answer (option 2) is wrong: '[]' binds tighter than unary '*' in C declarations, so 'int *(c[4])' means exactly the same as 'int *c[4]' - an array of 4 int pointers, not a pointer to an array. I verified this by compiling: sizeof(c) is 32 bytes (4 pointers of 8 bytes each), matching sizeof(b), so both b and c are arrays of pointers, making option 1 correct.", "topic": "C/C++"}, {"id": "pdf1-130", "question": "Which network protocol is often used for gaming?", "options": ["TCP", "FTP", "UDP", "HTTP"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "UDP is preferred for real-time gaming because it has no retransmission/ordering overhead, trading reliability for the low latency that fast-paced games need.", "topic": "CN"}, {"id": "pdf1-131", "question": "Which network topology is the most common way of setting up a network?", "options": ["Ring", "Bus", "Star", "Mesh"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Star topology, where every device connects to a central hub/switch, is the most common setup in modern LANs because it's easy to install, manage, and troubleshoot.", "topic": "CN"}, {"id": "pdf1-132", "question": "Which model can be selected if a user is involved in all the phases of SDLC?", "options": ["Waterfall Model", "Prototyping Model", "RAD Model", "Build AND Fix Model"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "This is a standard software-engineering MCQ (confirmed against multiple published answer keys for this exact question) where RAD is the intended answer because RAD relies on continuous user/client participation (e.g. JAD sessions) throughout every phase of development.", "topic": "Software Engineering"}, {"id": "pdf1-133", "question": "Which method is meant for coordinating access to resources with respect to the available IP addresses?", "options": ["MAC", "ACL", "DAC", "None of the choices"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "An Access Control List (ACL) is the mechanism used to permit or deny access to network resources based on criteria like source/destination IP address, commonly configured on routers and firewalls.", "topic": "CN"}, {"id": "pdf1-134", "question": "WHICH LAYER IS RESPONSIBLE FOR PROCESS TO PROCESS DELIVERY?", "options": ["NETWORK LAYER", "TRANSPORT LAYER", "SESSION LAYER", "DATA LINK LAYER"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The Transport layer (TCP/UDP) provides process-to-process delivery using port numbers, distinguishing it from the Network layer, which only handles host-to-host (IP address) delivery.", "topic": "CN"}, {"id": "pdf1-135", "question": "Which key skill was not mentioned by Kanter as needed by managers of innovative organisations?", "options": ["Coping", "Political", "Communicating", "Leading a team"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "low", "reasoning": "This references a specific list of skills Kanter attributed to managers of innovative organizations (coping, political, and team-leading skills); I could not independently verify the exact enumerated list from her work, so I deferred to the source's marked answer.", "topic": "Management"}, {"id": "pdf1-136", "question": "Which is/are the application(s) of stack", "options": ["Function calls", "Large number Arithmetic", "Evaluation of arithmetic expressions", "All of these"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Stacks underlie function call management (the call stack), expression evaluation/conversion (infix-postfix), and can also be used in large-number arithmetic routines (e.g. reversing digit order for addition), so all three listed uses are valid applications.", "topic": "DSA"}, {"id": "pdf1-137", "question": "Which is used for predicting virus?", "options": ["Firewall", "CWE", "IPS", "Exposures"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "An Intrusion Prevention System (IPS) actively monitors traffic and behavior to detect and block malware/attacks in real time, unlike a firewall (which just filters traffic by rule) or CWE (a weakness catalog, not a tool).", "topic": "Information Security"}, {"id": "pdf1-138", "question": "Which is the most optimal scheduling algorithm?", "options": ["FCFS-First Come First Served", "Shortest Job First", "Round Robin", "None of the Mentioned"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Shortest Job First is provably optimal for minimizing average waiting time among non-preemptive CPU scheduling algorithms, which is why it's called 'optimal' in OS textbooks despite practical issues like starvation.", "topic": "OS"}, {"id": "pdf1-139", "question": "Which is the most efferent phone directory search?", "options": ["Binary search tree", "Balanced BST", "Trie", "Linked List"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "A trie gives O(M) lookup time (M = string length) independent of the number of entries, beating a balanced BST's O(M log N), which is why tries are the standard choice for name/phone-directory style prefix search.", "topic": "DSA"}, {"id": "pdf1-140", "question": "which is the fastest storage unit in a usual memory hierarchy?", "options": ["cache", "main memory", "hard disk memory", "register"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "CPU registers sit at the top of the memory hierarchy and are the fastest storage, faster than cache, main memory, and disk, though also the smallest and most expensive per bit.", "topic": "CAO"}, {"id": "pdf1-141", "question": "Which is not the application of queue?", "options": ["Printing jobs", "Process waiting", "Function nesting", "Network packet forwarding"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Function nesting/recursion is managed with a stack (LIFO call frames), whereas printing jobs, process waiting lists, and packet forwarding are all naturally FIFO, i.e. queue-based.", "topic": "DSA"}, {"id": "pdf1-142", "question": "Which is not one of Fayol\u2019s principles?", "options": ["Authority and responsibility", "Globalization", "Unity of direction", "Unity of command"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Fayol's 14 principles (division of work, authority/responsibility, unity of command, unity of direction, etc.) predate and don't include 'globalization', which is a modern business concept, not one of his original management principles.", "topic": "Management"}, {"id": "pdf1-143", "question": "Which is first loaded into the BUS by the data transfer initiator?", "options": ["Data", "Address", "Control Information", "Address, Control Information"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "In a bus transaction, the initiating device first places the target's address and the relevant control signals (e.g. read/write) on the bus to set up and identify the transfer before any data is actually moved.", "topic": "CAO"}, {"id": "pdf1-144", "question": "Which is a true statement.", "options": ["Breadth-first search is the shortest path algorithm that works on un-weighted graphs", "Depth first search is the shortest path algorithm that works on un-weighted graphs", "Both of the above are true", "None of the above are true"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "BFS explores a graph level by level, so on an unweighted graph the first time it reaches a node is guaranteed to be via a shortest path; DFS gives no such guarantee since it can go deep down a long path first.", "topic": "DSA"}, {"id": "pdf1-145", "question": "Which HR practice would most likely be improved through a firm's efforts at corporate social responsibility?", "options": ["benefits", "recruitment", "compensation", "succession planning"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A firm's CSR reputation is a major driver of employer branding and candidate attraction, so recruitment is the HR practice most directly boosted by visible CSR efforts, more so than benefits, compensation, or succession planning.", "topic": "Management"}, {"id": "pdf1-146", "question": "Which directory implementation is used in most Operating System?", "options": ["Single level directory structure", "Two level directory structure", "Tree directory structure", "Acyclic directory structure"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Most modern operating systems (Windows, Linux, macOS) use a tree-structured directory hierarchy, letting users organize files into nested subdirectories, unlike the simpler single- or two-level schemes.", "topic": "OS"}, {"id": "pdf1-147", "question": "Which database level is closest to the users?", "options": ["Internal", "Physical", "Conceptual", "External"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "In the three-schema DBMS architecture, the external level defines individual user views/subsets of the data, making it the level closest to end users, while internal and physical levels concern storage.", "topic": "DBMS"}, {"id": "pdf1-148", "question": "Which data structure is used for implementing recursion?", "options": ["Queue", "Stack", "Arrays", "List"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Recursive function calls are implemented via the call stack, which pushes a new stack frame for each call and pops it on return, mirroring the LIFO nature of recursion.", "topic": "DSA"}, {"id": "pdf1-149", "question": "Which data structure is needed to convert infix notation to postfix notation?", "options": ["Branch", "Queue", "Tree", "Stack"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Infix-to-postfix conversion algorithms use a stack to hold operators and parentheses temporarily, popping them out in the correct precedence order to build the postfix expression.", "topic": "DSA"}, {"id": "pdf1-150", "question": "Which data model is independent of both hardware and DBMS?", "options": ["External", "Internal", "Conceptual", "All of these"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "The conceptual (logical) data model describes the overall community view of the data without reference to physical storage details or any specific DBMS product, unlike the internal (hardware/storage-dependent) or external (user-view-dependent) levels.", "topic": "DBMS"}, {"id": "pdf1-151", "question": "Which approach recognises that there is no optimal organisational design?", "options": ["Flexible", "Virtual", "Contingency", "Boundaryless"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Contingency theory holds there is no single 'one best way' to structure an organization; the ideal design depends on situational factors like environment, size, and technology.", "topic": "Management"}, {"id": "pdf1-152", "question": "Which among the following is equivalent to the given regular expression? ab*+b", "options": ["(ab)*+b", "a((b)*+b)", "(a(b)*)+b", "((a*b)b*)*"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Regex precedence is star > concatenation > union(+), so 'ab*+b' parses as (a concatenated with b*) unioned with b, i.e. (a(b)*)+b.", "topic": "TOC"}, {"id": "pdf1-153", "question": "Which access control type has a central authority that determines what objects people have access to depending on their role or organizational security policy?", "options": ["Mandatory Access Control", "Discretionary Access Control", "Non-Discretionary Access Control", "Rule-based Access control"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Mandatory Access Control (MAC) has a central authority enforce access based on a fixed organizational security policy, unlike DAC where the resource owner decides who gets access.", "topic": "Information Security"}, {"id": "pdf1-154", "question": "Which term refers to the discipline that deals with what is good and bad or right and wrong?", "options": ["morals and traditions", "social responsibility", "ethics", "cultural norms"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Ethics is literally defined as the branch of philosophy/discipline concerned with what is morally right and wrong.", "topic": "Business Ethics"}, {"id": "pdf1-155", "question": "Which of the following statements regarding inline functions is correct?", "options": ["It speeds up execution.", "It slows down execution.", "It increases the code size.", "It increases the code size and length."], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "Inline functions avoid function-call overhead so they speed up execution, which is the intended answer here, but the question is a bit flawed since 'increases code size' (option 3) is also a true statement about inlining.", "topic": "C/C++"}, {"id": "pdf1-156", "question": "Which of the following is the correct representation of pure virtual function?", "options": ["class base { public: virtual void display=0;};", "class base {public: virtual void display!=0;};", "class base {public: virtual void display () = 0 ;};", "class base {public: virtual void display () > 0 ;};"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "The correct C++ syntax for a pure virtual function requires the function signature with parentheses followed by '= 0;', e.g. 'virtual void display() = 0;'.", "topic": "OOPS"}, {"id": "pdf1-157", "question": "Which of the following is suitable to be considered as an object?", "options": ["Name", "Email", "Transaction", "Quantity"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Objects have identity, state, and behavior; a Transaction is an entity/process with behavior, while Name, Email, and Quantity are just simple data attributes, not standalone objects.", "topic": "OOPS"}, {"id": "pdf1-158", "question": "Which of the following concept of oops allows complier to inset arguments in a function call if it is not specified?", "options": ["Call by value", "Default arguments", "Call by reference", "Call by pointer"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Default arguments let the compiler substitute a pre-specified value for a parameter when the caller omits it in the function call.", "topic": "OOPS"}, {"id": "pdf1-159", "question": "Which access control model can be suited for bank teller application?", "options": ["Discretionary", "Mandatory", "Role-based", "Rule-based"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "A bank teller system is the textbook example of Role-Based Access Control, since permissions are tied to job roles like teller or manager rather than individual discretion.", "topic": "Information Security"}, {"id": "pdf1-160", "question": "When class B is inherited from class A, what is the order in which the destructors are called?", "options": ["Class A first Class B next", "Class B first Class A next", "Class B's only as it is the child class", "Class A's only as it is the parent class"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Destructors run in the reverse order of construction: the derived class (B) destructor executes first, then the base class (A) destructor.", "topic": "OOPS"}, {"id": "pdf1-161", "question": "When we concatenate two languages L1 and L2 recognized by machine M1 and M2 we obtain a machine with final state same as that of __________________", "options": ["M2", "M1", "M1 and M2", "M1 or M2"], "correct": 1, "original_marked": 3, "matches_original": false, "confidence": "high", "reasoning": "In the standard NFA construction for concatenation, epsilon transitions link M1's final states to M2's start state and only M2's original final states remain accepting, so the concatenated machine's final states equal M2's, not both machines'.", "topic": "TOC"}, {"id": "pdf1-162", "question": "When we concatenate two languages L1 and L2 recognized by machine M1 and M2 we obtain a machine with final state same as that of __________________", "options": ["M1 or M2", "M1", "M1 and M2", "M2"], "correct": 4, "original_marked": 3, "matches_original": false, "confidence": "high", "reasoning": "Same reasoning as the equivalent question: concatenation construction keeps only M2's final states as accepting, so the answer is M2 alone, not 'M1 and M2'.", "topic": "TOC"}, {"id": "pdf1-163", "question": "When there is more than one final state in the reduced FA, then its regular expression will contain _________ operator surely", "options": ["dot", "star", "binary+", "unary+"], "correct": 3, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "When a reduced FA has multiple final states, its regex is built as the union of the sub-expressions for each accepting path, so it must contain the union/'+' operator; star relates to loops, not to having multiple accept states.", "topic": "TOC"}, {"id": "pdf1-164", "question": "When there is more than one final state in the reduced FA, then its regular expression will contain _________ operator surely", "options": ["unary +", "dot", "binary +", "star"], "correct": 3, "original_marked": 4, "matches_original": false, "confidence": "high", "reasoning": "Same fact as the equivalent question: multiple final states force a union of per-final-state expressions, so the regex surely contains the binary '+' (union) operator, not star.", "topic": "TOC"}, {"id": "pdf1-165", "question": "When there is complete DFA with Five states out of which two are final states if F is modified such that it recognizes complement of the original language then there will be at least _________final states.", "options": ["2", "3", "7", "5"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Complementing a DFA swaps final and non-final states; with 5 states and 2 originally final, the 3 originally non-final states become the new final states.", "topic": "TOC"}, {"id": "pdf1-166", "question": "When there are infinite distinguishable strings then there cannot be a -------------", "options": ["automata", "finite automata", "regular expression", "both finite automata and regular expression"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "By the Myhill-Nerode theorem, infinitely many pairwise-distinguishable strings means the language is non-regular, so neither a finite automaton nor a regular expression can exist for it.", "topic": "TOC"}, {"id": "pdf1-167", "question": "When there are infinite distinguishable strings then there cannot be a -------------", "options": ["finite automata", "automata", "regular expression", "both finite automata and regular expression"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Same Myhill-Nerode reasoning: infinite distinguishable strings implies non-regularity, ruling out both a finite automaton and a regular expression (a more general automaton could still exist).", "topic": "TOC"}, {"id": "pdf1-168", "question": "When the project deals with developing a well understood application, then the model is called as", "options": ["Waterfall Model", "Spiral Model", "COCOMO Model", "Agile Model"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "In the COCOMO model, a project is classified as 'Organic' precisely when it involves developing a well-understood application with an experienced team, so this classification comes from the COCOMO model.", "topic": "Software Engineering"}, {"id": "pdf1-169", "question": "When the entries in the segment tables of two different processes point to the same physical address then ____________", "options": ["the segments are invalid", "the processes get blocked", "the address space is invalid", "the segments are shared"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "When segment table entries from two processes reference the same physical address, that memory segment is being shared between the processes (common for shared libraries or code).", "topic": "OS"}, {"id": "pdf1-170", "question": "When the computer processor does not get a data item it requires in the cache, then the problem is known as", "options": ["Cache miss", "Cache hit", "File caches", "Name cache"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A cache miss is, by definition, when the processor looks for data in the cache but it isn't there, forcing a fetch from main memory.", "topic": "CAO"}, {"id": "pdf1-171", "question": "When FA M is given which recognizes language L and reverse of L is found by using M then there can be ___________Final states", "options": ["Two", "Three", "Only one", "Any number"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Reversing an FA swaps the roles of start and final states; since the original machine M has exactly one start state, the reversed machine has exactly one final state.", "topic": "TOC"}, {"id": "pdf1-172", "question": "When employee satisfaction is measured, employees seemed to be more satisfied under a(n) ________ leadership style than under a(n) ________ one.", "options": ["laissez-faire; participative", "supportive; laissez-faire", "democratic; directive", "democratic; autocratic"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Classic leadership-style studies (e.g., Lewin) found employees generally report higher satisfaction under democratic leadership than under autocratic leadership.", "topic": "Management"}, {"id": "pdf1-173", "question": "When determining the most appropriate form of leadership, which of the following should be considered?", "options": ["The manager.", "The work environment.", "The group.", "All the other options are correct."], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Situational/contingency views of leadership hold that the best style depends jointly on the manager, the group being led, and the work environment, so all three matter.", "topic": "Management"}, {"id": "pdf1-174", "question": "When determining the most appropriate form of leadership, which of the following should be considered?", "options": ["The manager.", "The work environment.", "The group", "All the other answers are correct."], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Same as the equivalent question: appropriate leadership style depends on the manager, the group, and the work environment together, not any single factor.", "topic": "Management"}, {"id": "pdf1-175", "question": "When designing apps, a software company considers data protection issues. So, what should we call this strategy?", "options": ["Data protection by default", "Legitimate data protection", "Data protection by design", "Organisational data protection"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Embedding data protection considerations into an app during the design/development process is 'data protection by design' under GDPR, distinct from 'by default' which concerns default privacy-friendly settings after the system is built.", "topic": "Privacy & Compliance"}, {"id": "pdf1-176", "question": "When a state in a FA has self loop its regular expression will have -------------", "options": ["dot", "star", "binary+", "unary+"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A self loop on a state lets the machine repeat that transition zero or more times, which is exactly what the Kleene star operator represents in a regular expression.", "topic": "TOC"}, {"id": "pdf1-177", "question": "When a state in a FA has self loop its regular expression will have -------------", "options": ["dot", "binary+", "unary +", "star"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Same reasoning as the sibling question: a self loop corresponds to zero-or-more repetition, i.e. the star operator, which here is option 4.", "topic": "TOC"}, {"id": "pdf1-178", "question": "When a program tries to access a page that is mapped in address space but not loaded in physical memory, then", "options": ["segmentation fault occurs", "fatal error occurs", "page fault occurs", "no error occurs"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "A page that is part of the process's address space (mapped) but not currently resident in RAM triggers a page fault, prompting the OS to fetch it from disk.", "topic": "OS"}, {"id": "pdf1-179", "question": "What would be the asymptotic time complexity to insert an element at the second position in the linked list?", "options": ["O(1)", "O(n)", "O(n^2)", "None"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Inserting right after the head only requires following one existing pointer and relinking, a constant number of steps regardless of list length, so it's O(1) (this differs from inserting at an arbitrary/unknown position, which needs O(n) traversal).", "topic": "DSA"}, {"id": "pdf1-180", "question": "What will be the value of top, if there is a size of stack STACK_SIZE is 5", "options": ["5", "6", "4", "none"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "low", "reasoning": "The question gives no code or sequence of push/pop operations, so the value of 'top' can't actually be derived from the given information; deferring to the source's marked answer.", "topic": "DSA"}, {"id": "pdf1-181", "question": "What will be the output? #include<stdio.h> #include<string.h> main(){ char arr1[5]={'a','p','p','l','e'}; char arr2[5]; arr2=arr1; printf(\"%s\",arr2); }", "options": ["apple", "Error", "a", "0"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "In C, array names are not modifiable lvalues, so 'arr2 = arr1' is illegal and the code fails to compile, producing an error rather than any runtime output.", "topic": "C/C++"}, {"id": "pdf1-182", "question": "What will be the output? #include<stdio.h> main(){ char arr[]=\"ab.cd.ef\"; printf(\"%s\",strrchr(arr,'.')); }", "options": ["ab", ".cd", ".cd.ef", ".ef"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "strrchr finds the LAST occurrence of the character and returns a pointer from there to the end of the string, so it returns \".ef\" (the final dot onward), not the first dot.", "topic": "C/C++"}, {"id": "pdf1-183", "question": "What will be the output? #include<stdio.h> int value=100; void myFunction(int parameter) { printf(\"%d\",parameter); } main(){ int value=200; myFunction(value); }", "options": ["200", "100", "100 200", "200 100"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "main's local variable 'value' (200) shadows the global 'value' (100), and it's this local copy that gets passed by value into myFunction, so 200 is printed.", "topic": "C/C++"}, {"id": "pdf1-184", "question": "What will be the output #include<stdio.h> void myFunction() { return 1; } main(){ printf(\"%d\", myFunction()); }", "options": ["1", "0", "Error", "None of these"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "myFunction is declared void but its body has 'return 1;', a type mismatch that standard C compilers reject, so the program fails to compile.", "topic": "C/C++"}, {"id": "pdf1-185", "question": "What will be the output #include<stdio.h> main(){ int arr[4]={0,1,2,3}; int one,two,three; one=++arr[1]; two=arr[one]+1; three=arr[one+1]; printf(\"%d %d %d\",one,two,three); }", "options": ["a. 1 2 3", "a. 2 3 3", "a. 2 2 3", "a. 0 1 26"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "++arr[1] makes arr[1]=2 so one=2; two=arr[2]+1=2+1=3; three=arr[3]=3, giving \"2 3 3\".", "topic": "C/C++"}, {"id": "pdf1-186", "question": "What will be the output #include<stdio.h> main(){ float a[]={1.23,2.34,3.45,4.56,5.67}; printf(\"%d\",sizeof(a)/sizeof(a[-1])); }", "options": ["5", "1", "Error", "0"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "sizeof is evaluated at compile time from the operand's type, not its runtime value, so even though a[-1] is out of bounds, sizeof(a[-1]) is just sizeof(float); 20 bytes / 4 bytes = 5.", "topic": "C/C++"}, {"id": "pdf1-187", "question": "What will be the output #include<stdio.h> int myFunction1(int parameter) { return parameter; } int myFunction2(int *parameter) { return *parameter++; } main(){ int value=100; printf(\"%d %d\", myFunction1(value), myFunction2(&value)); }", "options": ["100 101", "101 101", "100 100", "101 100"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "myFunction1 just returns its copy of value (100); in myFunction2, '*parameter++' parses as '*(parameter++)' due to precedence, so it dereferences before incrementing the pointer, also yielding 100 \u2014 giving \"100 100\".", "topic": "C/C++"}, {"id": "pdf1-188", "question": "What will be the output #include <stdio.h> char* cut(char *parameter) { parameter+=5; return parameter; } main() { printf(\"%s\",cut(\"AllisWell!\")); }", "options": ["Allis", "Well!", "AllisWell!", "Error5"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Advancing the pointer by 5 chars into \"AllisWell!\" (A-l-l-i-s are indices 0-4) lands on index 5, 'W', so the returned string is \"Well!\".", "topic": "C/C++"}, {"id": "pdf1-189", "question": "What will be the output of the given program? #include<stdio.h> int myFunction(int parameter) { return parameter++; } main(){ int value1=100; int value2=myFunction(value1); printf(\"%d\",--value2); }", "options": ["100", "101", "99", "Error"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "'return parameter++' returns the value before incrementing, so value2 gets 100; then '--value2' pre-decrements it to 99 before printing.", "topic": "C/C++"}, {"id": "pdf1-190", "question": "What will be the output of the given code #include<stdio.h> void myFunction(int parameter) { printf(\"%d \",parameter); } main(){ int value1=1; myFunction(value1); static int value2; if (value2<value1) { value2++; main(); } }", "options": ["Error", "1", "2", "1 1"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "The first call prints \"1 \", then since the static value2 (0) is less than value1 (1) it recurses once more, printing \"1 \" again before the condition becomes false, giving \"1 1\" total.", "topic": "C/C++"}, {"id": "pdf1-191", "question": "What will be the output of the below code #include<stdio.h> int myFunction(int *parameter) { return ++*parameter; } main(){ int value=100; printf(\"%d \",value); myFunction(&value); printf(\"%d\",value); }", "options": ["100 100", "101 101", "101 100", "100 101"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "The first printf runs before myFunction modifies value, printing 100; myFunction then increments value via the pointer to 101, which the second printf shows, giving \"100 101\".", "topic": "C/C++"}, {"id": "pdf1-192", "question": "What will be printed? #include<stdio.h> int myFunction() { return 1; return 2; } main(){ printf(\"%d\", myFunction()); }", "options": ["1", "2", "1 2", "2 1"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A function returns at the first 'return' statement it executes, so 'return 2;' is unreachable dead code and only 1 is ever returned and printed.", "topic": "C/C++"}, {"id": "pdf1-193", "question": "What will be printed? #include<stdio.h> main(){ int myFunction() { return 1; } printf(\"%d\", myFunction()); }", "options": ["Invalid function definition", "myFunction() should be defined outside main method", "1", "0"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "low", "reasoning": "Nested function definitions are not part of standard ISO C and are only accepted by some compilers (e.g. GCC) as a non-standard extension, so whether this prints 1 or fails to compile actually depends on the compiler used; deferring to the source's marked answer.", "topic": "C/C++"}, {"id": "pdf2-001", "question": "What will be printed? #include<stdio.h> main(){ char arr[]=\"ab.cd.ef\"; printf(\"%s\",strchr(arr,'.')); }", "options": ["ab", ".cd", ".cd.ef", ".ef"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "strchr(arr,'.') returns a pointer to the first occurrence of '.' in the string, so %s prints everything from that point to the end: \".cd.ef\".", "topic": "C/C++"}, {"id": "pdf2-002", "question": "What will be printed #include<stdio.h> main(){ char arr[5]=\"apple\"; printf(\"%c\",0[arr]); }", "options": ["a. apple", "a", "97", "Error"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "0[arr] is equivalent to arr[0] because array indexing is really pointer arithmetic (*(arr+0) == *(0+arr)), so it just prints the first character, 'a'.", "topic": "C/C++"}, {"id": "pdf2-003", "question": "What type of teams are composed of workers from different functional departments of the organization that meet to solve an important organizational problem?", "options": ["Line teams.", "Cross-functional teams.", "Staff teams.", "Multi-dimensional teams."], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Cross-functional teams pull members from different departments (marketing, engineering, finance, etc.) to tackle a shared organizational problem.", "topic": "Management"}, {"id": "pdf2-004", "question": "What type of computer chips are volatile?", "options": ["RAM chips", "ROM chips", "CDROM", "FLASH MEMORY"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "RAM is volatile memory and loses its contents when power is removed, unlike ROM, CD-ROM, or flash memory which retain data.", "topic": "CAO"}, {"id": "pdf2-005", "question": "What type of encryption is capable of encrypting a fixed-length plaintext block into a 128-bit cipher text block at the same time?", "options": ["Block", "Symmetric", "Hash", "None of the choices"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A block cipher takes a fixed-length plaintext block and produces a fixed-length (e.g., 128-bit) ciphertext block in one operation, as opposed to stream ciphers which process data continuously.", "topic": "Information Security"}, {"id": "pdf2-006", "question": "What type of encryption encrypts the plain text byte by byte or bit by bit?", "options": ["Block", "Hash", "Stream", "Elliptic"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Stream ciphers encrypt plaintext one bit or byte at a time by combining it with a keystream, unlike block ciphers which operate on fixed-size chunks.", "topic": "Information Security"}, {"id": "pdf2-007", "question": "What terms are applied by sociologists to two contrasting pictures of organizations: competing individuals and groups or people acting with common interests?", "options": ["contingent, functional", "pooled, reciprocal", "pluralist, unitary", "co-operative, conflictual"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "In organizational sociology, the \"unitary\" frame views the organization as having shared goals, while the \"pluralist\" frame sees it as competing individuals/groups with different interests.", "topic": "Management"}, {"id": "pdf2-008", "question": "What should you do with someone's personal data once you've finished using it?", "options": ["Pass it on to someone else", "Throw it out.", "Give it back to the owner.", "Securely delete or destroy it."], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Data protection principles (e.g. GDPR's storage limitation) require that personal data no longer needed be securely deleted or destroyed rather than passed on or casually discarded.", "topic": "Privacy & Compliance"}, {"id": "pdf2-009", "question": "What should a project manager do or follow to ensure clear boundaries for project completion?", "options": ["Scope verification", "Completing a scope statement", "scope definition", "Risk management plan"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A completed scope statement formally documents deliverables, exclusions, and constraints, giving the project explicit, agreed-upon boundaries that prevent scope creep.", "topic": "Management"}, {"id": "pdf2-010", "question": "What oracle backup and recovery file contains user and system?", "options": ["Datafile", "Control file", "Online ReDo file", "Redolog file"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Datafiles are the physical files that store actual table/index data for both user and system (e.g. SYSTEM tablespace) data, while control files and redo logs store metadata and change records instead.", "topic": "DBMS"}, {"id": "pdf2-011", "question": "What is {1,2}* intersection {2,3}*", "options": ["{12,2}*", "{23,2}*", "{2}*", "{12,23}*"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "{1,2}* contains strings over symbols 1 and 2, and {2,3}* contains strings over symbols 2 and 3; the only strings possible in both are those made up solely of the shared symbol \"2\", giving {2}*.", "topic": "TOC"}, {"id": "pdf2-012", "question": "What is the value of the postfix expression 6 3 2 4 + - *", "options": ["Something between -15 and -100", "Something between -5 and -15", "Something between 5 and -5", "Something between 5 and 15"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Evaluating 6 3 2 4 + - * : (2+4)=6, then (3-6)=-3, then (6*-3)=-18, which falls in the \"-15 to -100\" range.", "topic": "DSA"}, {"id": "pdf2-013", "question": "What is the status of array after the first iteration of selection sort for the given array of elements:5,7,10,12,2,8", "options": ["5,7,10,12,2,8", "2,5,10,12,7,8", "2,7,10,12,5,8", "5,7,10,2,8,12"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Selection sort finds the minimum of the whole array (2, at index 4) and swaps it with the first element, giving 2,7,10,12,5,8 after the first pass.", "topic": "DSA"}, {"id": "pdf2-014", "question": "What is the result of the following operation? Top (Push (S, X))", "options": ["X", "Null", "S", "None"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Push(S, X) puts X on top of stack S, so Top() immediately after returns X.", "topic": "DSA"}, {"id": "pdf2-015", "question": "What is the real disadvantage of a linear list of directory entries?", "options": ["size of the linear list in memory", "linear search to find a file", "it is not reliable", "all of the mentioned"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A linear (list-based) directory structure requires a linear search through all entries to locate a file, which is slow for large directories.", "topic": "OS"}, {"id": "pdf2-016", "question": "What is the real disadvantage of a linear list of directory entries?", "options": ["size of the linear list in memory", "linear search to find a file", "it is not reliable", "all of the mentioned"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Duplicate of the linear directory question; the disadvantage is the linear search needed to find a file.", "topic": "OS"}, {"id": "pdf2-017", "question": "What is the postfix form of the following prefix * + a b \u2013 c d", "options": ["a b + c d \u2013 *", "a b c + * \u2013", "a b + * c d \u2013", "a b + * c d \u2013"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Converting prefix * + a b \u2013 c d: (+ a b) becomes \"ab+\" and (\u2013 c d) becomes \"cd\u2013\" in postfix, then the outer * is appended last, giving \"ab+cd\u2013*\".", "topic": "DSA"}, {"id": "pdf2-018", "question": "What is the name of the process in which an employee informs another responsible employee in the company about potentially unethical behavior?", "options": ["Whistleblowing", "Purging and releasing", "Identification", "Information transfer"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Whistleblowing is the term for an employee reporting suspected unethical or illegal conduct to someone in a position to act on it.", "topic": "Business Ethics"}, {"id": "pdf2-019", "question": "What is the level of recursion if the input array is { 4, 8, 32, 58,98,129,201 } and key is 8?", "options": ["5", "2", "3", "4"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Binary searching {4,8,32,58,98,129,201} for 8: the first comparison against the middle element 58 sends the search left, and the very next comparison finds 8, so the target is located on the 2nd recursive call.", "topic": "DSA"}, {"id": "pdf2-020", "question": "What is the difference is graph traversal and tree:", "options": ["There can be a loop in the graph", "DFS and BFS are the same", "There can\u2019t be a loop in the graph", "DFS and BFD are different"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Unlike trees, graphs can contain cycles/loops, which is why graph traversal algorithms (DFS/BFS) must track visited nodes to avoid infinite loops.", "topic": "DSA"}, {"id": "pdf2-021", "question": "What is the current industry for the measure of Software Quality?", "options": ["Iterations to Successful Build", "Number of Bugs Fixed", "Number of Defects per KLOC", "None in the list"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Defect density, measured as number of defects per thousand lines of code (KLOC), is the standard industry metric for software quality.", "topic": "Software Engineering"}, {"id": "pdf2-022", "question": "What is the function of HTTP?", "options": ["webserver and browser activity according to command", "Mark-up language", "Forming authority of the page", "Tag files and create effects"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "HTTP is the protocol that governs how a browser requests resources and how a web server responds, i.e. it directs web server/browser communication.", "topic": "CN"}, {"id": "pdf2-023", "question": "What is the complexity of quick sort algorithm, if the array to be sorted is already in sorted order?", "options": ["O(n2)", "O(nlogn)", "Constant", "O(n)"], "correct": 1, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "With a naive pivot choice (first or last element), an already-sorted array produces maximally unbalanced partitions every time, giving quicksort's classic worst case of O(n^2), not O(n log n).", "topic": "DSA"}, {"id": "pdf2-024", "question": "What is split horizon?", "options": ["Information about a route should not be sent back in the direction from which the original update came.", "It splits the traffic when you have a large bus (horizon) physical network.", "It holds the regular updates from broadcasting to a downed link.", "It prevents regular update messages from reinstating a route that has gone down."], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Split horizon is a routing loop-prevention rule stating a router should not advertise a route back out the interface from which it learned that route.", "topic": "CN"}, {"id": "pdf2-025", "question": "What is Cyclomatic complexity ?", "options": ["Black box testing", "White box testing", "Yellow box testing", "Green box testing"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Cyclomatic complexity counts the number of independent paths through source code and is a white-box (structural) testing metric used to guide path coverage testing.", "topic": "Software Engineering"}, {"id": "pdf2-026", "question": "What is Address Binding?", "options": ["going to an address in memory", "locating an address with the help of another address", "binding two addresses together to form a new address in a different memory space", "a mapping from one address space to another"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Address binding is the mapping of instructions/data from one address space (e.g. logical/symbolic) to another (e.g. physical memory), which can happen at compile, load, or execution time.", "topic": "OS"}, {"id": "pdf2-027", "question": "What is a network?", "options": ["A group of 1 or more devices that communicate", "A group of 2 or more devices that communicate", "When 2 or more computers are in the same building", "A group of 3 or more devices that communicate"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A network is defined as two or more devices linked together to communicate and share resources; a single device cannot form a network.", "topic": "CN"}, {"id": "pdf2-028", "question": "What is a Network Protocol", "options": ["Formal standards and policies comprised of memes", "Formal standards and policies", "Formal standards and policies comprised of rules, procedures and formats", "None of the above"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "A network protocol is a formal set of rules, procedures, and data formats that governs how devices exchange information.", "topic": "CN"}, {"id": "pdf2-029", "question": "What is a disadvantage of a star network?", "options": ["It is cheap", "It uses one cable", "It is expensive", "It has a terminator"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "A star topology needs a dedicated cable run from every node to the central hub/switch plus the hub hardware itself, making it more expensive in cabling and equipment than a bus topology.", "topic": "CN"}, {"id": "pdf2-030", "question": "What happens to a task force after it finishes its assignment?", "options": ["It is integrated with the organisation.", "It is disbanded.", "It continues after accomplishment.", "None of the other answers is correct."], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A task force is a temporary cross-functional team formed for a specific purpose, so it is disbanded once that assignment is complete.", "topic": "Management"}, {"id": "pdf2-031", "question": "What does DPIA expand as?", "options": ["Data Privacy Impact Assessment", "Data Protection Impact Assessment", "Data Privacy Identification Assessment", "Data Protection Identification Assessment"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "DPIA stands for Data Protection Impact Assessment, a GDPR-mandated process for identifying and minimizing data protection risks in a project.", "topic": "Privacy & Compliance"}, {"id": "pdf2-032", "question": "What does biometrics have to do with access control?", "options": ["Authorization", "Authentication", "Confirmation", "Certification"], "correct": 2, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "Biometrics (fingerprint, iris, face) verify that a subject is who they claim to be, which is the definition of authentication, not authorization (which governs what an already-authenticated subject may access).", "topic": "Information Security"}, {"id": "pdf2-033", "question": "What are the mid values in each level of recursion in the binary search for the input array { 4, 8, 58,98,129,201 } and key 201?", "options": ["58, 129, 201", "98, 129, 201", "98,201", "58,129,201"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Searching {4,8,58,98,129,201} for 201: mid=index2=58 (201>58, go right), mid=index4=129 (201>129, go right), mid=index5=201 (found) \u2014 so mids are 58, 129, 201.", "topic": "DSA"}, {"id": "pdf2-034", "question": "What are all candidate keys, other than the primary keys called?", "options": ["Partial keys", "Alternate keys", "Superkey keys", "None of these"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Candidate keys not chosen as the primary key are called alternate keys.", "topic": "DBMS"}, {"id": "pdf2-035", "question": "What Access Control paradigm was created to deal primarily with computer system information flow?", "options": ["Lattice-Based", "Integrity Based", "Flow-Based", "Area Based"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Lattice-based access control models (e.g. Bell-LaPadula) use a mathematical lattice of security labels specifically to govern and restrict information flow between subjects and objects.", "topic": "Information Security"}, {"id": "pdf2-036", "question": "What is another way to describe a parent-child relationship?", "options": ["Has-A", "Is-A", "Does-A", "Gets-A"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A parent-child (base-derived) relationship in inheritance is described as an 'Is-A' relationship, e.g. a Dog Is-A Animal.", "topic": "OOPS"}, {"id": "pdf2-037", "question": "Virtual memory technique facilitates sharing of memory among", "options": ["processes", "threads", "instructions", "programs"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Virtual memory allows multiple processes to share physical memory pages (e.g. shared libraries, copy-on-write), so the sharing unit here is processes.", "topic": "OS"}, {"id": "pdf2-038", "question": "Unity of command means:", "options": ["Parity of authority and responsibility", "The flow of command from superior to a subordinate", "Parity in controlling", "None of the above"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "low", "reasoning": "Unity of command precisely means each subordinate should receive orders from only one superior; none of the listed options state this exactly (option 2 describes chain of command instead), so 'None of the above' is the best fit but the question is loosely worded.", "topic": "Management"}, {"id": "pdf2-039", "question": "Unit testing is done by__________________?", "options": ["Users", "Developers", "Customers", "None of the mentioned"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Unit testing is performed by the developers who wrote the code, verifying individual functions/modules in isolation before integration.", "topic": "Software Engineering"}, {"id": "pdf2-040", "question": "Triple Bottom Line reporting refers to:", "options": ["using a low, medium, and high estimates for profitability forecasts.", "measuring the impact of the firm on stockholders, customers, and employees", "measuring the social, environmental, and financial performance of the firm.", "measuring the impact of local, state, and federal governments on the firm."], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "The Triple Bottom Line framework evaluates a firm's performance across three dimensions: social ('people'), environmental ('planet'), and financial ('profit').", "topic": "Business Ethics"}, {"id": "pdf2-041", "question": "Transfer time is ...", "options": ["the time is taken to locate the disk arm to a specified track where the data is to be read or write.", "the time is taken by the desired sector of disk to rotate into a position so that it can access the read/write heads.", "the time to transfer the data.", "the time taken to complete the execution."], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Disk access time breaks into seek time, rotational latency, and transfer time; transfer time specifically is the time needed to actually move the data once the head is positioned.", "topic": "OS"}, {"id": "pdf2-042", "question": "Traits or skills on which leaders differ from non-leaders include:", "options": ["Honesty and integrity", "Self-confidence", "Drive and desire to lead", "All the other options are correct"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Trait theory research identifies multiple traits distinguishing leaders from non-leaders, including honesty/integrity, self-confidence, and drive/desire to lead \u2014 all of the listed traits are correct.", "topic": "Management"}, {"id": "pdf2-043", "question": "Trait theory ignores ________.", "options": ["the physical traits of leaders.", "the aspects of honesty and integrity.", "the interactions of leaders and their group members as well as situational factors.", "the fact that leaders should be able to create visions and solve problems."], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "A key criticism of trait theory is that it focuses solely on innate personal characteristics and ignores situational factors and the dynamic interaction between leaders and followers.", "topic": "Management"}, {"id": "pdf2-044", "question": "Total number of levels in DFD", "options": ["1", "2", "3", "4"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "low", "reasoning": "DFDs are commonly taught as having levels 0 (context), 1, and 2 (three levels), though some texts extend to a level 3, so the 'total' count varies by source \u2014 deferring to the marked answer.", "topic": "Software Engineering"}, {"id": "pdf2-045", "question": "Total Development in programmer months of Utility programs", "options": ["TDEV=2.5xPM pow 0.38", "TDEV=2.5xPM pow0.35", "TDEV=2.5xPM pow0.32", "None of the above"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "In Boehm's COCOMO effort/schedule equations, utility-type (semi-detached mode) programs use the exponent 0.35 in TDEV = 2.5 \u00d7 PM^0.35.", "topic": "Software Engineering"}, {"id": "pdf2-046", "question": "Total Development in programmer months of Systems programs", "options": ["TDEV=2.5xPM pow 0.38", "TDEV=2.5xPM pow0.35", "TDEV=2.5xPM pow0.32", "None of the above"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Systems programs correspond to COCOMO's embedded mode (tightly constrained, complex), which uses the exponent 0.32 in TDEV = 2.5 \u00d7 PM^0.32.", "topic": "Software Engineering"}, {"id": "pdf2-047", "question": "Total bits for a direct-mapped cache with data of 16 KB and blocks of 4-word, assuming a 32-bit address are", "options": ["143K", "144K", "145K", "147K"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "16KB cache / 16B blocks (4 words) = 1024 blocks, needing 4 offset bits + 10 index bits, leaving 18 tag bits; total per block = 128 data + 18 tag + 1 valid = 147 bits, times 1024 blocks = 147 Kbits \u2014 this is the classic Hennessy & Patterson worked example.", "topic": "CAO"}, {"id": "pdf2-048", "question": "To read and write from a file we are using the standard C++ library called", "options": ["Fstream", "stream", "filestream", "None"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The C++ standard library header <fstream> provides ifstream/ofstream/fstream classes for reading and writing files.", "topic": "C/C++"}, {"id": "pdf2-049", "question": "To make a process as Zombie, which process needs to delay (sleep()) its execution? The parent process or the child process?", "options": ["parent to sleep for a while, child normal execution", "child to sleep for a while, parent normal execution", "parent and child both normal execution", "parent and child both to sleep for a while"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A zombie process is a terminated child whose exit status hasn't been reaped yet, so to demonstrate it the parent must sleep() (delay calling wait()) while the child exits normally and quickly.", "topic": "OS"}, {"id": "pdf2-050", "question": "To help the operating system estimate LRU, many processors provide a", "options": ["Use bit", "Reference bit", "Fault bit", "Both a and b"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Hardware provides a single bit per page, set on access, that different OS textbooks call either the 'use bit' or the 'reference bit' interchangeably \u2014 it's the same mechanism used to approximate LRU.", "topic": "OS"}, {"id": "pdf2-051", "question": "To create a dynamic record which is better?", "options": ["Stack", "Queue", "Linked list", "All of these"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "A linked list uses pointer-based dynamic memory allocation, so it can grow or shrink at runtime; stacks and queues are abstract behaviors usually implemented on top of arrays or linked lists rather than being inherently dynamic structures themselves.", "topic": "DSA"}, {"id": "pdf2-052", "question": "To avoid the race condition, the number of processes that may be simultaneously inside their critical section is", "options": ["8", "1", "16", "0"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Mutual exclusion requires that at most one process be allowed inside its critical section at a time; allowing more than one is exactly what causes a race condition.", "topic": "OS"}, {"id": "pdf2-053", "question": "Time Oriented Diagram", "options": ["class Diagram", "UseCase Diagram", "Object Diagram", "Sequence Diagram"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A sequence diagram explicitly lays messages out along a time axis to show the order of interactions between objects, making it the classic time-oriented UML diagram.", "topic": "Software Engineering"}, {"id": "pdf2-054", "question": "Through this principle of management, Henri Fayol guides the managers to exhibit exemplary behaviour and advises that they should not fall into the temptation of misusing their powers for personal benefit at the cost of the general interest of the organization. Which principle of management is being described in the above statement?", "options": ["Remuneration of employees", "Centralization and decentralization", "Subordination of individual interest to general interest", "Equity"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Fayol's 'subordination of individual interest to general interest' principle says managers must put organizational goals ahead of personal gain, which matches the warning against misusing power for personal benefit.", "topic": "Management"}, {"id": "pdf2-055", "question": "Threat to confidentiality is .....", "options": ["DDoS", "Malware", "Virus", "DoS"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Malware such as spyware or trojans is designed to steal or expose sensitive data, making it a confidentiality threat, whereas DoS/DDoS attacks target availability, not confidentiality.", "topic": "Information Security"}, {"id": "pdf2-056", "question": "Thomas Tharakan expects his employees to \"check their brains at the door.\" He does all the thinking, makes all the decisions, and issues commands to his subordinates. Thomas uses the ________style of leadership.", "options": ["autocratic", "authoritarian", "democratic", "laissez-faire"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A manager who makes every decision alone and simply issues commands, without any input from subordinates, is the textbook description of autocratic leadership.", "topic": "Management"}, {"id": "pdf2-057", "question": "This technique of scientific management helps in the development of the concept of the assembly line, which is widely used in automobile companies these days as well. Identify the technique.", "options": ["Motion study", "Standardization and simplification of work", "Method study", "Time study"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Method study (systematically examining and redesigning how a job is done to find the most efficient sequence of steps) is the scientific-management technique credited with shaping the assembly-line concept.", "topic": "Management"}, {"id": "pdf2-058", "question": "This code would work but is bad practice because", "options": ["The object attribute is changed by a method", "The object attribute is being changed directly through mainline code (outside of the class/object itself)", "There is no object being created", "The principle of encapsulation has been ignored"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "low", "reasoning": "The chunk doesn't include the actual code snippet being referenced, so it's not possible to independently confirm whether 'encapsulation ignored' or the more specific 'attribute changed directly outside the class' is the intended distinction; deferring to the source's marked answer.", "topic": "OOPS"}, {"id": "pdf2-059", "question": "There exists a language L. We define a string w such that w belongs to L and w=pqr and |w| >=n for some constant integer n.What can be the maximum length of the substring pq i.e. |pq|<=?", "options": ["n", "|p|", "|q|", "|w|n"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The pumping lemma guarantees that any sufficiently long string w=pqr in the language can be split so that the pumped portion pq lies within the first n characters, i.e. |pq| <= n.", "topic": "TOC"}, {"id": "pdf2-060", "question": "There are two abilities that you must have to properly understand ethics. The first is the \u2026\u2026\u2026\u2026\u2026\u2026\u2026\u2026. and the second ability is \u2026\u2026\u2026\u2026\u2026\u2026\u2026\u2026\u2026\u2026.", "options": ["ability to discern; concentration", "ability to visualize; devotion", "ability to distinguish; dedication", "ability to judge; dedication"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Understanding ethics requires both the ability to distinguish right from wrong and the dedication (moral commitment) to actually act on that distinction.", "topic": "Business Ethics"}, {"id": "pdf2-061", "question": "There are ____ type\u2019s specializations. They are full specialization and partial specialization", "options": ["1", "2", "3", "4"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The question itself names exactly two kinds of specialization -- full and partial -- so the blank is simply 2.", "topic": "DBMS"}, {"id": "pdf2-062", "question": "Theodore New-Comb\u2019s balance theory is related to", "options": ["Leadership", "Group formation", "Selection", "Retirement"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "medium", "reasoning": "Newcomb's balance theory describes how people with similar attitudes are drawn together to maintain psychological balance in their relationships, which is the mechanism behind informal group formation.", "topic": "Management"}, {"id": "pdf2-063", "question": "The word ______ refers to the portion of a _______ that carries a transmission.", "options": ["line; channel", "channel; link", "link; channel", "line; link"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "In standard networking terminology a channel is the portion of a physical link that carries one transmission, while the link is the entire physical transmission medium connecting two points.", "topic": "CN"}, {"id": "pdf2-064", "question": "The way the work activities and the departments are organised is called", "options": ["chain of command.", "span of control.", "unity of direction.", "esprit de corps."], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "None of the four listed terms is a perfect match for 'how work activities and departments are organized' (the precise textbook term is organizational structure); the question is ambiguously worded, so the source's marked answer is kept.", "topic": "Management"}, {"id": "pdf2-065", "question": "The view that sees profit maximization as the main objective is known as:", "options": ["Shareholder theory", "Principal-agent problem", "Stakeholder theory", "Corporation theory"], "correct": 1, "original_marked": 3, "matches_original": false, "confidence": "high", "reasoning": "Shareholder theory (the Friedman doctrine) is the view that a firm's primary duty is to maximize profit/shareholder returns; stakeholder theory is the opposing view that a firm should balance the interests of employees, customers, and the community alongside profit, so it is not the 'profit maximization is the main objective' view.", "topic": "Business Ethics"}, {"id": "pdf2-066", "question": "The VFS (virtual file system) activates file system-specific operations to handle local requests according to their _____", "options": ["size", "commands", "timings", "file system types"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "The VFS layer routes each request to the operations implemented by the specific underlying file system type (ext4, NFS, FAT, etc.) that is mounted at that location.", "topic": "OS"}, {"id": "pdf2-067", "question": "The Unix system call to get the size of a page is _________.", "options": ["pagesize()", "getpagesize()", "pagesizeof()", "sizeof()"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "getpagesize() is the standard Unix/POSIX system call that returns the size, in bytes, of a memory page on the system.", "topic": "OS"}, {"id": "pdf2-068", "question": "The University of Michigan studies used the two dimensions of ________ and ________ to study behavioural characteristics of leaders.", "options": ["employee oriented; production oriented", "consideration; initiating structure", "task; people", "decision-making; employee development"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The University of Michigan leadership studies identified employee-oriented and production-oriented as the two key behavioral dimensions of leaders; consideration/initiating structure is the corresponding pair from the (different) Ohio State studies.", "topic": "Management"}, {"id": "pdf2-069", "question": "The universal Turing machine U consists of", "options": ["1 input tape", "2 input tape", "3 input tape", "4 input tape"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "Textbook constructions of a universal Turing machine differ -- some use a single tape holding the encoded machine and input together, others use multiple tapes for simulation -- so without knowing the exact construction taught in this course, the source's marked answer is kept.", "topic": "TOC"}, {"id": "pdf2-070", "question": "The underlying technology on which the system is built is superseded by new technology is the __________ type of risk", "options": ["Project", "Product", "Business", "None in the list"], "correct": 3, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "In standard software risk classification (e.g. Sommerville's Software Engineering), 'the underlying technology on which the system is built is superseded by new technology' is a classic example of a business risk (technology-change risk), not a product risk.", "topic": "Software Engineering"}, {"id": "pdf2-071", "question": "The two major benefits are improvement in performance and minimization of cost to process the system", "options": ["True", "False"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "The statement is generic and lacks context about which system/technique it refers to, but claiming a technique improves performance while lowering processing cost is a plausible and commonly-true statement in this exam's source material, so it is kept as True.", "topic": "DBMS"}, {"id": "pdf2-072", "question": "The transformational leadership style", "options": ["encourages group members to transform themselves into better people.", "strives to change the group members' opinions by showing them a better way to think.", "changes opinions and attitudes without changing behaviours.", "encourages and inspires group members to go above and beyond selfish interests and do what is best for the common good of the group."], "correct": 4, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "Transformational leadership is defined as inspiring followers to rise above their own self-interest and work toward the common good of the group/organization, not merely changing their opinions by presenting a 'better way to think.'", "topic": "Management"}, {"id": "pdf2-073", "question": "The total number of states required to automate the given regular expression (aa)*(bb)*", "options": ["4", "3", "5", "7"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "The minimal DFA for (aa)*(bb)* needs states tracking the parity of a's seen before any b, the parity of b's seen after switching, plus one trap state for invalid symbols -- 5 states in total.", "topic": "TOC"}, {"id": "pdf2-074", "question": "The three major methods of allocating disk space that are in wide use are _____________", "options": ["contiguous", "linked", "indexed", "all of the mentioned"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Contiguous, linked, and indexed allocation are the three classic disk-space allocation schemes covered in every OS textbook, so 'all of the mentioned' is correct.", "topic": "OS"}, {"id": "pdf2-075", "question": "The technology is used to analyze and monitor network and information flow traffic_________", "options": ["Cloud access security brokers (CASBs)", "Managed detection and response (MDR)", "Network Security Firewall", "Network traffic analysis (NTA)"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Network Traffic Analysis (NTA) tools are specifically built to monitor and analyze network and information-flow traffic for anomalies, distinguishing them from broader tools like firewalls, CASBs, or MDR.", "topic": "Information Security"}, {"id": "pdf2-076", "question": "The technique of storing the previously calculated values is called?", "options": ["Saving value property", "Storing value property", "Memoization", "Mapping"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Memoization is the technique of caching results of expensive function calls so they can be reused instead of recomputed.", "topic": "DSA"}, {"id": "pdf2-077", "question": "The syntax for catching all exceptions in a program is \u2026\u2026\u2026\u2026.", "options": ["catch-all(\u2026) { }", "catchall(\u2026){ }", "catch(\u2026) { }", "catch(.){ }"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "In C++, catch(...) with an ellipsis is the catch-all handler that matches any exception type thrown in the try block.", "topic": "C/C++"}, {"id": "pdf2-078", "question": "he sum of the degrees of all vertices in an undirected graph", "options": ["2V", "E+1", "V+1", "2E"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "By the handshaking lemma, every edge contributes 2 to the total degree count (one to each endpoint), so the sum of all vertex degrees equals 2E.", "topic": "DSA"}, {"id": "pdf2-079", "question": "The subtraction of hit rate (1-hit rate) is known as", "options": ["Hit time", "Miss penalty", "Miss rate", "Cache"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Miss rate is defined as 1 minus the hit rate, i.e., the fraction of memory accesses that are not found in cache.", "topic": "CAO"}, {"id": "pdf2-080", "question": "The structure or format of data is called ___________", "options": ["Syntax", "Semantics", "Struct", "Formatting"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Syntax refers to the structural/formal rules governing how data or language constructs are arranged, as opposed to semantics which concerns meaning.", "topic": "TOC"}, {"id": "pdf2-081", "question": "The stress which is negative in nature and causes mental and physical problems is known as", "options": ["Eustress", "Distress", "Negative stress", "Permanent stress"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Distress is the negative form of stress that impairs performance and causes physical/mental harm, the opposite of positive 'eustress'.", "topic": "Management"}, {"id": "pdf2-082", "question": "The stress that exists for weeks, months, or even years is called", "options": ["Chronic stress", "Acute stress", "Negative stress", "Permanent stress"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Chronic stress is long-term stress that persists for weeks, months, or years, as opposed to acute stress which is short-lived.", "topic": "Management"}, {"id": "pdf2-083", "question": "The software cost estimation is done in stages as", "options": ["Basic COCOMO", "Intermediate COCOMO", "A and B", "None of the above"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Software cost estimation using COCOMO is carried out progressively through multiple stages, including Basic and Intermediate COCOMO, so 'both of the above' reflects that staged nature.", "topic": "Software Engineering"}, {"id": "pdf2-084", "question": "The single and multi-variable estimation models at different stages of estimation is performed by", "options": ["Halstead", "FP", "COCOMO", "None of the above"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "COCOMO provides single-variable (Basic) and multi-variable (Intermediate/Detailed) estimation models applied at different stages of a project's lifecycle.", "topic": "Software Engineering"}, {"id": "pdf2-085", "question": "The set of all strings over the alphabet {p,q} (including epsilon} is denoted by", "options": ["(q+p)*", "(q+p)^+", "p^+q^+", "p*q*"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The Kleene star (*) applied to an alphabet generates every possible string over it, including the empty string (epsilon), so (p+q)* is correct.", "topic": "TOC"}, {"id": "pdf2-086", "question": "The set of all strings over the alphabet {a,b} (including epsilon} is denoted by", "options": ["(a+b)^+", "a^+b^+", "a*b*", "(a+b)*"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "(a+b)* denotes the Kleene closure, which includes the empty string, unlike (a+b)+ which excludes epsilon.", "topic": "TOC"}, {"id": "pdf2-087", "question": "The semi-detached software is", "options": ["Development of the GUI", "Database module", "Networking Module", "None of the above"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Boehm's COCOMO semi-detached mode is classically illustrated by medium-complexity utility software such as compilers, editors, and database management systems.", "topic": "Software Engineering"}, {"id": "pdf2-088", "question": "The Scalar principle of organisation implies", "options": ["All authority must be vested to one person", "Manager should directly supervise only a limited number of subordinates", "Line of authority must be clearly defined", "A subordinate should have only one supervisor"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "The Scalar principle (chain of command) states that a clear, unbroken line of authority should run from the top of an organization down to the bottom.", "topic": "Management"}, {"id": "pdf2-089", "question": "The result of evaluating the prefix expression */b+-dacd, where a=3, b=6, c=1, d=5 is", "options": ["0", "5", "10", "15"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Evaluating right to left: (d-a)=2, (2+c)=3, (b/3)=2, then (2*d)=10 \u2014 so the prefix expression evaluates to 10.", "topic": "DSA"}, {"id": "pdf2-090", "question": "The recognizing capabilities of NDFSM and DFSM", "options": ["must be same", "may be different", "must be different", "none of the answers given"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "By the Rabin-Scott subset construction theorem, non-deterministic and deterministic finite state machines have equivalent recognizing power \u2014 both accept exactly the regular languages.", "topic": "TOC"}, {"id": "pdf2-091", "question": "The purpose of cache memory in a computer is to", "options": ["ensure fast booting", "reduce load on CPU registers", "Dya replace static memory", "speed up memory cycle time"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Cache memory sits between the CPU and main memory to reduce effective access latency, effectively speeding up the memory cycle time seen by the CPU.", "topic": "CAO"}, {"id": "pdf2-092", "question": "The project plan sets out", "options": ["the resources available to the project", "the work breakdown", "a schedule for the work", "all the above"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A project plan is a comprehensive document covering available resources, the work breakdown structure, and the schedule for the work \u2014 all of the listed items.", "topic": "Software Engineering"}, {"id": "pdf2-093", "question": "The process-related to process control, file management, device management, information about system and communication that is requested by any higher level language can be performed by __________", "options": ["Editors", "Compilers", "System Call", "Caching"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "System calls are the interface through which a program requests OS services such as process control, file and device management, and communication.", "topic": "OS"}, {"id": "pdf2-094", "question": "The process of planning starts with clearly laying down of_______________________.", "options": ["Policies", "Procedures", "Goals and Objectives", "All of the Above"], "correct": 3, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "Classical management theory holds that the planning process begins with clearly establishing goals and objectives, which then guide the policies and procedures that follow \u2014 not the other way around.", "topic": "Management"}, {"id": "pdf2-095", "question": "The process of perceiving the causes of behavior and outcomes is termed as", "options": ["Perception", "Stereotype", "Attribution", "Personality"], "correct": 3, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "This describes attribution theory \u2014 the process of inferring the causes behind others' behavior and outcomes \u2014 whereas perception is the broader process of organizing sensory input in general.", "topic": "Management"}, {"id": "pdf2-096", "question": "The process of accessing data stored in a serial access memory is similar to manipulating data on a ________", "options": ["Heap", "Binary Tree", "Array", "Stack"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Serial/sequential access memory requires accessing elements in order from one end, analogous to how a stack can only be accessed from its top (LIFO).", "topic": "DSA"}, {"id": "pdf2-097", "question": "The process model that represents a way of thinking that allows businesses and team members to quickly innovate and respond to the dynamic demands of an Organization is", "options": ["Waterfall Model", "Incremental Model", "RAD Model", "Agile Model"], "correct": 4, "original_marked": 3, "matches_original": false, "confidence": "high", "reasoning": "This is the standard definition of the Agile model \u2014 a mindset enabling teams to rapidly innovate and respond to changing business demands \u2014 not RAD, which is a specific rapid-prototyping development technique.", "topic": "Software Engineering"}, {"id": "pdf2-098", "question": "he process by which an individual gives meaning to the environment is called", "options": ["Perception", "Stereotype", "Attribution", "Personality"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Perception is formally defined as the process by which individuals organize and interpret sensory input to give meaning to their environment.", "topic": "Management"}, {"id": "pdf2-099", "question": "The primary or first component of DFD is known as", "options": ["Process", "Data", "Square", "Entity"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The process (drawn as a circle/bubble) is considered the primary component of a DFD since it represents the core data transformation being modeled.", "topic": "Software Engineering"}, {"id": "pdf2-100", "question": "The postfix form of A*B+C/D is?", "options": ["*AB/CD+", "AB*CD/+", "A*BC+/D", "ABCD+/*"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Converting A*B+C/D to postfix: A*B becomes AB*, C/D becomes CD/, and combining them with + last gives AB*CD/+.", "topic": "DSA"}, {"id": "pdf2-101", "question": "The postfix form of A*B+C/D is", "options": ["*AB/CD+", "AB*CD/+", "A*BC+/D", "ABCD+/*"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A*B+C/D parses as (A*B)+(C/D) by operator precedence; converting each sub-expression to postfix and keeping + last gives AB*CD/+.", "topic": "DSA"}, {"id": "pdf2-102", "question": "The policy for memory hierarchies: L1 data are never found in an L2 cache, refers to", "options": ["Write buffer", "Multilevel exclusion", "Write-through", "Multilevel inclusion"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Multilevel exclusion means data in L1 is guaranteed not to also be in L2 (the opposite of inclusion, where L2 always holds a superset of L1's data).", "topic": "CAO"}, {"id": "pdf2-103", "question": "The pager is concerned with the", "options": ["individual page of a process", "entire process", "entire thread", "first page of a process"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A pager handles individual pages being swapped in/out, unlike a swapper which moves entire processes between memory and disk.", "topic": "OS"}, {"id": "pdf2-104", "question": "The page table contains", "options": ["base address of each page in physical memory", "page offset", "page size", "displacement"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Each page table entry maps a virtual page to the base (frame) address of that page in physical memory.", "topic": "OS"}, {"id": "pdf2-105", "question": "The page replacement algorithm that suffers highly from Belady's anamoly is", "options": ["Least Recently Used", "Most Frequently Used", "First In First Out", "Least Frequently Used"], "correct": 3, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "Belady's anomaly (more frames causing more page faults) is a classic weakness of FIFO; LRU is a stack algorithm and is provably immune to it, so the PDF's marked answer (LRU) is incorrect.", "topic": "OS"}, {"id": "pdf2-106", "question": "The output of the requirement analysis and the requirement specification is used as the input for writing ____________", "options": ["User Acceptance Test Cases", "User Rejection Test Cases", "Product Rejection Test Cases", "Product Acceptance Test Cases"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Requirements and specifications define what the system must do, which is directly used to write User Acceptance Test Cases that verify the delivered product meets those requirements.", "topic": "Software Engineering"}, {"id": "pdf2-107", "question": "The output of the below program will be #include #include main(){ char Be[16]=\"Positive\"; char Positive[16]=\"Be \"; printf(\"%s\", strcpy(Positive, strcat(Positive,Be))); }", "options": ["a. Be Positive", "a. Positive Be", "a. Positive Positive Be", "a. Be Be Positive"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "strcat(Positive, Be) appends \"Positive\" (from Be) onto \"Be \" (from Positive), producing \"Be Positive\"; strcpy then just copies that same string back into Positive, so the printed output is \"Be Positive\".", "topic": "C/C++"}, {"id": "pdf2-108", "question": "The operation for adding an entry to a stack is traditionally called :", "options": ["add", "append", "insert", "push"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Adding an element to the top of a stack is universally called a push operation, paired with pop for removal.", "topic": "DSA"}, {"id": "pdf2-109", "question": "The objective of this technique of scientific management is to reduce a given line or a product to fixed type sizes and characteristics. Name the technique.", "options": ["Method study", "Differential piece wage system", "Standardization and simplification of work", "Functional foremanship"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Standardization and simplification of work is the scientific-management technique aimed at reducing products/parts to fixed, uniform types and sizes to cut waste and variety.", "topic": "Management"}, {"id": "pdf2-110", "question": "The number of states in DFA is --------than the number of states in NFA for the same Language.", "options": ["greater equal", "less", "Greater", "equal"], "correct": 1, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "Via subset construction, an NFA with n states converts to a DFA with at most 2^n states, so a DFA for the same language always has a number of states greater than or equal to the NFA's \u2014 the PDF's marked answer (\"less\") is incorrect.", "topic": "TOC"}, {"id": "pdf2-111", "question": "The number of states in a machine M recognizing L1UL2 will be __________________ where n is the number of states in M1 and m is the number of states in M2 .", "options": ["m+n", "m-n", "m+n+1", "n-m"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "The standard construction for the union of two NFAs adds one new start state connected by epsilon-transitions to both machines' start states, giving m+n+1 states.", "topic": "TOC"}, {"id": "pdf2-112", "question": "The number of comparisons required in the Linear search algorithm, if the search element is not present in the array,", "options": ["n+1", "n", "(n+ 1)/ 2", "n-1"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "If the target isn't in the array, linear search must check every one of the n elements before concluding it's absent.", "topic": "DSA"}, {"id": "pdf2-113", "question": "The number of auxiliary memory required for a Push Down Machine (PDM) to behave like a Finite State Machine (FSM) is", "options": ["1", "4", "0", "2"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "A pushdown automaton reduces to a plain finite state machine when it makes no use of its stack, i.e. zero auxiliary memory.", "topic": "TOC"}, {"id": "pdf2-114", "question": "The necessity of cost-benefit analysis in PM is to have a systemic approach to identify the pluses and minuses of various paths through a project", "options": ["True", "False"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Cost-benefit analysis in project management is precisely a systematic way to weigh the advantages and disadvantages of alternative project paths before choosing one.", "topic": "Management"}, {"id": "pdf2-115", "question": "The model in which environmental, social, and economic responsibilities are satisfied concurrently is known as ________.", "options": ["corporate social responsibility", "global activism", "giving back to the planet", "restoration and revivification"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Corporate social responsibility (CSR) is the standard management term for simultaneously addressing environmental, social, and economic obligations, often described as the triple bottom line.", "topic": "Business Ethics"}, {"id": "pdf2-116", "question": "The MMU is a", "options": ["Hardwar e", "Software", "Malware", "None of the given choices"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The Memory Management Unit (MMU) is a physical hardware component that translates virtual addresses to physical addresses.", "topic": "OS"}, {"id": "pdf2-117", "question": "The minimum number of transitions to pass to reach the final state as per the following regular expression is: {0,1}*{1000}", "options": ["4", "3", "5", "7"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The shortest string accepted by {0,1}*{1000} is simply \"1000\" (taking zero repetitions of {0,1}*), which requires 4 transitions to reach the final state.", "topic": "TOC"}, {"id": "pdf2-118", "question": "The minimum number of colors needed to color a graph having n (>3) vertices and 2 edges is", "options": ["1", "2", "3", "4"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "With only 2 edges among n>3 vertices, no odd cycle (triangle) can exist, so the graph is bipartite and just 2 colors suffice (and at least 2 are needed since an edge exists).", "topic": "DSA"}, {"id": "pdf2-119", "question": "The minimum length for strings in the regular expression ( ba* + aab* )* is_________", "options": ["2", "0", "1", "infinite"], "correct": 2, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "The outer Kleene star (...)* always allows zero repetitions, so the empty string is in the language, making the minimum string length 0, not 2 \u2014 the PDF's marked answer is incorrect.", "topic": "TOC"}, {"id": "pdf2-120", "question": "The minimum standards of ethical behaviour in a firm are based on ________, while higher standards are established by ________.", "options": ["corporate policies; human resources", "co-workers; mission statements", "organizational culture; laws", "laws; corporate leadership"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Laws set the legally-mandated floor for ethical conduct, while it's corporate leadership (through culture, policy, and example) that pushes a firm's standards above that legal minimum.", "topic": "Business Ethics"}, {"id": "pdf2-121", "question": "The maximum distance between two nodes present in the stack is 1 in the implementation of DFS. (length/edge= 1)", "options": ["True", "False"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "An iterative DFS stack can hold nodes from many different depths at once (e.g. unexplored siblings from a shallow level alongside nodes several levels deeper), so the claim that distance between any two stack nodes is always 1 is false.", "topic": "DSA"}, {"id": "pdf2-122", "question": "The maximum distance between two nodes present in the queue is 1 in the implementation of BFS. (length/edge= 1)", "options": ["True", "False"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "BFS processes the graph level by level, so at any moment the queue only ever contains nodes from two consecutive levels, meaning any two nodes in it differ in distance from the source by at most 1.", "topic": "DSA"}, {"id": "pdf2-123", "question": "The matrix structure is the correct structure when three conditions are met. Which of the following is one of these three conditions?", "options": ["Pressure exists to share scarce resources across product lines.", "Technical quality is not very important.", "The environmental domain of the organization is simple.", "The environmental domain of the organization is certain and stable."], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A matrix structure is used when scarce resources (like specialized staff) must be shared across multiple product lines, alongside dual pressures and a complex, uncertain environment requiring high coordination.", "topic": "Management"}, {"id": "pdf2-124", "question": "The management of business activities that is conducted in more than one country is called:", "options": ["domestic management.", "altruistic management.", "comparative management.", "international management."], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Managing business activities across more than one country is by definition international management (as distinct from domestic or comparative management).", "topic": "Management"}, {"id": "pdf2-125", "question": "The logical file system maintains structures consisting of information about a file...", "options": ["Program counter", "file control block", "Process control block", "file pointer"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The logical file system maintains the file control block (FCB), which stores metadata such as permissions, size, and location for each file.", "topic": "OS"}, {"id": "pdf2-126", "question": "The lexical analysis for a modern language such as Java needs the power of which one of the following machine models in a necessary and sufficient sense?", "options": ["Finite state automata", "Non-deterministic pushdown automata", "Deterministic pushdown automata", "Turing machine"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Tokens in languages like Java are specified by regular expressions, and finite automata recognize exactly the regular languages \u2014 no more power is needed and no less would suffice.", "topic": "TOC"}, {"id": "pdf2-127", "question": "The Lattice-Based Access Control paradigm was created primarily to address _____.", "options": ["Affinity", "Availability", "Confidentiality", "Integrity"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Lattice-based access control grew out of 1970s military security models (e.g. Bell-LaPadula style classification levels) built specifically to enforce confidentiality of information.", "topic": "Information Security"}, {"id": "pdf2-128", "question": "The language defined by S-->SS is", "options": ["2 l", "2l +1", "2l-1", "Null/\u0190"], "correct": 1, "original_marked": 1, "matches_original": false, "confidence": "low", "reasoning": "The question text is truncated/garbled \u2014 a bare production S-->SS doesn't define a complete language on its own, and the answer options (2^l style counts) suggest this belongs with a missing terminal-producing rule, so the intended answer can't be reconstructed reliably; deferring to the source's marking.", "topic": "TOC"}, {"id": "pdf2-129", "question": "The Knapsack problem where the objective function is to minimize the profit is __", "options": ["Greedy", "Dynamic 0 / 1", "Backtracking", "Branch & Bound 0/1"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "medium", "reasoning": "When the 0/1 knapsack objective is flipped to minimization, it's typically solved with (Least-Cost) Branch & Bound, which prunes the search tree using a cost bound; plain greedy and DP target the standard maximization form.", "topic": "DSA"}, {"id": "pdf2-130", "question": "The intersection of CFL and regular language", "options": ["Is always regular and context free", "Is always regular", "Need not be regular", "IS always context free"], "correct": 4, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "Context-free languages are closed under intersection with a regular language, so the result is always context-free \u2014 but it need not be regular (e.g. intersecting the non-regular CFL {a^n b^n} with \u03a3* still gives a non-regular language), so option 1 overstates the guarantee.", "topic": "TOC"}, {"id": "pdf2-131", "question": "The interactive transmission of data within a time sharing system may be best suited to", "options": ["simplex lines", "half-duplex lines", "full duplex lines", "diplex-lines"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Interactive terminal sessions in time-sharing systems send short bursts in alternating directions (type, then wait for the response), which classic data-communications texts identify as best suited to half-duplex lines.", "topic": "CN"}, {"id": "pdf2-132", "question": "The instruct Kernel to do various operations of the calling program and exchange data between the Kernel at the program", "options": ["Shell", "Editors", "System Calls", "Commands"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "System calls are the defined interface a user program uses to request kernel services and exchange data with the kernel.", "topic": "OS"}, {"id": "pdf2-133", "question": "The initial array elements are 1,7,5,2 after which the following operation are performed enqueue(6), enqueue(8), dequeue, dequeue, enqueue(9), enqueue(0). what are the final elements of the array?", "options": ["1,7,5,2,9,0", "1,7,5,2,6,8", "5,2,6,8,9,0", "5,2,9,0,6,8"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Starting from 1,7,5,2 and applying the operations in order (enqueue 6,8 -> 1,7,5,2,6,8; dequeue twice removes 1 then 7 -> 5,2,6,8; enqueue 9,0) leaves the queue as 5,2,6,8,9,0.", "topic": "DSA"}, {"id": "pdf2-134", "question": "The implied, enforced, or felt obligation of managers, acting in their official capacities, to serve or protect the interests of groups other than themselves is known as ________.", "options": ["human resource ethics", "environmen tal morality", "corporate social responsibility", "business-centre d morality"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "This is the standard definition of corporate social responsibility \u2014 managers' felt duty to serve interests beyond their own or the firm's narrow interests.", "topic": "Business Ethics"}, {"id": "pdf2-135", "question": "The idea of developing an initial implementation, getting the user feedback, and evolving it through various versions until an acceptable system is made is", "options": ["Agile Process Model", "Waterfall Process Model", "Incremental Process Model", "RAD Process Model"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Building an initial version, collecting user feedback, and refining it through successive releases until it's acceptable is the defining idea of the Incremental Process Model.", "topic": "Software Engineering"}, {"id": "pdf2-136", "question": "The group development stage described as \"Deforming and Mourning\" is", "options": ["Storming", "Norming", "Performing", "Adjourning"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "In Tuckman's group development model, the final 'Adjourning' stage is also called deforming and mourning because the group disbands and members experience a sense of loss.", "topic": "Management"}, {"id": "pdf2-137", "question": "The garbage can model is related to", "options": ["Leadership", "Learning", "Decision making", "Recruitment"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "The garbage can model (Cohen, March & Olsen) describes organizational choice/decision-making as a somewhat chaotic mixing of problems, solutions, participants, and choice opportunities.", "topic": "Management"}, {"id": "pdf2-138", "question": "The fundamental activity of a process arranged in a linear order of software development paradigm is", "options": ["Spiral model", "Big Bang model", "V-model", "Waterfall model"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A strictly linear, sequential arrangement of development activities (requirements -> design -> implementation -> testing -> maintenance) is exactly the Waterfall model.", "topic": "Software Engineering"}, {"id": "pdf2-139", "question": "The following graph, which is not a topological ordering of the following graph", "options": ["123456", "132456", "324165", "324156"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "low", "reasoning": "This question includes a diagram \u2014 see the image above and verify the answer visually; not independently fact-checked.", "topic": "DSA", "diagram": "pdf2_p35_y368.png"}, {"id": "pdf2-140", "question": "The following is not a type of organisation structure.", "options": ["Line organis ation", "Staff organisation", "Matrix organisation", "Flexible organisation"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Line, staff, and matrix are all standard, named organization structure types; 'flexible organisation' is not a recognized formal structure category in management theory.", "topic": "Management"}, {"id": "pdf2-141", "question": "The five items: A, B, C, D and E are pushed in the stack, one after the other starting from A. The stack is popped into four items and each element is inserted in a queue. Then two elements are deleted from the queue and pushed back on the stack. Now one item is popped from the stack. The popped item is.", "options": ["A", "B", "C", "D"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Tracing it through: stack A,B,C,D,E (E on top) pops 4 as E,D,C,B into a queue; dequeuing 2 removes E then D; pushing those back (E then D) onto the remaining stack [A] gives A,E,D with D on top, so the next pop yields D.", "topic": "DSA"}, {"id": "pdf2-142", "question": "The file-position pointer is ___ value that specifies the location in the file as a number of bytes from the file's starting location", "options": ["Interger", "Float", "Null", "None"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The file-position pointer is stored as an integer byte offset from the start of the file, used by read/write calls to track the current position.", "topic": "OS"}, {"id": "pdf2-143", "question": "the file system allows the same system call interface (the API) to be used for different types of file systems.", "options": ["NTFS", "EXT2", "VFS(virtual file system)", "DOS"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "The Virtual File System (VFS) provides a uniform system-call interface so the OS can support NTFS, EXT2, DOS FAT, etc. through one common API.", "topic": "OS"}, {"id": "pdf2-144", "question": "The extent to which a leader lets followers make decisions themselves rather than making the decisions for them are focused on by _______________ leadership styles.", "options": ["Laissez-faire and general", "Participative and autocratic", "Employee-ori ented and job-centred", "Laissez-faire and close"], "correct": 2, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "The dimension of 'how much decision-making authority a leader hands to followers' is precisely the autocratic-versus-participative continuum in leadership theory; 'laissez-faire and general' is not the standard paired terminology for that specific dimension.", "topic": "Management"}, {"id": "pdf2-145", "question": "The execution when it finds the solution otherwise starts the problem from the top", "options": ["Backtracking", "Divide and conquer", "Branch and Bound", "Dynamic programming"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Backtracking explores a path, and if it doesn't find a solution it undoes the choice and restarts exploration from an earlier point, matching this description.", "topic": "DSA"}, {"id": "pdf2-146", "question": "The Epsilon-Closure of any state q will contain the state ______________ irrespective of q.", "options": ["Epsilon", "q", "Final state", "p"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "By definition the epsilon-closure of a state always includes the state itself, since a state can reach itself via zero epsilon transitions.", "topic": "TOC"}, {"id": "pdf2-147", "question": "The entity that has a primary key is", "options": ["weak entity", "Full Entity", "Complete Entity", "Strong Entity"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A strong entity has its own primary key that uniquely identifies its instances; a weak entity lacks one and depends on a related strong entity's key instead.", "topic": "DBMS"}, {"id": "pdf2-148", "question": "The encryption methodology is used in .", "options": ["IDS", "Firewall", "Host", "VPN"], "correct": 4, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "A VPN is defined by its use of encryption to build a secure tunnel over an untrusted network; firewalls primarily do packet filtering and access control rather than encrypting traffic.", "topic": "Information Security"}, {"id": "pdf2-149", "question": "The employees should be rewarded for their suggestions which results in a substantial reduction in the cost. Which principle of management advocates this?", "options": ["Science, not the rule of thumb", "Co-operation, not individualism", "Harmony, not discord", "Science, not art"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Taylor's 'Cooperation, not individualism' principle holds that management and workers should share the gains from efficiency improvements, which supports rewarding employees for cost-saving suggestions.", "topic": "Management"}, {"id": "pdf2-150", "question": "The element of role identity which describes how others believe one should behave in a given situation.", "options": ["Role perception", "Role expectation", "Role identification", "Role description"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Role expectation is the part of role identity concerning how others believe a person should behave in a given situation, distinct from role perception (how the person themselves sees it).", "topic": "Management"}, {"id": "pdf2-151", "question": "The element of role identity which describes how an individual is expected to behave according to his own perception in the group is called", "options": ["Role perception", "Role expectation", "Role identification", "Role description"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Role perception is how a person believes they are expected to act in a given situation, based on their own interpretation \u2014 as opposed to role expectation, which is how others believe they should act.", "topic": "Management"}, {"id": "pdf2-152", "question": "The divisional structure has a special feature of __________________.", "options": ["flexibility.", "reliabilty.", "both flexibility and reliability.", "change."], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Divisional structures are organized around products, markets, or regions, which lets each division adapt quickly to its own environment \u2014 flexibility is the classic advantage taught for this structure.", "topic": "Management"}, {"id": "pdf2-153", "question": "The Directors\u2019 responsibilities are unlikely to include.", "options": ["a fiduciary duty", "a duty to keep proper accounting records", "a duty to propose high dividends for shareholders", "A. a duty of care"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Directors owe a fiduciary duty, a duty of care, and a duty to keep proper accounting records, but they are not obligated to propose high dividends \u2014 dividend policy depends on the company's actual financial position and retained-earnings needs.", "topic": "Business Ethics"}, {"id": "pdf2-154", "question": "The device used to identify fast-spreading threats is ...", "options": ["IDS", "IPS", "Firewall", "VPN"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "An Intrusion Detection System (IDS) monitors network traffic and flags/identifies suspicious or fast-spreading threats, whereas an IPS actively blocks them rather than just identifying them.", "topic": "Information Security"}, {"id": "pdf2-155", "question": "The device used to block unauthorized access to your network is ...", "options": ["IDS", "Firewall", "IPS", "VPN"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A firewall filters inbound and outbound traffic against a rule set, which is exactly the mechanism used to block unauthorized access to a network.", "topic": "Information Security"}, {"id": "pdf2-156", "question": "The device used for providing secured remote access is ...", "options": ["IDS", "IPS", "Firewall", "VPN"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A VPN (Virtual Private Network) encrypts traffic over a public network so remote users can securely connect to a private network, which is its defining use case.", "topic": "Information Security"}, {"id": "pdf2-157", "question": "The decision-making in an organic structure is generally", "options": ["decentralised.", "centralised.", "formalised.", "None of the other answers is correct."], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Organic structures are flexible and adaptive, pushing decision-making authority down toward lower levels (decentralised) rather than concentrating it at the top like a mechanistic structure does.", "topic": "Management"}, {"id": "pdf2-158", "question": "he DBMS language component which can be embedded in a program is", "options": ["The data definition language(DDL)", "The data manipulation language (DML)", "The database administrator (DBA)", "A query language"], "correct": 2, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "Embedded DML lets data-manipulation statements (SELECT/INSERT/UPDATE/DELETE) be written directly inside a host programming language; DDL is used separately to define schema and is not the component embedded in application code.", "topic": "DBMS"}, {"id": "pdf2-159", "question": "The data transmission on the asynchronous BUS is also referred as ___________", "options": ["Bulk transmission", "Same time transmission", "Switch mode transmission", "Hand-Shake transmission."], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Asynchronous bus transfers rely on a request/acknowledge handshake between sender and receiver rather than a shared clock, which is why it's called handshake transmission.", "topic": "CAO"}, {"id": "pdf2-160", "question": "The data structure required to check whether an expression contains balanced parenthesis is", "options": ["Stack", "Queue", "Tree", "Array"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A stack (LIFO) is the standard structure for checking balanced parentheses: push on each opening bracket and pop-and-match on each closing bracket.", "topic": "DSA"}, {"id": "pdf2-161", "question": "The Cost benefit analysis evaluates the following benefits", "options": ["Direct costs", "Intangible costs", "Opportunity costs", "None of the above"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "low", "reasoning": "Cost-benefit analysis actually considers direct, indirect, intangible, and opportunity costs together, so singling out just one of direct/intangible/opportunity as 'the' answer isn't well-defined from the question as worded \u2014 deferring to the source's marked answer.", "topic": "Management"}, {"id": "pdf2-162", "question": "The control takes place after the action is called as", "options": ["Feed Forward Control", "Concurrent Control", "Feedback Control", "Control measure"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Feedback control measures results after an activity is completed and uses that information to correct future actions, unlike feed-forward (before) or concurrent (during) control.", "topic": "Management"}, {"id": "pdf2-163", "question": "The Contingency theory focuses on", "options": ["Situational variables", "Interrelationships", "Groups and human behavior", "Economic needs of workers"], "correct": 1, "original_marked": 3, "matches_original": false, "confidence": "high", "reasoning": "Contingency theory holds that there is no single best way to manage or organize \u2014 the right structure or leadership style depends on situational variables, not on group dynamics or human behavior per se (that's closer to the human relations/behavioral school).", "topic": "Management"}, {"id": "pdf2-164", "question": "The connected graph with n vertices and n edges consists of at least m different spanning trees, what is the largest integer m?", "options": ["1", "2", "3", "6"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "A connected graph with n vertices and n edges has exactly one extra edge beyond a spanning tree, so it contains exactly one cycle; since a simple graph's shortest possible cycle has 3 edges, every such graph is guaranteed at least 3 spanning trees (remove any one of the 3 cycle edges).", "topic": "DSA"}, {"id": "pdf2-165", "question": "The concept of ________ has evolved from the traditional view of corporate social responsibility.", "options": ["social scaffolding", "planetary progressivism", "work-life balance", "corporate sustainability"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Corporate sustainability broadened traditional CSR by explicitly folding in long-term environmental and economic viability alongside social responsibility (the 'triple bottom line').", "topic": "Business Ethics"}, {"id": "pdf2-166", "question": "The COCOMO model depends of time factors", "options": ["True", "False"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "COCOMO estimates effort, cost, and development schedule (time to develop, TDEV) from project size and cost drivers, so time is one of the factors the model produces and depends on.", "topic": "Software Engineering"}, {"id": "pdf2-167", "question": "The cache term is now applied when a buffering is employed for reusing commonly occurring items, for example", "options": ["File caches", "Name cache", "Flash memory", "Both a and b"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "File caches and name caches are both classic examples of buffering used to speed up repeated access to commonly used items; flash memory is a storage medium, not an example of this caching technique.", "topic": "OS"}, {"id": "pdf2-168", "question": "The basic limitation of FSM is that", "options": ["all of the comments are true", "it cannot remember arbitrary large amounts of information", "it sometimes fails to recognize grammars that are regular", "it sometimes recognized grammars that are not regular"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A finite state machine has only a fixed number of states, so it cannot store or remember an unbounded amount of information (e.g., cannot count arbitrarily high), which is precisely why it fails to recognize languages that require memory, like a^n b^n.", "topic": "TOC"}, {"id": "pdf2-169", "question": "The attribute composed of multiple components, each with an independent existence is called", "options": ["Composite attribute", "Simple attribute", "Single valued attribute", "Derived attribute"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A composite attribute can be broken into smaller sub-parts that each have independent meaning, such as Name splitting into First Name and Last Name.", "topic": "DBMS"}, {"id": "pdf2-170", "question": "The attribute age can be a", "options": ["Single Valued", "Multi Valued", "Derived", "Composite"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Age is typically modeled as a derived attribute since it can be computed at query time from the stored Date of Birth rather than stored and updated directly.", "topic": "DBMS"}, {"id": "pdf2-171", "question": "The assumptions about the future in which the planning is implemented are termed as", "options": ["Boundaries", "Premises", "Limits", "Hypothesis"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Planning premises are the assumed future conditions \u2014 economic, technological, competitive, etc. \u2014 under which a plan is expected to be carried out.", "topic": "Management"}, {"id": "pdf2-172", "question": "The assignment of individual duties and responsibilities is most appropriately described in which of the following documents?", "options": ["Security policy", "Enforcement guidelines", "Acceptable use policy", "Program manual"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "An acceptable use policy is the document employees typically sign that spells out their individual duties, responsibilities, and expected behavior regarding organizational resources, distinct from higher-level security or program policies.", "topic": "Information Security"}, {"id": "pdf2-173", "question": "The algorithm which chooses the page that has not been used for the longest period of time is _________.", "options": ["First in first out algorithm", "Least recently used algorithm", "Additional reference bit algorithm", "Counting based page replacement algorithm"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The Least Recently Used (LRU) algorithm replaces the page that hasn't been referenced for the longest time, based on the principle that recent usage predicts near-future usage.", "topic": "OS"}, {"id": "pdf2-174", "question": "The aim of this process is to develop low-quality software solutions that exceed or meet user expectations within time frame is development life cycle.", "options": ["True", "False"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The SDLC aims to produce high-quality software that meets user needs within time and budget constraints; the statement is false because it describes the goal as 'low-quality' software.", "topic": "Software Engineering"}, {"id": "pdf2-175", "question": "The advantage of pure virtual function than normal virtual function is \u2026\u2026\u2026\u2026\u2026\u2026.", "options": ["It reduces the program code size in terms of number of lines", "It reduces the memory space", "the compiler easily finds syntax error in a program", "the time complexity is linear"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Declaring a function pure virtual makes the class abstract and forces every derived class to override it (or itself remain abstract), so the compiler catches a missing implementation as an error at compile time rather than it failing silently at runtime.", "topic": "OOPS"}, {"id": "pdf2-176", "question": "The address of a page table in memory is stored in", "options": ["stack pointer", "page table base register", "page register", "program counter"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The page table base register (PTBR) holds the physical address of the page table in memory, and the CPU uses it plus the page number to index into the table on every translation.", "topic": "OS"}, {"id": "pdf2-177", "question": "The address generated by the CPU is referred to as ____________", "options": ["Physical address", "Logical address", "Neither physical nor logical", "Network Address"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The CPU generates a logical (virtual) address, which the MMU then translates into a physical address using the base/limit or page table mechanism.", "topic": "OS"}, {"id": "pdf2-178", "question": "he actual count of elements associated with the connectivity is called __________ of the relationship connectivity.", "options": ["Cardinality", "Entity type", "Entity set", "None of these"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Cardinality describes the actual number of instances of one entity that can be associated with instances of another entity in a relationship (e.g., 1:1, 1:N, M:N).", "topic": "DBMS"}, {"id": "pdf2-179", "question": "The access mode of Magnetc Disk is", "options": ["Sequential access", "Random access", "Associative access", "SemiRandom access"], "correct": 2, "original_marked": 4, "matches_original": false, "confidence": "high", "reasoning": "Magnetic disks are classified as random (direct) access storage devices, since any block can be addressed and read directly without scanning through preceding data, unlike sequential-access magnetic tape.", "topic": "OS"}, {"id": "pdf2-180", "question": "The ability to temporarily halt the CPU and use this time to send information on buses is called", "options": ["Direct memory access", "Vectoring the interrupt", "System Interrupt", "Cycle stealing"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Cycle stealing is the technique where a DMA controller temporarily takes over the bus for one memory cycle, forcing the CPU to pause briefly while data is transferred.", "topic": "CAO"}, {"id": "pdf2-181", "question": "The ___________ must design and program the overlay structure.", "options": ["programmer", "system architect", "system designer", "system analyst"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Overlays are a programmer-managed technique (not handled by the OS) where the programmer decides which code/data modules can share the same memory region at different times.", "topic": "OS"}, {"id": "pdf2-182", "question": "The __________ model defines the stored data structures in terms of the database model used.", "options": ["Physical level", "Conceptual level", "External level", "None of these"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The conceptual (logical) level describes the whole database's structure using the chosen data model (e.g., relational, hierarchical), independent of physical storage details, which matches \"in terms of the database model used\".", "topic": "DBMS"}, {"id": "pdf2-183", "question": "The ________ style of leadership describes a leader who tends to involve employees in decision making, delegate authority, encourage participation in deciding work methods and goals, and uses feedback as an opportunity for coaching employees.", "options": ["participative", "autocratic", "democratic", "laissez-faire"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "This is the textbook description of participative leadership: involving subordinates in decisions, delegating authority, and using feedback as coaching rather than criticism.", "topic": "Management"}, {"id": "pdf2-184", "question": "The _______ theory states a manager\u2019s choice of organizational structures and control systems depends on the characteristics of the external environment.", "options": ["Mechanistic", "Management science", "Organic", "Contingency"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Contingency theory holds that there is no single best way to organize; the right structure and control system depends on situational factors like the external environment.", "topic": "Management"}, {"id": "pdf2-185", "question": "The ______ technique expands the bandwidth of a signal by replacing each data bit with n bits.", "options": ["DSSS", "FHSS", "FDM", "TDM"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Direct Sequence Spread Spectrum (DSSS) spreads the signal by replacing each data bit with a longer chip sequence of n bits, expanding the bandwidth in exchange for noise/interference resistance.", "topic": "CN"}, {"id": "pdf2-186", "question": "The \"means\" of leadership involve", "options": ["getting results through others.", "the ability to build cohesive, goal-oriented teams.", "the process of influencing an organized group toward accomplishing its goals", "the process of forcibly making others comply.."], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "low", "reasoning": "This question hinges on a specific textbook's distinction between the \"ends\" and \"means\" of leadership that could not be independently verified; the marked option (the classic Stogdill-style definition of leadership as influencing a group toward its goals) is kept as given.", "topic": "Management"}, {"id": "pdf2-187", "question": "The Simple Security Condition requires that a subject S can read an object O only if _____and any DAC permits", "options": ["Is > Io", "LO \u2264 LS", "L0\u2264 LS", "Is \u2264 Io"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Bell-LaPadula's Simple Security Property (\"no read up\") requires the object's security level to be less than or equal to the subject's clearance level (L(O) \u2264 L(S)) before a read is allowed.", "topic": "Information Security"}, {"id": "pdf2-188", "question": "The number of subordinates a superior can effectively handle is called", "options": ["Organising people", "Span of control", "Direction", "Coordination"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Span of control is the management term for the number of subordinates a manager can supervise effectively.", "topic": "Management"}, {"id": "pdf2-189", "question": "The easiest form of offline password hash attack which can be used for capturing insecure passwords is?", "options": ["Hybrid", "Dictionary", "Brute-force", "Man-in-the-mid dle"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A dictionary attack simply hashes a list of common/likely passwords and compares them to stolen hashes, making it the easiest offline attack against weak, insecure (guessable) passwords compared to exhaustive brute force.", "topic": "Information Security"}, {"id": "pdf2-190", "question": "The -------------- access control model in which users are not given much freedom to decide who can access their files and is recognized for its structure and use of security labels?", "options": ["Discretionary", "Mandatory", "Role-based", "Nondiscretiona ry"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Mandatory Access Control (MAC) assigns security labels/clearances centrally, so users have little say over who can access their files, unlike the user-controlled Discretionary Access Control model.", "topic": "Information Security"}, {"id": "pdf2-191", "question": "That an enterprise must behave as a good citizen is an example of its responsibility towards:", "options": ["owners.", "workers.", "consumers.", "community."], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Acting as a \"good citizen\" (e.g., environmental stewardship, philanthropy, civic involvement) reflects an enterprise's social responsibility toward the community at large, not a specific stakeholder group like owners or workers.", "topic": "Business Ethics"}, {"id": "pdf2-192", "question": "Thackeray Manufacturing recently developed a code of ethics. Which of the following topics is most likely covered in the document?", "options": ["business conduct", "fair competition", "HR issues", "All the other answers are correct"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A comprehensive corporate code of ethics typically addresses business conduct, fair competition, and HR issues together, so \"all of the above\" is the expected answer.", "topic": "Business Ethics"}, {"id": "pdf2-193", "question": "Testing the end to end functionality of the system as a whole is defined as _______________", "options": ["Unit Testing", "Functional Testing", "Stress Testing", "Load Testing"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Among the given choices, functional testing is the one aimed at verifying the application's complete functional behavior against requirements, as opposed to unit-level checks or performance-focused stress/load testing.", "topic": "Software Engineering"}, {"id": "pdf2-194", "question": "Templates ___ some common errors found in code that makes heavy use of function-like macros", "options": ["Reject", "Allow", "Discard", "None"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "low", "reasoning": "The well-known Stroustrup point is that templates \"avoid\" many common macro-related errors (unsafe substitution, no type checking); none of the given options (Reject/Allow/Discard/None) is an exact match, so the marked option is kept given the ambiguous wording.", "topic": "C/C++"}, {"id": "pdf2-195", "question": "Template uses ___ keyword?", "options": ["class", "typename", "both class & typename", "function"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "C++ allows either the `class` or `typename` keyword interchangeably to declare a template type parameter.", "topic": "C/C++"}, {"id": "pdf2-196", "question": "Template creates___ versions of a function at run time", "options": ["Similar", "Different", "None", "Both similar and different"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Templates are instantiated for each distinct type they're used with, producing different generated versions of the function/class for each type argument.", "topic": "C/C++"}, {"id": "pdf2-197", "question": "Template classes and functions ____ the code duplication of different data types and thus makes the development easier and faster.", "options": ["Allow", "Eliminate", "Permit", "None"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Templates let you write one generic definition instead of separate overloads per data type, eliminating the code duplication that would otherwise be needed.", "topic": "C/C++"}, {"id": "pdf2-198", "question": "TCP/IP MODEL DOES NOT HAVE ______ LAYER BUT OSI MODEL HAVE THIS LAYER.", "options": ["SESSION LAYER", "PRESENTATI ON LAYER", "APPLICATION LAYER", "Both Session and Presentation layer"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "The TCP/IP model collapses the OSI model's separate Session and Presentation layers into its single Application layer, so both are missing from TCP/IP.", "topic": "CN"}, {"id": "pdf2-199", "question": "Tangible premises in planning doesn\u2019t include", "options": ["capital investment", "Unit of production", "Cost per unit", "Goodwill"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Tangible planning premises are quantifiable factors like capital investment, units of production, and cost per unit; goodwill is intangible and can't be measured precisely, so it's the odd one out.", "topic": "Management"}, {"id": "pdf3-001", "question": "Synchronous and Asynchronous data transfer classification is based on ______________", "options": ["Time at which data transfer happens", "Type of data transfer occurs", "Type of devices connected to them", "None of the mentioned options"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Synchronous transfer happens on a shared clock/fixed timing; asynchronous transfer happens on an as-needed handshake basis without shared timing \u2014 the classification is about when the transfer occurs.", "topic": "CAO"}, {"id": "pdf3-002", "question": "Suppose the following disk request sequence (track numbers) for a disk with 100 tracks is given: 45, 20, 90, 10, 50, 60, 80, 25, 70. Assume that the initial position of the R/W head is on track 50. The additional distance that will be traversed by the R/W head when the Shortest Seek Time First (SSTF) algorithm is used compared to the SCAN (Elevator) algorithm (assuming that SCAN algorithm moves towards 100 when it starts execution) is _________ tracks", "options": ["8", "9", "10", "11"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "SSTF from 50 services in order 50,45,60,70,80,90,25,20,10 for a total head movement of 130; SCAN moving toward 100 first services 50,60,70,80,90 then reverses (without overshooting to the physical disk edge) through 45,25,20,10 for 120, a difference of 10 tracks.", "topic": "OS"}, {"id": "pdf3-003", "question": "Suppose that a system has a paging system with 8 entries in a page table. Given that there are three processes of equal sizes, creating 8 valid entries in their page tables. What would be the total number of frames allocated to these three processes under the condition that 2 pages are shared by the three processes?", "options": ["24", "20", "18", "30"], "correct": 2, "original_marked": null, "matches_original": false, "confidence": "high", "reasoning": "3 processes \u00d7 8 page-table entries = 24 total entries, but 2 pages are shared across all 3 processes, so those pages need only 1 frame each instead of 3, removing 2\u00d7(3-1)=4 duplicate frames: 24-4=20 frames.", "topic": "OS"}, {"id": "pdf3-004", "question": "Suppose a disk has 201 cylinders, numbered from 0 to 200. At some time the disk arm is at cylinder 100, and there is a queue of disk access requests for cylinders 30, 85, 90, 100, 105, 110, 135 and 145. If Shortest-Seek Time First (SSTF) is being used for scheduling the disk access, the request for cylinder 90 is serviced after servicing ____________ number of requests.", "options": ["1", "2", "3", "4"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "From head position 100, SSTF services 100 (distance 0), then 105 (5), then 110 (5), and only then 90 (20) is the closest remaining request \u2014 so cylinder 90 is serviced after 3 prior requests.", "topic": "OS"}, {"id": "pdf3-005", "question": "Supervision of employees is greatly enhanced by having a small span of control, but it is", "options": ["expensive.", "time-consumin g.", "resource-cons uming.", "complex."], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A small span of control means each supervisor oversees fewer employees, so more supervisors/managers are needed, which raises payroll and overhead costs \u2014 i.e., it is expensive.", "topic": "Management"}, {"id": "pdf3-006", "question": "Stress that usually lasts for short time and may be due to work pressure, meeting deadlines pressure or minor accident, or any related matters is called", "options": ["Chronic stress", "Acute stress", "Negative stress", "Permanent stress"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Short-lived stress triggered by deadlines or a minor incident is acute stress; chronic stress is the long-lasting, recurring kind.", "topic": "Management"}, {"id": "pdf3-007", "question": "State true or false. i) Unix, support multiple user processes but only support one thread per process. A java run time environment is an example of a system of one process with multiple threads.", "options": ["True, False", "True, True", "False, True", "False, False"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "This is genuinely ambiguous: sources disagree on whether the JRE truly counts as the textbook's 'one process, multiple threads' example versus modern multi-threaded UNIX making statement (a) false, so the marked answer is kept rather than guessed.", "topic": "OS"}, {"id": "pdf3-008", "question": "SP 800 series standard are defined by....", "options": ["NIST", "COBIT", "COSO", "ISO"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "NIST publishes the SP 800 series of computer/information security guidelines and standards.", "topic": "Information Security"}, {"id": "pdf3-009", "question": "Sort out the following virus based on their severity: Resident virus, non-resident virus, boot sector virus, and macro virus", "options": ["Resident virus, non-resident virus, boot sector virus, and macro virus", "Boot sector virus, resident virus, non-resident virus and macro virus", "Boot sector virus, non-resident virus, resident virus and macro virus", "Boot sector virus, non-resident virus, macro virus and resident virus"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "low", "reasoning": "There is no universally agreed 'severity ranking' of these virus categories in security literature, so this question is inherently subjective/ambiguous \u2014 the marked answer is kept rather than asserting a definitive order.", "topic": "Information Security"}, {"id": "pdf3-010", "question": "Social responsibility is ______________.", "options": ["the same as legal responsibility.", "broader than legal responsibility.", "narrower than legal responsibility.", "None of the other answers is correct."], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Legal responsibility is the minimum compliance required by law, while social responsibility includes voluntary ethical and societal obligations beyond the law \u2014 so it is broader than legal responsibility.", "topic": "Business Ethics"}, {"id": "pdf3-011", "question": "Significant percentage of the spent time in moving data in two levels in the memory hierarchy, then the memory-hierarchy is said to", "options": ["Mixed", "Write stall", "Averaging", "Thrash"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "When a large share of execution time is spent moving data back and forth between two levels of the memory hierarchy instead of doing useful work, the hierarchy is said to be thrashing.", "topic": "CAO"}, {"id": "pdf3-012", "question": "Select the output of the following #include<stdio.h> main(){ char arr1[5]=\"apple\"; char arr2[5]=\"apple\"; if (arr1==arr2) printf(\"Same\"); else printf(\"Not Same\"); }", "options": ["a. Same", "a. Not Same", "a. Error", "a. None of these"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "arr1 and arr2 are two distinct arrays; array names decay to their own separate addresses, so arr1==arr2 compares pointers, not contents, and prints 'Not Same' even though both hold \"apple\".", "topic": "C/C++"}, {"id": "pdf3-013", "question": "Seek Time is --------", "options": ["the time taken to locate the disk arm to a specified track where the data is to be read or write.", "the time taken by the desired sector of disk to rotate into a position so that it can access the read/write heads", "the time to transfer the data.", "the time is taken to complete the execution."], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Seek time is the time needed to move the disk arm/head to the track that holds the desired data.", "topic": "OS"}, {"id": "pdf3-014", "question": "SDLC stands for", "options": ["Software Development Life Cycle", "System Development Life cycle", "Software Design Life Cycle", "System Design Life Cycle"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "SDLC commonly stands for Software Development Life Cycle, the standard process for planning, building, testing, and deploying software.", "topic": "Software Engineering"}, {"id": "pdf3-015", "question": "Scientific Management is related to", "options": ["Elton Mayo", "Henry Fayol", "F W Taylor", "Max Weber"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "F. W. Taylor is regarded as the father of Scientific Management, focused on optimizing worker efficiency through systematic study.", "topic": "Management"}, {"id": "pdf3-016", "question": "Scalar chain is a", "options": ["Leadership chain", "Authority chain", "Decision making chain", "Control chain"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Fayol's scalar chain principle describes the formal chain of authority/command running from top management down to the lowest rank.", "topic": "Management"}, {"id": "pdf3-017", "question": "Sanjana works as a production supervisor, and she believes one of her subordinates is drinking during his lunch break. Sanjana\u2019s employer does not have a specific rule regarding the subordinate's behaviour. Which of the following would most likely assist Sanjana with her problem in this situation?", "options": ["corporate code of ethics", "corporate vision statement", "corporate code of conduct", "labour legislation"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "With no specific written rule covering this behavior, a corporate code of ethics (the broad statement of guiding values/principles) is what helps a manager judge the right action, unlike a code of conduct which lists specific behavioral rules that don't exist here.", "topic": "Business Ethics"}, {"id": "pdf3-018", "question": "RTM stands for ____________", "options": ["Repeated Trade Matrix", "Redundant Trace Module", "Robust Test Mechanism", "Requirement traceability matrix"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "RTM stands for Requirement Traceability Matrix, used to trace requirements through design, development, and testing.", "topic": "Software Engineering"}, {"id": "pdf3-019", "question": "Routing is performed by ________ in OSI architecture", "options": ["network layer", "data link layer", "transport layer", "session layer"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "In the OSI model, the network layer is responsible for logical addressing and routing packets between networks.", "topic": "CN"}, {"id": "pdf3-020", "question": "Rotational Latency is ---", "options": ["the time is taken to locate the disk arm to a specified track where the data is to be read or write.", "B. the time taken by the desired sector of disk to rotate into a position so that it can access the read/write heads.", "the time to transfer the data.", "the time is taken to complete the execution."], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Rotational latency is the time it takes for the desired disk sector to rotate around to the read/write head.", "topic": "OS"}, {"id": "pdf3-021", "question": "Reverse polish notation is used by", "options": ["Stack", "Queue", "Linked list", "All of these"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Reverse Polish (postfix) notation is evaluated using a stack to hold operands until the operators that combine them are reached.", "topic": "DSA"}, {"id": "pdf3-022", "question": "Return type of is_open() function is ___", "options": ["int", "bool", "float", "char *"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "In C++ file streams, is_open() returns a bool indicating whether the stream object is currently associated with an open file.", "topic": "C/C++"}, {"id": "pdf3-023", "question": "Resource allocation graph can be used to avoid deadlock for 'n' processes", "options": ["Yes", "No"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The resource-allocation-graph deadlock-avoidance algorithm generalizes to any number of processes as long as each resource type has only a single instance.", "topic": "OS"}, {"id": "pdf3-024", "question": "Requirement of two pointer is not mandatory in", "options": ["Stack", "Queue", "Linked list", "All of these"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A stack only needs a single 'top' pointer for all operations, unlike a queue (front and rear pointers) or linked lists, which typically need two pointers for many operations.", "topic": "DSA"}, {"id": "pdf3-025", "question": "Relationship set in ER diagram", "options": ["Divided Rectangle", "Non Divided Rectangle", "Line", "Diamond"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "In standard ER diagram notation, a relationship set is drawn as a diamond connecting the related entity rectangles.", "topic": "DBMS"}, {"id": "pdf3-026", "question": "Relations produced by ER model will always be in", "options": ["1 NF", "2 NF", "3 NF", "4 NF"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "ER-to-relational mapping produces relations whose attributes are atomic (non-multivalued), which by definition satisfies 1NF, though higher normal forms are not guaranteed.", "topic": "DBMS"}, {"id": "pdf3-027", "question": "Relation between two different function with two constant are applicable in", "options": ["F(n)=O(g(n))", "F(n)=\u03b8(g(n))", "F(n)=\u038f(g(n))", "All of them"], "correct": 2, "original_marked": 4, "matches_original": false, "confidence": "high", "reasoning": "Only Theta notation is defined using two constants (c1 and c2) bounding f(n) from both above and below; Big-O and Omega each use just one constant.", "topic": "DSA"}, {"id": "pdf3-028", "question": "Related to Fibonacci sequence, which of the following is more appropriate.", "options": ["Integer sequence", "Irrational number", "Both are true", "None is correct"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Every Fibonacci number (0, 1, 1, 2, 3, 5, ...) is an integer, so the Fibonacci sequence is an integer sequence; only the related golden ratio is irrational.", "topic": "DSA"}, {"id": "pdf3-029", "question": "Regular expressions that do not contain the star operator can represent only finite languages", "options": ["True", "False", "Can't determined", "Neither True and Nor False"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Without the Kleene star, a regular expression can only concatenate or union a bounded number of symbols, so it can describe only a finite language.", "topic": "TOC"}, {"id": "pdf3-030", "question": "Regular Expression recognizes --------grammars", "options": ["type-1", "type-2", "type-3", "type-0"], "correct": 3, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "In the Chomsky hierarchy, regular expressions correspond exactly to type-3 (regular) grammars, not type-2 (context-free) grammars.", "topic": "TOC"}, {"id": "pdf3-031", "question": "Recursion fails due to fixed size", "options": ["Linked list", "Queue", "Stack", "All of these"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Recursive calls are pushed onto the call stack, which has a fixed size, so deep or unbounded recursion causes a stack overflow.", "topic": "DSA"}, {"id": "pdf3-032", "question": "Random access memories are useful in applications where", "options": ["Data consists of numbers", "Short access time is required", "Each stored word is processed differently", "Data naturally needs to flow in and out in serial form"], "correct": 2, "original_marked": 4, "matches_original": false, "confidence": "high", "reasoning": "RAM's defining advantage is that any location can be accessed directly in roughly constant time, so it suits applications needing short access time; serial data flow is the use case for serial-access memory, not RAM.", "topic": "CAO"}, {"id": "pdf3-033", "question": "Queues serve a major role in", "options": ["Simulation of recursion", "Simulation of arbitrary linked list", "Simulation of limited resource allocation", "All of these"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "A queue's FIFO ordering makes it the natural structure for modeling a waiting line for a limited or shared resource (e.g., CPU or printer scheduling).", "topic": "DSA"}, {"id": "pdf3-034", "question": "Program always deals with ____________", "options": ["logical address", "absolute address", "physical address", "relative address"], "correct": 1, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "A running program only ever references logical (virtual) addresses generated by the CPU; the MMU translates these into physical addresses that the program never sees directly.", "topic": "OS"}, {"id": "pdf3-035", "question": "Prims algorithm is based on", "options": ["Divide and conquer method", "Dynamic programming", "Greedy method", "Branch and bound"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Prim's algorithm greedily adds the cheapest edge that connects the growing MST to a new vertex at each step.", "topic": "DSA"}, {"id": "pdf3-036", "question": "Plan-driven process is a process where all the activities are planned first and the progress is measured against the plan is", "options": ["Agile Process Model", "Waterfall Process Model", "Prototyping Process Model", "RAD Process Model"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The Waterfall model plans every phase upfront and tracks progress against that fixed plan, which is exactly what defines a plan-driven process.", "topic": "Software Engineering"}, {"id": "pdf3-037", "question": "Pharming is an attack which referred to", "options": ["Collecting social data from victim device", "Installing any software or app in victim device", "Attacking victim device", "Attacking victim social network"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "Pharming actually redirects victims to a fraudulent site via DNS/host-file tampering to harvest data; none of the given options describe this precisely, so the source's marked answer is kept as the best available guess.", "topic": "Information Security"}, {"id": "pdf3-038", "question": "Persons who can influence others and who possess managerial authority are termed ________.", "options": ["entrepreneurs", "leaders", "managers", "visionaries"], "correct": 2, "original_marked": 3, "matches_original": false, "confidence": "high", "reasoning": "This is the standard management-textbook (Robbins) definition of a 'leader': someone who influences others and also holds formal managerial authority; 'manager' alone does not require the influence component.", "topic": "Management"}, {"id": "pdf3-039", "question": "Periodically adding, changing and deleting file records is called as File?", "options": ["Updating", "Upgrading", "Reconstructing", "Renewing"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Adding, changing, and deleting records over time to keep a file current is the definition of file updating (maintenance).", "topic": "DBMS"}, {"id": "pdf3-040", "question": "Parallel computing means doing several tasks simultaneously thus improving the performance of the _____.", "options": ["Data system", "Computer system", "Memory", "Vector system"], "correct": 2, "original_marked": 3, "matches_original": false, "confidence": "high", "reasoning": "Parallel computing runs multiple tasks at once to boost the overall performance of the computer system, not specifically memory.", "topic": "CAO"}, {"id": "pdf3-041", "question": "Page fault occurs when the referenced page is", "options": ["not in main memory", "not in secondary memory", "not in tertiary memory", "not in shared memory"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A page fault is triggered exactly when a referenced page is not currently resident in main (physical) memory.", "topic": "OS"}, {"id": "pdf3-042", "question": "overflow condition was raised by the stack, which of the condition holds false", "options": ["maximum limit exceeds", "top of the stack is reached", "limited stack size", "none of these"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "The question is ambiguously worded about which overflow-related statement is 'false'; the source's marked answer is kept since no option can be confidently ruled out as the intended false statement.", "topic": "DSA"}, {"id": "pdf3-043", "question": "Output will be #include<stdio.h> int myFunction(int parameter) { return parameter; } main(){ int value=100; printf(\"%d %d\", myFunction(value), myFunction(value+100)); }", "options": ["100 100", "100 200", "Error", "Warning during compilation"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "myFunction simply returns its argument, so the two calls independently return 100 and 200; C's unspecified argument-evaluation order doesn't change these results, giving \"100 200\".", "topic": "C/C++"}, {"id": "pdf3-044", "question": "Output will be #include<stdio.h> #include<string.h> main(){ char Be[16]=\"Positive \"; char Positive[16]=\"Positive \"; printf(\"%d\",strcmp(Be,Positive) ); }", "options": ["1", "-1", "0", "Error"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Both char arrays hold the identical string \"Positive \", so strcmp returns 0.", "topic": "C/C++"}, {"id": "pdf3-045", "question": "Output of the given code will be #include<stdio.h> #include<string.h> main(){ char Be[16]=\"Positive \"; char Positive[16]=\"positive \"; printf(\"%d\",strcmp(Be,Positive) ); }", "options": ["1", "-1", "0", "Error"], "correct": 2, "original_marked": 4, "matches_original": false, "confidence": "high", "reasoning": "strcmp compares byte by byte; 'P' (0x50) is less than 'p' (0x70), so Be < Positive and strcmp returns a negative value (-1) \u2014 the code compiles and runs fine, there's no error.", "topic": "C/C++"}, {"id": "pdf3-046", "question": "Output of the following code will be #include<stdio.h> int myFunction() { return 1; } int myFunction(int a) { return 2; } main(){ printf(\"%d %d\", myFunction(), myFunction(1)); }", "options": ["1 1", "1 2", "2 2", "Error"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "C (unlike C++) has no function overloading, so declaring two functions both named myFunction is an illegal redefinition and causes a compile-time error.", "topic": "C/C++"}, {"id": "pdf3-047", "question": "Operating System maintains the page table for", "options": ["each process", "each thread", "each instruction", "each address"], "correct": 1, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "Each process has its own virtual address space, so the OS keeps one page table per process, not per thread.", "topic": "OS"}, {"id": "pdf3-048", "question": "Open mail relays are", "options": ["Mail user agent", "Mail transfer agent", "Mail delivers agent", "Internet mail extension"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "An open mail relay is an SMTP server (a Mail Transfer Agent) misconfigured to forward mail for anyone, not just its own users.", "topic": "CN"}, {"id": "pdf3-049", "question": "Only one external reference is required for", "options": ["Linear linked list", "Circular linked list", "Double ended list", "None of these"], "correct": 2, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "A circular linked list needs only one external pointer (conventionally to the last node) to reach every node, since last->next loops back to the first node; a linear list needs a separate tail pointer for O(1) end access.", "topic": "DSA"}, {"id": "pdf3-050", "question": "Nusrat sees her role as someone who provides direction and resources for her team then gets out of their way and lets them do their work however they think best. Nusrat uses the ________ style of leadership.", "options": ["autocratic", "participative", "democratic", "laissez-faire"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Providing direction and resources and then stepping back to let the team decide how to work themselves is the laissez-faire ('hands-off') leadership style.", "topic": "Management"}, {"id": "pdf3-051", "question": "Non-type template parameters provide the ability to pass what type of data at compile time", "options": ["int", "float", "constant expression", "none of the mentioned"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Non-type template parameters must be compile-time constants (constant expressions) \u2014 not restricted to just int or float \u2014 covering ints, enums, pointers, etc. known at compile time.", "topic": "C/C++"}, {"id": "pdf3-052", "question": "Non-type parameters are mainly used for specifying _____ values or any other constant value for a particular instance of a template.", "options": ["max and min", "max or min", "min", "max"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Non-type parameters are typically used to fix a single bound, like a maximum or a minimum size, for a particular template instance (e.g. an array size), so 'max or min' fits better than requiring both at once.", "topic": "C/C++"}, {"id": "pdf3-053", "question": "Nesting of try block is \u2026\u2026\u2026\u2026..", "options": ["syntax error", "possible in C++", "logical error", "both (a) and (c)"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "C++ explicitly allows try blocks to be nested inside other try or catch blocks; this is standard, legal syntax.", "topic": "C/C++"}, {"id": "pdf3-054", "question": "Nesting of catch block is \u2026\u2026\u2026\u2026\u2026", "options": ["syntax error", "possible in C++", "logical error", "None of the above"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Just like try blocks, catch blocks can contain their own nested try-catch structures in C++, so nesting is perfectly valid.", "topic": "C/C++"}, {"id": "pdf3-055", "question": "Negative cash flow is one of the classification when desired rate of return is minimum by actual rate of return", "options": ["True", "False"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "The question is awkwardly worded, but in capital budgeting a return is effectively classified as 'negative' when the actual rate of return falls short of the desired/minimum rate; deferring to the marked answer since the phrasing is genuinely ambiguous.", "topic": "Management"}, {"id": "pdf3-056", "question": "Narrow span of control results into", "options": ["Tall structure", "Flat structure", "Mechanistic structure", "All the above"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A narrow span of control means each manager supervises fewer people, which requires more hierarchical levels and produces a tall organizational structure.", "topic": "Management"}, {"id": "pdf3-057", "question": "N Ach, N Aff and N Pow are related", "options": ["McClelland\u2019s Learned Needs", "ERG theory", "Justice Theory", "Equity theory"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "N Ach (need for achievement), N Aff (need for affiliation), and N Pow (need for power) are the three needs in McClelland's Learned/Acquired Needs Theory of motivation.", "topic": "Management"}, {"id": "pdf3-058", "question": "Multivalued attribute Example", "options": ["Student Name", "Student address", "Student Phone number", "Student Id number"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "A multivalued attribute can hold more than one value for a single entity; a student can have multiple phone numbers, making it the classic textbook example, unlike name, address, or ID which are typically single-valued.", "topic": "DBMS"}, {"id": "pdf3-059", "question": "Minnesota Multi-phasic Personality Inventory (MMPI) is used to assess", "options": ["Attitude", "Personality", "Work engagement", "Wellbeing"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "MMPI (Minnesota Multiphasic Personality Inventory) is a standardized psychometric test specifically designed to assess personality traits and psychopathology.", "topic": "Management"}, {"id": "pdf3-060", "question": "Memory management technique in which system stores and retrieves data from secondary storage for use in main memory is called", "options": ["fragmentation", "paging", "mapping", "spooling"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Paging is the memory management scheme where logical memory is divided into fixed-size pages that are moved between secondary storage and main memory frames.", "topic": "OS"}, {"id": "pdf3-061", "question": "Memory Address locations are specified using which data representation?", "options": ["Sign-magnitude", "one`s complement", "Unsigned", "two`s complement"], "correct": 3, "original_marked": 4, "matches_original": false, "confidence": "high", "reasoning": "Memory addresses are always non-negative (they index locations starting at 0), so they are represented using unsigned binary representation \u2014 two's complement is reserved for signed values, which addresses never are.", "topic": "CAO"}, {"id": "pdf3-062", "question": "McKinsky\u2019s 7S framework doesn\u2019t include:", "options": ["System", "Shared value", "Share holders", "Staff"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "McKinsey's 7S framework consists of Strategy, Structure, Systems, Shared Values, Skills, Style, and Staff \u2014 'Shareholders' is not one of the seven S's.", "topic": "Management"}, {"id": "pdf3-063", "question": "MBTI is used to measure", "options": ["Attitude", "Behaviour", "Personality", "Response"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "The Myers-Briggs Type Indicator (MBTI) is a self-report questionnaire designed to measure psychological personality type and preferences.", "topic": "Management"}, {"id": "pdf3-064", "question": "Max Weber belongs to which school of Management thought?", "options": ["Scientific", "Administrative", "Bureaucratic", "Human relations"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Max Weber founded the Bureaucratic school of management thought, emphasizing formal rules, hierarchy, and impersonal relationships.", "topic": "Management"}, {"id": "pdf3-065", "question": "Match the following: i. Breadth-first search a. Heap ii. Depth-first search b. Stack iii. Sorting c. Queue", "options": ["i-a ii-b iii-c", "i-c ii-b iii-a", "i-c ii-a iii-b", "i-a ii-b iii-c"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "BFS is implemented using a Queue, DFS is implemented using a Stack, and sorting algorithms like heap sort rely on a Heap \u2014 matching i-c, ii-b, iii-a.", "topic": "DSA"}, {"id": "pdf3-066", "question": "Match the following elements of organisation with their characteristics A) 1. Strategic apex ----- A. Decentralised and professional bureaucracy B) 2. Techno - structure ------ B. Centralised and Simple structure C) 3. Middle line ------ C. Dominant standardisation and machine bureaucracy D) 4. Support staff ------ D. Autonomy and Divisional structure E) 5. Operating core ------- E. Mutual adjustments and machine bureaucracy", "options": ["1-B, 2-C, 3-D, 4-E, 5-A", "1-C, 2-B, 3-E, 4-D, 5-A", "1-E, 2-C, 3-B, 4-A, 5-D", "1-B, 2-A, 3-E, 4-C, 5-D"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "In Mintzberg's model, Strategic apex pairs with a centralized simple structure, Techno-structure with standardization/machine bureaucracy, Middle line with autonomy/divisional structure, Support staff with mutual adjustment, and Operating core with decentralized professional bureaucracy \u2014 i.e. 1-B, 2-C, 3-D, 4-E, 5-A.", "topic": "Management"}, {"id": "pdf3-067", "question": "Management as a process refers to __________", "options": ["Group of managers", "Functions of management", "Subject of management", "All of these"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Management as a process refers to the set of functions \u2014 planning, organizing, staffing, directing, and controlling \u2014 that managers carry out.", "topic": "Management"}, {"id": "pdf3-068", "question": "Management as a Noun refers to __________", "options": ["Group of managers", "Functions of management", "Subject of management", "All of these"], "correct": 1, "original_marked": 3, "matches_original": false, "confidence": "high", "reasoning": "When 'management' is used as a noun it refers to the group of people who run an organization (e.g. 'the management decided...'), not to the academic subject of study.", "topic": "Management"}, {"id": "pdf3-069", "question": "Magnetic tape is a", "options": ["serial access medium", "Random access medium", "A parallel access medium", "NONE"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Magnetic tape must be read from the beginning to reach a given point, making it a sequential/serial access medium, unlike disks which allow random access.", "topic": "CAO"}, {"id": "pdf3-070", "question": "LSD stands for ________________", "options": ["Lean Software Development", "Live Software Development", "Less Software Data", "Least Software Data loss"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "LSD stands for Lean Software Development, an agile methodology that adapts lean manufacturing principles to software.", "topic": "Software Engineering"}, {"id": "pdf3-071", "question": "Lower and upper limits are present in which chart ?", "options": ["Run chart", "Bar chart", "Control chart", "None of the mentioned"], "correct": 3, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "Control charts plot data with a center line plus an upper control limit (UCL) and lower control limit (LCL) to detect process variation; run charts show trends over time without such statistical limits.", "topic": "Management"}, {"id": "pdf3-072", "question": "Logical memory is broken into blocks of the same size called ________", "options": ["frames", "pages", "backing store", "registers"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Logical (virtual) memory is divided into fixed-size blocks called pages, which map to equally-sized frames in physical memory.", "topic": "OS"}, {"id": "pdf3-073", "question": "Linked list uses", "options": ["Random memory allocation", "Static memory allocation", "Fixed memory allocation", "Dynamic memory allocation"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Linked lists allocate each node dynamically at runtime (e.g. via malloc/new) rather than reserving a fixed contiguous block, which is what lets them grow and shrink.", "topic": "DSA"}, {"id": "pdf3-074", "question": "Like normal parameters, we can specify _____arguments to templates.", "options": ["Default", "Function", "Class", "None"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "C++ templates support default template arguments, just as functions support default parameter values, so an unspecified template parameter falls back to its default.", "topic": "C/C++"}, {"id": "pdf3-075", "question": "Let w be a string and separated by three variable m, n, and o as per pumping lemma for regular language. What does these variables represent?", "options": ["string", "string count", "string and string count", "none"], "correct": 1, "original_marked": 2, "matches_original": false, "confidence": "low", "reasoning": "The pumping lemma splits a string w into three parts (usually called x, y, z); here m, n, o play that role and are themselves substrings (strings) of w, not counts \u2014 though the question's non-standard notation makes this reading uncertain.", "topic": "TOC"}, {"id": "pdf3-076", "question": "Let the initial value of count be 5. What will be the final value of count if the instructions are executed in the following order: S1;T1;S2;T2;S3;T3. Process P0: { S1: register1=count; S2: register1=register1 - 5 S3: count=register1 } Process P1: { T1: register2=count; T2: register2=register2 X 5 T3: count=register2 }", "options": ["50", "25", "10", "0"], "correct": 2, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "Tracing S1;T1;S2;T2;S3;T3 with count=5: register1=5, register2=5, register1=0, register2=25, count=0 (S3), then count=25 (T3, executes last). Final count is 25.", "topic": "OS"}, {"id": "pdf3-077", "question": "Let the initial value of count be 10. What will be the final value of count if the instructions are executed in the following order: S1;T1;S2;T2;S3;T3. Process P0: { S1: register1=count; S2: register1=register1 - 5 S3: count=register1 } Process P1: { T1: register2=count; T2: register2=register2 X 5 T3: count=register2 }", "options": ["50", "20", "10", "1"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Tracing S1;T1;S2;T2;S3;T3 with count=10: register1=10, register2=10, register1=5, register2=50, count=5 (S3), then count=50 (T3, executes last). Final count is 50.", "topic": "OS"}, {"id": "pdf3-078", "question": "Let int arr[4]={0,1,2,3}. Which of the following are valid operations? I. arr++ II. ++arr III. arr+4 IV. arr*4", "options": ["a. I and II", "a. III", "a. IV", "a. All"], "correct": 2, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "An array name is not a modifiable lvalue, so arr++ and ++arr are illegal; arr*4 makes no sense for a pointer. Only arr+4 (pointer arithmetic on the decayed array) is valid, so only III is correct.", "topic": "C/C++"}, {"id": "pdf3-079", "question": "Legitimate power is based on the subordinate's perception that the leader has a right to exercise influence because of the leader\u2019s", "options": ["role or position within the organisation.", "expertise and knowledge.", "personal characteristics and personality.", "ability to punish or reward."], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Legitimate power comes from a person's formal role or position of authority within the organization, per French and Raven's bases of power.", "topic": "Management"}, {"id": "pdf3-080", "question": "Left linear grammars are ...... of CFG", "options": ["Power set", "Sub set", "Super set", "Nullable"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Regular grammars (including left-linear grammars) are a proper subset of context-free grammars.", "topic": "TOC"}, {"id": "pdf3-081", "question": "Lean philosophy regards everything not adding value to the customer as __________", "options": ["Unnecessary", "Waste", "Useful", "Necessary"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Lean philosophy defines anything that does not add value for the customer as waste, to be eliminated.", "topic": "Software Engineering"}, {"id": "pdf3-082", "question": "Lean Development follows the principle of ______________", "options": ["Decide as late as possible", "Deliver as late as possible", "Decide as early as possible", "Not building integrity"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Lean software development principles include 'decide as late as possible' (keep options open until you have enough information), paired with 'deliver as fast as possible'.", "topic": "Software Engineering"}, {"id": "pdf3-083", "question": "Leadership is the process whose important ingredient is the _____________ exercised by the leaders on the group members.", "options": ["friendship", "loyalty", "trust", "influence"], "correct": 4, "original_marked": 3, "matches_original": false, "confidence": "high", "reasoning": "Leadership is classically defined as the process of influencing group members toward achieving goals; influence, not trust, is the key ingredient named in this definition.", "topic": "Management"}, {"id": "pdf3-084", "question": "Leadership has a lot of characteristics, and a leader must not maintain this trait in his behaviour:", "options": ["co-existence", "taking responsibility", "avoiding responsibility", "All the other answers are correct"], "correct": 3, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "The question asks which trait a leader must NOT maintain; avoiding responsibility is the negative trait, whereas taking responsibility is a desirable leadership trait a leader should keep.", "topic": "Management"}, {"id": "pdf3-085", "question": "Leaders that focus on the individuality and personality needs of their employees and emphasize building good interpersonal relationships are:", "options": ["job-centred", "laissez-faire", "employee-oriente d", "task-oriented"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Leaders who focus on employees' individuality, personal needs, and interpersonal relationships are described as employee-oriented (as opposed to job/task-oriented).", "topic": "Management"}, {"id": "pdf3-086", "question": "Leaders that focus on production and the job\u2019s technical aspects are:", "options": ["job-centred", "laissez-faire", "general", "autocratic"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Leaders who emphasize production and the technical aspects of the job are described as job-centered, contrasted with employee-centered leaders.", "topic": "Management"}, {"id": "pdf3-087", "question": "Lakshan sends an encrypted message to Ruhan but it is intercepted by Tanish. Tanish cannot read it but forwards it on to Ruhan from an anonymous address she controls. Which precept of the CIA Triad would have been violated?", "options": ["Confidentiality", "Integrity", "Availability", "Authentication"], "correct": 4, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "This is a classic CIA-triad scenario (Alice/Bob/Trudy style): since Tanish never reads the message, confidentiality is intact, and content is unmodified so integrity holds; but forwarding it from an anonymous address means Ruhan can no longer verify who really sent it, which violates authentication.", "topic": "Information Security"}, {"id": "pdf3-088", "question": "Keerthana solicits input from her subordinates before making decisions that will affect them. She often praises them for good work and gently offers suggestions to improve their performance. Keerthana uses the ________ style of leadership.", "options": ["autocratic", "participative", "democratic", "supportive"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Soliciting subordinates' input before deciding, while coaching and praising performance, is the textbook description of a participative leadership style.", "topic": "Management"}, {"id": "pdf3-089", "question": "Kalam Enterprises recently fired two employees who were caught stealing tools from the firm's warehouse. As a result, the CEO of Kalam wants to strengthen the firm's ethical culture and prevent future violations by redesigning the firm's ethics program. Which of the following questions is the LEAST relevant when developing Kalam's new ethics program?", "options": ["What behaviour is expected of Kalam employees?", "What is the opinion of stakeholders regarding Kalam's ethics?", "How are ethical situations communicated and resolved at Kalam?", "What is the process for Kalam establishing a corporate giving program?"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "When redesigning an ethics program after a theft incident, questions about expected conduct, stakeholder views, and how issues get resolved are directly relevant; a corporate giving program is unrelated to preventing employee misconduct.", "topic": "Business Ethics"}, {"id": "pdf3-090", "question": "Josephus problem is a best example of", "options": ["Singly linked list", "Doubly linked list", "Circular linked list", "All of these"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "The Josephus problem (people arranged in a circle, eliminating every k-th person) is classically modeled using a circular linked list.", "topic": "DSA"}, {"id": "pdf3-091", "question": "It is through ______________ that group members can be inspired, motivated, and guided to be successful and productive.", "options": ["fellowship", "sportsmanship", "coercion", "leadership"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Leadership is the mechanism through which group members are inspired, motivated, and guided toward productive goals.", "topic": "Management"}, {"id": "pdf3-092", "question": "It is possible to use more than one generic data type in a class template, and each generic data type is separated by the ___.", "options": [".", ", (Comma)", ";", "\"\""], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "In C++ class templates with multiple type parameters, each generic type is separated by a comma, e.g. template<class T1, class T2>.", "topic": "C/C++"}, {"id": "pdf3-093", "question": "It is often difficult to estimate size at an early stage in a project when only a specification is available", "options": ["True", "False"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Early in a project, only a specification (not detailed design) is usually available, which makes accurate size estimation genuinely difficult; this statement is true.", "topic": "Software Engineering"}, {"id": "pdf3-094", "question": "it is necessary for a programming language that it must support all these_____ features completely to become a pure Object-Oriented Language.", "options": ["encapsulation, inheritance, and polymorphism", "encapsulation and polymorphism", "Inheritance, and polymorphism", "Encapsulation and inheritance"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A pure object-oriented language must fully support all core OOP pillars together: encapsulation, inheritance, and polymorphism.", "topic": "OOPS"}, {"id": "pdf3-095", "question": "is a placeholder name which will be determined when the class is instantiated.", "options": ["Ttype", "type", "Type", "None"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "The intended concept is that a template parameter (commonly written as 'Type' or 'T') is a placeholder resolved at instantiation, but the option text here ('Ttype') looks garbled/OCR-mangled and the near-duplicate options ('type'/'Type') make the intended choice ambiguous, so the originally marked option is kept.", "topic": "C/C++"}, {"id": "pdf3-096", "question": "Internal premises in planning doesn\u2019t include", "options": ["Money", "Materials", "Machines", "Competitors strategy"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Internal premises are factors within the organization's control (money, materials, machines); competitors' strategy is an external premise, not internal.", "topic": "Management"}, {"id": "pdf3-097", "question": "Interaction Diagram", "options": ["class + Object", "state + Activity", "component + Deployment", "Sequence + collaboration"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "In UML, interaction diagrams are the category comprising sequence diagrams and collaboration (communication) diagrams.", "topic": "Software Engineering"}, {"id": "pdf3-098", "question": "int main(){fork();fork();fork();fork();exit(0);printf(\u201chello\u201d);}How many \u201chello\u201d messages will be printed if the following program is executed?", "options": ["16", "8", "4", "0"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "exit(0) is called immediately after the four fork() calls and before printf, so every process (parent and all children) terminates before reaching the printf statement, printing 'hello' zero times.", "topic": "OS"}, {"id": "pdf3-099", "question": "Institute of Electrical and Electronics Engineers (IEEE) is the largest international professional group. What are the standards developed by this organization?", "options": ["Computing, communication, electrical engineering, and electronics", "Communication, electrical engineering, and electronics", "Electrical engineering and electronics", "Electrical engineering and computing"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "IEEE develops standards spanning computing, communications, electrical engineering, and electronics, reflecting its broad scope as the largest international professional engineering organization.", "topic": "Software Engineering"}, {"id": "pdf3-100", "question": "Information security is the protection of data. Information will be protected mainly based on", "options": ["Its sensitivity to the company", "Its confidentiality", "Its value", "All the above"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Information protection decisions typically weigh sensitivity, confidentiality requirements, and business value together, so 'all the above' is the most complete answer.", "topic": "Information Security"}, {"id": "pdf3-101", "question": "Independent testers are _____________ and identify different defects at the same time.", "options": ["Isolated", "Biased", "Unbiased", "Modular"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Independent testers have no stake in the code they test, so they are unbiased and tend to spot defects the original developers overlook.", "topic": "Software Engineering"}, {"id": "pdf3-102", "question": "In working with his employees, Rahman involves them in decision making and encourages them to participate in deciding their work methods and goals. Rahman\u2019s leadership style can best be described as ________.", "options": ["autocratic", "laissez-faire", "democratic", "participative"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "low", "reasoning": "Involving employees in decisions about work methods and goals is textbook democratic leadership, though 'participative' describes almost the same behavior and different test banks use either term for this exact scenario.", "topic": "Management"}, {"id": "pdf3-103", "question": "In which cache organization, index field is not required during block identification", "options": ["Direct mapping", "set associative", "2-way associative", "fully associative"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A fully associative cache has no fixed index field since any block can go in any line; only tag and offset are used to locate data.", "topic": "CAO"}, {"id": "pdf3-104", "question": "In which attack, text messages (other than email) are used for hacking personal information?", "options": ["Phishing", "Moshing", "Vishing", "Smishing"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Smishing is SMS-based phishing, where text messages are used to trick victims into revealing personal information.", "topic": "Information Security"}, {"id": "pdf3-105", "question": "In which attack, phone calls are used for hacking personal information?", "options": ["Phishing", "Moshing", "Vishing", "Smishing"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Vishing (voice phishing) uses phone calls to trick victims into giving up personal or financial information.", "topic": "Information Security"}, {"id": "pdf3-106", "question": "In which attack, email is used for hacking personal information?", "options": ["Phishing", "Moshing", "Vishing", "Smishing"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Phishing is the classic email-based social engineering attack used to steal personal information.", "topic": "Information Security"}, {"id": "pdf3-107", "question": "In this type of culture the behaviour of individuals are shaped by tradition, loyalty, personal commitment, extensive socialization and self-management", "options": ["Clan", "Market", "Entrepreneurial", "Bureaucratic"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A clan culture is family-like, built on tradition, loyalty, personal commitment, socialization, and self-management rather than rules or markets.", "topic": "Management"}, {"id": "pdf3-108", "question": "In this type of topology data travels only in one direction", "options": ["Bus", "Ring", "Star", "Mesh"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "In a (unidirectional) ring topology each node passes data to its single neighbor in one direction around the loop.", "topic": "CN"}, {"id": "pdf3-109", "question": "In the segment table the segment base contains the ____________", "options": ["starting logical address of the process", "starting physical address of the segment in the memory", "segment offset", "segment length"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The segment base field in a segment table stores the starting physical address where that segment resides in memory; the offset is added to it to get the physical address.", "topic": "OS"}, {"id": "pdf3-110", "question": "In the linked list, each node contains a minimum of two fields. One field is the data field to store the data second field is?", "options": ["Pointer to character", "Pointer to integer", "Pointer to node", "Node"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Besides the data field, a linked list node has a pointer field that stores the address of (points to) the next node in the list.", "topic": "DSA"}, {"id": "pdf3-111", "question": "In the graph traversing, Stack is useful for which searching algorithm?", "options": ["Depth first search", "Breadth first search", "In-order search", "Pre-order search"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "DFS explores as deep as possible along a branch before backtracking, which is naturally implemented using a stack (explicit or via recursion).", "topic": "DSA"}, {"id": "pdf3-112", "question": "In the below function \u201cfactorial\u201d, all automatic variables are stored in #include <stdio.h> int factorial(int i) { if(i <= 1) { return 1; } return i * factorial(i - 1); } main() { printf(\"%d\",factorial(5)); }", "options": ["Array", "Register", "Stack", "Queue"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Each recursive call to factorial() creates a new automatic-variable/activation record that is pushed onto the call stack, and popped off on return.", "topic": "C/C++"}, {"id": "pdf3-113", "question": "In synchronous TDM, for n signal sources of the same data rate, each frame contains _______ slots.", "options": ["n + 1", "n - 1", "0 to n", "n"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "In synchronous TDM each of the n input sources gets exactly one dedicated slot per frame, regardless of whether it has data to send, so a frame has n slots.", "topic": "CN"}, {"id": "pdf3-114", "question": "In segmentation technique, each address is specified by ____________", "options": ["an offset and value", "a value and segment number", "a key and value", "a segment number and offset"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A segmented address is a two-part address consisting of a segment number and an offset within that segment.", "topic": "OS"}, {"id": "pdf3-115", "question": "In regular language pumping lemma, w= mn^io belongs to L then i ranges from?", "options": ["i>=0", "i<=0", "i>=1", "i<0"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The pumping lemma for regular languages states that for w = xy^iz in L, the pumped string stays in L for every i >= 0 (i=0 removes y entirely).", "topic": "TOC"}, {"id": "pdf3-116", "question": "In Mintzberg\u2019s management roles, the role that evaluate the performance of managers in different functions is called", "options": ["Liaison", "Figurehead", "Monitor", "Disseminator"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "The Monitor role involves scanning the organization and environment for information, which includes tracking and evaluating the performance of managers across functions.", "topic": "Management"}, {"id": "pdf3-117", "question": "In Mintzberg\u2019s management roles, the role that describes ethical guidelines and the principles of behavior employees are to follow in their dealings with customers and suppliers is", "options": ["Liaison", "Figurehead", "Monitor", "Disseminator"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "low", "reasoning": "None of the four options is a clean textbook match for setting ethical codes of conduct toward customers and suppliers; Figurehead (symbolic/ceremonial head of the organization) is the closest fit and is kept as marked since the question itself is ambiguous.", "topic": "Management"}, {"id": "pdf3-118", "question": "In Mintzberg\u2019s management roles, the role that coordinates between different departments and establish alliances between different organizations, is termed as", "options": ["Liaison", "Figurehead", "Monitor", "Disseminator"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The Liaison role is specifically about building and maintaining a network of contacts, coordinating across departments, and forming alliances with outside organizations.", "topic": "Management"}, {"id": "pdf3-119", "question": "In memory management , a technique called as paging, physical memory is broken into fixed-sized blocks called ___________.", "options": ["Pages", "Frames", "Blocks", "Segments"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "In paging, physical memory is divided into fixed-size frames, while logical (process) memory is divided into pages of the same size.", "topic": "OS"}, {"id": "pdf3-120", "question": "In interactive environments such as time-sharing systems, the primary requirement is to provide reasonably good response time and in general, to share system resources equitably. In such situations, the scheduling algorithm that is most popularly applied is ________.", "options": ["Shortest Remaining Time Next (SRTN) Scheduling", "Priority Based Preemptive Scheduling", "Round Robin Scheduling", "None of the above"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Round Robin scheduling gives every process a small time quantum in turn, which provides fair, responsive service in interactive time-sharing systems.", "topic": "OS"}, {"id": "pdf3-121", "question": "In India, whose law governs data privacy and information technology?", "options": ["Banking Regulation Act 1949", "IT Act 2000", "Indian Penal Code", "IT (amendment) Act 2008"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The Information Technology Act, 2000 (as amended) is India's primary legislation governing information technology, electronic transactions, and data privacy/security.", "topic": "Privacy & Compliance"}, {"id": "pdf3-122", "question": "In hospitals, the following type of departmentalisation is common -", "options": ["By function", "By committee", "By geographical region", "All of the above"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Hospitals typically organize into departments by specialty/function (cardiology, radiology, surgery, etc.), which is classic functional departmentalization.", "topic": "Management"}, {"id": "pdf3-123", "question": "In his speech the previous day, the new CEO had discussed his experience in the industry and his education. Haripriya thought that the new CEO would do a great job given these characteristics, coupled with his good oratory skills and the fact that he just looked like a CEO. Haripriya realized that she had been judging the new CEO in a manner consistent with the ________ theories of leadership.", "options": ["trait", "behavioural", "contingency", "situational"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Judging a leader based on personal characteristics like experience, education, oratory skill, and appearance reflects trait theory, which attributes leadership to inherent personal qualities.", "topic": "Management"}, {"id": "pdf3-124", "question": "In FIFO page replacement algorithm, when a page must be replaced", "options": ["oldest page is chosen", "newest page is chosen", "random page is chosen", "first page is chosen"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "FIFO page replacement evicts the page that has been resident in memory the longest, i.e., the oldest page, regardless of recent use.", "topic": "OS"}, {"id": "pdf3-125", "question": "In expectancy theory, the belief that effort will lead to performance is termed as", "options": ["Expectancy", "Instrumentality", "Valence", "Values"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "In Vroom's expectancy theory, expectancy is specifically the effort-to-performance belief, i.e. that exerting effort will lead to the desired performance level.", "topic": "Management"}, {"id": "pdf3-126", "question": "In contiguous allocation _____________", "options": ["each file must occupy a set of contiguous blocks on the disk", "each file is a linked list of disk blocks", "all the pointers to scattered blocks are placed together in one location", "none of the mentioned"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Contiguous allocation means each file occupies a set of consecutive blocks on disk, which gives fast sequential and direct access but causes external fragmentation.", "topic": "OS"}, {"id": "pdf3-127", "question": "In CIA Triad, CIA refers to ....", "options": ["Confidentiality, Integrity and Authentication", "Confidentiality, Integrity and Availability", "Confidentiality, Integrity and Accessibility", "Confidentiality, Integrity and Authorization"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "CIA Triad stands for Confidentiality, Integrity, and Availability, the three core goals of information security.", "topic": "Information Security"}, {"id": "pdf3-128", "question": "In Big Five Personality dimensions, a person\u2019s range of interest in new things. Open people are creative, curious, and artistically sensitive, as opposed to being closed-minded is called as", "options": ["Conscientiousness", "Extraversion\u2013Introversion", "Agreeableness", "Openness to Experience"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Openness to Experience is the Big Five dimension describing curiosity, creativity, and receptiveness to new ideas.", "topic": "Management"}, {"id": "pdf3-129", "question": "In Big Five Personality dimensions, the hardworking, diligent, organized, dependable, and persistent behavior of a person is termed as", "options": ["Conscientiousn ess", "Extraversion \u2013Introversio n", "Agreeableness", "Emotional Stability"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Conscientiousness describes hardworking, organized, dependable, and persistent behavior in the Big Five model.", "topic": "Management"}, {"id": "pdf3-130", "question": "In an optical fiber, the inner core is _________ the cladding.", "options": ["less dense than", "denser than", "the same density as", "another name for"], "correct": 2, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "The core of an optical fiber is denser (has a higher refractive index) than the cladding, which is what causes total internal reflection of light within the core.", "topic": "CN"}, {"id": "pdf3-131", "question": "In an inverted page table scheme", "options": ["One page table is used in a system", "One page table for each process is used in a system", "One page table for each file is used in a system", "One page table for each program is used in a system"], "correct": 1, "original_marked": 3, "matches_original": false, "confidence": "high", "reasoning": "An inverted page table uses a single system-wide table with one entry per physical frame (indexed by frame, not process), rather than one table per process or per file.", "topic": "OS"}, {"id": "pdf3-132", "question": "In ABC University, there are several \u2018Departments\u2019 including Computer Science, Information Technology, Mechanical, Civil, Finance and Maintenance. Some departments have students and some are not. If department and student are entity sets in this university database and they are linked through a relationship named DS, which among the following is a partial participation?", "options": ["Participation of department in student", "Participation of department in DS", "Participation of student in department", "Participation of student in DS"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Since some departments have no students, not every department instance participates in DS, making department's participation in the DS relationship partial (while every student must belong to a department, so student's participation is total).", "topic": "DBMS"}, {"id": "pdf3-133", "question": "In a time sharing scheduling algorithm which of the data structure is used?", "options": ["Stack", "Queue", "Linked list", "Circular queue"], "correct": 4, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "Time-sharing systems use Round Robin scheduling, which is implemented with a circular queue so the CPU scheduler can cycle back to the front of the ready list after reaching the end.", "topic": "OS"}, {"id": "pdf3-134", "question": "In a stack, the command to access an nth element from the top of the stack s will be", "options": ["S[Top \u2013n]", "S[Top +n]", "S[top-n-1]", "None of the option"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Using the convention that the top element itself is 0 positions from the top, the nth element from the top of array-based stack S is accessed as S[Top-n].", "topic": "DSA"}, {"id": "pdf3-135", "question": "In a Segmentation scheme, given the logical address (4, 50) and the corresponding base address in the segment table as 5000, what is the physical address mapped to the given logical address?", "options": ["0050", "4050", "5050", "4000"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "In segmentation, the physical address is base + offset, so 5000 (base) + 50 (offset) = 5050.", "topic": "OS"}, {"id": "pdf3-136", "question": "In a reactive approach, the bulk of the test design work begins __________", "options": ["Before any software is made", "After some modules are completed", "After every module, testing is done", "After the software has been produced"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "In a reactive testing approach, test design work only begins in earnest after the software has already been produced, in contrast to a proactive approach where tests are designed early.", "topic": "Software Engineering"}, {"id": "pdf3-137", "question": "In a Paging scheme with page sizes of 1K, given the logical address (2, 35) and the corresponding frame number in the page table as 4, what is the physical address mapped to the given logical address?", "options": ["5131", "2030", "2083", "4131"], "correct": 4, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "Physical address = frame_number * page_size + offset = 4*1024 + 35 = 4131; the page number is only used to look up the frame, not in the final address.", "topic": "OS"}, {"id": "pdf3-138", "question": "In a Page replacement algorithm, which of the following type of page is the best page to replace.", "options": ["not recently used but modified", "recently used but clean", "neither recently used nor modified", "recently used and modified"], "correct": 3, "original_marked": 4, "matches_original": false, "confidence": "high", "reasoning": "The best page to evict is one that is both not recently used and not modified (clean), since it requires no write-back and is unlikely to be needed soon; a page that is recently used and modified is actually the worst choice to replace.", "topic": "OS"}, {"id": "pdf3-139", "question": "In a circular queue, the value of r will be", "options": ["r=r+1", "r=(r+1)%[queue_ size-1]", "r=(r+1)%queue_s ize", "r=(r-1)%queue_si ze"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "In a circular queue the rear pointer wraps around using modulo arithmetic: r = (r+1) % queue_size.", "topic": "DSA"}, {"id": "pdf3-140", "question": "In ___________ each component at lower hierarchy is tested individually and then the components that rely upon these components are tested.", "options": ["Top down testing", "Unit testing", "Bottom up", "Load testing"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Bottom-up testing tests lower-level components first, then progressively tests the higher-level components that depend on them.", "topic": "Software Engineering"}, {"id": "pdf3-141", "question": "In _______ transmission, the channel capacity is shared by both communicating devices at all times.", "options": ["simplex", "half-duplex", "full-duplex", "half-simplex"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "In full-duplex transmission both devices can send and receive simultaneously, so the channel capacity is shared by both devices at all times (unlike half-duplex, where they take turns).", "topic": "CN"}, {"id": "pdf3-142", "question": "In MAC Tuples ,Process can read object when: Object MAC range (lr, hr); process MAC label pl", "options": ["\u2140 pl (lr, hr)", "pl U (lr, hr)", "pl (lr, hr) \u2208", "pl dom hr"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "low", "reasoning": "The notation in this MAC-tuple question is garbled/illegible (special symbols didn't render), so the intended read access rule can't be confirmed independently; deferring to the source's marked answer.", "topic": "Information Security"}, {"id": "pdf3-143", "question": "Imposing a total ordering of all resource types, and ensuring process requests resources in an increasing order of enumeration voilates the _______________ condition for deadlock", "options": ["Mut ual excl usi on", "Hol d and Wai t", "Circ ular Wai t", "No Pre em ptio n"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Forcing a total ordering on resource types and requiring processes to request them in increasing order prevents a cycle from forming, which is exactly how the circular wait condition for deadlock is eliminated.", "topic": "OS"}, {"id": "pdf3-144", "question": "If there is a unique LMD , the grammar is", "options": ["ambiguous", "un ambiguous", "LLG", "RLG"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A grammar with a unique leftmost derivation (and unique parse tree) for every string it generates is by definition unambiguous.", "topic": "TOC"}, {"id": "pdf3-145", "question": "If there is a complete DFA M1 recognizing a language L1 and has m states out of which two are final states then the machine M recognizing L1 complement will have _____________ final states.", "options": ["m", "m+2", "2", "m-2"], "correct": 4, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "Complementing a DFA swaps final and non-final states, so the new number of final states equals the old number of non-final states: m - 2.", "topic": "TOC"}, {"id": "pdf3-146", "question": "If the stringent regulations on the operational procedures exist, the project is considered as Semi -detached", "options": ["True", "False"], "correct": 2, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "In the COCOMO model, stringent regulations on operational procedures (along with strong hardware coupling) characterize the Embedded mode, not the Semi-detached mode, so the statement is False.", "topic": "Software Engineering"}, {"id": "pdf3-147", "question": "If the data transfers are done asynchronously, which of the data structure is possible?", "options": ["Stack", "Queue", "Linked list", "All of these"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "low", "reasoning": "The question is vague, but a queue (FIFO buffer) is the conventional data structure used to hold data arriving asynchronously until it can be processed; deferring to the source's marked answer given the ambiguity.", "topic": "CAO"}, {"id": "pdf3-148", "question": "If the characters 'D' 'C' 'B' 'A' are placed in a queue (in that order), and then removed one at a time, in what order will they be removed?", "options": ["DCAB", "ABCD", "ABDC", "DCBA"], "correct": 4, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "A queue is FIFO, so items come out in the same order they went in: D was inserted first and is removed first, giving DCBA (ABCD would be the answer only for a stack, which is LIFO).", "topic": "DSA"}, {"id": "pdf3-149", "question": "R is a regular language and M is a finite language then L U M must be regular language", "options": ["True", "False", "Can't determined", "Neither True and Nor False"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Every finite language is regular, and regular languages are closed under union, so the union of a regular language and a finite language is always regular.", "topic": "TOC"}, {"id": "pdf3-150", "question": "If M1 machine recognizing L with n states, then M2 recognizing L* constructed Using Thompson construction will have ------------- states.", "options": ["n-1", "n+2", "n+1", "n"], "correct": 2, "original_marked": 3, "matches_original": false, "confidence": "high", "reasoning": "Thompson's construction for the Kleene star of an n-state NFA adds exactly two new states (a new start state and a new accepting state) wired with epsilon transitions, giving n+2 states total.", "topic": "TOC"}, {"id": "pdf3-151", "question": "If L1 and L2 are languages such that L2, L1L2, and L2L1 are all regular, then L1 must be regular.", "options": ["True", "False", "Can't determined", "Neither True and Nor False"], "correct": 2, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "False: take L2 = the empty language; then L1L2 = L2L1 = the empty set (regular) for ANY L1 at all, including non-regular ones, so L1 need not be regular.", "topic": "TOC"}, {"id": "pdf3-152", "question": "If L1 and L2 are CFL and R a regular set, one of the languages below is not necessarily a CFL. which one?", "options": ["L1nL2", "L1nR", "L1L2", "L1UL2"], "correct": 1, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "CFLs are closed under union, concatenation, and intersection with a regular set, but NOT under intersection with another CFL, so L1\u2229L2 is the one that need not be a CFL.", "topic": "TOC"}, {"id": "pdf3-153", "question": "If an item is referenced once, then it again be referenced soon; given statement is stated by", "options": ["Temporary locality", "Spatial locality", "Temporal locality", "Spectral Locality"], "correct": 3, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "This is the definition of temporal locality: a recently accessed item is likely to be accessed again soon. 'Temporary locality' is just a distractor with no real meaning.", "topic": "CAO"}, {"id": "pdf3-154", "question": "If a selection sort algorithm in the worst case is taking 20sec for processing an array of size 32. Which of the following is close to the maximum input size that can be solved in 5 minutes?", "options": ["256", "512", "1024", "128"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Selection sort is O(n^2), so time constant k = 20/32^2; solving k*n^2=300 gives n \u2248 sqrt(300*1024/20) \u2248 124, which is closest to 128.", "topic": "DSA"}, {"id": "pdf3-155", "question": "If a problem can be broken into subproblems that are reused several times", "options": ["Overlapping subproblems", "Optimal substructure", "Memoization", "Greedy"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "When a problem's subproblems recur multiple times (as opposed to being solved only once each), that property is called overlapping subproblems, the hallmark that makes memoization/DP useful.", "topic": "DSA"}, {"id": "pdf3-156", "question": "Identity and Access Management (IdAM) is for ...", "options": ["Storing multiple passwords", "Protecting multiple data", "Providing Data Leakage Prevention", "Providing Data Leakage in cloud"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "low", "reasoning": "The options are all loosely worded; IAM's core purpose is controlling who can access which resources/data, which best fits 'protecting multiple data' among these weak choices, but none of the options is a textbook-precise definition.", "topic": "Information Security"}, {"id": "pdf3-157", "question": "Identify which one feature explains Indian Ethos.", "options": ["Belief in Ego Assertion.", "Spirit of Sacrifice and Self Control", "Emphasis on Individual Achievement", "Your Status defines your Character"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Indian Ethos in management emphasizes spirituality, self-control, and sacrifice for the collective good, unlike Western ideas centered on individual ego/status/achievement.", "topic": "Business Ethics"}, {"id": "pdf3-158", "question": "Identify the organisational risk from the following", "options": ["Software components which should be reused contain defects which limit their functionality", "Required training for staff is not available", "Customers fail to understand the impact of requirements changes", "None in the list"], "correct": 4, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "In the standard risk classification (Sommerville), reused-component defects is a technology risk, lack of training is a people risk, and customers misunderstanding changes is a requirements risk; true organisational risks (e.g. restructuring, budget cuts) aren't listed, so the answer is 'None in the list'.", "topic": "Software Engineering"}, {"id": "pdf3-159", "question": "Identify the model which is not coming under the four categories of access control models?", "options": ["Discretionary", "Mandatory", "Role-based", "Delegated"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "The four classic access control models are Discretionary (DAC), Mandatory (MAC), Role-based (RBAC), and Attribute/Rule-based \u2014 'Delegated' is not one of the standard four categories.", "topic": "Information Security"}, {"id": "pdf3-160", "question": "Human Relations School is related to", "options": ["Elton Mayo", "Henry Fayol", "F W Taylor", "Max Weber"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The Human Relations School of management grew out of Elton Mayo's Hawthorne studies, which highlighted social/psychological factors in worker productivity.", "topic": "Management"}, {"id": "pdf3-161", "question": "How often should your data be backed up?", "options": ["In accordance with your organization\u2019s backup policy", "Once a fortnight.", "Once a month.", "Once a week."], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Backup frequency is not a fixed universal number; it should follow whatever schedule the organization's own backup policy specifies based on its data criticality and recovery needs.", "topic": "Information Security"}, {"id": "pdf3-162", "question": "How many \u201cSCOPE\u201ds are printed?, how many \u201cSCOPE\u201ds are printed by only child processes? int main() { if(fork() || fork()) fork(); printf(\"SCOPE\"); }", "options": ["5,2", "5,3", "5,4", "5,1"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Tracing fork() with || (short-circuit OR) produces 5 total processes (1 original + 4 children), and since all forking after the original happens in child branches too, exactly 4 of the 5 prints come from child processes.", "topic": "C/C++"}, {"id": "pdf3-163", "question": "How many \u201cSCOPE\u201ds are printed?, how many \u201cSCOPE\u201ds are printed by only child processes? int main() { if(fork() && fork()) fork(); printf(\"SCOPE\"); } Answer is 4,3 according to me", "options": ["5,2", "5,3", "5,4", "5,1"], "correct": 2, "original_marked": null, "matches_original": false, "confidence": "low", "reasoning": "Tracing fork() with && (short-circuit AND) actually yields 4 total processes and 3 by children (matching the handwritten note '4,3'), but that pair isn't among the listed options at all; '5,3' is picked as the closest available option since it at least gets the child count right, so treat this one with caution.", "topic": "C/C++"}, {"id": "pdf3-164", "question": "How many \u201chello\u201d messages will be printed if the following program is executed? int main() { pid_t p; fork(); if (p >0) { fork(); fork(); } if (p==0) { fork(); fork(); exit(0); } printf(\u201chello\u201d); }", "options": ["2", "3", "1", "4"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "The variable p is declared but never assigned (fork()'s return value is discarded, not stored in p), so both if-conditions rely on an indeterminate/garbage value; treating both ifs as not reliably triggering leaves only the initial fork(), giving 2 prints, but this hinges on an ambiguous undefined-behavior assumption.", "topic": "C/C++"}, {"id": "pdf3-165", "question": "How many \u201chello\u201d messages will be printed if the following program is executed? int main() { pid_t p; fork(); if (p >0) { fork(); fork(); exit(0); } if (p==0) { fork(); fork(); exit(0); } printf(\u201chello\u201d); }", "options": ["1", "3", "0", "4"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "low", "reasoning": "Like the previous question, p is never assigned so its value is indeterminate, making the two if-branches unreliable to trace definitively; deferring to the marked answer (0) since the question's correctness hinges on an assumption about undefined behavior.", "topic": "C/C++"}, {"id": "pdf3-166", "question": "How many undirected graphs (not necessarily connected) can be constructed out of a given set V = {v1, v2, ... vn} of n vertices?", "options": ["n(n-1)/2", "2^n", "2n!", "2^(n(n-1)/2)"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "With n vertices there are n(n-1)/2 possible edges, and each edge can independently be present or absent, giving 2^(n(n-1)/2) distinct undirected graphs.", "topic": "DSA"}, {"id": "pdf3-167", "question": "How many principles of the Data Protection Act are there?", "options": ["8", "5", "6", "7"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The (UK) Data Protection Act 1998 defines 8 data protection principles governing fair, lawful, and secure processing of personal data.", "topic": "Privacy & Compliance"}, {"id": "pdf3-168", "question": "How many minimum no of stack is required for the runtime executable script", "options": ["1", "2", "3", "4"], "correct": 1, "original_marked": null, "matches_original": false, "confidence": "low", "reasoning": "The question is garbled/unclear, but a single runtime stack is generally the minimum needed to manage function calls/execution context for a running script, so 1 is the best guess among the options.", "topic": "OS"}, {"id": "pdf3-169", "question": "How many address lines are needed to address each memory locations in a 2048 x 4 memory chip?", "options": ["10", "12", "11", "8"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "2048 = 2^11 locations, so 11 address lines are needed to uniquely address each location; the '4' just describes the word width (data lines), not address lines.", "topic": "CAO"}, {"id": "pdf3-170", "question": "How many rounds are there in DES?", "options": ["15", "8", "64", "16"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "DES (Data Encryption Standard) applies its Feistel round function 16 times to encrypt a block.", "topic": "Information Security"}, {"id": "pdf3-171", "question": "How does your personal computer (end device/host) recognize its IP address and the Gateway IP address to use for transmitting packets to remote hosts without any manual configuration when you connect it to the internet?", "options": ["A. DNS (Domain Name System)", "A. ARP (Address Resolution Protocol)", "A. DHCP (Dynamic Host Configuration Protocol)", "A. FTP (File transfer protocol)"], "correct": 3, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "DHCP automatically assigns a host its IP address, subnet mask, and default gateway when it joins a network, with no manual configuration needed; ARP only resolves a known IP to a MAC address on the local link.", "topic": "CN"}, {"id": "pdf3-172", "question": "Hospitals, banks, and supermarkets are all linked using which network type?", "options": ["WAN", "LAN", "BUS", "WiFi"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Hospitals, banks, and supermarkets with branches spread across a city/country/globe are interconnected over large geographic distances, which is what defines a WAN.", "topic": "CN"}, {"id": "pdf3-173", "question": "Hofstede\u2019s framework is regarding", "options": ["Personality", "Culture", "Perception", "Stereotype"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Hofstede's framework is a model of national/organizational culture, defined by dimensions like power distance, individualism, and uncertainty avoidance.", "topic": "Management"}, {"id": "pdf3-174", "question": "Hit-rate of the processor is the memory fraction, found in", "options": ["DRAM", "SRAM", "Magnetic disk", "Cache"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Hit rate is the fraction of memory accesses satisfied by the cache (as opposed to going to main memory), so it's a cache-specific metric.", "topic": "CAO"}, {"id": "pdf3-175", "question": "Hiding internal data from the outside world and accessing it only through publicly exposed methods is known as data", "options": ["inheritance", "polymorphism", "abstraction", "encapsulation"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Hiding internal implementation details and exposing only public methods to interact with an object is the definition of encapsulation in OOP.", "topic": "OOPS"}, {"id": "pdf3-176", "question": "Harsha Electronics has used several methods to create an ethical culture that both employees and customers appreciate. What is the most effective way for the firm to sustain its ethical culture?", "options": ["asking job candidates ethical questions", "implementing an ethics audit regularly", "publishing the firm's code of ethics periodically", "ensuring that new employees receive ethics training"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Sustaining (as opposed to just creating) an ethical culture requires ongoing monitoring, which is exactly what a regular ethics audit provides; one-time actions like publishing a code or screening candidates don't keep checking whether the culture is actually holding up.", "topic": "Business Ethics"}, {"id": "pdf3-177", "question": "Hardware, Personnel ,Facility are not the factors of Cost", "options": ["True", "False"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Hardware, personnel, and facilities are all standard cost factors in project/software cost estimation, so the statement that they are 'not' cost factors is False.", "topic": "Software Engineering"}, {"id": "pdf3-178", "question": "Hardware unavailability risk is the _________ type of risk", "options": ["Project", "Product", "Business", "None in the list"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "In Pressman's risk taxonomy, project risks are those that threaten the project plan/schedule (e.g., staffing changes, budget cuts, hardware that doesn't arrive on time), so hardware unavailability is classified as a project risk, not a product or business risk.", "topic": "Software Engineering"}, {"id": "pdf3-179", "question": "Hardware solution to the critical section problem using test&set while (true) { while ( TestAndSet (&lock )); /* do nothing // critical section lock = FALSE; // remainder section }", "options": ["Implements mutual exclusion and progress", "Implements only mutual exclusion", "Implements progress and bounded waiting.", "Implements mutual exclusion and bounded waiting."], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The basic TestAndSet busy-wait solution guarantees mutual exclusion (only one process can see the lock as free at a time) and progress (the lock is granted immediately once free), but it can starve a specific process indefinitely, so it fails bounded waiting.", "topic": "OS"}, {"id": "pdf3-180", "question": "Hardware solution to the critical section problem using swap: while(true) {key = TRUE; while(key==TRUE) Swap(&lock,&key); //critical sectionlock = FALSE; //remainder section}", "options": ["Implements mutual exclusion and progress", "Implements only mutual exclusion", "Implements progress and bounded waiting.", "Implements mutual exclusion and bounded waiting."], "correct": 1, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "The Swap-based solution shown is structurally identical to the TestAndSet solution (same busy-wait loop pattern), so per standard OS textbooks (Silberschatz et al.) it also satisfies mutual exclusion and progress but not bounded waiting -- the source PDF's marked answer ('only mutual exclusion') is inconsistent with the correct answer it gave for the equivalent TestAndSet question.", "topic": "OS"}, {"id": "pdf3-181", "question": "Guess the output. #include<stdio.h> #include<string.h> main(){ char Be[16]=\"Positive \"; char Positive[16]=\"Be \"; strcat(Be,Positive); printf(\"%s\",Be ); }", "options": ["Be", "Positive", "Positive Be", "Be Positive"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "strcat(Be, Positive) appends the contents of Positive (\"Be \") onto the end of Be (\"Positive \"), producing \"Positive Be \", which prints as \"Positive Be\".", "topic": "C/C++"}, {"id": "pdf3-182", "question": "Guess the output #include<stdio.h> main(){ int value=100; myFunction(value); } void myFunction(int parameter) { parameter=200; printf(\"%d\", parameter); }", "options": ["100", "200", "100 200", "Error"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "C passes arguments by value, so myFunction gets a copy of value; it sets its local parameter to 200 and prints it inside the function, giving output 200 (main never prints anything itself).", "topic": "C/C++"}, {"id": "pdf4-001", "question": "Guess the output #include<stdio.h> main(){ int a=100; int b=200; int c[1][2][3]={&a}; c[1][1][1]=&b; printf(\"%d\",c[1][1][1]); }", "options": ["200", "100", "a. Address of variable a", "a. Address of variable b"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "low", "reasoning": "The code has out-of-bounds array access and an implicit pointer-to-int assignment (undefined behavior), but read literally, c[1][1][1] is assigned &b, so printing it shows the address of variable b.", "topic": "C/C++"}, {"id": "pdf4-002", "question": "Guess the output of the following #include main(){ typedef char arr[4]; arr arr1[4]; printf(\"%d\",sizeof(arr1)); }", "options": ["Error", "4", "44", "16"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "arr1 is declared as an array of 4 elements of type arr (char[4]), so sizeof(arr1) = 4 * 4 = 16 bytes.", "topic": "C/C++"}, {"id": "pdf4-003", "question": "Guess the output of the below code #include<stdio.h> int myFunction1(int parameter) { return parameter; } int myFunction2(int *parameter) { return ++*parameter; } main(){ int value=100; printf(\"%d %d\", myFunction1(value), myFunction2(&value)); }", "options": ["100 100", "101 100", "100 101", "101 101"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "low", "reasoning": "The order of evaluation of function call arguments in C is unspecified; assuming the common left-to-right teaching convention, myFunction1(100) prints 100 before value is incremented, then myFunction2 increments and returns 101, giving \"100 101\" \u2014 but a right-to-left evaluating compiler would give a different result.", "topic": "C/C++"}, {"id": "pdf4-004", "question": "Greetwell Technologies wants to gain the confidence of employees and customers by developing a strong ethical culture. Which of the following methods would be the best way for the firm's HR department to accomplish this goal?", "options": ["placing the code of ethics on the firm's intranet", "posting the code of ethics in the breakroom", "providing ethics training to employees", "having employees sign ethics contracts"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Formal ethics training actively teaches employees how to apply the code in real situations, which builds a stronger ethical culture than merely posting or signing a document.", "topic": "Business Ethics"}, {"id": "pdf4-005", "question": "Given grammar G as follows: G { S --> aB | B --> Sb } This grammar is", "options": ["regular and context-free", "not regular and not context-free", "regular, but not context-free", "context-free, but not regular"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "This mirrors the classic S\u2192aB, B\u2192Sb|b grammar that generates a^n b^n, which is context-free but provably not regular (it fails the pumping lemma for regular languages).", "topic": "TOC"}, {"id": "pdf4-006", "question": "Given five memory partitions of 200Kb, 500Kb, 200Kb, 300Kb, 600Kb (in order), which algorithm would be able to successfully place the following processes of 212 Kb, 417 Kb, 112 Kb, and 126 Kb?", "options": ["Best Fit", "Worst Fit", "First Fit", "All the given choices."], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Simulating placement of processes 212, 417, 112, 126 into partitions 200, 500, 200, 300, 600 shows First Fit, Best Fit, and Worst Fit can all successfully place every process for this specific set.", "topic": "OS"}, {"id": "pdf4-007", "question": "Given five memory partitions of 100Kb, 500Kb, 200Kb, 300Kb, 600Kb (in order), which algorithm would be able to successfully place the following processes of 212 Kb, 417 Kb, 112 Kb, and 426 Kb?", "options": ["Best Fit", "Worst Fit", "First Fit", "All the given choices."], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Simulating each algorithm shows only Best Fit places all four processes (212\u2192300Kb, 417\u2192500Kb, 112\u2192200Kb, 426\u2192600Kb); First Fit and Worst Fit both exhaust the large partitions early and can't fit the 426Kb process.", "topic": "OS"}, {"id": "pdf4-008", "question": "Given an arbitrary non-deterministic finite automaton (NFA). with N states, the maximum number of states in an equivalent minimized DFA is at least.", "options": ["2N", "N!", "2^N", "N^2"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "By the standard subset construction, an NFA with N states can require up to 2^N states in the equivalent (worst-case) minimized DFA.", "topic": "TOC"}, {"id": "pdf4-009", "question": "Generic functions perform ____ operation for all the versions of a function except the data type differs", "options": ["A. Different", "A. Same", "A. Similar", "A. None"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Generic (template) functions execute identical logic for every type they're instantiated with \u2014 only the data type parameter changes, not the operation performed.", "topic": "C/C++"}, {"id": "pdf4-010", "question": "Frustration-Regression is related to", "options": ["Maslow\u2019s Hierarchy", "ERG theory", "Justice Theory", "Equity theory"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Frustration-regression is a defining principle of Alderfer's ERG theory: failure to satisfy a higher-level need causes a person to regress and re-focus on a lower-level need.", "topic": "Management"}, {"id": "pdf4-011", "question": "Frames from one LAN can be transmitted to another LAN via the device", "options": ["Router", "Bridge", "Repeater", "Modem"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A bridge operates at the data-link layer and forwards frames between two LAN segments, which is exactly what's described.", "topic": "CN"}, {"id": "pdf4-012", "question": "Frames from one LAN can be transmitted to another LAN via the device", "options": ["Router", "Bridge", "Repeater", "Modem"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Duplicate of the previous question \u2014 a bridge is the layer-2 device that forwards frames between LANs.", "topic": "CN"}, {"id": "pdf4-013", "question": "For every pair of regular expressions r and s, the languages denoted by r(sr)* and (rs)*r are the same.", "options": ["True", "False", "Can't determined", "Neither True and Nor False"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Expanding both expressions for increasing n (e.g., r, rsr, rsrsr, ...) shows r(sr)^n and (rs)^n r always produce the same alternating string, so the identity holds \u2014 this is a well-known regex equivalence.", "topic": "TOC"}, {"id": "pdf4-014", "question": "For every ....grammar there is equivalent grammar for the same language which is .....", "options": ["ambiguous grammar, un ambiguous grammar", "un ambiguous grammar, ambiguous grammar", "ambiguous grammar, ambiguous grammar", "un ambiguous grammar, un ambiguous grammar"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "low", "reasoning": "This fill-in-the-blank is ambiguously worded and the general claim is complicated by the existence of inherently ambiguous context-free languages (which have no unambiguous grammar at all), so deferring to the source's marked answer.", "topic": "TOC"}, {"id": "pdf4-015", "question": "For declaring function templates, __ arguments in template declaration must be generic (class T).", "options": ["all", "Any one", "One", "none"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Standard C++ textbook rule: in a function template declaration, all template parameters must be generic (class T) types.", "topic": "C/C++"}, {"id": "pdf4-016", "question": "For declaring class templates, ___ of the arguments in template declaration may be non-generic ordinary data types.", "options": ["Some", "all", "None of the argument", "One"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Unlike function templates, a class template declaration can mix generic type parameters with some ordinary (non-generic) data type parameters.", "topic": "C/C++"}, {"id": "pdf4-017", "question": "For any two functions g(n) and f(n), f(n) = Q(g(n)) iff", "options": ["f(n) = O(g(n)) and f(n) = W(g(n))", "f(n) > O(g(n)) and f(n) = W(g(n))", "f(n) = O(g(n)) and f(n) =>W(g(n))", "None of these"], "correct": 1, "original_marked": null, "matches_original": false, "confidence": "high", "reasoning": "By definition, f(n) = \u0398(g(n)) if and only if f(n) = O(g(n)) AND f(n) = \u03a9(g(n)) \u2014 g(n) must simultaneously be an asymptotic upper and lower bound on f(n).", "topic": "DSA"}, {"id": "pdf4-018", "question": "Finite automata recognizes --------grammars", "options": ["type-3", "type-1", "type-2", "type-0"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Finite automata exactly recognize the type-3 (regular) grammars in the Chomsky hierarchy.", "topic": "TOC"}, {"id": "pdf4-019", "question": "Finite automata --------------- memory", "options": ["Infinite", "No auxiliary memory", "Finite", "auxiliary memory"], "correct": 2, "original_marked": 4, "matches_original": false, "confidence": "low", "reasoning": "Finite automata are defined as having no auxiliary memory (unlike a PDA's stack or a Turing machine's tape); the source's highlighted option ('auxiliary memory' alone, without 'no') looks like a marking slip on this garbled fill-in-the-blank.", "topic": "TOC"}, {"id": "pdf4-020", "question": "Find the shortest path from the root to a given node v. Which algorithm would one use to find this shortest path?", "options": ["DFS", "BFS", "Either BFS or DFS", "The statement is incomplete"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "low", "reasoning": "BFS finds shortest path from a root in an unweighted graph, but the question never states whether edges are weighted, so strictly the question is under-specified \u2014 a genuinely ambiguous question, so deferring to the source's marked answer.", "topic": "DSA"}, {"id": "pdf4-021", "question": "Find the correct syntax of throw statement:", "options": ["throw (exception);", "throw exception;", "throw;", "All of the above"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "throw(exception);, throw exception; and throw; (bare rethrow) are all valid C++ throw statement forms.", "topic": "C/C++"}, {"id": "pdf4-022", "question": "Find the correct statement(s) (i). A try block can throw an exception using \u201cthrow\u201d (ii). A catch block always catch and handle the exception and never ever throws the exception. (iii). A catch also sometimes throws the exception using \u201cthrow\u201d", "options": ["only (i)", "only (i) and (iii)", "only (ii) and (iii)", "(i), (ii) and (iii)"], "correct": 2, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "A try block can raise an exception with throw (i, true) and a catch block can rethrow using throw; (iii, true); statement ii is false because catch blocks are not required to always fully handle an exception and never rethrow it.", "topic": "C/C++"}, {"id": "pdf4-023", "question": "Find out the true statement(s) from the following: (i). Virtual constructors are not at all possible. (ii). It is possible to have virtual destructor without virtual constructors. (iii). Both virtual constructors and virtual destructors are not possible in C++. (iv). Only Virtual constructors are allowed; but not virtual destructors.", "options": ["(i) and (ii) only", "(i) only", "(iii) only", "(iv) only"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Constructors can never be declared virtual in C++, but destructors can be virtual independently of the constructor, so both (i) and (ii) are true statements.", "topic": "OOPS"}, {"id": "pdf4-024", "question": "Find out the incorrect statement(s). (i). There are only predefined exception handling mechanism available in C++ (ii). User-defined exception handling is possible in C++ (iii). Both (i) and (ii) is possible in C++", "options": ["(i) and (ii) only", "(i) only", "(iii) only", "None of the above"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "low", "reasoning": "The statements are ambiguously phrased, especially (iii) 'both (i) and (ii) is possible', making it unclear exactly which combination the question intends as incorrect, so deferring to the source's marked answer.", "topic": "C/C++"}, {"id": "pdf4-025", "question": "Find out the incorrect statement(s) (i). pure virtual functions should be defined in derived class. (ii). virtual function concept can be implemented even without inheritance. (iii). the keyword \u201cvirtual\u201d prevents compile-time binding", "options": ["(ii) and (iii) only", "(i) and (iii) only", "(iii) only", "(ii) only"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "low", "reasoning": "Each sub-statement is individually debatable (a pure virtual function isn't strictly required to be overridden in the immediate derived class, and 'prevents compile-time binding' is a defensible description of how virtual enables late binding), making this a genuinely ambiguous combination question, so deferring to the source's marked answer.", "topic": "OOPS"}, {"id": "pdf4-026", "question": "F.W. Taylor has done the following studies for improving the production process:", "options": ["Time Study, Fatigue Study and Fatal Study.", "Time Study, Motion Study and Fatal Study.", "Time Study, Motion Study and Fatigue Study.", "Time Study, Motivation Study and Fatigue Study."], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "F.W. Taylor's scientific management introduced Time Study, Motion Study, and Fatigue Study to improve production processes.", "topic": "Management"}, {"id": "pdf4-027", "question": "Exhaustive testing is__________________?", "options": ["always possible", "practically possible", "impractical but possible", "impractical and impossible"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Exhaustive testing is theoretically possible but practically infeasible for any non-trivial program because of the combinatorial explosion of input/path combinations.", "topic": "Software Engineering"}, {"id": "pdf4-028", "question": "Executives and managers at ABC Enterprises actively encourage a strong ethical culture at the firm. Which of the following would be the most likely result of the firm's actions?", "options": ["increased employee interest in development programs", "frequent use of human resource information systems", "changes in corporate communication methods", "improvements in organizational performance"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A strong ethical culture is linked to better employee conduct, trust, and decision-making, which translates into improved organizational performance.", "topic": "Business Ethics"}, {"id": "pdf4-029", "question": "Exceptions are\u2026\u2026..", "options": ["Syntax error", "Logic error", "Compile time error", "Run time error"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Exceptions are unexpected conditions detected during program execution, so they are classified as run-time errors (not caught at compile time).", "topic": "OOPS"}, {"id": "pdf4-030", "question": "Exception handling is the correlation between \u2026\u2026\u2026\u2026\u2026\u2026\u2026", "options": ["try and catch block", "retry and recatch block", "both (a) and (b)", "Neither (a) nor (b)"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Exception handling works by placing risky code in a try block and handling the thrown exception in a corresponding catch block.", "topic": "OOPS"}, {"id": "pdf4-031", "question": "Example for Associative type of memory", "options": ["Main Memory", "Cache Memory", "Magnetic", "Optical"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Cache memory is commonly implemented using associative (content-addressable) memory so that any stored address can be searched in parallel.", "topic": "CAO"}, {"id": "pdf4-032", "question": "Every weak entity set can b", "options": ["Using generalization", "Adding appropriate attributes", "Using aggregation", "None of the above"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A weak entity set can be converted into a strong entity set by adding appropriate key attributes so it no longer depends on another entity for identification.", "topic": "DBMS"}, {"id": "pdf4-033", "question": "Every context free language is context sensitive language", "options": ["True", "False", "nothing", "True and False"], "correct": 1, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "In the Chomsky hierarchy, context-free languages are a proper subset of context-sensitive languages, so the statement is True, not False as marked.", "topic": "TOC"}, {"id": "pdf4-034", "question": "Event based modelling in UML", "options": ["Activity Diagram", "State Diagram", "Class Diagram", "Object Diagram"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "UML's State (state-transition) diagram models event-driven behavior, showing how an object's state changes in response to events.", "topic": "Software Engineering"}, {"id": "pdf4-035", "question": "Evaluate the following prefix expression * - + 4 3 5 / + 2 4 3", "options": ["8", "4", "1", "None"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Evaluating step by step: (+4 3)=7, (7-5)=2 for the left operand, and (+2 4)=6, (6/3)=2 for the right operand, so *2 2 = 4.", "topic": "DSA"}, {"id": "pdf4-036", "question": "Evaluate the following postfix expression 1 4 1 8 6 / 3 + + 5 / +", "options": ["2", "8", "3", "None"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "The expression has 7 operands but only 5 operators (one short of the 6 needed), so it is malformed and cannot reduce to a single valid value like 2, 8, or 3 \u2014 the answer is None.", "topic": "DSA"}, {"id": "pdf4-037", "question": "Ethics training should ________.", "options": ["start at the bottom and move upward through all organizational levels.", "focus only on the employees who deal with the public on a day-to-day basis.", "begin at the top and continue through all levels of the organization.", "start with mid-level management and move laterally through the organization."], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Ethics training is most effective when top management visibly commits first, setting the tone that then cascades through all organizational levels.", "topic": "Business Ethics"}, {"id": "pdf4-038", "question": "Esprit de corps refers to", "options": ["Team work and cooperation", "A Single Boss", "Flexibility", "None of these"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Esprit de corps, one of Fayol's 14 principles of management, emphasizes team spirit, harmony, and cooperation among employees.", "topic": "Management"}, {"id": "pdf4-039", "question": "Environmental protection can best be done by the efforts of ____________.", "options": ["business people.", "the scientists.", "the government.", "all the people."], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Environmental protection is a shared responsibility that requires collective action from all people, not just businesses, scientists, or government alone.", "topic": "Business Ethics"}, {"id": "pdf4-040", "question": "Ensuring processes request resources only if all resources are available in the system, violates the _______________ condition of deadlock", "options": ["Mutual exclusion", "Hold and Wait", "Circular Wait", "No Preemption"], "correct": 2, "original_marked": null, "matches_original": false, "confidence": "high", "reasoning": "Hold and Wait prevention requires a process to request and be allocated all the resources it needs at once, so it never holds some while waiting for others.", "topic": "OS"}, {"id": "pdf4-041", "question": "End-to-end connectivity is provided from host-to-host in:", "options": ["Network layer", "Session layer", "Transport layer", "Datalink layer"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "The Transport layer (e.g., TCP/UDP) provides end-to-end, host-to-host connectivity and reliable data delivery between applications.", "topic": "CN"}, {"id": "pdf4-042", "question": "Empty stack top pointer indicates to", "options": ["Last memory location", "Set to 1", "Set to -1", "Beginning of memory location"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "By convention, the top pointer of an empty stack is initialized to -1, signaling that no elements are currently present.", "topic": "DSA"}, {"id": "pdf4-043", "question": "Effort is mostly used to estimate______________", "options": ["Project resource costs", "Project duration", "Remaining calendar time", "Contingencies"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "low", "reasoning": "This question is ambiguously worded in the source; effort estimates feed into both cost and duration calculations, so the original 'project duration' answer is kept but not fully certain.", "topic": "Software Engineering"}, {"id": "pdf4-044", "question": "Effort Adjustment Factor is the product of effort multipliers of all the_________attributes", "options": ["11", "12", "14", "15"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "In COCOMO II, the Effort Adjustment Factor (EAF) is the product of the effort multipliers of all 15 cost-driver attributes.", "topic": "Software Engineering"}, {"id": "pdf4-045", "question": "Effective access time is directly proportional to ____________", "options": ["page read/write time", "hit ratio", "memory access time", "page-fault rate"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Effective Access Time increases as the page-fault rate increases, since each fault adds a costly page-fault service time on top of normal memory access time.", "topic": "OS"}, {"id": "pdf4-046", "question": "Early research on leadership traits ________.", "options": ["sought to prove that charisma was an essential trait of leadership", "focused on behavioural traits rather than physical traits of a leader", "found consistent and unique traits that would apply to all effective leaders", "focused on characteristics that might differentiate leaders from non-leaders"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Early trait-based leadership research aimed to identify physical, social, and personal characteristics that distinguish leaders from non-leaders, though it never found a universally consistent set.", "topic": "Management"}, {"id": "pdf4-047", "question": "EA stands for______.", "options": ["Effective add", "Effective absolute", "Effective address", "End address"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "EA (Effective Address) is the actual memory address computed from an instruction's addressing mode, used to access the operand.", "topic": "CAO"}, {"id": "pdf4-048", "question": "Dynamic growing stack finds the solution with the help of", "options": ["Array implementation", "Pointer implementation", "Linked list implementation", "All of these"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "low", "reasoning": "A dynamically growing stack is most naturally implemented with a pointer-based linked list rather than a fixed-size array; the source's 'All of these' answer is kept since the question's options overlap ambiguously (linked lists are themselves pointer-based).", "topic": "DSA"}, {"id": "pdf4-049", "question": "During the ______ design phase of database design, the properties of data is given importance, rather than its storage details", "options": ["conceptual", "logical", "physical", "actual"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The conceptual design phase focuses on what data and relationships exist (via an ER model), independent of how the data will actually be stored.", "topic": "DBMS"}, {"id": "pdf4-050", "question": "DSDM stands for _____________", "options": ["Dynamic systems development method", "Dynamic solutions development method", "Database systems development method", "Database solutions development method"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "DSDM stands for Dynamic Systems Development Method, an agile project delivery framework.", "topic": "Software Engineering"}, {"id": "pdf4-051", "question": "Draw up plans to avoid or minimise the effects of the risk is called ____________", "options": ["Risk identification", "Risk analysis", "Risk planning", "Risk monitoring"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Risk planning is specifically about drawing up plans/strategies to avoid or minimize the effects of a risk, distinct from identifying, analyzing, or monitoring it.", "topic": "Management"}, {"id": "pdf4-052", "question": "Double Diamond representation in ER diagram", "options": ["weak Entity Set", "Total Participation", "Strong Entity Set", "Complete Entity Set"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "A double diamond denotes the identifying relationship that connects a weak entity to its owner entity, so it's tied to the weak-entity notation; none of the given options say 'identifying relationship' directly, which makes this a bit ambiguous.", "topic": "DBMS"}, {"id": "pdf4-053", "question": "Does an algorithm solve the all-pair shortest path problem?", "options": ["Floyd\u2019s algorithm", "Prim\u2019s algorithm", "Dijkstra\u2019s algorithm", "Warshall\u2019s algorithm"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Floyd's (Floyd-Warshall) algorithm uses dynamic programming to compute shortest paths between every pair of vertices in a weighted graph.", "topic": "DSA"}, {"id": "pdf4-054", "question": "Do vertices dominate over vertex 6 in the given graph?", "options": ["1,2,4,5", "0,1,2,4,7", "1,3,4,5,7", "0,1,2,3,4,5"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "low", "reasoning": "This question includes a diagram \u2014 see the image above and verify the answer visually; not independently fact-checked.", "topic": "DSA", "diagram": "pdf4_p14_y516.png"}, {"id": "pdf4-055", "question": "Disk scheduling policies results in minimum amount of head movement.", "options": ["FCFS", "Circular SCAN", "Elevator", "CSCAN"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "low", "reasoning": "The option list oddly repeats the same algorithm ('Circular SCAN' and 'CSCAN' are the same thing), which makes the question ambiguous; Elevator (SCAN) is the standard answer for reducing head movement among the given choices.", "topic": "OS"}, {"id": "pdf4-056", "question": "Disk Response Time is...", "options": ["the average of time spent by a request waiting to perform its I/O operation.", "the time taken to locate the disk arm to a specified track where the data is to be read or write.", "the time taken by the desired sector of disk to rotate into a position so that it can access the read/write heads.", "the time taken to complete the execution."], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "In disk scheduling terminology, response time is defined as the average time a request spends waiting before its I/O operation is performed.", "topic": "OS"}, {"id": "pdf4-057", "question": "Dialogue control and Token management are responsibility of which OSI Layer", "options": ["session layer", "network layer", "transport layer", "data link layer"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The OSI session layer is responsible for dialogue control (managing who transmits when) and token management.", "topic": "CN"}, {"id": "pdf4-058", "question": "Design techniques which one is used to finding all the pairs of shortest distances in a graph?", "options": ["Backtracking", "Greedy", "Dynamic programming", "Divide and Conquer"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Finding all-pairs shortest distances (e.g., Floyd-Warshall) is a classic dynamic programming technique, building the solution from smaller subproblems.", "topic": "DSA"}, {"id": "pdf4-059", "question": "Departmentalization is a process in which", "options": ["Tasks are grouped into jobs", "Jobs are grouped into effective work groups", "Work groups are grouped into identifiable segments", "All the other answers are correct"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Departmentalization textbook definitions describe it as the whole sequential process: tasks grouped into jobs, jobs into work groups, and work groups into larger departments, so 'all of the above' is correct.", "topic": "Management"}, {"id": "pdf4-060", "question": "Definition of a language L with alphabet {a} is given as following. L= { a^nk | k > 0, and n is a positive integer constant} What is the minimum number of states needed in a DFA to recognize L", "options": ["2^n+1", "n+1", "k+1", "2^k+1"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A DFA must track a's mod n using n states (residues 0..n-1), plus one extra initial state to keep the empty string (m=0) distinguishable from a true multiple (m>0), giving n+1 states in total.", "topic": "TOC"}, {"id": "pdf4-061", "question": "Decision table technique is sometimes also referred to as a ________ table.", "options": ["Cause-effect", "Redundant", "Extreme", "Isolated"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Decision tables are also called cause-effect tables because they map input conditions (causes) to resulting actions (effects).", "topic": "Software Engineering"}, {"id": "pdf4-062", "question": "Databases overall structure is maintained in a file called", "options": ["Redolog File", "Data file", "Control file", "All"], "correct": 3, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "The control file (not the redo log) stores the database's overall physical structure, including the database name and the locations of datafiles and redo log files.", "topic": "DBMS"}, {"id": "pdf4-063", "question": "Data on someone's racial or ethnic heritage, political, philosophical, or religious beliefs, union affiliation, and health or sex life and sexual orientation, either directly or indirectly. What kind of personal information is this?", "options": ["Direct personal data", "Indirect personal data", "Pseudonymized data", "Special category personal data"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Under data-protection law (e.g., GDPR), racial/ethnic origin, political or religious beliefs, and health/sexual-orientation data are classified as 'special category' personal data needing extra protection.", "topic": "Privacy & Compliance"}, {"id": "pdf4-064", "question": "CPU fetches the instruction from memory according to the value of ____________", "options": ["program counter", "status register", "instruction register", "program status word"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The program counter holds the address of the next instruction, which the CPU uses to fetch instructions from memory.", "topic": "CAO"}, {"id": "pdf4-065", "question": "Correct relationship", "options": ["O(log n) < O(n) < O( n* log n) < O(2^n ) < O(n^2 )", "O(n) < O(log n) < O( n* log n) < O(2^n ) < O(n^2 )", "O(n) < O(log n) < O( n* log n) < O(n^2 ) < O(2^n )", "O(log n) < O(n) < O( n* log n) < O(n^2 ) < O(2^n )"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Standard asymptotic growth ordering is log n < n < n log n < n^2 < 2^n.", "topic": "DSA"}, {"id": "pdf4-066", "question": "Control that monitors ongoing employee activities during their progress, to ensure they are consistent with quality standards, is called as", "options": ["Feed Forward Control", "Concurrent Control", "Feedback Control"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Concurrent control monitors activities as they happen, catching deviations from standards in real time.", "topic": "Management"}, {"id": "pdf4-067", "question": "Control that attempts to identify and prevent deviations before they occur is called as", "options": ["Feed Forward Control", "Concurrent Control", "Feedback Control", "Control measure"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Feedforward control is proactive: it aims to identify and prevent deviations before they actually occur.", "topic": "Management"}, {"id": "pdf4-068", "question": "Contingency theories of leadership are based on the belief that:", "options": ["there is no single style of leadership appropriate to all situations.", "there is a single style of leadership appropriate to all managers.", "there is a single style of leadership appropriate to all situations.", "None of the other answers is correct."], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Contingency theories of leadership hold that no single leadership style is best for every situation; effectiveness depends on the context.", "topic": "Management"}, {"id": "pdf4-069", "question": "Contemporary organizations are redesigning their ethics programs to facilitate a broader, more consistent process that ________.", "options": ["embraces chaos and forges new paradigms.", "incorporates the analysis of outcomes and continual improvement .", "uses outcome analysis to focus on short-term goals.", "relies on expediency and situational management."], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Modern ethics programs aim for a systematic, ongoing process that analyzes outcomes and drives continual improvement, rather than short-term or ad hoc fixes.", "topic": "Business Ethics"}, {"id": "pdf4-070", "question": "Consider the regular language L = (111 + 11111)*. The minimum number of states in any DFA accepting the language is", "options": ["3", "5", "8", "9"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Since gcd(3,5)=1, the largest count of 1's not expressible as 3a+5b is 7 (Frobenius number), so a unary DFA needs one state for each count 0-7 plus one absorbing accepting state for all counts >=8 -- 9 distinguishable states total.", "topic": "TOC"}, {"id": "pdf4-071", "question": "Consider the followings right-linear grammar G = (N,T,P,S) N={S} P{ S-->aS|aA A-->bA|b} T={a,b} Which of the following regular expression denotes L(G)?", "options": ["a*b*", "aa*bb*", "a(ab)*b", "(a+b)*"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "S must apply S->aS zero or more times then S->aA exactly once (giving one or more a's), and A must apply A->bA zero or more times then A->b (giving one or more b's), so L(G) = aa*bb*.", "topic": "TOC"}, {"id": "pdf4-072", "question": "Consider the following languageL={a^nb^n| n>=1} L is", "options": ["regular", "CFL but not regular", "type 0 language but not type 1", "CSL but not CFL"], "correct": 2, "original_marked": 4, "matches_original": false, "confidence": "high", "reasoning": "a^n b^n (n>=1) is the textbook example of a context-free language that is not regular (generated by S->aSb|ab); it IS a CFL, so it cannot be 'CSL but not CFL' as marked.", "topic": "TOC"}, {"id": "pdf4-073", "question": "Consider the following language L={a^nb^mc^pd^q | n,m, p,q>=1} L is", "options": ["CFL but not regular", "CSL but not CFL", "type 0 language but not type 1", "regular"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Because a, b, c, d each just need one-or-more occurrences with no count matching between the blocks, the language is simply aa*bb*cc*dd*, which is regular.", "topic": "TOC"}, {"id": "pdf4-074", "question": "Consider the following DFA. How many states does the DFA has after minimization?", "options": ["5", "4", "3", "2"], "correct": 3, "original_marked": null, "matches_original": false, "confidence": "low", "reasoning": "This question includes a diagram \u2014 see the image above and verify the answer visually. No answer was marked in the source PDF either, so the option shown here is unverified; work it out from the figure.", "topic": "TOC", "diagram": "pdf4_p20_y72.png"}, {"id": "pdf4-075", "question": "Consider the following statement: virtual void show() = 0; It is called as \u2026\u2026.", "options": ["Virtual function", "Pure virtual function", "Syntax Error", "Only variable can be equated to Zero; not functions- So it is not supported by C++."], "correct": 2, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "Setting a virtual function's declaration to '= 0' specifically makes it a pure virtual function (which forces the class to be abstract), not just a plain virtual function.", "topic": "OOPS"}, {"id": "pdf4-076", "question": "Consider that a page is 1KB in size and a process is 9485 bytes in length. What would be the number of valid entries in the corresponding page table?", "options": ["8", "10", "9", "11"], "correct": 2, "original_marked": 3, "matches_original": false, "confidence": "high", "reasoning": "9485 bytes / 1024-byte pages = 9.26, so 9 full pages plus a 10th partial page are needed, giving 10 valid page-table entries.", "topic": "OS"}, {"id": "pdf4-077", "question": "Consider pumping lemma of regular language, here w= pqr and q refers to the middle part and |q|>0.What do we call the process of repeating q 0 or more times before checking that they still belong to the language L or not?", "options": ["Pumping", "Generating", "Creating", "Producing"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "In the pumping lemma, repeatedly inserting/removing copies of the middle substring q is literally called 'pumping' q.", "topic": "TOC"}, {"id": "pdf4-078", "question": "Consider an operating system capable of loading and executing a single sequential user process at a time. The disk head scheduling algorithm used is First Come First Served (FCFS). If FCFS is replaced by Shortest Seek Time First (SSTF), claimed by the vendor to give 50% better benchmark results, what is the expected improvement in the I/O performance of user programs?", "options": ["50%", "40%", "25%", "0%"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "This is the classic GATE 2004 question: with only one sequential process, there is never more than one outstanding disk request, so no scheduling algorithm has anything to reorder \u2014 improvement is 0%.", "topic": "OS"}, {"id": "pdf4-079", "question": "CONCERT and CONDUCTOR are entity sets with attributes as follows; CONCERT(coid, location, time, date), CONDUCTOR(soloid, fname, lname, phone). CONDUCTS is a one-to-many relationship from CONDUCTOR to CONCERT. While reducing the ERD to schemas, what would be the schema for CONDUCTS?", "options": ["CONDUCTS(coid, soloid)", "CONDUCTS(coid, location, time, date, soloid, fname, lname, phone)", "CONDUCTS(soloid, coid)", "None of the above"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "For a 1:N relationship, the rule is to embed the primary key of the 'one' side (CONDUCTOR's soloid) directly into the 'many' side's table (CONCERT); no separate CONDUCTS relation is created, so none of the listed schemas is right.", "topic": "DBMS"}, {"id": "pdf4-080", "question": "Components of attitude doesn\u2019t include", "options": ["Cognitive Component", "Behavioral component", "Affective component", "Personality Component"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "The classic ABC model of attitude has three components: Affective, Behavioral, and Cognitive \u2014 'Personality' is not one of them.", "topic": "Management"}, {"id": "pdf4-081", "question": "Comparison of two results and to make sure its accuracy is a process of", "options": ["Waterfall model", "Big Bang model", "V-model", "Spiral model"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "low", "reasoning": "The question is garbled, but among SDLC models the V-model is built around verification/validation \u2014 comparing actual results against expected results at each stage \u2014 which best fits the description.", "topic": "Software Engineering"}, {"id": "pdf4-082", "question": "Company (cid, name, department). Here, the \u2018name\u2019 is a --------------------------- and \u2018Company\u2019 is a ----------------------", "options": ["Relation, Attribute", "Attribute, Relation", "Tuple, Relation", "Tuple, Attribute"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "In Company(cid, name, department), 'name' is a column, i.e. an attribute, while 'Company' is the table itself, i.e. a relation.", "topic": "DBMS"}, {"id": "pdf4-083", "question": "Compaction is ______", "options": ["a technique for overcoming internal fragmentation", "a paging technique", "a technique for overcoming external fragmentation", "a technique for overcoming fatal error"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Compaction shuffles allocated memory together to merge scattered free blocks into one contiguous block, which is the standard fix for external fragmentation.", "topic": "OS"}, {"id": "pdf4-084", "question": "Communication between a computer and a keyboard involves ______________ transmission.", "options": ["Automatic", "Half-duplex", "Full-duplex", "Simplex"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A keyboard only sends data to the computer and never receives data back, so it's simplex transmission.", "topic": "CN"}, {"id": "pdf4-085", "question": "Communication between a computer and a keyboard involves ______________ transmission", "options": ["Automatic", "Half-Duplex", "Full-Duplex", "Simplex"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Same reasoning as any keyboard-to-computer link: data flows one way only, which is the definition of simplex transmission.", "topic": "CN"}, {"id": "pdf4-086", "question": "Class contains....................", "options": ["Members", "data types", "variables", "all of them"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A class can hold data members (variables), member/nested data types, and functions collectively called members, so 'all of them' is the best description of what a class contains.", "topic": "OOPS"}, {"id": "pdf4-087", "question": "Choose the software quality activites from the below", "options": ["Prepares an SQA plan for a project", "Records any noncompliance and reports to senior management", "Participates in the development of the project's software process description", "All the options"], "correct": 4, "original_marked": 3, "matches_original": false, "confidence": "high", "reasoning": "Preparing an SQA plan, participating in the process-description development, and recording/reporting noncompliance are all genuine SQA group activities from the standard Pressman list, so 'All the options' is correct, not just one of them.", "topic": "Software Engineering"}, {"id": "pdf4-088", "question": "Choose the purpose of reviews from the below", "options": ["Serve as a filter for the software process", "Uncover errors that can then be removed", "Catch large classes of errors that escape the originator more than other practitioners", "All the options"], "correct": 4, "original_marked": 3, "matches_original": false, "confidence": "high", "reasoning": "Reviews are documented to serve as a process filter, uncover removable errors, and catch error classes the originator tends to miss \u2014 all three are standard, textbook-cited purposes of reviews, so the answer should be 'All the options'.", "topic": "Software Engineering"}, {"id": "pdf4-089", "question": "Choose an internal software quality from given below:", "options": ["scalability", "usability", "reusability", "reliability"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Usability and reliability are external quality attributes visible to users, while reusability is an internal attribute tied to code structure that developers care about.", "topic": "Software Engineering"}, {"id": "pdf4-090", "question": "Charles Babbage was a professor of __________ subject", "options": ["Computer Science", "Mathematics", "Management", "None of these"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Charles Babbage held the Lucasian Chair of Mathematics at Cambridge University.", "topic": "Other"}, {"id": "pdf4-091", "question": "Change control procedures are developed by organizations to ensure that ________", "options": ["All changes are authorized, tested, and recorded.", "Changes are controlled by the Policy Control Board (PCB).", "All changes are requested, scheduled, and completed on time.", "Management is advised of changes made to systems."], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Change control procedures exist so that every change to a system goes through authorization, testing, and record-keeping before it's applied.", "topic": "Information Security"}, {"id": "pdf4-092", "question": "Centralisation", "options": ["Increasing the importance of subordinate role", "Decreasing the importance of subordinate role", "Both are correct", "None"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Centralisation concentrates decision-making authority at the top, which reduces the autonomy and importance of subordinate roles.", "topic": "Management"}, {"id": "pdf4-093", "question": "Build a new product will cost 55,000 with expected sales of 55,000 per unit (unit price = 4)", "options": ["1,65,750", "1,68,750", "1,78,750", "1,75,750"], "correct": 1, "original_marked": null, "matches_original": false, "confidence": "low", "reasoning": "The question text is corrupted/incomplete (numbers and cost breakdown don't line up), so no reliable calculation is possible; option 1 is closest to a simple revenue-minus-cost estimate, but treat this one with caution.", "topic": "Management"}, {"id": "pdf4-094", "question": "Boehm divided the historical project data into following types of projects", "options": ["Application", "Utility programs", "A and B", "None of the above"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Boehm's historical COCOMO project data was drawn from both application (data-processing/organic) and utility/system (semidetached-embedded) program types, so 'A and B' fits best among the given choices.", "topic": "Software Engineering"}, {"id": "pdf4-095", "question": "Blocks to be placed at the upper level of the hierarchy scheme used, is from direct memory to", "options": ["Set definitive", "Block associative", "Fully associative", "Set associative"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Set-associative mapping is the generalized cache placement scheme that sits between direct mapping (one fixed location) and fully associative mapping (any location).", "topic": "CAO"}, {"id": "pdf4-096", "question": "Because it is difficult to find one single person with all the needed qualities, Taylor suggested the appointment of a specialist through this technique of scientific management. Identify the technique.", "options": ["Standardization and simplification of work", "Method study", "Functional foremanship", "Motion study"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Taylor's functional foremanship splits supervisory duties among several specialist foremen instead of requiring one person to have every needed skill.", "topic": "Management"}, {"id": "pdf4-097", "question": "baa*c denotes the set", "options": ["{b^na^mc^p|n,m,p>=1}", "{ba^nc|n>=0}", "{ba^nc|n>=1}", "{w|w is a string of a,b,c}"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "baa*c = 'b' followed by one literal 'a' followed by zero-or-more additional 'a's followed by 'c', so the total count of a's is always at least 1, giving {ba^nc | n>=1}.", "topic": "TOC"}, {"id": "pdf4-098", "question": "Authority always flows from", "options": ["Superior to subordinate", "Subordinate to superior", "Both Superior to subordinate and Subordinate to superior", "None of the other answers is correct"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Authority is delegated downward through the management hierarchy \u2014 from superior to subordinate \u2014 while responsibility flows upward.", "topic": "Management"}, {"id": "pdf4-099", "question": "Attributes, relations and map entities in oracle is represented by", "options": ["Conceptual schema", "Physical schema", "Logical schema", "All of above"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "low", "reasoning": "In Oracle's architecture, tables, columns and their relationships belong to the logical structure (schema objects), as opposed to the physical structure of datafiles and blocks.", "topic": "DBMS"}, {"id": "pdf4-100", "question": "Attack against availability is ....", "options": ["Trojan Horse", "Malware", "VIRUS", "DoS"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Of the CIA triad, availability is what a Denial-of-Service (DoS) attack specifically targets by overwhelming or knocking out a system.", "topic": "Information Security"}, {"id": "pdf4-101", "question": "Assuming that memory is byte-addressable, if a frame size is 2KB, what is the number of bits required to represent the page offset?", "options": ["12", "10", "9", "11"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Frame size 2KB = 2048 bytes = 2^11, so the page offset needs 11 bits to address every byte within a frame.", "topic": "OS"}, {"id": "pdf4-102", "question": "Assume that a process has 3 user threads assigned to one kernel thread. Thread 1 is blocked, Tread2 is running and thread 3 is ready. What will be the state of the process?", "options": ["Running", "Ready", "Terminated", "Blocked"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "In the many-to-one threading model the kernel only sees a single kernel thread, so a blocking call by any one user thread blocks the whole process from the OS's point of view, regardless of the other threads' logical states.", "topic": "OS"}, {"id": "pdf4-103", "question": "Assume page size as 2KB and a process is 72750 bytes in length. What is the size of the internal fragment?", "options": ["878", "1078", "978", "1178"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "72750 bytes needs ceil(72750/2048) = 36 pages; 36*2048 = 73728, so internal fragmentation = 73728 - 72750 = 978 bytes.", "topic": "OS"}, {"id": "pdf4-104", "question": "Assume we have an object called Employee. Which of the following best represent this object's identity?", "options": ["Name", "Staff ID", "Date of Birth", "Address"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Object identity is a unique identifier distinct from attributes that can change or repeat (like name or address); Staff ID uniquely identifies the Employee object.", "topic": "OOPS"}, {"id": "pdf4-105", "question": "Assess the likelihood and consequences of these risk is called ______________", "options": ["Risk identification", "Risk analysis", "Risk planning", "Risk monitoring"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Risk analysis is the step where identified risks are assessed for their likelihood (probability) and consequences (impact).", "topic": "Software Engineering"}, {"id": "pdf4-106", "question": "Assertion (A): The virtual function supports dynamic-binding Reason (R): The inheritance concept helps in achieving it.", "options": ["A is correct; R is the correct explanation for A", "A and R are correct; But R is not the actual reason for A", "A is incorrect; R is correct", "Both A and R are incorrect"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Virtual functions achieve dynamic binding (runtime polymorphism), and this mechanism only makes sense in an inheritance hierarchy where a derived class overrides a base class's virtual function, so inheritance is indeed the correct explanation.", "topic": "OOPS"}, {"id": "pdf4-107", "question": "As a professional, what should be your primary source of ethical guidance in the workplace?", "options": ["corporate HR policies", "corporate code of ethics", "corporate mission statement", "corporate procedures"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A company's code of ethics is the formal, primary reference document for expected ethical conduct in the workplace.", "topic": "Business Ethics"}, {"id": "pdf4-108", "question": "Arunima, an HR manager, has been given the task of strengthening the ethical culture at her firm. Which of the following activities would be most beneficial?", "options": ["e-mailing ethics codes to all employees", "posting ethics code posters in the hallways", "writing a memo about ethics to top executives", "discussing ethics during performance appraisals"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Embedding ethics into performance appraisals ties ethical behavior to real consequences (ratings, raises, promotions), making it far more effective at shaping culture than passive communication like emails or posters.", "topic": "Business Ethics"}, {"id": "pdf4-109", "question": "Arrange the 32-bit number 0x0A0B0C0D in big endian order starting from address 1000h", "options": ["1000h-0D, 1001h-0C, 1002h-0B, 1003\u20130A", "1000h-0A, 1001h-0B, 1002h-0C, 1003-0D", "1000h-0B, 1001h-0A, 1002h-0D, 1003h-0C", "1000h\u20130C, 1001h-0B, 1002h-0D, 1003h-0A"], "correct": 2, "original_marked": null, "matches_original": false, "confidence": "high", "reasoning": "In big-endian order the most significant byte is stored at the lowest address: 1000h=0A, 1001h=0B, 1002h=0C, 1003h=0D, matching option 2. The source PDF left this unmarked.", "topic": "CAO"}, {"id": "pdf4-110", "question": "ARP (Address Resolution Protocol) is....", "options": ["a TCP/IP protocol used to dynamically bind a high level IP Address to a low-level physical hardware address", "a TCP/IP high level protocol for transferring files from one machine to another", "a protocol used to monitor computers", "a protocol that handles error and control messages"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "ARP's job is to resolve (bind) an IP address to the corresponding physical MAC address on a local network.", "topic": "CN"}, {"id": "pdf4-111", "question": "Analysis the probabilty and effects for the risk \"The size of the software is underestimated\"", "options": ["High and Serious", "Moderate and Serious", "Moderate and Tolerable", "High and Tolerable"], "correct": 1, "original_marked": 4, "matches_original": false, "confidence": "high", "reasoning": "In Sommerville's standard software risk table, \"the size of the software is underestimated\" is rated High probability / Serious effect, not High/Tolerable.", "topic": "Software Engineering"}, {"id": "pdf4-112", "question": "Analysis the probabilty and effects for the risk \"HighCatastrophicKey staff are ill at critical times in the project\"", "options": ["High and Serious", "Moderate and Serious", "Moderate and Tolerable", "High and Tolerable"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "In Sommerville's standard software risk table, \"key staff are ill at critical times in the project\" is rated Moderate probability / Serious effect.", "topic": "Software Engineering"}, {"id": "pdf4-113", "question": "An over-generalized, oversimplified, and self-perpetuating belief about people\u2019s personal characteristics is known as", "options": ["Perception", "Stereotype", "Attribution", "Personality"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "This is the textbook definition of a stereotype: an oversimplified, generalized belief applied to people based on group membership.", "topic": "Management"}, {"id": "pdf4-114", "question": "An organisation establishes relationships among", "options": ["People, work, and resources", "Customer, work, and resources", "People, work, and management", "Customer, work, and management"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Organizing is defined as establishing relationships among people, the work they do, and the resources they use to achieve goals.", "topic": "Management"}, {"id": "pdf4-115", "question": "An industry having low growth rate ,but possess high relative market share. In BCG matrix, its placed in:", "options": ["Stars", "Question Marks", "Cash cows", "Dogs"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "In the BCG matrix, high relative market share combined with low market growth defines a \"Cash Cow\" - a mature business generating steady cash with little reinvestment needed.", "topic": "Management"}, {"id": "pdf4-116", "question": "An individuals\u2019 ability to cooperate with other members of the organization and work effectively in teams is called as", "options": ["Technical skills", "Human skills", "Conceptual skills", "Employee skills"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Human skills refer to the ability to work well with, understand, motivate, and cooperate with other people, individually or in teams.", "topic": "Management"}, {"id": "pdf4-117", "question": "An implied understanding of mutual contributions between a person and his or her organization, which is not a written document, is called as", "options": ["Psychological contract", "Legal contract", "Illegal contact", "Unwritten contract"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A psychological contract is the unwritten set of mutual expectations and obligations between an employee and employer, as opposed to a formal legal contract.", "topic": "Management"}, {"id": "pdf4-118", "question": "An example for external premises in planning is", "options": ["Money", "Materials", "Machines", "Competitors strategy"], "correct": 4, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "Planning premises are split into internal (money, materials, machines, men - resources within the firm) and external (competitors' strategy, government policy, technology, economy). \"Competitors' strategy\" is external; \"Money\" is an internal premise, so the marked answer is incorrect.", "topic": "Management"}, {"id": "pdf4-119", "question": "An evaluative statements that is either favorable or unfavorable about objects, people, or events is called", "options": ["Attitude", "Stereotype", "Attribution", "Personality"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "An attitude is defined as an evaluative statement, favorable or unfavorable, about objects, people, or events.", "topic": "Management"}, {"id": "pdf4-120", "question": "An acyclic graph, what is the maximum number of edge.", "options": ["n", "n+1", "2n-1", "n-1"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "An acyclic undirected graph (a forest) on n vertices has at most n-1 edges, with equality achieved when it forms a single spanning tree.", "topic": "DSA"}, {"id": "pdf4-121", "question": "Amount of data utilized by the stack, which of the content holds", "options": ["not a fixed size", "the amount of the data fluctuates", "depends on stack's lifetime", "all of these"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "low", "reasoning": "The question is oddly worded and ambiguous in the source material, so the originally marked option is kept; generally a stack's data usage is described as fluctuating as items are pushed and popped.", "topic": "DSA"}, {"id": "pdf4-122", "question": "Among the Mintzberg\u2019s management roles, figurehead comes under", "options": ["Interpersonal roles", "Informational roles", "Decision roles", "Leader roles"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "In Mintzberg's managerial roles, figurehead (along with leader and liaison) falls under the Interpersonal roles category.", "topic": "Management"}, {"id": "pdf4-123", "question": "All of the following are elements of planning EXCEPT:", "options": ["Developing Plans", "Monitoring Performance", "Establishing Strategies", "Coordinate Activities"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Monitoring performance is part of the controlling function of management, not planning; planning covers setting strategies, developing plans, and coordinating activities.", "topic": "Management"}, {"id": "pdf4-124", "question": "After a study of the work processes on a project, a quality audit team reports to the project manager that irrelevant quality standards were being used by the project, which might lead to rework. What was the objective of the project manager in initiating this study?", "options": ["Quality control", "Quality planning", "Checking adherence to processes", "None in the list"], "correct": 3, "original_marked": 4, "matches_original": false, "confidence": "high", "reasoning": "A quality audit's objective is to determine whether project activities comply with organizational and project policies, processes, and procedures - i.e., checking adherence to processes - so option 3 fits better than \"none in the list.\"", "topic": "Software Engineering"}, {"id": "pdf4-125", "question": "Administrative Management is related to", "options": ["Elton Mayo", "Henry Fayol", "F W Taylor", "Max Weber"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Henri Fayol is credited with the Administrative Management theory, focused on general management principles and functions, distinct from Taylor's scientific management or Weber's bureaucracy.", "topic": "Management"}, {"id": "pdf4-126", "question": "Aditi has a reputation of being fair, helpful, and understanding. She even helped her subordinate overcome a personal crisis. Which one of the following dimensions of leadership is Aditi displaying here?", "options": ["consideration", "initiating structure", "employee orientation", "task orientation"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Consideration is the leadership dimension where a leader shows trust, respect, and concern for subordinates' well-being, which matches Aditi's fairness and personal support.", "topic": "Management"}, {"id": "pdf4-127", "question": "Activity Bar charts show schedule against ______________", "options": ["task dependencies", "calendar time", "critical bar chart", "defining milestones"], "correct": 2, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "A bar (Gantt) chart plots activities against a calendar time scale; showing dependencies between tasks is the job of a network/logic diagram, not a bar chart.", "topic": "Management"}, {"id": "pdf4-128", "question": "According to this principle of general management, \u201can organization should safeguard against abuse of managerial power, but at the same time, a manager should have the necessary authority to carry out his responsibility.\u201d Name the principle of management described in the given statement.", "options": ["Discipline", "Authority and responsibility", "Unity of command", "Unity of direction"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Fayol's Authority and Responsibility principle pairs a manager's right to give orders with accountability, while guarding against abuse of that power.", "topic": "Management"}, {"id": "pdf4-129", "question": "According to the University of Iowa behavioural studies, group members' satisfaction levels were generally ________.", "options": ["higher under a supportive leader in the long run.", "improved when the leader was production oriented", "maintained when the leader was directive in the short run", "higher under a democratic leader than under an autocratic one"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "The University of Iowa studies (Lewin, Lippitt, White) found member satisfaction was generally higher under democratic leadership than under autocratic leadership.", "topic": "Management"}, {"id": "pdf4-130", "question": "According to the Ohio State studies, the ________ dimension of leader behaviour is defined as the extent to which a leader has job relationships characterized by mutual trust and respect for group members' ideas and feelings.", "options": ["relationship management", "consideration", "people orientation", "integrity"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "In the Ohio State studies, 'consideration' is defined as the extent to which a leader builds job relationships marked by mutual trust and respect for subordinates' feelings.", "topic": "Management"}, {"id": "pdf4-131", "question": "According to the Ohio State studies, ________ refers to the extent to which a leader is likely to define and shape his or her role and the roles of group members in the search for goal attainment.", "options": ["people orientation", "production orientation", "initiating structure", "consideration"], "correct": 3, "original_marked": 4, "matches_original": false, "confidence": "high", "reasoning": "The Ohio State studies define 'initiating structure' as the extent to which a leader defines and structures their own role and the roles of followers to attain goals; 'consideration' is the separate, people-focused dimension.", "topic": "Management"}, {"id": "pdf4-132", "question": "According to Henri Fayol, if this principle of general management is violated, \u201cauthority is undermined, discipline is in jeopardy, order disturbed, and stability threatened.\u201d Identify the principle.", "options": ["Authority and responsibility", "Discipline", "Unity of command", "Equity"], "correct": 3, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "This is Fayol's own description of Unity of Command being violated ('one boss for one employee'); breaking it undermines authority, discipline, order, and stability, per Fayol's original writing.", "topic": "Management"}, {"id": "pdf4-133", "question": "According to Burns and Stalker, which of the following is a feature of organic organisations?", "options": ["Emphasis on vertical communication channels", "Prestige drawn from personal contribution", "Stress on obedience to superiors and loyalty to the organisation", "Knowledge requirement based on job"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Burns and Stalker's organic organizations emphasize personal contribution and expertise over formal rank, unlike mechanistic organizations which stress vertical communication and obedience to superiors.", "topic": "Management"}, {"id": "pdf4-134", "question": "According to research, what characteristic is most frequently shared by firms that receive high rankings for corporate social responsibility?", "options": ["encouraging employees to participate in civic activities", "requiring managers to understand ethics laws", "promoting integrity through ethics training", "linking compensation to ethical behaviours"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "low", "reasoning": "No single option is unambiguously verifiable from a specific study without the source textbook, so the marked answer (promoting integrity through ethics training) is kept as the best available answer.", "topic": "Business Ethics"}, {"id": "pdf4-135", "question": "Access is determined by rules in Rule-Based Access Control (RuBAC). What type of access control would such restrictions fall under?", "options": ["Discretionary Access Control (DAC)", "Mandatory Access control (MAC)", "Non-Discretionary Access Control (NDAC)", "Lattice-based Access control"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Rule-Based Access Control is a form of Non-Discretionary Access Control because access is governed by system-enforced rules rather than by resource owners or fixed security labels.", "topic": "Information Security"}, {"id": "pdf4-136", "question": "Ability of an individual to analyze complex situations and to rationally process and interpret available information is called", "options": ["Technical skills", "Human skills", "Conceptual skills", "Employee skills"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Conceptual skills, in Katz's three-skill model, refer to the mental ability to analyze complex situations and process abstract information, as opposed to technical or human skills.", "topic": "Management"}, {"id": "pdf4-137", "question": "ABC Airways uses software to manage reservation of its passengers. After a year of its use, the database administrator decided to add few attributes with the passenger table. If he is able to change the structure of passenger table without adjusting its front-end, how do we call such independence?", "options": ["Physical data independence", "Logical data independence", "External data independence", "View data independence"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Logical data independence lets the conceptual/logical schema (like adding a table attribute) change without requiring changes to the external/application view.", "topic": "DBMS"}, {"id": "pdf4-138", "question": "A mistake in software code or configuration that provides an attacker with indirect access to a system or network is called as...", "options": ["Vulnerabilit y", "Virus", "Trojan Horse", "Exposures"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A flaw in code or configuration that an attacker can exploit for indirect access is the standard definition of a vulnerability.", "topic": "Information Security"}, {"id": "pdf4-139", "question": "A visual drawing of the reporting relationships within an organization is called a(n):", "options": ["work specialization chart.", "unity of command chart.", "organization chart.", "division of labour chart."], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "An organization chart is the standard visual diagram of formal reporting relationships within a company.", "topic": "Management"}, {"id": "pdf4-140", "question": "A view of database that appears to an application program is known as _______", "options": ["Virtual table", "Schema", "Subschema", "None of the above"], "correct": 3, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "The database view seen by a specific application program is called a subschema; 'schema' refers to the overall logical structure of the entire database.", "topic": "DBMS"}, {"id": "pdf4-141", "question": "A variable that derive \u0190 is called .", "options": ["\u0190", "@", "*", "Nullable"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "low", "reasoning": "The question text is corrupted/garbled in the source (OCR artifact), so the marked answer 'Nullable' is kept as the best available answer without a clear way to verify intent.", "topic": "DBMS"}, {"id": "pdf4-142", "question": "A stable set of characteristics and tendencies that determine commonalities and differences in people\u2019s behavior is called", "options": ["Attitude", "Stereotype", "Attribution", "Personality"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Personality is defined as the stable set of psychological traits and tendencies that shape consistent patterns of individual behavior.", "topic": "Management"}, {"id": "pdf4-143", "question": "A software process is a set of related activities that gives outcome to the ____________of the software", "options": ["Production", "Engineeing", "Sales", "None of the above"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A software process is classically defined (Sommerville) as a set of related activities leading to the production of a software product.", "topic": "Software Engineering"}, {"id": "pdf4-144", "question": "A rule of thumb is if you can find another company which can do a non-core activity better and faster, ________________.", "options": ["you should keep produ cing.", "you should comp ete with the comp any.", "you should outsource.", "you should increase your efficiency."], "correct": 3, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "The core outsourcing rule of thumb is: if another firm can perform a non-core activity better and faster, you should outsource it rather than keep doing it in-house.", "topic": "Management"}, {"id": "pdf4-145", "question": "A reporting relationship in which an employee receives orders from, and reports to, only one supervisor is known as:", "options": ["Line of authority", "Unity of direction", "Unity of command", "Responsibility"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Unity of command means each employee reports to and receives orders from only one supervisor.", "topic": "Management"}, {"id": "pdf4-146", "question": "A relationship between the instances of a single entity type is called ___________", "options": ["Recursive relationship", "Ternary relationship", "Binary relationship", "None of these"], "correct": 1, "original_marked": 4, "matches_original": false, "confidence": "high", "reasoning": "A relationship between instances of the same entity type (e.g., an employee 'manages' another employee) is called a recursive (unary) relationship in ER modeling.", "topic": "DBMS"}, {"id": "pdf4-147", "question": "A pure virtual function implicitly means", "options": ["do-everything function", "do-nothing function", "do-something function", "None of the above."], "correct": 2, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "A pure virtual function has no implementation in the base class (declared with '= 0'), making it effectively a 'do-nothing' function that forces derived classes to override it.", "topic": "OOPS"}, {"id": "pdf4-148", "question": "A process of verifying the validity of a claimed identity of a person is called?", "options": ["Identification", "Authentication", "Authorization", "Accountability"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Authentication is the process of verifying that a claimed identity is genuine, typically via credentials like passwords or biometrics.", "topic": "Information Security"}, {"id": "pdf4-149", "question": "A process is thrashing if", "options": ["it is spending more time paging than executing", "it is spending less time paging than executing", "page fault occurs", "swapping cannot take place"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Thrashing occurs when a process spends more time paging (swapping pages in/out) than actually executing instructions.", "topic": "OS"}, {"id": "pdf4-150", "question": "A problem is said to be decidable if it is a", "options": ["recursively enumerable", "recursive", "context-sensiti ve", "None of the choices."], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A problem is decidable if a Turing machine can decide it (always halts with yes/no), which corresponds to the language being recursive; recursively enumerable only guarantees halting on 'yes' instances.", "topic": "TOC"}, {"id": "pdf4-151", "question": "A period of \"testing-out\" the leaders in group development stages", "options": ["Storming", "Norming", "Performing", "Adjourning"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "In Tuckman's storming stage, members challenge and test the leader's authority and policies while vying for position in the group.", "topic": "Management"}, {"id": "pdf4-152", "question": "A mistake in the software code that provides an attacker with direct access to a system or network is called as....", "options": ["Vulnerability", "Virus", "Trojan Horse", "Backdoor Attack"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A vulnerability is a coding flaw or weakness that an attacker can exploit to gain direct access to a system or network.", "topic": "Information Security"}, {"id": "pdf4-153", "question": "A memory buffer used to accommodate a speed differential is called ____________", "options": ["stack pointer", "cache", "accumulator", "disk buffer"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Cache is a small, fast buffer that sits between the CPU and main memory to absorb their speed difference.", "topic": "CAO"}, {"id": "pdf4-154", "question": "a logical disk component that manages a disk's internal operations as it relates to a computer and is abstract to a human user.....", "options": ["disk management", "scheduler", "memory management", "file management system"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "The file management system handles a disk's internal organization while presenting files abstractly to the user, hiding physical disk details.", "topic": "OS"}, {"id": "pdf4-155", "question": "A leader uses _____________ when giving the individual or group the authority and responsibility to decide.", "options": ["consultatiom", "laissez-faire", "joint decision", "delegation"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Delegation is the act of granting a subordinate the authority and responsibility to make decisions.", "topic": "Management"}, {"id": "pdf4-156", "question": "A language that can generate the new data types is known as ___ languages as they can handle the new data types", "options": ["Overloaded", "Encapsulated", "Reprehensible", "Extensible"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Extensible languages allow programmers to define new data types beyond the language's built-in ones.", "topic": "OOPS"}, {"id": "pdf4-157", "question": "A group of experts are taking decision in this through consensus", "options": ["Interacting groups", "Delphi Methods", "Nominal groups", "Participative decision making"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The Delphi method gathers independent expert opinions over iterative rounds to converge on a consensus decision.", "topic": "Management"}, {"id": "pdf4-158", "question": "A function template can have __template argument.", "options": ["1", "2", "A. More than one", "0"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "A function template can take more than one template parameter, e.g. template<class T, class U>.", "topic": "C/C++"}, {"id": "pdf4-159", "question": "a file system with data stored on a server. The data is accessed and processed as if it was stored on the local client machine.", "options": ["distributed file system", "stand-alone machine", "Internet file system", "EXT2 FS"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A distributed file system stores data on a server but makes it accessible to the client as though it were local.", "topic": "OS"}, {"id": "pdf4-160", "question": "A dollar value is not used to measure all costs and benefits", "options": ["True", "False"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Many costs and benefits in a feasibility/cost-benefit study are intangible (e.g. goodwill, morale) and cannot be reduced to a dollar figure.", "topic": "Software Engineering"}, {"id": "pdf4-161", "question": "A department can be created by", "options": ["function", "product", "process", "All the other answers are correct"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Departmentalization can be organized by function, product, or process\u2014all are standard bases for creating departments.", "topic": "Management"}, {"id": "pdf4-162", "question": "A DBMS query language is designed to", "options": ["Specify the structure of a database", "Support end users who use english-like commands", "Support in the development of complex applications software", "All of the above"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A DBMS query language serves all these purposes: defining database structure, supporting end-user queries in plain language, and aiding application development.", "topic": "DBMS"}, {"id": "pdf4-163", "question": "A dataStore in DFD represents", "options": ["Sequential File", "Disk Store", "Repository of Data", "a Random Access Memory"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "In a DFD, a data store is an abstract repository of data, not tied to a specific physical storage medium like a disk or file.", "topic": "Software Engineering"}, {"id": "pdf4-164", "question": "A data dictionary is a special file that contains", "options": ["The Data type of all fields in all files", "The name of all fields in all files", "The data type of all fields in all files", "All of the above"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A data dictionary records metadata such as field names and data types for all files in a system, so both listed items (and thus 'all of the above') apply.", "topic": "DBMS"}, {"id": "pdf4-165", "question": "A cost benefit analysis involves measurable metrics such as", "options": ["Revenue earned or costs", "Quality or costs", "Benefits or costs", "None of the above"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Measurable (tangible) cost-benefit metrics are things like revenue earned or costs incurred, which can be expressed in dollars, unlike intangible factors such as quality.", "topic": "Software Engineering"}, {"id": "pdf4-166", "question": "A contingency model of leadership is the path-goal theory. This suggests that subordinates will see leadership behaviour as a motivating influence if:", "options": ["path-goal relationships are clarified.", "their effective performance will satisfy their needs.", "the necessary direction, guidance, training, and support is provided.", "all the other options are correct."], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Path-goal theory holds that leadership is motivating when relationships are clarified, performance satisfies needs, and support is provided\u2014all three conditions apply.", "topic": "Management"}, {"id": "pdf4-167", "question": "A complete graph can have", "options": ["n^2 spanning trees", "n^(n-2) spanning trees", "n^(n+2) spanning trees", "n^(n+2) spanning trees"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "By Cayley's formula, a complete graph on n vertices has exactly n^(n-2) distinct spanning trees.", "topic": "DSA"}, {"id": "pdf4-168", "question": "A company is running with a peer-to-peer network of 30 computers. The policy is such that all system users are responsible for their own security and they can set file and folder privileges on their own. Which of the following access control model best suits the configuration at this company?", "options": ["Discretionary", "Mandatory", "Role-based", "Nondiscretionary"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Discretionary Access Control lets individual resource owners set their own file/folder permissions, matching this peer-to-peer setup.", "topic": "Information Security"}, {"id": "pdf4-169", "question": "A clustered system ____.", "options": ["Gathers together multiple CPUs to accomplish computational work", "Is an operating system that provides file sharing across a network", "Is used when rigid time requirements are present", "Can only operate one application at a time"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A clustered system links together multiple CPUs/nodes so they can jointly perform computational work.", "topic": "OS"}, {"id": "pdf4-170", "question": "A bus is one possible local area network topology. One advantage of a bus network is", "options": ["the failure of one node does not affect the rest of the network", "the performance of the network is unaffected by the number of users", "failure of the main bus cable will only affect a few users", "it has the fastest performance of any network topology"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "In a bus topology each node taps independently into the shared cable, so a single node failing does not knock out the rest of the network.", "topic": "CN"}, {"id": "pdf4-171", "question": "A Block can be placed in a restricted set of places in the cache", "options": ["Direct mapping", "set associative", "fully associative", "Indirect associative"], "correct": 2, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "This is the textbook definition of set-associative mapping, where a block can go into a restricted set of cache locations; direct mapping restricts a block to exactly one location, so the marked answer is incorrect.", "topic": "CAO"}, {"id": "pdf4-172", "question": "A better measurement of performance of memory-hierarchy is the", "options": ["Average memory access time", "Average memory hit rate", "Average memory miss rate", "Write stall"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Average memory access time combines hit time and miss penalty, making it a more complete performance measure than hit rate or miss rate alone.", "topic": "CAO"}, {"id": "pdf4-173", "question": "A ____________ of an issue consists of weighing and balancing all of the competing demands on a firm by each of those who have a claim on it.", "options": ["stakeholder analysis", "board of directors\u2019 analysis", "corporation analysis", "management analysis"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Stakeholder analysis is exactly the process of weighing and balancing the competing claims of everyone affected by a firm's decision.", "topic": "Business Ethics"}, {"id": "pdf4-174", "question": "A ____________ leader avoids power and leaves the group entirely to itself.", "options": ["socialistic", "democratic", "autocratic", "laissez-faire"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A laissez-faire leader avoids exercising power and leaves decisions entirely to the group.", "topic": "Management"}, {"id": "pdf4-175", "question": "A _______ is a data communication system within a building, plant, or campus, or between nearby buildings.", "options": ["MAN", "LAN", "WAN", "None of the above"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A LAN is confined to a building, plant, or campus, distinguishing it from the larger geographic scope of a MAN or WAN.", "topic": "CN"}, {"id": "pdf4-176", "question": "A high-level document which defines the management plan in detail for how security should be practiced throughout the organization is called?", "options": ["Guidelines", "Policies", "Procedures", "Standards"], "correct": 2, "original_marked": 3, "matches_original": false, "confidence": "high", "reasoning": "A security policy is the high-level document stating management's plan and intent for how security will be practiced across the whole organization; procedures are the detailed step-by-step instructions that implement a policy, which is different from what's being described.", "topic": "Information Security"}, {"id": "pdf4-177", "question": "______is concerned with the safety of a person's personal information while accessing the Internet on any computer or mobile device.", "options": ["Digital agony", "Digital privacy", "Digital secrecy", "Digital protection"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Digital privacy is the term for protecting a person's personal information while they use the internet or a device.", "topic": "Privacy & Compliance"}, {"id": "pdf4-178", "question": "________is not a proper metric of a program's size", "options": ["LOC", "KLOC", "KDSI", "None of the above"], "correct": 4, "original_marked": 3, "matches_original": false, "confidence": "high", "reasoning": "LOC, KLOC, and KDSI (thousand delivered source instructions, used directly in the COCOMO model) are all standard, recognized size-oriented metrics, so none of the listed options is actually improper.", "topic": "Software Engineering"}, {"id": "pdf4-179", "question": "___________model provide ideas about historical projects", "options": ["Waterfall", "Spiral", "COCOMO", "Incremental"], "correct": 3, "original_marked": 4, "matches_original": false, "confidence": "high", "reasoning": "COCOMO's effort/cost equations are derived by fitting regression formulas to data from completed historical projects, which is exactly what lets it 'provide ideas' based on past project experience.", "topic": "Software Engineering"}, {"id": "pdf4-180", "question": "_____________used node as activity and links as precedence", "options": ["on-arrow approach", "precedence networks", "Timeline chart", "None of the above"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Precedence (activity-on-node) networks represent activities as nodes and use the links between them purely to show precedence/dependency relationships.", "topic": "Management"}, {"id": "pdf4-181", "question": "_________________ provides a framework for effective delivery of technology, forms the basis for management, and also provides the context for work products, milestones, quality measures, and change management", "options": ["Prototyping Model", "Linear Sequential Model", "Process", "Cost estimation"], "correct": 3, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "This is the standard textbook definition of a software process: it establishes the framework for delivering technology, forms the basis for management control, and provides context for work products, milestones, quality measures, and change management \u2014 not a specific lifecycle model like Linear Sequential.", "topic": "Software Engineering"}, {"id": "pdf4-182", "question": "_______________ ensure there is always an up-to-date system that can be demonstrated to the client.", "options": ["Domain Object Modelling", "Individual Class (Code) Ownership", "Visibility of progress and results", "Regular Builds"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Regular (e.g. daily/nightly) builds keep a current, working version of the system compiled and ready at all times, which is what makes it possible to demo an up-to-date system to the client whenever needed.", "topic": "Software Engineering"}, {"id": "pdf4-183", "question": "_____________ is triggered by modifications, migration or retirement of existing software.", "options": ["Regression Testing", "Unit Testing", "Maintenance testing", "Integration Testing"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Maintenance testing is specifically defined (e.g. by ISTQB) as testing triggered by modifications, migration, or retirement of an operational system.", "topic": "Software Engineering"}, {"id": "pdf4-184", "question": "_____________ is the system call that the parent has to invoke in order to avoid creating zombie processes?", "options": ["wait()", "Sleep()", "exec()", "execvp()"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The parent must call wait() to collect the child's exit status; if it doesn't, a terminated child stays as a zombie entry in the process table until reaped.", "topic": "OS"}, {"id": "pdf4-185", "question": "_____________ is a lack of access control policy.", "options": ["Bug", "Threat", "Vulnerability", "Attack"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "A vulnerability is a weakness in a system, such as a missing or inadequate access control policy, that could be exploited by a threat.", "topic": "Information Security"}, {"id": "pdf4-186", "question": "_____________ consists of exploring and explaining the domain of the problem to be solved.", "options": ["Feature Teams", "Inspections", "Domain Object Modelling", "Configuration Management"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Domain object modelling is by definition the activity of exploring and explaining the problem domain by identifying its key objects and concepts.", "topic": "Software Engineering"}, {"id": "pdf4-187", "question": "____________ is the technique by which a partially loaded program can be executed.", "options": ["Cache memory", "Virtual memory", "Associative memory", "Shared memory"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Virtual memory (via demand paging) lets a process begin and continue execution even though only part of it currently resides in physical memory.", "topic": "OS"}, {"id": "pdf4-188", "question": "___________ is very useful in situations when data have to be stored and then retrieved in reverse order.", "options": ["Stack", "Queue", "List", "Linked List"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A stack follows LIFO order, making it the natural structure for storing data that must later be retrieved in reverse order.", "topic": "DSA"}, {"id": "pdf4-189", "question": "___________ is the system call that has to be invoked by the child to replace the memory image of the child?", "options": ["wait()", "sleep()", "exec()", "exit()"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "exec() replaces the calling process's memory image with a new program, which is how a child process (typically after fork()) loads and runs different code.", "topic": "OS"}, {"id": "pdf4-190", "question": "___________ is a model that illustrates how testing activities integrate with software development phases.", "options": ["Waterfall Model", "V-Model", "Spiral Model", "Iterative Model"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The V-Model explicitly pairs each development phase (requirements, design, coding, etc.) with a corresponding testing phase, illustrating how testing integrates with development.", "topic": "Software Engineering"}, {"id": "pdf4-191", "question": "___________ communication modes support two-way traffic but in only one direction at a time?", "options": ["simplex", "half duplex", "three-quarters duplex", "all of the above"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Half-duplex supports two-way communication but only one direction can transmit at any given moment (e.g. walkie-talkies), unlike full duplex which allows both directions simultaneously.", "topic": "CN"}, {"id": "pdf4-192", "question": "__________ is the responsible for carrying out the instructions and procedures necessary for performing software configuration management tasks are documented in the software configuration management plan.", "options": ["Project manager", "Project leader", "Programmer", "None from the list"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "Overall accountability for executing the software configuration management plan is generally attributed to the project manager in most course material, though the question's options don't include the more precise role (a dedicated configuration/SCM manager), so this is somewhat ambiguous.", "topic": "Software Engineering"}, {"id": "pdf4-193", "question": "__________ is the process of using a function for more than one purpose. It allows the use of different internal structures of the object by keeping the same external interface.", "options": ["Inheritance", "Polymorphism", "Abstraction", "Encapsulation"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Polymorphism lets the same interface/function be used for objects with different internal implementations, i.e. 'one interface, many forms.'", "topic": "OOPS"}, {"id": "pdf4-194", "question": "__________ is the process of using a function for more than one purpose. It allows the use of different internal structures of the object by keeping the same external interface.", "options": ["Inheritance", "Polymorphism", "Abstraction", "Encapsulation"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Duplicate of the previous question: polymorphism lets the same interface/function be used for objects with different internal implementations.", "topic": "OOPS"}, {"id": "pdf4-195", "question": "__________ is the minimum number of steps that can execute for the given parameters", "options": ["Average case", "Worst case", "Time complexity", "Best case"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Best case refers to the minimum number of steps an algorithm executes for a given input size, as opposed to worst case (maximum) or average case.", "topic": "DSA"}, {"id": "pdf5-001", "question": "__________ is the average number of steps that can be executed for the given parameters", "options": ["Average case", "Worst case1", "Time complexity", "Best case"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Average case complexity is defined as the average (expected) number of steps executed over all possible inputs of a given size.", "topic": "DSA"}, {"id": "pdf5-002", "question": "__________ in the code are signs of bad code designs and should be avoided.", "options": ["Repetitions", "Modularity", "Functions", "Documentation"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Repeated/duplicated code is a classic code smell that increases maintenance cost and bug risk, so it's considered a sign of poor design.", "topic": "Software Engineering"}, {"id": "pdf5-003", "question": "__________ cable consists of inner copper core and a second conducting outer sheath", "options": ["Coaxial cable", "Twisted Pair", "Optical fibre cable", "shielded Twisted Pair"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A coaxial cable has a central copper conductor wrapped in insulation, surrounded by a second conducting metallic sheath (shield).", "topic": "CN"}, {"id": "pdf5-004", "question": "__________ begins at the root and follows a path down to the specified file.", "options": ["Relative path name", "Absolute path name", "Standalone name", "All of the above"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "An absolute path always starts at the root directory and traces the full path down to the file, unlike a relative path which starts from the current directory.", "topic": "OS"}, {"id": "pdf5-005", "question": "_________ utilization is the use of available bandwidth to achieve specific goals.", "options": ["Amplitude", "Frequency", "Bandwidth", "None of the above"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Bandwidth utilization refers to how effectively the available bandwidth of a link is used, typically through multiplexing or spreading techniques.", "topic": "CN"}, {"id": "pdf5-006", "question": "_________ memory management scheme will produce least fragment", "options": ["Best Fit", "Worst Fit", "First Fit", "None of the given choices"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Best fit searches for the smallest hole that satisfies the request, which minimizes leftover wasted space per allocation and generally yields the least fragmentation among the classic fit strategies.", "topic": "OS"}, {"id": "pdf5-007", "question": "_________ is the maximum number of steps that can execute for the given parameters", "options": ["Average case", "Worst case", "Time complexity", "Best case"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Worst case complexity is defined as the maximum number of steps an algorithm can take over all inputs of a given size.", "topic": "DSA"}, {"id": "pdf5-008", "question": "_________ is not the operation that can be performed on queue.", "options": ["Insertion", "Deletion", "Retrieval", "Traversal"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A queue supports insertion (enqueue), deletion (dequeue), and retrieval (peek/front), but traversal is not a standard queue operation since it would break the strict FIFO access pattern.", "topic": "DSA"}, {"id": "pdf5-009", "question": "_________ are used for cellular phone, satellite, and wireless LAN communications.", "options": ["Radio waves", "Infrared waves", "Microwaves", "None of the above"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Microwaves are unidirectional, high-frequency waves well suited for cellular phones, satellite links, and wireless LANs.", "topic": "CN"}, {"id": "pdf5-010", "question": "_________ affect schedule or resources", "options": ["Project risks", "Project people", "Task dependencies", "None in the list"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Project risks are uncertain events that, if they occur, impact the project's schedule and/or resource allocation, which is the standard project management definition.", "topic": "Management"}, {"id": "pdf5-011", "question": "________ cable consists of two insulated copper wires twisted together.", "options": ["Coaxial", "Fiber-optic", "Twisted-pair", "none of the above"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Twisted-pair cable is defined as two insulated copper wires twisted together to reduce electromagnetic interference.", "topic": "CN"}, {"id": "pdf5-012", "question": "________ are used for short-range communications such as those between a PC and a peripheral device.", "options": ["Radio waves", "Infrared waves", "Microwaves", "none of the above"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Infrared signals cannot penetrate walls and are used for short-range line-of-sight communication, such as a remote control or PC-to-peripheral link.", "topic": "CN"}, {"id": "pdf5-013", "question": "_______ is the singleness of purpose that makes possible the creation of one plan of action to guide managers in resource allocations.", "options": ["Unity of direction", "Unity of command", "Unity of resources", "Unity of authority"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "This is Fayol's principle of Unity of Direction: one head and one plan for a group of activities with the same objective, guiding resource allocation.", "topic": "Management"}, {"id": "pdf5-014", "question": "_______ is designed to be used in wireless applications in which stations must be able to share the medium without interception by an eavesdropper and without being subject to jamming from a malicious intruder.", "options": ["Multiplexing", "Spread spectrum", "Modulation", "None of the above."], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Spread spectrum spreads a signal over a wide frequency band precisely so it resists eavesdropping and jamming, making it suited to secure wireless sharing of the medium.", "topic": "CN"}, {"id": "pdf5-015", "question": "_______ diagrams are important part of object modeling methodology", "options": ["application", "data", "class", "level"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Class diagrams model the objects, their attributes, operations, and relationships, making them central to object modeling methodology (e.g., UML).", "topic": "OOPS"}, {"id": "pdf5-016", "question": "______ can be applied when the bandwidth of a link (in hertz) is greater than the combined bandwidths of the signals to be transmitted.", "options": ["TDM", "FDM", "Both TDM or FDM", "Neither TDM or FDM"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "This is the textbook definition of FDM (Frequency Division Multiplexing): applicable when the link's bandwidth in hertz exceeds the combined bandwidths of the signals to be sent.", "topic": "CN"}, {"id": "pdf5-017", "question": "______ cables are composed of a glass or plastic inner core surrounded by cladding,all encased in an outside jacket.", "options": ["Coaxial", "Fiber-optic", "Twisted-pair", "none of the above"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Fiber-optic cable consists of a glass or plastic core surrounded by cladding and an outer protective jacket.", "topic": "CN"}, {"id": "pdf5-018", "question": "_____ is the concept in which a process is copied into main memory from the secondary memory according to the requirement.", "options": ["Paging", "Demand paging", "Segmentation", "Swapping"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Demand paging loads a page into main memory from secondary storage only when it is actually needed (referenced), rather than loading the whole process upfront.", "topic": "OS"}, {"id": "pdf5-019", "question": "____ provide member functions for repositioning the file-position pointer.", "options": ["istream", "ostream", "istream and ostream", "None"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "istream provides seekg() and ostream provides seekp() for repositioning the get and put file-position pointers respectively, so both classes together provide this capability.", "topic": "C/C++"}, {"id": "pdf5-020", "question": "____ is designed to use the high bandwidth capability of fiber-optic cable.", "options": ["WDM", "FDM", "TDM", "None of the above"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "WDM (Wavelength Division Multiplexing) is designed specifically to exploit the very high bandwidth of fiber-optic cable by combining multiple light-wavelength signals on one fiber.", "topic": "CN"}, {"id": "pdf5-021", "question": "____ function can create versions of the add function for adding the int, float or double type values.", "options": ["Sum()", "Add()", "Total()", "all"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Function overloading lets multiple versions of a function share the same name (Add) while differing in parameter types (int, float, double), so Add() is the function being overloaded.", "topic": "C/C++"}, {"id": "pdf5-022", "question": "____ data type represents the file stream generally, and has the capabilities of both ofstream and ifstream which means it can create files, write information to files, and read information from files.", "options": ["Fstream", "stream", "filestream", "None"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "fstream is the C++ file stream class that combines the read capability of ifstream and the write capability of ofstream, allowing both reading and writing to files.", "topic": "C/C++"}, {"id": "pdf5-023", "question": "Which of the following statements is false?", "options": ["The halting problem for Turing machine is undecidable.", "Determining whether a context-free grammar is ambiguous is undecidable.", "Given two arbitrary context-free grammars, G1 and G2 , it is undecidable with L(G1) = L(G2)", "Given two regular grammars G1 and G2 , it is undecidable whether L(G1) = L(G2)"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Equivalence of two regular grammars (or DFAs) IS decidable via minimization/comparison algorithms, unlike halting, CFG ambiguity, and CFG equivalence which are all undecidable, so statement 4 is the false one.", "topic": "TOC"}, {"id": "pdf5-024", "question": "Which one of the following is decidable?", "options": ["Given a string M, a string s, and an integer k, M accepts s with k steps", "Equivalence of two given Turing machines", "Language accepted by a given DFA is nonempty", "Language generated by a CFG is nonempty"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "The question is ambiguous: bounded halting (M accepts s within k steps) is decidable, but DFA-language-nonempty and CFG-language-nonempty are also decidable problems, so multiple options technically qualify; only Turing machine equivalence is truly undecidable. The answer key's choice of option 1 is kept since the question as posed doesn't cleanly isolate one correct answer.", "topic": "TOC"}, {"id": "pdf5-025", "question": "0n2 1n The language { / n \u22650 } over the alphabet { 0, 1, 2} is", "options": ["Not recursive", "is recursive and is a deterministic CFL", "is a regular language", "is not a deterministic CFL but a CFL."], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The language {0^n 2 1^n : n \u2265 0} can be recognized by a deterministic pushdown automaton that pushes 0's, then pops one for each 1 after seeing the unambiguous center marker '2', making it both recursive and a deterministic CFL.", "topic": "TOC"}, {"id": "pdf5-026", "question": "It is undecidable, whether", "options": ["an arbitrary TM has 15 states", "an arbitrary TM halts after 10 steps", "an arbitrary TM ever prints a specific letter", "an arbitrary TM accepts a string w in 5 steps"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Whether a TM ever prints a given symbol is undecidable (a classic halting-problem reduction), while checking state count or simulating a fixed number of steps is always decidable.", "topic": "TOC"}, {"id": "pdf5-027", "question": "1) Which of these statements is TRUE about a LAN?", "options": ["a. A LAN connects computers in a small area such as an office", "a. A modem is needed to connect a computer to a LAN", "a. A LAN consists of only one computer", "a. Internet is a LAN"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A LAN (Local Area Network) connects computers within a small geographic area like an office or building; it needs no modem, has multiple nodes, and is not the same as the Internet.", "topic": "CN"}, {"id": "pdf5-028", "question": "Which one of the following protocols is used for the noisy channel?", "options": ["Simplest protocol", "Half duplex", "Selective repeat ARQ", "Hybrid"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Selective-Repeat ARQ is designed for noisy channels since it adds error and flow control by retransmitting only corrupted or lost frames; the other listed options aren't real noisy-channel protocols.", "topic": "CN"}, {"id": "pdf5-029", "question": "Which of the following is not a primitive root of 17?", "options": ["7", "10", "14", "4"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "4 mod 17 has order 4 (4^4 = 256 = 1 mod 17), not the full order 16, so it is not a primitive root; 7, 10, and 14 all have order 16 mod 17.", "topic": "Information Security"}, {"id": "pdf5-030", "question": "Which error detection method uses one's complement arithmetic?", "options": ["Simple parity check", "Checksum", "Two-dimensional parity check", "CRC"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The checksum method sums data segments using one's complement arithmetic and sends the complement of the sum as the check value.", "topic": "CN"}, {"id": "pdf5-031", "question": "Which error detection method involves polynomials?", "options": ["CRC", "Simple parity check", "Two-dimensional parity check", "Checksum"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "CRC (Cyclic Redundancy Check) treats bit strings as polynomials and uses polynomial (modulo-2) division to generate the check bits.", "topic": "CN"}, {"id": "pdf5-032", "question": "What is the minimum hamming distance of this coding scheme d (01101,10011)?", "options": ["1", "2", "3", "4"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Comparing 01101 and 10011 bit by bit, positions 1-4 differ and position 5 matches, giving a Hamming distance of 4.", "topic": "CN"}, {"id": "pdf5-033", "question": "What is the efficiency of the Go back N ARQ protocol?", "options": ["N = N / (2a + 2a)", "N = N / (1 + 2a)", "N = N * (2a + 2a)", "N = N * (1 + 2a)"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The standard efficiency formula for Go-Back-N ARQ is N/(1+2a), where N is the window size and a is the propagation-to-transmission time ratio.", "topic": "CN"}, {"id": "pdf5-034", "question": "The term that refers to a set of procedures used to restrict the amount of data that the sender can send before waiting for acknowledgment is", "options": ["Error control", "Flow control", "Delay", "Byte stuffing"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Flow control is the mechanism that limits how much data a sender can transmit before it must wait for acknowledgment, preventing the receiver from being overwhelmed.", "topic": "CN"}, {"id": "pdf5-035", "question": "The hamming distance between the words 101101101 and 110110010 is", "options": ["4", "5", "6", "7"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Comparing 101101101 and 110110010 bit by bit, the bits differ at 7 of the 9 positions, giving a Hamming distance of 7.", "topic": "CN"}, {"id": "pdf5-036", "question": "The ________ method provides a one-time session key for two parties.", "options": ["Diffie-Hell man", "RSA", "DES", "AES"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Diffie-Hellman key exchange lets two parties derive a shared one-time session key over an insecure channel without ever transmitting the key itself.", "topic": "Information Security"}, {"id": "pdf5-037", "question": "Protocols in which the sender waits for a positive acknowledgment before advancing to the next data item are often called", "options": ["ARQ", "PPR", "ARS", "PRS"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "ARQ stands for Automatic Repeat reQuest, the family of protocols where the sender waits for a positive acknowledgment before sending the next item and retransmits if none arrives.", "topic": "CN"}, {"id": "pdf5-038", "question": "Parity bits are used for which of the following purposes?", "options": ["Encryption of data", "To transmit faster", "To detect errors", "To identify the user"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Parity bits are a simple error-detection mechanism, added so the receiver can check whether a bit was flipped during transmission.", "topic": "CN"}, {"id": "pdf5-039", "question": "In the _________Protocol, if no acknowledgment for a frame has arrived, we resend all outstanding frames.", "options": ["Stop-and-W ait", "Simplest", "Go-Back-N ARQ", "Selective-R epeat ARQ"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "In Go-Back-N ARQ, if an acknowledgment times out the sender resends the entire window of outstanding (unacknowledged) frames, not just the lost one.", "topic": "CN"}, {"id": "pdf5-040", "question": "In the _________ Protocol, the sender sends one frame, stops until it receives confirmation from the receiver, and then sends the next frame.", "options": ["Stop-and-W ait", "Simplest", "Go-Back-N ARQ", "Selective-R epeat ARQ"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Stop-and-Wait is defined by sending exactly one frame, then pausing until the receiver's acknowledgment arrives before sending the next frame.", "topic": "CN"}, {"id": "pdf5-041", "question": "In the _________ Protocol, the sender sends its frames one after another with no regard to the receiver.", "options": ["Stop-and-W ait", "Simplest", "Go-Back-N ARQ", "Selective-R epeat ARQ"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The Simplest Protocol has no flow or error control, so the sender just transmits frames back-to-back regardless of the receiver's state.", "topic": "CN"}, {"id": "pdf5-042", "question": "In the _________ protocol we avoid unnecessary transmission by sending only frames that are corrupted.", "options": ["Stop-and-W ait ARQ", "Go-Back-N ARQ", "Selective-Re peat ARQ", "None of the above"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Selective-Repeat ARQ retransmits only the specific frames that were corrupted or lost, avoiding the wasted retransmissions that Go-Back-N causes.", "topic": "CN"}, {"id": "pdf5-043", "question": "In stop and wait flow control, for n data packets sent, how many acknowledgments are needed?", "options": ["n-1", "n", "2n", "n+1"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "In stop-and-wait flow control every single data packet must be individually acknowledged before the next is sent, so n packets require n acknowledgments.", "topic": "CN"}, {"id": "pdf5-044", "question": "In stop and wait automatic repeat request, acknowledgment number is announced in the sequence of", "options": ["Next frame", "Previous frame", "Zeros", "Last frame"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "In Stop-and-Wait ARQ the acknowledgment number announces the sequence number of the next frame the receiver expects, not the frame just received.", "topic": "CN"}, {"id": "pdf5-045", "question": "In Selective Repeat ARQ, if 4 is the number of bits for the sequence number, then the maximum size of the send window must be _____.", "options": ["15", "16", "31", "8"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "For Selective-Repeat ARQ the maximum send window size is 2^(m-1); with m=4 sequence bits that is 2^3 = 8.", "topic": "CN"}, {"id": "pdf5-046", "question": "In Selective Repeat ARQ, if 4 is the number of bits for the sequence number, then the maximum size of the receive window must be _____.", "options": ["15", "16", "31", "8"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "In Selective-Repeat ARQ the receive window is always the same size as the send window, 2^(m-1); with m=4 that gives 8.", "topic": "CN"}, {"id": "pdf5-047", "question": "In Go-Back-N ARQ, if frames 5, 6, and 7 are received successfully, the receiver may send an ACK _________ to the sender.", "options": ["5", "6", "7", "8"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Go-Back-N uses cumulative acknowledgments naming the next frame expected, so after correctly receiving frames 5, 6, and 7 the receiver sends ACK 8.", "topic": "CN"}, {"id": "pdf5-048", "question": "In Go-Back-N ARQ, if 10 is the number of bits for the sequence number, then the maximum size of the receive window must be _____.", "options": ["15", "16", "31", "1"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Go-Back-N ARQ always uses a receive window of size 1, regardless of how many bits are used for the sequence number, because frames must be accepted strictly in order.", "topic": "CN"}, {"id": "pdf5-049", "question": "In CRC if the data unit is 100110111 and the divisor is 1111 then what is dividend at the receiver?", "options": ["1001110011 01", "1001101110 01", "100111001", "1001110011 10"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "low", "reasoning": "Dividing data 100110111 (padded with 3 zero bits) by divisor 1111 using modulo-2 division gives remainder 101, so the transmitted/received codeword should be 100110111101; the listed option text is garbled by extraction artifacts and doesn't cleanly match this, so the originally marked option is kept.", "topic": "CN"}, {"id": "pdf5-050", "question": "If the sender of a statement cannot successfully dispute its authorship, this ability is called ____________.", "options": ["Authenticati on", "Non-repudia tion", "Confidential ity", "Integrity"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Non-repudiation is the security property ensuring a sender cannot later deny having sent a message, typically enforced through digital signatures.", "topic": "Information Security"}, {"id": "pdf5-051", "question": "If the information is protected from unauthorized change which of the following holds good.", "options": ["Availability", "Authenticity", "Non-repudia tion", "Integrity"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Integrity is the CIA-triad property that guarantees information hasn't been altered by unauthorized parties; availability, authenticity, and non-repudiation address different concerns.", "topic": "Information Security"}, {"id": "pdf5-052", "question": "Error control in the data link layer is based on", "options": ["Automatic repeat request", "Manually repeat request", "Situation based", "Terminated request"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Data link layer error control relies on ARQ (Automatic Repeat reQuest), where the receiver requests retransmission of corrupted or lost frames.", "topic": "CN"}, {"id": "pdf5-053", "question": "CRC stands for", "options": ["Cyclic Redundancy Check", "Code Repeat Check", "Code Redundancy Check", "Cyclic Repeat Check"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "CRC is the standard abbreviation for Cyclic Redundancy Check, a checksum-based error-detection technique.", "topic": "CN"}, {"id": "pdf5-054", "question": "Caesar Cipher is also referred to as _________", "options": ["Shift Cipher", "Row transpositio n cipher", "One \u2013 pad", "None of the choices"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The Caesar cipher shifts each letter by a fixed number of positions, which is why it's commonly called a Shift Cipher.", "topic": "Information Security"}, {"id": "pdf5-055", "question": "Bob receives a message digitally signed by Alice. Bob wants to verify the signature, he requires?", "options": ["Alice\u2019s Public key", "Bob\u2019s Public Key", "Alice\u2019s Private Key", "Bob\u2019s Private Key"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Digital signatures are verified with the signer's public key, so Bob needs Alice's public key to check a signature she created with her private key.", "topic": "Information Security"}, {"id": "pdf5-056", "question": "An error detecting code is which code is the remainder resulting from dividing the bits to be checked by a predetermined binary number, is known as", "options": ["Cyclic redundancy check", "Checksum", "Error detecting code", "Hamming code"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "This describes CRC exactly: the transmitted bits are divided by a fixed generator polynomial/binary number and the remainder forms the check value.", "topic": "CN"}, {"id": "pdf5-057", "question": "______________ attacks involve modification of the contents of the message.", "options": ["Passive", "Active", "Both Passive and Active", "None of the given choices"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Active attacks alter data or system state (e.g., modification, replay, masquerade); passive attacks only eavesdrop without changing content.", "topic": "Information Security"}, {"id": "pdf5-058", "question": "_____________ is a technique of decoding messages from a non-readable form back to readable format without knowing how they were initially converted from readable format to non-readable format.", "options": ["Cryptograph y", "Encryption", "Decryption", "Cryptanalysi s"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Recovering readable text from ciphertext without knowledge of how it was encrypted is the definition of cryptanalysis (as opposed to decryption, which assumes the key/method is known).", "topic": "Information Security"}, {"id": "pdf5-059", "question": "___________ is referred to the process of analysing information systems using mathematical formulas to understand the hidden aspects of the system.", "options": ["Cryptograph y", "Cryptanalysi s", "Cryptology", "None of the choices"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Cryptanalysis is the mathematical study of cryptographic systems aimed at uncovering weaknesses or hidden information, distinct from cryptography (which builds the systems).", "topic": "Information Security"}, {"id": "pdf5-060", "question": "___________ is the relationship between the message and signature in case of Digital Signature.", "options": ["Many to One", "One to Many", "Many to Many", "One to One"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Each message produces a unique signature tied to its own hash, so the message-to-signature relationship in digital signatures is one-to-one.", "topic": "Information Security"}, {"id": "pdf5-061", "question": "The term that is used to set standards to enable intercommunication among equipment from a variety of manufactures is called", "options": ["a. project 802", "a. project 8802", "a. project 208", "a. project 2088"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "IEEE Project 802 defines LAN/MAN standards so that equipment from different manufacturers can interoperate.", "topic": "CN"}, {"id": "pdf5-062", "question": "IEEE standard was adopted by", "options": ["ISO", "ANSI", "OSI", "IEEE"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "low", "reasoning": "IEEE 802 standards were adopted both by ANSI (as American national standards) and by ISO (as the ISO 8802 series), so without the exact source wording this question is ambiguous; the source's marked answer (ANSI) is kept.", "topic": "CN"}, {"id": "pdf5-063", "question": "Which of the following symmetric block cipher supports multiple key sizes?", "options": ["DES", "AES", "Double DES", "Triple DES"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "AES supports multiple key sizes (128, 192, and 256 bits), unlike DES/Double DES/Triple DES which use fixed 56-bit component keys.", "topic": "Information Security"}, {"id": "pdf5-064", "question": "Which of the following ensures that data received was sent by the specified sender?", "options": ["Confidentiality", "Authenticity", "Non-repudiation", "None of the choices"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "low", "reasoning": "This phrasing sits between Authenticity (verifying the claimed sender) and Non-repudiation (sender can't deny sending it); the definitions overlap enough that the source's marked answer, Non-repudiation, is kept without full confidence.", "topic": "Information Security"}, {"id": "pdf5-065", "question": "Which of the following encryption has the capability for computing over encrypted data without access to the secret key?", "options": ["Homomorphic Encryption", "RSA", "Elliptic Curve cryptography", "None of the choices"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Homomorphic encryption uniquely allows computations to be performed directly on encrypted data without decrypting it or needing the secret key.", "topic": "Information Security"}, {"id": "pdf5-066", "question": "To construct cipher text, __________________ technique reorders plaintext characters.", "options": ["Substitution", "Transposition", "neither (a) nor (b)", "both (a) and (b)"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Transposition ciphers rearrange (reorder) the positions of plaintext characters, while substitution ciphers replace characters with others.", "topic": "Information Security"}, {"id": "pdf5-067", "question": "The science and art of converting messages to make them secure and resistant to attacks is known as _________________.", "options": ["Cryptography", "Cryptanalysis", "Cryptology", "None of the choices"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Cryptography is defined as the art and science of transforming messages to make them secure against adversaries.", "topic": "Information Security"}, {"id": "pdf5-068", "question": "DES will fall under the category of ___________", "options": ["Electronic Cipher Book", "Electronic Code Book", "Complex block cipher", "None of the choices"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "low", "reasoning": "Strictly, Electronic Code Book (ECB) is a mode of operation rather than a 'category' DES belongs to (DES is itself a complex/Feistel block cipher), so this question's wording is imprecise; the source's marked answer is kept.", "topic": "Information Security"}, {"id": "pdf5-069", "question": "A ________ is used to verify the integrity of a message.", "options": ["Message digest", "Decryption algorithm", "Digital envelope", "None of the above"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A message digest (cryptographic hash) is used to verify that a message hasn't been altered, confirming its integrity.", "topic": "Information Security"}, {"id": "pdf5-070", "question": "In IDEA, the key size is ____________", "options": ["128 bytes", "128 bits", "256 bytes", "256 bits"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "IDEA (International Data Encryption Algorithm) uses a 128-bit key.", "topic": "Information Security"}, {"id": "pdf5-071", "question": "Which of these is a disadvantage of a Bus network?", "options": ["Expensive", "Needs extra hardware", "Slow", "To connect devices to each other"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Bus topology performance degrades and communication slows as more devices/traffic are added to the shared cable, which is its main practical disadvantage among the given options.", "topic": "CN"}, {"id": "pdf5-072", "question": "_________ is a communications protocol standard for transmitting small amounts of digital information using conventional FM Sound Broadcast techniques", "options": ["Radio System", "Radio Data System", "Radio Broadcast Data System", "Broadcast Data System"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "RDS (Radio Data System) is the standard for embedding small amounts of digital data within conventional FM broadcast signals.", "topic": "CN"}, {"id": "pdf5-073", "question": "Which of the following statement/statements is/are TRUE, with respect to vectored interrupts?", "options": ["In vectored interrupt, device identifies itself to the processor by sending the starting address of the service routine.", "Code sent by the vectored interrupt are upto 32 bits", "In vectored interrupt starting address sent by the device to identify itself is referred as \u201cservice location\u201d", "All the mentioned options"], "correct": 1, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "In vectored interrupts the device identifies itself by sending the starting address of its service routine (the 'interrupt vector'); that address is not called a 'service location', and the identifying code is typically only a few bits (not up to 32 bits), so statement 1 is the true one, not statement 2.", "topic": "CAO"}, {"id": "pdf5-074", "question": "Which of the following statement/statements is/are FALSE with respect to Centralized BUS arbitration?", "options": ["In centralized BUS arbitration, the processor takes into account the various parameters and assigns the BUS to that device", "Centralized Bus arbitration involves both Processor and DMA controller for its processing.", "Centralized Bus arbitration is similar to Priority interrupt circuit.", "None of the mentioned options."], "correct": 3, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "Centralized bus arbitration is analogous to a daisy-chain priority circuit, not a priority interrupt circuit, so statement 3 is the false one; the processor-parameter description in statement 1 is actually accurate.", "topic": "CAO"}, {"id": "pdf5-075", "question": "Which of the following statement is CORRECT, when the process request for DMA operation.", "options": ["The process, which has requested for DMA is temporarily suspended.", "The process, which has requested for DMA continues execution.", "Another process, gets executed.", "The process, which has requested for DMA is temporarily suspended and another process start executing."], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "When a process requests a DMA transfer it is suspended (blocked waiting for I/O completion) while the CPU is freed up to schedule and run another process.", "topic": "CAO"}, {"id": "pdf5-076", "question": "Which of the following RAID levels gives the striping at the Block level and double distributed parity for address both speed and fault tolerance issue.", "options": ["RAID 10", "RAID 2", "RAID 6", "RAID 5"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "RAID 6 uses block-level striping plus double distributed parity, so it can survive two disk failures while still giving good speed from striping.", "topic": "CAO"}, {"id": "pdf5-077", "question": "Which of the following is TRUE, with respect to RAID 5,", "options": ["Distributed Parity", "Minimum number of Disks required is 3", "High hardware cost for implementation", "All the mentioned options"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "low", "reasoning": "RAID 5 does need a minimum of 3 disks, but it also genuinely uses distributed parity (option 1) and has low, not high, hardware cost - two options are individually true, making the question ambiguous.", "topic": "CAO"}, {"id": "pdf5-078", "question": "Which of the following is TRUE, w. r. t, \u201cdifference between DMA and Interrupt mode of I/ O data transfer\u201d?", "options": ["DMA involves the processor for the I/O transfer", "The rate of data transfer is moderate in DMA", "The amount of data transfer is less in DMA", "None of the mentioned options."], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "DMA bypasses the processor entirely during transfer, moves data at a much higher rate than interrupt-driven I/O, and can transfer large blocks - so all three prior statements are false and 'None' is correct.", "topic": "CAO"}, {"id": "pdf5-079", "question": "Which of the following is not under the category of Flynn\u2019s classification", "options": ["SISD", "MIMD", "SIMD", "None of the mentioned options"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "SISD, SIMD and MIMD (along with MISD) are all genuine categories in Flynn's classification, so none of the listed options is actually excluded from it.", "topic": "CAO"}, {"id": "pdf5-080", "question": "Which of the following has the highest data rate?", "options": ["RAID 1", "RAID 3", "RAID 4", "RAID 5"], "correct": 2, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "RAID 3 (bit-interleaved parity) engages every disk in parallel on each request, giving it the highest data transfer rate for large transfers among these levels - not RAID 1, whose transfer rate is essentially that of a single disk.", "topic": "CAO"}, {"id": "pdf5-081", "question": "The significance of I/O mapped I/O with memory mapped I/O is", "options": ["I/O mapped I/O is faster than memory mapped I/O in terms of data transfer.", "I/O mapped I/O devices have large buffer space.", "I/O mapped I/O devices need to deal with only fewer address lines at the time of communication.", "All the mentioned options."], "correct": 3, "original_marked": null, "matches_original": false, "confidence": "high", "reasoning": "I/O-mapped I/O uses a separate, much smaller address space than memory-mapped I/O, so devices only need to decode a few address lines during communication.", "topic": "CAO"}, {"id": "pdf5-082", "question": "The mechanism in which I/O device is accessed by continuous monitoring its status using status flag is referred as ___________________________", "options": ["Program \u2013 controlled I/O", "Memory mapped I/O", "I/ O mapped I/O", "Interrupt driven I/O"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Repeatedly checking a device's status flag in a loop before transferring data is exactly what program-controlled (polling) I/O means.", "topic": "CAO"}, {"id": "pdf5-083", "question": "The _________________ is used to overcome the contention over the BUS possession and usage.", "options": ["Multiple BUS structure", "Single BUS Structure", "BUS Optimizers", "BUS arbitrator"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A bus arbitrator is the hardware that grants bus ownership to one requesting master at a time, which is exactly how bus contention is resolved.", "topic": "CAO"}, {"id": "pdf5-084", "question": "State the number of registers present in DMA controller", "options": ["1", "2", "3", "No registers"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "A basic DMA controller has three registers: an address register, a word/byte count register, and a control/status register.", "topic": "CAO"}, {"id": "pdf5-085", "question": "Overall speed of transfer in RAID level 4 is", "options": ["Low", "Very low", "High", "None of the mentioned options"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "RAID 4 stripes data across independent disks with a single dedicated parity disk, giving high read throughput since data disks can be read independently and in parallel.", "topic": "CAO"}, {"id": "pdf5-086", "question": "Once DMA transfer is completed, it is notified to the CPU through ____________ signal", "options": ["Acknowledgement signal", "Interrupt Signal", "Program status word", "None of the mentioned options."], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Once a DMA controller finishes its transfer, it raises an interrupt to notify the CPU that the data is ready, since the CPU was not involved during the transfer itself.", "topic": "CAO"}, {"id": "pdf5-087", "question": "In bus arbitration, the controller which initiates data communication on the BUS at any time is called", "options": ["Bus Arbitrator", "Bus Master", "Processor", "Controller"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The device currently in control of the bus and driving a data transfer is called the bus master; arbitration decides which requester becomes master next.", "topic": "CAO"}, {"id": "pdf5-088", "question": "How interrupt latency can be reduced?", "options": ["Amount of information saved automatically by the processor when an interrupt request should be kept to a minimum.", "By means of shadow registers", "Processor with small number of registers, hardware unit is used to save the information automatically, once the processor accepts the interrupt request.", "All the mentioned options."], "correct": 4, "original_marked": 1, "matches_original": false, "confidence": "low", "reasoning": "Minimizing automatically-saved processor state, using shadow registers, and using a dedicated hardware unit to save context are all recognized, independent techniques for cutting interrupt latency, so 'all of the mentioned options' fits better than singling out just one.", "topic": "CAO"}, {"id": "pdf5-089", "question": "During DMA transfer, the signals and addresses are issued by the _______________ unit", "options": ["DMA controllers", "Device drivers", "CPU", "The program itself"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "During a DMA transfer the DMA controller itself drives the address and control lines on the bus, which is the whole point of offloading the transfer from the CPU.", "topic": "CAO"}, {"id": "pdf5-090", "question": "DMA transfer is initiated by ________________ of the following", "options": ["Processor", "The process being executed", "I/O devices", "Operating System"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The processor sets up the DMA controller's registers (address, count, direction) to start a DMA transfer before stepping back and letting the controller run it.", "topic": "CAO"}, {"id": "pdf5-091", "question": "Decomposing the instruction execution into sub-tasks, each sub-tasks were executed in exclusive unit, all such units operate concurrently, and the defined technique is referred as _____________", "options": ["UMA", "DMA", "Pipelining", "Vector Processing"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Breaking instruction execution into stages that run concurrently in separate hardware units, each working on a different instruction, is the definition of pipelining.", "topic": "CAO"}, {"id": "pdf5-092", "question": "_____________ is the efficient method to implement multiple interrupt handling.", "options": ["Polling Method", "Vectored interrupts", "Interrupt nesting", "None of the mentioned options"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Interrupt nesting lets a higher-priority interrupt preempt a lower-priority one currently being serviced, which is the standard efficient way to manage multiple simultaneous interrupts by priority.", "topic": "CAO"}, {"id": "pdf5-093", "question": "Which of the following statement is TRUE, with respect to \u201cdifference between subroutines and interrupt-service enabled\u201d?", "options": ["During subroutine execution, the changes in status information and content registers are anticipated", "During subroutine execution, the changes in status information and content registers are unanticipated", "During interrupt service enabling, the changes in status information and content registers are anticipated.", "None of the mentioned options"], "correct": 1, "original_marked": null, "matches_original": false, "confidence": "high", "reasoning": "A subroutine call is planned by the programmer, so exactly which registers and flags it will change is known (anticipated) in advance, unlike an interrupt, which arrives asynchronously and is inherently unanticipated.", "topic": "CAO"}, {"id": "pdf5-094", "question": "Which of following statement/statements is /are TRUE, w. r. t DMA Controller?", "options": ["The DMA controller can perform operations on two different disks simultaneous, if the appropriate details are known.", "The DMA controller is directly connected to the system bus to provide faster access.", "When the R/W bit of the status register of the DMA controller is set to 1, then Read operation is performed.", "All the mentioned options."], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "low", "reasoning": "The DMA controller sits directly on the system bus and a status-register R/W bit conventionally flags a read, but whether a single controller can truly run two disks at once is debatable, so 'all of the mentioned' is only a moderately confident pick.", "topic": "CAO"}, {"id": "pdf5-095", "question": "The control circuit which is responsible for the DMA transfer is known as _________", "options": ["DMA controller", "DMA interface", "Data Controller", "CPU control unit."], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The DMA controller is the dedicated control circuit that manages address generation and bus signaling for a DMA transfer, independent of the CPU.", "topic": "CAO"}, {"id": "pdf5-096", "question": "MIMD classified computers are known as ______________, if the processor has high degree of interactions among themselves.", "options": ["UMA", "NUMA", "Dynamic Memory accessing", "Random Memory Accessing"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Tightly-coupled MIMD systems that share memory through a common bus are split into UMA and NUMA; UMA machines give every processor equally fast, uniform access to shared memory, which corresponds to the highest degree of processor-to-processor interaction.", "topic": "CAO"}, {"id": "pdf5-097", "question": "I/O device is connected to the interconnection network by using a device interface, the interface includes _________________________registers accessed by the processor.", "options": ["Data", "Status", "Control", "Data, Status and Control"], "correct": 4, "original_marked": null, "matches_original": false, "confidence": "high", "reasoning": "A standard I/O device interface exposes data, status, and control registers to the processor, not just one of the three.", "topic": "CAO"}, {"id": "pdf5-098", "question": "High-speed of I/O data transfer is possible by using _______________ mechanism", "options": ["Interrupt driven I/O", "Program \u2013 controlled I/O", "DMA", "Memory mapped I/O"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "DMA transfers data directly between device and memory without routing every word through the CPU, making it the fastest of the listed I/O mechanisms.", "topic": "CAO"}, {"id": "pdf5-099", "question": "Worst-case complexity is mostly used in algorithm designs instead of remaining complexity cases. Because of", "options": ["Worst-case complexity measure is simple and easy.", "Worst-case complexity has better understanding parameters.", "Best-case for almost any algorithm is trivial and determination of Average case complexity requires more parameters.", "None"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Best-case analysis is usually trivial (e.g., an already-sorted array) and average-case analysis needs a probability distribution over inputs, so worst-case analysis is preferred as a simple, guaranteed upper bound.", "topic": "DSA"}, {"id": "pdf5-100", "question": "Which of the following is an undecidable problem?", "options": ["Euler\u2019s circuit problem", "Halting problem", "Traveling sales man problem", "Knapsack problem"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The Halting Problem is the classic example proven by Turing to be undecidable - no general algorithm can determine whether an arbitrary program halts on a given input.", "topic": "TOC"}, {"id": "pdf5-101", "question": "Which of the following way is best to represent the algorithms", "options": ["English literature step by step", "Flowchart", "Pseudocode", "None"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Pseudocode is preferred because it is precise and close to real code, unlike natural language (ambiguous) or flowcharts (hard to use for complex logic).", "topic": "DSA"}, {"id": "pdf5-102", "question": "Which of the following statement is the correct reason for analyzing algorithms?", "options": ["To choose the best algorithm for a particular task", "To study and improve the algorithm performance from existing algorithms", "Both", "None"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Algorithm analysis is done both to pick the best algorithm for a task and to improve on existing algorithms' performance, so both reasons apply.", "topic": "DSA"}, {"id": "pdf5-103", "question": "Which of the following statement is correct for Recursion", "options": ["Structure or code representation is complex.", "Used First in First out principle.", "Required more memory space to hold intermediate results on the system stacks.", "Took less time than iterative method."], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Recursive calls are pushed onto the system call stack, so recursion needs extra memory to hold intermediate states until the base case unwinds.", "topic": "DSA"}, {"id": "pdf5-104", "question": "Which of the following is not NP-Hard problem", "options": ["Hamiltonian Cycle Problem", "Travelling Salesman Problem", "Euler\u2019s circuit problem", "All the above"], "correct": 3, "original_marked": 4, "matches_original": false, "confidence": "high", "reasoning": "Hamiltonian Cycle and TSP are both NP-hard, but the Eulerian circuit problem is solvable in polynomial time (a connected graph has one iff every vertex has even degree), so it is the one that is NOT NP-hard.", "topic": "TOC"}, {"id": "pdf5-105", "question": "Which of the following is not criteria for algorithms", "options": ["Alertness", "Definiteness", "Finiteness", "Effectiveness"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The standard algorithm criteria are input, output, definiteness, finiteness, and effectiveness; \"alertness\" is not one of them.", "topic": "DSA"}, {"id": "pdf5-106", "question": "Which of the following is compulsory criteria for algorithms", "options": ["Easiness", "Simple", "Activeness", "Finiteness"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Finiteness (the algorithm must terminate after a finite number of steps) is one of the five compulsory criteria of an algorithm.", "topic": "DSA"}, {"id": "pdf5-107", "question": "What is the primary usage of asymptotic analysis?", "options": ["Measure the efficiency of algorithms that don\u2019t depend on machine-specific constants.", "Used to judge an algorithm whether is it suitable to a particular system or not", "Used to find the minimum specification of hardware to execute the algorithm", "None"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Asymptotic analysis measures how an algorithm's running time or space grows with input size, independent of machine-specific constants.", "topic": "DSA"}, {"id": "pdf5-108", "question": "Use of Omega notation (\u03a9) notation?", "options": ["To specify the least or minimum amount of resources that needed over all inputs of size", "To specify Best case complexity", "To Specify Worst case complexity", "Both A and B"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Omega notation gives the asymptotic lower bound, i.e., the minimum resources needed over all inputs of a given size, which is exactly how best-case complexity is described.", "topic": "DSA"}, {"id": "pdf5-109", "question": "Undecidable problems mean:", "options": ["Problems that polynomial algorithms can solve", "Problems that deterministic polynomial algorithms can solve", "Problems that non-deterministic polynomial algorithms can solve", "Problems that any algorithm cannot solve"], "correct": 4, "original_marked": 3, "matches_original": false, "confidence": "high", "reasoning": "An undecidable problem (like the Halting Problem) is one that no algorithm can solve at all, regardless of time taken \u2014 it is not about polynomial or non-deterministic solvability.", "topic": "TOC"}, {"id": "pdf5-110", "question": "The algorithms whose time complexity is O(n2) belong to", "options": ["NP-Hard", "NP-Complete", "P", "None"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "O(n^2) is a polynomial-time complexity, and any problem solvable in polynomial time belongs to class P.", "topic": "TOC"}, {"id": "pdf5-111", "question": "Space complexity is measured using the word. Which of the following statement is correct for term word.", "options": ["Word is a collection of bits stored in computer memory. Its size is a 4 to 64 bits", "Word is a collection variable used in an algorithm, which is a sum of each variable type memory occupied memory.", "Word is a count of statements used in the algorithm", "Word is the total algorithm size."], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "In space complexity analysis, a \"word\" refers to a fixed-size unit of memory (commonly cited as ranging roughly from a few bits up to 64 bits depending on the system); the exact wording of this option is unusual, so treat with some caution.", "topic": "DSA"}, {"id": "pdf5-112", "question": "SAT or B-SAT is an example for", "options": ["NP-Hard", "NP-Complete", "P", "None"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Boolean satisfiability (SAT), by the Cook-Levin theorem, is the classic example of an NP-Complete problem.", "topic": "TOC"}, {"id": "pdf5-113", "question": "P class problem means:", "options": ["Problems that can be solvable in polynomial time", "Tractable problems.", "whose time complexity is O(N^c) where N is input size and C is constant", "All"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Class P problems are exactly those solvable in polynomial time (O(N^c)), which makes them tractable, so all three statements describe P correctly.", "topic": "TOC"}, {"id": "pdf5-114", "question": "One problem which is known to be NP-Complete and from that problem give Transformation to some other problem in NP, then that NP problem becomes:", "options": ["NP-Hard", "NP-Complete", "P", "None"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "If an NP-complete problem reduces in polynomial time to a problem that is already in NP, that target problem is NP-hard and in NP, which by definition makes it NP-Complete.", "topic": "TOC"}, {"id": "pdf5-115", "question": "NP-complete problems mean:", "options": ["Problems in NP", "Problems in P", "Problems in NP and NP-Hard", "Problems in P and NP"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "NP-Complete problems are defined as the intersection of NP and NP-Hard: they are in NP and every NP problem reduces to them.", "topic": "TOC"}, {"id": "pdf5-116", "question": "NP class of decision problem can be:", "options": ["Solved by non-deterministic polynomial algorithms", "Solved by deterministic polynomial algorithms", "Solved by polynomial algorithms", "None"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "NP decision problems are those solvable by a non-deterministic algorithm in polynomial time (equivalently, verifiable in polynomial time on a deterministic machine).", "topic": "TOC"}, {"id": "pdf5-117", "question": "In recursion, which data structure were used", "options": ["Hash table", "Stack", "Queue", "Dictionary"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Recursive function calls are managed using a stack (the call stack), which tracks each call's state until it returns.", "topic": "DSA"}, {"id": "pdf5-118", "question": "In Algorithm time complexity analysis which of the following is correct?", "options": ["Only compile time is considered.", "Only Execution Time is considered.", "Both Compile execution time is considered.", "None"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Time complexity analysis concerns how execution (run) time grows with input size; compile time is not part of this analysis.", "topic": "DSA"}, {"id": "pdf5-119", "question": "In algorithm analysis, Constant time means?", "options": ["Algorithm terminates after a specified time.", "Algorithm automatically produces output in a specified constant time.", "Algorithm checks whether it can be completed in a given time or not.", "Algorithm requires the same fixed number of steps (regardless of) independent of the input size."], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Constant time, O(1), means the algorithm performs a fixed number of operations regardless of input size.", "topic": "DSA"}, {"id": "pdf5-120", "question": "If every problem in NP can be polynomial-time reducible to a problem \"A,\" and \"A\" is not in NP, then \"A\" is called:", "options": ["NP-Hard", "NP-Complete", "P", "None"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A problem to which every NP problem reduces, but which itself need not be in NP, is by definition NP-Hard.", "topic": "TOC"}, {"id": "pdf5-121", "question": "If every problem in NP can be polynomial-time reducible to a problem \"A,\" and \"A\" is also in NP, then \"A\" is called:", "options": ["NP-Hard", "NP-Complete", "P", "None"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A problem that every NP problem reduces to, and which is itself in NP, satisfies both conditions of NP-Completeness.", "topic": "TOC"}, {"id": "pdf5-122", "question": "Consider two Algorithm\u2019s A and B, with time-complexities 100 n + 1 and n2 + n + 1, respectively. Which of the following statements is correct.", "options": ["Algorithm-A takes almost ten times longer than Algorithm-B.", "Algorithm-A is better than Algorithm-B.", "For smaller input, Algorithm-B is best, and for bigger input, Algorithm-A is best", "For smaller input, Algorithm-A is best, and for bigger input, Algorithm-B is best"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Solving 100n+1 = n^2+n+1 gives a crossover at n=99: for n<99, n^2+n+1 is smaller (B is faster), and for n>99, 100n+1 is smaller (A is faster) \u2014 matching option 3 exactly.", "topic": "DSA"}, {"id": "pdf5-123", "question": "Class NP problems are:", "options": ["verifiable in polynomial time", "Solvable in polynomial time", "Not Solvable in Non polynomial time", "None"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "NP problems are defined as those whose proposed solutions can be verified in polynomial time, not necessarily solved in polynomial time.", "topic": "TOC"}, {"id": "pdf5-124", "question": "Analysis of an Algorithms means", "options": ["Determine the amount of space to store on the hard disk", "Determine the amount of duration to execute or RUN", "Determining the amount of electrical power to complete the algorithm task.", "Determining the required number of instructions and storage memory required for an algorithm."], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Analysis of algorithms means determining the time (number of instructions/steps) and space (memory) an algorithm requires, which is the most complete option given.", "topic": "DSA"}, {"id": "pdf5-125", "question": "In a full binary tree if there are L leaves, then total number of nodes N are?", "options": ["a) N = 2*L", "b) N = L + 1", "c) N = L \u2013 1", "d) N = 2*L \u2013 1"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "In a full binary tree, internal nodes = L-1, so total nodes N = (L-1) + L = 2L-1.", "topic": "DSA"}, {"id": "pdf5-126", "question": "Which of the following Recursive Algorithms analysis method is not suitable for all cases.", "options": ["Substitution Method", "Recurrence Tree Method", "Master Method", "None"], "correct": 3, "original_marked": 4, "matches_original": false, "confidence": "high", "reasoning": "The Master Method only applies to recurrences of the exact form T(n)=aT(n/b)+f(n) meeting specific conditions, so it fails for many recurrences that the more general Substitution and Recurrence Tree methods can still handle.", "topic": "DSA"}, {"id": "pdf5-127", "question": "Which operator connects the structure name to its member name?", "options": [".", "->", "-", "*"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The dot (.) operator is used to access a member of a structure directly through the structure variable; -> is used only with pointers to structures.", "topic": "C/C++"}, {"id": "pdf5-128", "question": "Which of the following are themselves a collection of different data types?", "options": ["string", "int", "structures", "char"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "A structure groups together variables of different data types under one name, unlike int, char, or string which are single data types.", "topic": "C/C++"}, {"id": "pdf5-129", "question": "Prior to use a pointer variable", "options": ["It should be declared", "It should be initialized", "It should be either declared or initialized", "It should be declared and initialized"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A pointer must first be declared (to specify its type) and then initialized (assigned a valid address) before it is safely dereferenced or used.", "topic": "C/C++"}, {"id": "pdf5-130", "question": "C structure are also called as", "options": ["Primary datatype", "User-defined datatype", "Built-in datatype", "Default datatype"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Structures are defined by the programmer to group custom fields together, making them user-defined data types as opposed to built-in primitive types.", "topic": "C/C++"}, {"id": "pdf5-131", "question": "What is the average case time complexity for finding the height of the binary tree?", "options": ["a) h = O(loglogn)", "b) h = O(nlogn)", "c) h = O(n)", "d) h = O(log n)"], "correct": 3, "original_marked": 4, "matches_original": false, "confidence": "high", "reasoning": "Computing a binary tree's height requires a traversal that visits every node exactly once, giving O(n) time regardless of whether the tree is balanced, so the complexity is O(n), not O(log n).", "topic": "DSA"}, {"id": "pdf5-132", "question": "What is a full binary tree?", "options": ["a) Each node has exactly zero or two children", "b) Each node has exactly two children", "c) All the leaves are at the same level", "d) Each node has exactly one or two children"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "By definition, a full (or proper) binary tree is one where every node has either zero or exactly two children, never just one.", "topic": "DSA"}, {"id": "pdf5-133", "question": "What is a complete binary tree?", "options": ["a) Each node has exactly zero or two children", "b) A binary tree, which is completely filled, with the possible exception of the bottom level, which is filled from right to left", "c) A binary tree, which is completely filled, with the possible exception of the bottom level, which is filled from left to right", "d) A tree In which all nodes have degree 2"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "A complete binary tree has every level fully filled except possibly the last, and the last level's nodes are filled from left to right with no gaps.", "topic": "DSA"}, {"id": "pdf5-134", "question": "The number of edges from the node to the deepest leaf is called _________ of the tree.", "options": ["a) Height", "b) Depth", "c) Length", "d) Width"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The height of a node (and of the tree, measured from the root) is defined as the number of edges on the longest downward path to a leaf.", "topic": "DSA"}, {"id": "pdf5-135", "question": "Product (productid varchar2(10), productname varchar2(10), product_price number,manufacturing_date date, vendorId varchar2(10)) Vendor (vendorId varchar2(10), vendorname varchar2(10), location varchar2(10)) The sql query to establish not null constraint on the vendorid column in the vendor table is", "options": ["alter table vendor add constraint vendorid not null;", "alter table vendor modify constraint vendorid not null;", "alter table vendor modify vendorid varchar2(10) not null;", "alter table vendor add constraint vendor_nn not null;"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "In Oracle SQL, adding a NOT NULL constraint to an existing column is done with ALTER TABLE ... MODIFY <column> <datatype> NOT NULL, not with an ADD CONSTRAINT clause that omits the column definition.", "topic": "DBMS"}, {"id": "pdf5-136", "question": "Some addresses in the address space of the processor are assigned to I/O locations, which are implemented as a bit storage circuits organized in the form of registers, and this type of arrangement is called __________________", "options": ["I/O registers", "I/O address space", "Memory mapped I/O", "I/O mapped I/O"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "When I/O device registers are assigned addresses from the same address space as memory, this scheme is called memory-mapped I/O.", "topic": "CAO"}, {"id": "pdf5-137", "question": "Telnet transfer data in", "options": ["Encrypted format", "Secure channel", "Simple plain text", "Privileged mode"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Telnet sends all data, including login credentials, as unencrypted plain text, which is why it is considered insecure.", "topic": "CN"}, {"id": "pdf5-138", "question": "Present-day electronic mail systems are based on", "options": ["Store and forward model", "Save and retrieve model", "Forward and retrieve model", "Save and pop model"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Modern email systems (SMTP-based) use a store-and-forward model, where a message is stored at intermediate servers and forwarded until it reaches the recipient's mailbox.", "topic": "CN"}, {"id": "pdf5-139", "question": "Did FTP link to which protocol stack?", "options": ["Network layer", "TCP/IP layer", "Presentation layer", "Application layer"], "correct": 4, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "FTP is a standard application-layer protocol that runs over TCP, using separate control and data connections; none of the other listed layers correctly classify FTP.", "topic": "CN"}, {"id": "pdf5-140", "question": "Worldwide Web is a collection of", "options": ["Web ID", "Web page", "Web browser", "Web URLs"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The World Wide Web is fundamentally a huge, interlinked collection of web pages (documents) accessible via the internet.", "topic": "CN"}, {"id": "pdf5-141", "question": "Which of the following is an advantage of SNMP?", "options": ["No security risk", "Detailed messages", "High bandwidth", "Support proprietary protocol"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A key advantage of SNMP is that it can carry detailed, descriptive messages between managed devices and the manager, rather than just terse preset codes.", "topic": "CN"}, {"id": "pdf5-142", "question": "Which is false about FTP?", "options": ["Transfer files and folders back and forth", "Builds and maintains a website", "Securely transferring files", "uploads or downloads files"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Standard FTP transmits data and credentials in plain text with no built-in encryption, so 'securely transferring files' is the false statement about it.", "topic": "CN"}, {"id": "pdf5-143", "question": "These are the idempotent method in the stateless protocol", "options": ["PUT", "CONNECT", "POST", "EXIT"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "PUT is idempotent in HTTP because sending the same PUT request multiple times produces the same server state, unlike POST which can create duplicate resources each time.", "topic": "CN"}, {"id": "pdf5-144", "question": "The patch is a request method used for", "options": ["Check server function", "Web browser function", "Partial modification", "Create a tunnel to a server"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "The HTTP PATCH method is used to apply a partial modification to a resource, as opposed to PUT which replaces the entire resource.", "topic": "CN"}, {"id": "pdf5-145", "question": "Numerous IT organizations collect and gather information in hierarchical structure also manage and monitor files with the help of which protocol?", "options": ["SNMP", "Telnet", "FTP", "SMTP"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "SNMP organizes managed information in a hierarchical MIB (Management Information Base) tree, which is exactly the protocol used by organizations to monitor and manage network devices and files.", "topic": "CN"}, {"id": "pdf5-146", "question": "Multiple web resources create common theme forms", "options": ["Website", "Webserver", "Web page", "Web browser"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A website is a collection of related web resources (pages, media, etc.) grouped together under a common theme and typically a single domain.", "topic": "CN"}, {"id": "pdf5-147", "question": "In the Internet stack, the protocol data unit (PDU) for the application layer is", "options": ["Segment", "Datagram", "Message", "Frame"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "The application layer's protocol data unit is called a message (data); segment is transport layer, datagram/packet is network layer, and frame is data link layer.", "topic": "CN"}, {"id": "pdf5-148", "question": "For the client-server model, it uses a separate connection for controlling the data is", "options": ["File transfer protocol", "Dynamic host control protocol", "Secure shell protocol", "IETF"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "FTP uniquely uses two separate TCP connections in the client-server model: one for control commands and one for the actual data transfer.", "topic": "CN"}, {"id": "pdf5-149", "question": "An alert to a remotely located host from one application through agents of management protocol is", "options": ["Inform", "Get", "Trap", "Set"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "In SNMP, a Trap is an unsolicited alert message sent from an agent on a managed device to the manager to report an event, without being polled first.", "topic": "CN"}, {"id": "pdf5-150", "question": "A web page cannot be viewed on the world wide web if", "options": ["Type URL of the page", "Select the hyperlink", "Type HTTP", "Follow resource link"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "This question is ambiguously worded (all listed actions normally do let you view a page), so the source PDF's marked answer is kept rather than guessing.", "topic": "CN"}, {"id": "pdf5-151", "question": "Which detects user activity on the internet and sends the data to a third party in the background?", "options": ["Malware", "Adware", "Spyware", "Security treat"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Spyware secretly monitors a user's online activity and transmits the collected data to a third party without consent.", "topic": "Information Security"}, {"id": "pdf5-152", "question": "Integrates business firewall capabilities with an intrusion prevention system (IPS) and application control using a multi-layered approach known as", "options": ["Packet-filtering firewall", "Stateful Inspection firewall", "Application-level firewall", "Next-Generation firewall"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A Next-Generation Firewall (NGFW) combines traditional firewall filtering with an intrusion prevention system and application-level control in one integrated, multi-layered device.", "topic": "Information Security"}, {"id": "pdf5-153", "question": "Encryption is a form of security. Encryption, on the other hand, offers nothing to keep hackers and other digital pests distant. We'll need? to achieve this objective.", "options": ["Hubs", "Bridge", "Routers", "Firewalls"], "correct": 4, "original_marked": 3, "matches_original": false, "confidence": "high", "reasoning": "Encryption only protects data confidentiality; firewalls are the network devices that actually block unauthorized access and keep hackers out, so the correct option is Firewalls, not Routers.", "topic": "Information Security"}, {"id": "pdf5-154", "question": "This theories talk about Freudian approach that discusses the id, superego, and ego.", "options": ["Trait Personality Theories", "Psychodynamic Personality Theories", "Humanistic Personality Theories", "Self efficacy theories"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Psychodynamic personality theories are rooted in Freud's model of the id, ego, and superego driving personality and behavior.", "topic": "Management"}, {"id": "pdf5-155", "question": "Participative management", "options": ["a) Empower employees", "a) Collective decision making", "Both empower employees and collective decision making", "Neither empower employees nor collective decision making"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Participative management involves both empowering employees with authority and involving them in collective/group decision making, so it covers both listed elements.", "topic": "Management"}, {"id": "pdf5-156", "question": "In his book, Capitalism and Freedom, Milton Friedman argues that ________.", "options": ["doing well while doing good is an essential corporate mantra", "socially responsible behaviour adds to the corporation's bottom line", "corporations are responsible for the environment, society, and profits", "the only social responsibility of business is to increase profits"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "In Capitalism and Freedom, Milton Friedman famously argued that a business's only social responsibility is to increase its profits within the rules of the game.", "topic": "Business Ethics"}, {"id": "pdf5-157", "question": "Ethics training should be part of a ________.", "options": ["reactive strategy", "contextual strategy", "defensive strategy", "proactive strategy"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Ethics training is a preventive measure, so it belongs to a proactive strategy that anticipates and avoids ethical problems before they occur.", "topic": "Business Ethics"}, {"id": "pdf5-158", "question": "y 2 = x 3 \u2212 5x + 1 defined over E17. If P = (3, 9) what is \u2013 P?", "options": ["(3, 9)", "(3, 4)", "(3, 8)", "none of the above"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "For an elliptic curve over a prime field, the inverse of point P=(x,y) is -P=(x, -y mod p); here -9 mod 17 = 8, giving -P = (3, 8).", "topic": "Information Security"}, {"id": "pdf5-159", "question": "Which variant of DES is also called Encrypt-Decrypt-Encrypt mode?", "options": ["Double DES", "Triple DES with two keys", "Triple DES with three keys", "None of the given choices"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "The Encrypt-Decrypt-Encrypt (EDE) sequence technically describes Triple DES (both the two-key and three-key variants use E-D-E), so this question's phrasing is ambiguous between those two options; the source's marked answer of 'Double DES' does not match standard cryptography terminology, but no other option can be confidently singled out as the intended one either.", "topic": "Information Security"}, {"id": "pdf5-160", "question": "The plain text \u201ccome home tomorrow\u201d will be transformed into which of the following if it uses Rail-fence technique.", "options": ["cmhmtmrooeoeoorw", "cmtmhmrooreoeowo", "cmhmtmeoeoroorwo", "None of the given choices"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Writing 'comehometomorrow' in a 2-rail zigzag and reading row by row (even-index letters then odd-index letters) produces 'cmhmtmrooeoeoorw', matching option 1.", "topic": "Information Security"}, {"id": "pdf5-161", "question": "The Diffie-Hellman key exchange is vulnerable to which of the following attacks?", "options": ["Meet-in-the-middle attack", "Man-in-the-middle attack", "Phishing attack", "Snooping"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Plain Diffie-Hellman has no authentication of the exchanged public values, so an attacker can intercept and substitute keys in a man-in-the-middle attack.", "topic": "Information Security"}, {"id": "pdf5-162", "question": "The term _____ means the redesign of a vertical organization along its horizontal workflows and processes.", "options": ["vertical linkage", "vertical network grouping", "innovation", "reengineering"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Business process reengineering is the redesign of a vertical, function-based organization around its horizontal workflows and processes.", "topic": "Management"}, {"id": "pdf5-163", "question": "Terminology that defines the extent to which activities within an organisation are to be subdivided", "options": ["Departmentali sation", "Divisional structure", "Work specialisation", "Formalisation"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Work specialisation (division of labor) is the degree to which tasks in an organization are broken down into separate, specialized jobs. Formalisation (a related but distinct OB concept) refers to how standardized an organization's jobs are, not how subdivided they are.", "topic": "Management"}, {"id": "pdf6-001", "question": "In work specialisation, efficiency is generated through________________.", "options": ["a variety of tasks.", "repetitive tasks.", "training.", "guidance of managers."], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Work specialization boosts efficiency by having each worker repeat the same narrow task over and over, building speed and skill through repetition.", "topic": "Management"}, {"id": "pdf6-002", "question": "In an organic structure, formalisation is", "options": ["high.", "low.", "moderate.", "absent."], "correct": 2, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "Organic structures are flexible and decentralized with low formalization (few written rules/procedures) \u2014 it's mechanistic structures that have high formalization.", "topic": "Management"}, {"id": "pdf6-003", "question": "A(n) _____ is a group that is made up of organizationally or geographically dispersed members who are linked primarily through advanced information and communications technologies.", "options": ["vertical linkage", "functional department", "organisational committee", "virtual team"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A virtual team is exactly a group of organizationally or geographically dispersed members connected mainly through information and communication technology.", "topic": "Management"}, {"id": "pdf6-004", "question": "A small span of control decreases employee autonomy through", "options": ["tight supervision.", "loose supervision.", "biased supervision.", "lack of supervision."], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A small span of control means each manager oversees fewer subordinates, allowing closer, tighter supervision that limits employee autonomy.", "topic": "Management"}, {"id": "pdf6-005", "question": "_____ means people are organized according to what the organization produces.", "options": ["Functional grouping", "Divisional grouping", "Multi-focused grouping", "Horizontal grouping"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Divisional grouping organizes people around what the organization produces (products, services, or markets), unlike functional grouping which is by skill or activity.", "topic": "Management"}, {"id": "pdf6-006", "question": "\u201cThe entire organization should be moving towards a common objective in a common direction\u201d this principle is termed as", "options": ["Unity of command", "Unity of direction", "Unity of group", "Unity of management"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Fayol's principle of unity of direction states that a group of activities with the same objective should be guided by one plan and one head, i.e. common objective and common direction.", "topic": "Management"}, {"id": "pdf6-007", "question": "\u201cKeyboard Interrupt is an example for \u2026\u2026\u2026\u2026\u2026.", "options": ["Synchrono us exception", "Asynchrono us exception", "Both (a) and (b)", "Neither (a) nor (b)"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A keyboard interrupt is triggered by an external event unrelated to the instruction currently executing, which is the definition of an asynchronous exception (interrupt).", "topic": "CAO"}, {"id": "pdf6-008", "question": "\u201cArray Index out of range\u201d is an example for \u2026\u2026\u2026\u2026\u2026.", "options": ["Synchrono us exception", "Asynchrono us exception", "Both (a) and (b)", "Neither (a) nor (b)"], "correct": 1, "original_marked": 4, "matches_original": false, "confidence": "high", "reasoning": "An array-index-out-of-range fault occurs synchronously \u2014 it's raised immediately as a direct result of executing the specific bounds-checked instruction, not from an outside event, so it's a synchronous exception, not \"neither.\"", "topic": "CAO"}, {"id": "pdf6-009", "question": "Which one of the following is not a step in planning?", "options": ["Establishing objectives", "Developing premises", "Determining alternative courses", "Identifying needs of employees"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Standard planning steps are setting objectives, developing premises, and identifying/evaluating alternative courses of action; identifying employee needs is an HR/staffing concern, not a planning step.", "topic": "Management"}, {"id": "pdf6-010", "question": "Which of the following is the fundamental assumption about human behaviour ?", "options": ["Caused behaviour", "Goal oriented behaviour", "Motivated behaviour", "All of the above"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Organizational behavior theory treats human behavior as caused, motivated, and goal-oriented all at once \u2014 these three are the foundational assumptions together, not alternatives.", "topic": "Management"}, {"id": "pdf6-011", "question": "Which of the following is not right about the formal organization", "options": ["Deliberately planned & created by management", "Stable & predictable", "Violation of rules may lead to penalties", "Managers are chosen"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "In a formal organization, managers are appointed through the organizational hierarchy rather than \"chosen\" the way leaders emerge informally in a group, so that statement is the odd one out among true statements about formal organizations.", "topic": "Management"}, {"id": "pdf6-012", "question": "Which of the following is correct about \u2018Grapevine\u2019 ?", "options": ["It tends to exist when members of formal group know one- another well", "It is the result of social forces at work place.", "It is more common in times of high organisational excitement.", "All the above"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "The grapevine is an informal network driven by social interaction, thrives among well-acquainted group members, and intensifies during periods of high organizational excitement or uncertainty \u2014 all three statements are accurate.", "topic": "Management"}, {"id": "pdf6-013", "question": "Which of the following is an objective of time study?", "options": ["To determine the number of workers to be employed", "To formulate suitable incentive schemes", "To calculate the labor costs", "All of the above"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Time study supports staffing decisions, incentive scheme design, and labor cost calculation, so all three listed objectives are correct.", "topic": "Management"}, {"id": "pdf6-014", "question": "Which of the following holds true for the relation?", "options": ["O(2n)", "\u03b8(2n)", "\u038f(2n)", "None of these"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "This question includes a diagram \u2014 see the image above and verify the answer visually; not independently fact-checked.", "topic": "DSA", "diagram": "pdf6_p4_y581.png"}, {"id": "pdf6-015", "question": "Which of the following does NOT describe a problem with scientific management?", "options": ["Productivity increases may not be reflected in workers\u2019 pay", "It is better suited to complex jobs.", "Improvement is not necessarily maintainable.", "It is better suited to simple jobs."], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "low", "reasoning": "Scientific management is well known for working best on simple, repetitive jobs and breaking down on complex ones, which makes the \"complex jobs\" option arguably the false/non-problem statement instead \u2014 the wording here is ambiguous enough that the source's marked answer is kept rather than guessed.", "topic": "Management"}, {"id": "pdf6-016", "question": "Virtual functions work because of \u2026\u2026\u2026\u2026\u2026\u2026\u2026\u2026\u2026", "options": ["Virtual pointer correctly points to Virtual table", "Virtual Pointer does not point to virtual table", "There is no concept of Virtual table and virtual pointer working mechanism.", "Both (b) and (c)"], "correct": 1, "original_marked": null, "matches_original": false, "confidence": "high", "reasoning": "Virtual functions work at runtime because each object's virtual pointer (vptr) correctly points to its class's virtual table (vtable), which stores the addresses of the actual overriding functions to call.", "topic": "C/C++"}, {"id": "pdf6-017", "question": "This stress is positive stress which motivates a person", "options": ["Chronic stress", "Acute stress", "Eustress", "Distress"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Eustress is the term for positive stress that motivates and energizes a person, as opposed to distress, which is negative and harmful.", "topic": "Management"}, {"id": "pdf6-018", "question": "The theorist who advocated standard methodology for doing a task and suggested that workers were motivated by pay according to output (piecework) is", "options": ["Fayol", "Taylor", "Mintzberg"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Frederick Taylor pioneered scientific management, standardizing task methods and advocating piece-rate pay tied to worker output.", "topic": "Management"}, {"id": "pdf6-019", "question": "The technique of differential piece rate system was developed by Taylor to", "options": ["Discriminate between efficient and inefficient workers", "Reward the efficient worker", "Motivate the inefficient workers to perform better", "All of the above"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Taylor's differential piece-rate system was designed to distinguish efficient from inefficient workers, reward the efficient, and push the inefficient to improve \u2014 all three purposes apply.", "topic": "Management"}, {"id": "pdf6-020", "question": "The managerial function of organizing is_____________", "options": ["to review and adjust the plan in light of changing conditions", "to establish a program for the accomplishment of objectives", "to create a structure of function and duties to be performed by a group of people", "to get things done through and with the help of people"], "correct": 3, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "Organizing is specifically defined as creating a structure of functions and duties for a group of people to perform; \"establishing a program for accomplishing objectives\" describes planning, not organizing.", "topic": "Management"}, {"id": "pdf6-021", "question": "The keyword virtual can be used for\u2026\u2026\u2026\u2026\u2026.", "options": ["data members (or) variables", "Member functions", "classes", "Both (b) and (c)"], "correct": 4, "original_marked": 3, "matches_original": false, "confidence": "high", "reasoning": "The \"virtual\" keyword in C++ applies to both member functions (virtual functions, enabling polymorphism) and classes (virtual base classes, for virtual inheritance) \u2014 never to data members \u2014 so the complete answer is \"both,\" not \"classes\" alone.", "topic": "C/C++"}, {"id": "pdf6-022", "question": "The Hawthorne Studies doesn\u2019t include", "options": ["The illumination studies", "The Relay Assembly Test Room Studies", "The mass interviewing Program", "The time and motion study"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "The Hawthorne Studies consisted of the illumination studies, the relay assembly test room studies, the bank wiring room study, and the mass interviewing program; the time-and-motion study belongs to Taylor's scientific management, not the Hawthorne Studies.", "topic": "Management"}, {"id": "pdf6-023", "question": "The behavioral science approaches add which of the following emphases to management?", "options": ["The study of people who satisfy social needs at work and how informal, as well as a formal organization affects behavior", "The scientific study of human behaviour and developing behavioural techniques", "Both A and B", "None of the above"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The behavioral science approach specifically refers to applying rigorous, scientific research methods to studying human behavior at work, distinguishing it from the earlier, more intuition-based human relations movement.", "topic": "Management"}, {"id": "pdf6-024", "question": "The attributions that emphasize some aspect of the individual, such as ability or skill, to explain behavior is termed as", "options": ["Dispositional Attributions", "Situational Attributions", "Event Attributions", "Skill Attributions"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Dispositional (internal) attributions explain behavior by pointing to personal traits like ability or skill, in contrast to situational (external) attributions that point to circumstances.", "topic": "Management"}, {"id": "pdf6-025", "question": "The application of this principle of management leads to higher production and better work for the same effort. Identify the related principle of general management.", "options": ["Discipline", "Equity", "Division of work", "Unity of command"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Fayol's division of work principle holds that specialization of labor increases output and quality for the same amount of effort.", "topic": "Management"}, {"id": "pdf6-026", "question": "Planning function of management is performed by________________________.", "options": ["Top Management", "Middle Management", "Lower Management", "All of the above"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Planning happens at every level of management: top management sets strategic plans, middle management sets tactical plans, and lower management sets operational plans.", "topic": "Management"}, {"id": "pdf6-027", "question": "MBO is", "options": ["Management By Options", "Management By Operations", "Management By Objectives", "Management By Orders"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "MBO stands for Management By Objectives, a model where managers and employees jointly set and track goals.", "topic": "Management"}, {"id": "pdf6-028", "question": "Management as a discipline refers to __________", "options": ["Group of managers", "Functions of management", "Subject of management", "All of these"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Management 'as a discipline' means it is treated as a field/subject of academic study with its own theories and principles, not the group of managers themselves.", "topic": "Management"}, {"id": "pdf6-029", "question": "In Mintzberg\u2019s management roles, the role that communicate to employees the organization\u2019s vision and purpose is called", "options": ["Liaison", "Figurehead", "Monitor", "Disseminator"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "The Disseminator is one of Mintzberg's informational roles, responsible for passing information such as the organization's vision and purpose on to employees.", "topic": "Management"}, {"id": "pdf6-030", "question": "In expectancy theory, value of rewards is termed as", "options": ["Expectancy", "Instrumentality", "Valence", "Values"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "In Vroom's expectancy theory, valence is the value or attractiveness an individual places on the reward.", "topic": "Management"}, {"id": "pdf6-031", "question": "In expectancy theory, the belief that performance leads to rewards is termed as", "options": ["Expectancy", "Instrumentality", "Valence", "Values"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Instrumentality is the belief that good performance will actually lead to the promised reward (the performance-to-reward link).", "topic": "Management"}, {"id": "pdf6-032", "question": "In Big Five Personality dimensions, the degree to which a person is sociable, gregarious, and assertive versus reserved, quiet and timid is called as", "options": ["Conscientiousness", "Extraversion\u2013Introver sion", "Agreeableness", "Emotional Stability"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Extraversion is the Big Five trait describing sociability, gregariousness, and assertiveness versus reserve and timidity.", "topic": "Management"}, {"id": "pdf6-033", "question": "In Big Five Personality dimensions, the degree of working well with others by sharing trust, warmth, and cooperativeness is called as", "options": ["Conscientiousness", "Extraversion\u2013Introver sion", "Agreeableness", "Emotional Stability"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Agreeableness describes how well a person works with others through trust, warmth, and cooperation.", "topic": "Management"}, {"id": "pdf6-034", "question": "In Big Five Personality dimensions, the ability a person displays in handling stress by remaining calm, focused, and self-confident, as opposed to insecure, anxious, and depressed is known as", "options": ["Conscientiousness", "Extraversion\u2013Introversion", "Agreeableness", "Emotional Stability"], "correct": 4, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "This description (calm, focused, self-confident vs. insecure, anxious, depressed) is the textbook definition of Emotional Stability, not Conscientiousness, which is about dependability and achievement orientation \u2014 the marked answer looks like an error.", "topic": "Management"}, {"id": "pdf6-035", "question": "In a try-catch block, if exception is not caught in try block, the control must go to \u2026\u2026\u2026\u2026\u2026\u2026..", "options": ["catch block", "same try block again", "immediate line of code or normal immediate block", "throw block"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "When an exception occurs/is thrown inside a try block, control transfers to the matching catch block that handles it.", "topic": "OOPS"}, {"id": "pdf6-036", "question": "Highest level of Maslow\u2019s Hierarchy is", "options": ["Security", "Physiological", "Esteem", "Self- Actualization"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Self-actualization sits at the top of Maslow's hierarchy, representing the need to realize one's full potential.", "topic": "Management"}, {"id": "pdf6-037", "question": "Group development stages in the order are", "options": ["Forming, Performing, Storming, Norming, Adjourning", "Forming, Norming, Storming, Performing, Adjourning", "Forming, Norming, Performing, Storming, Adjourning", "Forming, Storming, Norming, Performing, Adjourning"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Tuckman's model of group development runs Forming, Storming, Norming, Performing, Adjourning.", "topic": "Management"}, {"id": "pdf6-038", "question": "Find the incorrect statement(s) from the following: (i). A virtual function is allowed to be a static member (ii). Virtual keyword decides the dynamic binding", "options": ["(i) only", "(ii) only", "All are incorrect", "All are correct"], "correct": 1, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "A static member function cannot be declared virtual in C++ (no 'this' pointer/vtable access), so statement (i) is false; the virtual keyword does enable dynamic binding, so statement (ii) is true \u2014 meaning only (i) is incorrect, not (ii).", "topic": "C/C++"}, {"id": "pdf6-039", "question": "Find the correct statement(s) below:", "options": ["There should be one catch block for one try block.", "There may be multiple catch block for single try block.", "There may be a catch block without even a single try block.", "All are correct"], "correct": 2, "original_marked": null, "matches_original": false, "confidence": "high", "reasoning": "A single try block can have multiple catch blocks (one per exception type), and a catch block must always be attached to a try block, so only the 'multiple catch blocks' statement is correct.", "topic": "OOPS"}, {"id": "pdf6-040", "question": "Find the correct order in Exception Handling:", "options": ["Hit \u2013 Throw - Catch \u2013 Handle", "Hit-catch-Throw-Handle", "Handle-Throw-Catch-Hit", "Hit-Catch-Handle-Throw"], "correct": 1, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "The logical exception-handling flow is: the exception occurs (Hit), it is Thrown, then Caught, then Handled, so the correct order is Hit-Throw-Catch-Handle.", "topic": "OOPS"}, {"id": "pdf6-041", "question": "Fibonnaci sequence complexity can only be identified by?", "options": ["Iterative method", "Recursive method", "Master theorem", "All of them"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "low", "reasoning": "The question is vaguely worded; strictly the Master theorem doesn't cleanly apply to Fibonacci's linear recurrence T(n)=T(n-1)+T(n-2), but the intended point seems to be that complexity can be analyzed through several methods, so the marked answer is kept.", "topic": "DSA"}, {"id": "pdf6-042", "question": "Exception handling means \u2026\u2026.", "options": ["clearing runtime errors", "managing runtime errors", "clearing logic errors", "managing logic errors"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Exception handling is about managing (not eliminating) errors that surface at runtime, as opposed to compile-time or logic errors.", "topic": "OOPS"}, {"id": "pdf6-043", "question": "Documents that outline how goals are to be accomplished are called", "options": ["Plans", "Goals", "Strategies", "Ideas"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Plans are the documents that lay out how goals are to be accomplished.", "topic": "Management"}, {"id": "pdf6-044", "question": "By comparing ______ with standards, the manager can know whether the goals are achieved or not.", "options": ["Risk", "Ideas", "Actual performance", "Costs"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "The controlling function compares actual performance against set standards to check whether goals were achieved.", "topic": "Management"}, {"id": "pdf6-045", "question": "Attributions that emphasize the environment\u2019s effect on behavior is called", "options": ["Dispositional Attributions", "Situational Attributions", "Event Attributions", "Skill Attributions"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Situational attribution credits behavior to external/environmental factors rather than to a person's disposition.", "topic": "Management"}, {"id": "pdf6-046", "question": "An example for intangible premises in planning is", "options": ["capital investment", "Unit of production", "Cost per unit", "Goodwill"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Goodwill is an intangible planning premise since it can't be precisely measured, unlike capital investment, unit output, or cost per unit which are quantifiable.", "topic": "Management"}, {"id": "pdf6-047", "question": "A persons\u2019 knowledge and ability to make effective use of any process or technique constitutes", "options": ["Technical skills", "Human skills", "Conceptual skills", "Employee skills"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Technical skill is the knowledge and ability to effectively use the tools, techniques, and procedures of a specific field.", "topic": "Management"}, {"id": "pdf6-048", "question": "A persons\u2019 knowledge and ability to make effective use of any process or technique constitutes", "options": ["Technical skills", "Human skills", "Conceptual skills", "Employee skills"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Technical skill is the knowledge and ability to effectively use the tools, techniques, and procedures of a specific field (duplicate of the previous question).", "topic": "Management"}, {"id": "pdf6-049", "question": "Find the correct statement(s) below:", "options": ["There should be one catch block for one try block.", "There may be multiple catch block for single try block.", "There may be a catch block without even a single try block.", "All are correct"], "correct": 2, "original_marked": null, "matches_original": false, "confidence": "high", "reasoning": "A single try block can have multiple catch blocks, and a catch block must always be attached to a try block, so only the 'multiple catch blocks' statement is correct.", "topic": "OOPS"}, {"id": "pdf6-050", "question": "Find the correct order in Exception Handling:", "options": ["Hit \u2013 Throw - Catch \u2013 Handle", "Hit-catch-Throw-Handle", "Handle-Throw-Catch-Hit", "Hit-Catch-Handle-Throw"], "correct": 1, "original_marked": null, "matches_original": false, "confidence": "high", "reasoning": "The logical exception-handling flow is: the exception occurs (Hit), it is Thrown, then Caught, then Handled, so the correct order is Hit-Throw-Catch-Handle.", "topic": "OOPS"}, {"id": "pdf6-051", "question": "Fibonnaci sequence complexity can only be identified by?", "options": ["Iterative method", "Recursive method", "Master theorem", "All of them"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "low", "reasoning": "The question is oddly worded, but Fibonacci's time complexity can be derived via iterative counting, by solving the recursive recurrence relation, or approximated with the Master theorem, so 'all of them' is the intended catch-all answer.", "topic": "DSA"}, {"id": "pdf6-052", "question": "Exception handling means \u2026\u2026.", "options": ["clearing runtime errors", "managing runtime errors", "clearing logic errors", "managing logic errors"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Exception handling doesn't erase errors from existence; it manages (catches and responds to) runtime errors so the program can keep running.", "topic": "OOPS"}, {"id": "pdf6-053", "question": "Documents that outline how goals are to be accomplished are called", "options": ["Plans", "Goals", "Strategies", "Ideas"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A plan is the document that lays out the specific steps and methods for achieving a goal; goals are the 'what', plans are the 'how'.", "topic": "Management"}, {"id": "pdf6-054", "question": "By comparing ______ with standards, the manager can know whether the goals are achieved or not.", "options": ["Risk", "Ideas", "Actual performance", "Costs"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Controlling involves comparing actual performance against set standards to check whether objectives were achieved.", "topic": "Management"}, {"id": "pdf6-055", "question": "Attributions that emphasize the environment\u2019s effect on behavior is called", "options": ["Dispositional Attributions", "Situational Attributions", "Event Attributions", "Skill Attributions"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Situational attribution explains behavior as caused by external, environmental factors, as opposed to dispositional attribution, which blames internal traits.", "topic": "Management"}, {"id": "pdf6-056", "question": "An example for intangible premises in planning is", "options": ["capital investment", "Unit of production", "Cost per unit", "Goodwill"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Goodwill is intangible because it can't be precisely measured or quantified, unlike capital investment, unit production, or cost per unit.", "topic": "Management"}, {"id": "pdf6-057", "question": "A persons\u2019 knowledge and ability to make effective use of any process or technique constitutes", "options": ["Technical skills", "Human skills", "Conceptual skills", "Employee skills"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Technical skill is defined as the knowledge and proficiency needed to use a specific process, method, or technique effectively.", "topic": "Management"}, {"id": "pdf6-058", "question": "A base class that contain pure virtual function is said be", "options": ["virtual child class", "abstract base class", "super base class", "None of the above"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A class containing at least one pure virtual function cannot be instantiated and is called an abstract base class.", "topic": "C/C++"}, {"id": "pdf6-059", "question": "PDA can recognise", "options": ["any grammar", "only CFG", "only regular grammar", "any unambiguous grammar"], "correct": 2, "original_marked": 3, "matches_original": false, "confidence": "high", "reasoning": "Pushdown automata recognize exactly the context-free languages (PDA and CFG are equivalent in power); regular languages are only a subset of what a PDA accepts, so 'only regular grammar' is incorrect.", "topic": "TOC"}, {"id": "pdf6-060", "question": "Network congestion occurs........", "options": ["in case of traffic overloading", "when a system terminates", "when connection between two nodes terminates", "when connection between three nodes terminates"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Congestion occurs when the traffic offered to the network exceeds its handling capacity, i.e., traffic overloading.", "topic": "CN"}, {"id": "pdf6-061", "question": "FORTRAN is a", "options": ["regular language", "context free language", "context sensitive language", "None of the above"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "FORTRAN is a classic textbook example of a context-sensitive language because constructs like B(J) are ambiguous between array indexing and a function call without surrounding context.", "topic": "TOC"}, {"id": "pdf6-062", "question": ".......................is the protocol suite for the current Internet.", "options": ["TCP/IP", "NCP", "UNIX", "ACM"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "TCP/IP is the foundational protocol suite the modern Internet is built on.", "topic": "CN"}, {"id": "pdf6-063", "question": "Which organization has authority over interstate and international commerce in the communications field", "options": ["ITU-T", "IEEE", "FCC", "ISOC"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "The FCC (Federal Communications Commission) is the body that regulates interstate and international communications.", "topic": "CN"}, {"id": "pdf6-064", "question": "Which of the following ISO standards is typically used as a framework for network communications?", "options": ["IEEE", "802.1X", "Ethernet", "OSI/RM"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "The OSI Reference Model is the ISO standard framework used to describe how network communication layers interact.", "topic": "CN"}, {"id": "pdf6-065", "question": "Which one of the following model induces administrative overload in a huge environment?", "options": ["Rule based access control", "Directory based access control", "Lattice based access control", "ID based access control"], "correct": 2, "original_marked": null, "matches_original": false, "confidence": "low", "reasoning": "Directory-based access control requires maintaining an individual access directory per subject, which becomes costly to administer as the number of users and objects grows in a large environment; the source PDF left this unmarked.", "topic": "Information Security"}, {"id": "pdf6-066", "question": "Which one of the following model enables frequent changes to data permissions?", "options": ["Rule-based", "List-based", "Role-based", "Ticket based"], "correct": 3, "original_marked": null, "matches_original": false, "confidence": "high", "reasoning": "Role-based access control (RBAC) lets administrators change a user's effective permissions quickly just by reassigning roles, making it well-suited to frequent permission changes; the source PDF left this unmarked.", "topic": "Information Security"}, {"id": "pdf6-067", "question": "Which access control model is defined based on a specific profile for every user?", "options": ["Lattice based access control", "Directory based access control", "Rule based access control", "ID based access control"], "correct": 4, "original_marked": null, "matches_original": false, "confidence": "low", "reasoning": "ID-based (identity-based) access control ties permissions to a specific profile created for each individual user; the source PDF left this unmarked.", "topic": "Information Security"}, {"id": "pdf6-068", "question": "Tractable problems mean", "options": ["Problems that cannot be solved in polynomial time", "Problems that can be solved in polynomial time", "Problems that can be solved in constant time", "Problems that can be solved in non-polynomial time"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Tractable problems are those solvable in polynomial time, i.e., the complexity class P.", "topic": "DSA"}, {"id": "pdf6-069", "question": "Intractable problems means", "options": ["Problems that cannot be solved in polynomial time", "Problems that can be solved in polynomial time", "Problems that can be solved in constant time", "Problems that can be solved in non-polynomial time"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Intractable problems cannot be solved in polynomial time and require super-polynomial time algorithms.", "topic": "DSA"}, {"id": "pdf6-070", "question": "Which of the following would lead you to believe that a given system is an SMP-type system?", "options": ["Each processor is assigned a specific task", "There is a boss\u2013worker relationship between the processors", "Each processor performs all tasks within the operating system", "None of the above"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "In a Symmetric Multiprocessing (SMP) system, every processor runs the full OS and can execute any task, unlike asymmetric multiprocessing's boss-worker split.", "topic": "OS"}, {"id": "pdf6-071", "question": "Which of the following statements is false?", "options": ["Mobile devices must be concerned with power consumption.", "Mobile devices can provide features that are unavailable on desktop or laptop computers.", "The difference in storage capacity between a mobile device and a laptop is shrinking.", "Mobile devices usually have fewer processing cores than a standard desktop computer."], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "This is the known false statement from the textbook: the storage-capacity gap between mobile devices and laptops has not meaningfully closed, while the other three statements about mobile devices hold true.", "topic": "OS"}, {"id": "pdf6-072", "question": "Which of the following statements concerning open-source operating systems is true?", "options": ["Solaris is open source", "Source code is freely available", "They are always more secure than commercial, closed systems", "All open-source operating systems share the same set of goals"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "By definition, open-source operating systems make their source code freely available; being open source doesn't automatically make an OS more secure or mean all open-source OSes share identical goals.", "topic": "OS"}, {"id": "pdf6-073", "question": "Which of the following operating systems is not open source?", "options": ["Windows", "BSD UNIX", "Linux", "PCLinuxOS"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Windows is closed-source/proprietary, unlike BSD UNIX, Linux, and PCLinuxOS, which are all open source.", "topic": "OS"}, {"id": "pdf6-074", "question": "Which of the following is a property of peer-to-peer systems?", "options": ["Clients and servers are not distinguished from one another", "Separate machines act as either the client or the server but not both.", "They do not offer any advantages over traditional client-server systems", "They suffer from the server acting as the bottleneck in performance"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "In peer-to-peer systems, every node can act as both client and server, so there's no strict distinction between the two roles.", "topic": "OS"}, {"id": "pdf6-075", "question": "Which of the following file systems is supported by the windows OS?", "options": ["NTFS", "FAT32", "exFAT", "All of the these"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Windows supports multiple file systems, including NTFS, FAT32, and exFAT.", "topic": "OS"}, {"id": "pdf6-076", "question": "What statement concerning privileged instructions is considered false?", "options": ["They may cause harm to the system", "They can only be executed in kernel mode.", "They cannot be attempted from user mode.", "They are used to manage interrupts"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Privileged instructions can be attempted from user mode - the CPU will simply trap to the OS when it detects the violation, so 'cannot be attempted' is the false statement.", "topic": "OS"}, {"id": "pdf6-077", "question": "What is Scheduling?", "options": ["Allowing a job to use the processor", "Making proper use of Processor", "None of the mentioned", "All of the mentioned"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Scheduling is the mechanism by which a job/process is allowed to use the processor.", "topic": "OS"}, {"id": "pdf6-078", "question": "What are some other terms for kernel-mode?", "options": ["Supervisor mode", "System mode", "Privileged mode", "All of the above"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Supervisor mode, system mode, and privileged mode are all synonyms used interchangeably for kernel mode.", "topic": "OS"}, {"id": "pdf6-079", "question": "Two important design issues for cache memory are ____.", "options": ["Speed and volatility", "Size and replacement policy", "Power consumption and reusability", "Size and access privileges"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Cache size and the replacement policy (which block to evict on a miss) are core design trade-offs in cache memory design.", "topic": "CAO"}, {"id": "pdf6-080", "question": "The two separate modes of operating in a system are", "options": ["Supervisor mode and system mode", "Kernel mode and privileged mode", "Physical mode and logical mode", "User mode and kernel mode"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Operating systems separate execution into user mode (restricted) and kernel mode (privileged) to protect system resources.", "topic": "OS"}, {"id": "pdf6-081", "question": "The portion of the process scheduler in an operating system that dispatches processes is concerned with", "options": ["Assigning ready processes to CPU", "Assigning ready processes to the waiting queue", "Assigning running processes to blocked queue", "All of the mentioned"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The dispatcher's job is to hand the CPU over to the process selected by the scheduler from the ready queue.", "topic": "OS"}, {"id": "pdf6-082", "question": "The most common secondary storage device is ____.", "options": ["Random-access memory", "Solid-state disks", "Tape drives", "Magnetic disk"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Magnetic disk (hard disk) has traditionally been the most common secondary storage device in general-purpose systems.", "topic": "OS"}, {"id": "pdf6-083", "question": "In what way is an operating system like a government?", "options": ["It seldom functions correctly", "It creates an environment within which other programs can do useful work.", "It performs the most useful functions by itself.", "It is always concerned primarily with the individual's needs"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Like a government, an OS performs no useful function by itself but creates an environment in which other (application) programs can do useful work.", "topic": "OS"}, {"id": "pdf6-084", "question": "Embedded computers typically run on a ____ operating system", "options": ["Real-time", "Windows XP", "Network", "Clustered"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Embedded systems typically need predictable, time-bound responses, so they run real-time operating systems.", "topic": "OS"}, {"id": "pdf6-085", "question": "Bluetooth and 802.11 devices use wireless technology to communicate over several feet, in essence creating a ____.", "options": ["Local-area network", "Wide-area network", "Small-area network", "Metropolitan-area network"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Short-range wireless tech like Bluetooth and 802.11 connecting nearby devices effectively forms a small-area (personal-area) network, smaller in scope than a LAN.", "topic": "CN"}, {"id": "pdf6-086", "question": "A(n) ________ is the unit of work in a system.", "options": ["Process", "Operating System", "Timer", "Mode bit"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A process (a program in execution) is the basic unit of work that an OS schedules and manages.", "topic": "OS"}, {"id": "pdf6-087", "question": "A _____ provides a file-system interface that allows clients to create and modify files", "options": ["Compute-server system", "File-server system", "Wireless network", "Network computer"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A file-server system exposes a file-system interface so remote clients can create, read, and modify files.", "topic": "OS"}, {"id": "pdf6-088", "question": "A ____ is a custom build of the Linux operating system", "options": ["LiveCD", "Installation", "Distribution", "VMWare Player"], "correct": 3, "original_marked": 4, "matches_original": false, "confidence": "high", "reasoning": "A Linux 'distribution' (e.g., Ubuntu, Fedora) is a custom build of the Linux OS bundled with specific packages and tools; VMWare Player is unrelated virtualization software, not a Linux build.", "topic": "OS"}, {"id": "pdf6-089", "question": "A ____ can be used to prevent a user program from never returning control to the operating system", "options": ["Portal", "Program Counter", "Firewall 2", "Timer"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A timer interrupt forces control back to the OS after a set interval, preventing a user program from monopolizing the CPU indefinitely.", "topic": "OS"}, {"id": "pdf6-090", "question": "__________ is a set of software frameworks that provide additional services to application developers.", "options": ["System programs", "Virtualization", "Cloud computing", "Middleware"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Middleware is the standard term for software frameworks that provide additional services (e.g., databases, messaging) on top of the OS to application developers.", "topic": "OS"}, {"id": "pdf6-091", "question": "____ operating systems are designed primarily to maximize resource utilization.", "options": ["PC", "Handheld computer", "Mainframe", "Network"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Mainframe operating systems are built to maximize utilization of expensive, shared CPU/IO resources across many jobs.", "topic": "OS"}, {"id": "pdf6-092", "question": "In length instruction some programs wants a complex instruction set containing more instruction, more addressing modes and greater address rang, as in case of", "options": ["RISC", "CISC", "Both", "None"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "CISC (Complex Instruction Set Computer) architectures deliberately include more instructions, more addressing modes, and a larger address range, unlike the simplified RISC design.", "topic": "CAO"}, {"id": "pdf6-093", "question": "------------------------is not a good practice in order to enhance the security offered by password authentication?", "options": ["Enabling account lockout controls", "Enforcing a reasonable password policy", "Using password verification tools and password cracking tools against your own password database file", "Allowing users to reuse the same password"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Allowing password reuse weakens security by letting compromised or guessable passwords persist, unlike lockouts, policies, and self-auditing which strengthen it.", "topic": "Information Security"}, {"id": "pdf6-094", "question": "Match the items of List-II with the items of List-I and indicate the code of correct matching. List-I List-II (Model of Organisational (Employee Behaviour) Orientation) (i) Responsible (a) Autocratic behaviour (ii) Security and (b) Custodial benefits (iii) Job (b) Custodial performance (d) Collegial (iv) Obedience Answer of (a) (b) (c) (d) in List-ll", "options": ["(iv) (ii) (iii) (i)", "(iv) (iii) (i) (ii)", "(i) (iv) (iii) (ii)", "(iv) (i) (ii) (iii)"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "In Keith Davis's OB models, Autocratic pairs with obedience, Custodial with security/benefits, Supportive with job performance, and Collegial with responsible behavior, giving the order (iv)(ii)(iii)(i).", "topic": "Management"}, {"id": "pdf6-095", "question": "1. To control access by an active entity such as individual or process to an object encompasses designing:", "options": ["Access Rules", "Access Matrix", "Identification controls", "Access terminal"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Controlling what an active entity (subject) can do to an object is implemented by defining access rules (a policy of permitted/denied operations) that govern each access attempt.", "topic": "Information Security"}, {"id": "pdf6-096", "question": "1. Rule-Based Access Control access is defined based on rules. Such rules would fit within what type of access control?", "options": ["Discretionary Access Control (DAC)", "Mandatory Access control (MAC)", "Non-Discretionary Access Control (NDAC)", "Lattice-based Access control"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Rule-Based Access Control is classified as a form of Non-Discretionary Access Control (NDAC), alongside Role-Based Access Control, since access is governed by system-defined rules rather than by resource owners.", "topic": "Information Security"}, {"id": "pdf6-097", "question": "1. In which of the following access control model, a central authority will determine what objects the subjects have access to and the access control is based on role or on the organizational security policy?", "options": ["Mandatory Access Control", "Discretionary Access Control", "Non-Discretionary Access Control", "Rule-based Access control"], "correct": 3, "original_marked": 4, "matches_original": false, "confidence": "high", "reasoning": "Non-Discretionary Access Control (NDAC) is precisely defined as a model where a central authority grants access based on role or organizational security policy; 'rule-based' is only one specific NDAC mechanism, not the umbrella answer being described.", "topic": "Information Security"}, {"id": "pdf6-098", "question": "In which access control model, there are sets of elements which have greatest lower bound of values and the least upper bound of values?", "options": ["Mandatory model", "Discretionary model", "Lattice model", "Rule model"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "The Lattice-based access control model organizes security levels as a mathematical lattice, using greatest lower bound (meet) and least upper bound (join) operations to determine access.", "topic": "Information Security"}, {"id": "pdf6-099", "question": "1. If a user admitting an identity to a system regularly in the form of a log-on ID, then what type of act it is?", "options": ["Authentication", "Identification", "Authorization", "Confidentiality"], "correct": 2, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "Presenting a log-on ID (username) to claim an identity is Identification; Authentication is the separate step of proving that claimed identity (e.g., with a password).", "topic": "Information Security"}, {"id": "pdf6-100", "question": "1. ----------- is the type of discretionary access control (DAC) model which is based on an individual's identity.", "options": ["Identity-based Access control", "Rule-based Access control", "Non-Discretionary Access Control", "Lattice-based Access control"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Identity-based Access Control is the DAC variant where access decisions are tied directly to an individual's identity rather than their role or a rule set.", "topic": "Information Security"}, {"id": "pdf6-101", "question": "Which of the following security services provided by Kerberos?", "options": ["Availability and nonrepudiation", "Confidentiality and authentication", "Confidentiality and integrity", "Availability and authorization"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "low", "reasoning": "Kerberos is chiefly known for mutual authentication and also encrypts tickets/session keys, which supports both confidentiality and integrity of exchanged data; the exact intended pairing (confidentiality+authentication vs confidentiality+integrity) is genuinely ambiguous, so the source's marked answer is kept.", "topic": "Information Security"}, {"id": "pdf6-102", "question": "Which of the following is considered as foremost parameter to decide the quality of a biometric device?", "options": ["Accuracy", "Acceptability", "Enrollment time", "Invasiveness"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Accuracy (measured via False Accept/Reject Rates) is the primary metric used to judge a biometric system's quality; acceptability, enrollment time, and invasiveness are secondary usability factors.", "topic": "Information Security"}, {"id": "pdf6-103", "question": "Stronger security can be provided by means of incorporating one of the following. What it is?", "options": ["Password and a PIN", "One-time password", "Pass phrase and a smart card", "Fingerprint"], "correct": 3, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "Combining a pass phrase (something you know) with a smart card (something you have) is two-factor authentication, which is stronger than a single-factor one-time password.", "topic": "Information Security"}, {"id": "pdf6-104", "question": "One of the following cannot be considered as an example of a deterrent access control?", "options": ["Encryption", "Auditing", "Awareness training", "Antivirus software"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Antivirus software is a preventive/corrective control that actively blocks malware, whereas encryption, auditing, and awareness training all function as deterrents by discouraging or logging policy violations.", "topic": "Information Security"}, {"id": "pdf6-105", "question": "Mention True or false. In role-based access control, every user takes one or more roles, and based on the roles, each user is allowed to access the system resources.", "options": ["True", "False"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "This is the standard definition of role-based access control (RBAC): users are assigned roles, and roles determine resource access, so the statement is true.", "topic": "Information Security"}, {"id": "pdf6-106", "question": "Mention True or false. Authorization deals with deciding who the user is, and the authentication deals with restricting what operations or data the user can access.", "options": ["True", "False"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The statement has authentication and authorization swapped: authentication verifies who the user is, while authorization restricts what the user can do, so the statement as written is false.", "topic": "Information Security"}, {"id": "pdf6-107", "question": "-------------- form of biometric device is least accepted for authentication purpose.", "options": ["Iris scan", "Retina scan", "Fingerprint", "Facial geometry"], "correct": 2, "original_marked": 4, "matches_original": false, "confidence": "high", "reasoning": "Retina scanning is the least accepted biometric because it requires very close, intrusive eye contact with the scanner and can reveal health information, making users uncomfortable compared to fingerprint, iris, or facial recognition.", "topic": "Information Security"}, {"id": "pdf6-108", "question": "Initially what step has to be carried out to define access control?", "options": ["Accountabilit y logging", "ACL verification", "Subject authorization", "Subject identification"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Access control always starts with identifying the subject (who is requesting access) before authentication, authorization, or accountability logging can occur.", "topic": "Information Security"}, {"id": "pdf6-109", "question": "15. An authentication factor which is physiological or behavioural characteristic unique to a subject is called?", "options": ["Account ID", "Biometric factor", "Token", "IQ"], "correct": 2, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "A unique physiological or behavioral characteristic used for authentication is, by definition, a biometric factor; an account ID is just an identifier, not an authentication factor.", "topic": "Information Security"}, {"id": "pdf6-110", "question": "Let us assume that an organization is using discretionary access control model for security. Then it is vulnerable to one of the following attack. What it is?", "options": ["SYN flood", "Impersonation", "Denial of service", "Birthday attack"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "low", "reasoning": "DAC's classic weakness is that a malicious program can inherit and misuse a legitimate user's privileges (Trojan-horse style privilege abuse), which is closest among the given options to impersonation; the wording is imprecise so this is not a fully clean match.", "topic": "Information Security"}, {"id": "pdf6-111", "question": "15. Which one of the following access controls defined based on the use of labels?", "options": ["Discretionary", "Mandatory", "Role-based", "Nondiscretio nary"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Mandatory access control (MAC) assigns security labels/clearances to subjects and objects and grants access based on comparing those labels.", "topic": "Information Security"}, {"id": "pdf6-112", "question": "1. In order to authenticate the users requesting to access the resources, One of the following technologies meant which can be used for fingerprint scanning, iris scanning and retina scanning", "options": ["Micrometrics", "Macrometrics", "Biometrics", "MicroBiometric s"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Biometrics is the general technology category covering fingerprint, iris, and retina scanning for identity verification.", "topic": "Information Security"}, {"id": "pdf6-113", "question": "Which return type cannot return any value to the calling function?", "options": ["int", "float", "void", "double"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "A function declared with return type void does not return any value to the caller, unlike int, float, or double.", "topic": "C/C++"}, {"id": "pdf6-114", "question": "Which operator cannot be used with floating point numbers?", "options": ["+", "-", "%", "*"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "The modulus operator (%) in C only works on integer operands and cannot be applied to floating point numbers, unlike +, -, and *.", "topic": "C/C++"}, {"id": "pdf6-115", "question": "Which of the following is the conversion character associated with short integer?", "options": ["%c", "%h", "%e", "%f"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "low", "reasoning": "The exam's intended specifier for short int is %h (used as a modifier, e.g. %hd, in real C), while %c is char, %e is scientific-notation float, and %f is float; this is a simplified textbook convention rather than strict ISO C.", "topic": "C/C++"}, {"id": "pdf6-116", "question": "Which of the following is a valid variable name?", "options": ["Initial.Na me", "A+B", "$amt", "Floats"], "correct": 4, "original_marked": 3, "matches_original": false, "confidence": "high", "reasoning": "C identifiers may only contain letters, digits, and underscores; \"Floats\" is a valid identifier, while \"Initial.Name\" (period), \"A+B\" (plus sign), and \"$amt\" (dollar sign) all contain illegal characters.", "topic": "C/C++"}, {"id": "pdf6-117", "question": "What will be output for printf(\u201c%c\u201d, 65);", "options": ["65", "A", "10", "a"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "printf(\"%c\", 65) prints the character whose ASCII code is 65, which is 'A'.", "topic": "C/C++"}, {"id": "pdf6-118", "question": "To find a raised to power of b , the function we would use is", "options": ["a^b", "a**c", "pow(b,A.", "pow(a,B."], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "The standard library function is pow(base, exponent), so raising a to the power b is written pow(a, b).", "topic": "C/C++"}, {"id": "pdf6-119", "question": "To check the equality of two variables a and b , in C language", "options": ["if (a=b)", "if (a equalto(b))", "if (a==b)", "if((a,b)=0)"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "C uses the double equals (==) operator to test equality; a single = is assignment, so if(a==b) is the correct equality check.", "topic": "C/C++"}, {"id": "pdf6-120", "question": "The declaration unsigned u indicates:", "options": ["u is a character", "u is an unsigned integer", "u is unsigned character", "u is unsigned long integer"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "In C, \"unsigned\" used alone is shorthand for \"unsigned int\", so unsigned u declares u as an unsigned integer.", "topic": "C/C++"}, {"id": "pdf6-121", "question": "How many times \u201cHi\u201d will be printed. { int x=0; printf(\u201cHi\u201d); findarea(x); }", "options": ["1", "2", "infinite", "0"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "low", "reasoning": "This appears to be a recursive-function trick question where findarea() calls itself (and reprints \"Hi\") without a base case, producing infinite output; the full body of findarea() is not shown in this text extraction, so this could not be independently traced.", "topic": "C/C++"}, {"id": "pdf6-122", "question": "Given a= 00110010 (50) . Write C statements to determine whether bit 1 in the above pattern is ON/OFF.(least significant bit is bit 0)", "options": ["a & 0x03", "a|0x03", "a & 0x02", "a | 0x02"], "correct": 3, "original_marked": null, "matches_original": false, "confidence": "high", "reasoning": "With bit 0 as the least significant bit, bit 1 is isolated by the mask 0x02 (binary 00000010), so a & 0x02 tests whether bit 1 is on or off.", "topic": "C/C++"}, {"id": "pdf6-123", "question": "For using clrscr() function, the standard library file to be included", "options": ["conio.h", "stdio.h", "math.h", "stdstream.h"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "In Turbo C/older compilers, clrscr() is declared in conio.h, which must be included to use it.", "topic": "C/C++"}, {"id": "pdf6-124", "question": "Which operator retrieves the lvalue of a variable?", "options": ["&", "*", "\u2013>", "#"], "correct": 1, "original_marked": 3, "matches_original": false, "confidence": "high", "reasoning": "The unary & (address-of) operator retrieves the lvalue (memory location/address) of a variable; it requires an lvalue operand and returns its address.", "topic": "C/C++"}, {"id": "pdf6-125", "question": "Which operator produces the one\u2019s complement of the given binary value?", "options": ["Logical AND", "Bitwise AND", "Logical OR", "Bitwise NOT"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "The bitwise NOT (~) operator flips every bit of its operand, producing the one's complement of the value.", "topic": "C/C++"}, {"id": "pdf6-126", "question": "Which operator is used to dereference a pointer?", "options": ["&", "*", "\u2013>", "~"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The * operator dereferences a pointer, giving the value stored at the address it points to; & is the address-of operator, not dereference.", "topic": "C/C++"}, {"id": "pdf6-127", "question": "Which operator has the lowest precedence?", "options": ["Sizeof", "Unary", "Assignment", "Comma"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "In C's operator precedence table the comma operator sits at the very bottom, lower than assignment, unary, and sizeof.", "topic": "C/C++"}, {"id": "pdf6-128", "question": "Which of the following is not a character constant?", "options": ["\u2018A\u2019", "\u201cA\u201d", "\u2018 \u2019", "\u2018*\u2019"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "\"A\" in double quotes is a string literal (a char array terminated by '\\0'), not a character constant; character constants use single quotes like 'A'.", "topic": "C/C++"}, {"id": "pdf6-129", "question": "Which of the following are true statements I. goto can be used in for loop to come out of the loop II. continue takes you to beginning of the loop III. continue can be used in switch statement IV. break can be used in switch statement", "options": ["Only statement (I) is correct", "Only statement (II) is correct", "Both statements II & III are\u2019 correct", "only IV is correct"], "correct": 4, "original_marked": null, "matches_original": false, "confidence": "low", "reasoning": "break unambiguously works inside switch; continue is only meaningful in loops and cannot be used to control a bare switch, which is the classic textbook distinction this question is testing. The question is poorly constructed since goto-out-of-loop (I) is also technically true but not offered in combination, so treat this with caution.", "topic": "C/C++"}, {"id": "pdf6-130", "question": "When two strings are equal strcmp(stg1,stg2) returns", "options": ["-1", "0", "1", "true"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "strcmp returns 0 when the two strings are identical; it returns negative or positive values based on lexicographic difference otherwise.", "topic": "C/C++"}, {"id": "pdf6-131", "question": "What is ascii value for 0 and 9", "options": ["30, 39", "31, 40", "31,39", "56, 64 48-57"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "The ASCII codes for digit characters '0' through '9' run from 48 to 57, which matches the \"48-57\" portion of this (OCR-garbled) option.", "topic": "C/C++"}, {"id": "pdf6-132", "question": "To read a character and echo the character on to screen , with out the need to press enter key, appropriate function is", "options": ["getchecho()", "getch()", "getchar()", "getcharecho()"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "getche() reads a single keypress and echoes it to the screen immediately, with no need to press Enter (the trailing 'e' likely got dropped during text extraction, unlike getch() which reads silently without echo).", "topic": "C/C++"}, {"id": "pdf6-133", "question": "The operator which compares two values is", "options": ["Assignment", "Relational", "Unary", "Equality"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "low", "reasoning": "Both relational (<, >, <=, >=) and equality (==, !=) operators compare two values, so this question is ambiguous between the two; deferring to the source's marked answer of Equality.", "topic": "C/C++"}, {"id": "pdf6-134", "question": "Ternary operator operates on how many operands?", "options": ["1", "2", "3", "4"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "The ternary operator (?:) is C's only operator that takes three operands: a condition, a true-case value, and a false-case value.", "topic": "C/C++"}, {"id": "pdf6-135", "question": "Structure declaration and definition and are placed above void main(). Which one of the following statements are NOT true.", "options": ["its required by all functions", "Its global declaration", "Space available", "They are global declaration and available to all"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "A global structure declaration is available to every function in the file, but that doesn't mean every function is required to use it, making \"required by all functions\" the false statement; the question's other options are loosely worded, so treat this cautiously.", "topic": "C/C++"}, {"id": "pdf6-136", "question": "Memory is allocated for a function when the function is", "options": ["declared", "defined", "called", "returned"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Memory for a function's local variables and stack frame is allocated at call time (on the stack), not when it is merely declared or defined.", "topic": "C/C++"}, {"id": "pdf6-137", "question": "Identify the erroneous expression.", "options": ["X=y=2, 4;", "res = ++a * 5;", "res = /4;", "res = a++ \u2013b *2"], "correct": 3, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "\"res = /4;\" is a syntax error because the division operator has no left operand; \"X=y=2, 4;\" is valid (a comma expression: y=2, then X=y, then the unused constant 4), so it is not erroneous.", "topic": "C/C++"}, {"id": "pdf6-138", "question": "Following code converts c to char c =\u2019A\u2019 c=c+\u2019a\u2019-65", "options": ["to upper case", "to lower case", "to a number", "to character c"], "correct": 2, "original_marked": 4, "matches_original": false, "confidence": "high", "reasoning": "With c='A' (65), c = c + 'a' - 65 evaluates to 65 + 97 - 65 = 97, which is 'a' \u2014 this is the standard formula for converting an uppercase letter to lowercase.", "topic": "C/C++"}, {"id": "pdf6-139", "question": "Conversion specifier for string in scanf statement are", "options": ["%d", "%f", "%c", "%s %s"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "%s is the scanf conversion specifier used to read a string.", "topic": "C/C++"}, {"id": "pdf6-140", "question": "ASCII value for a , z are", "options": ["66 ,91", "65,90", "97, 122", "96, 121"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "In ASCII, lowercase 'a' is 97 and lowercase 'z' is 122.", "topic": "C/C++"}, {"id": "pdf6-141", "question": "ASCII value for A , Z are", "options": ["66 ,91", "65,90", "97 , 122", "96 121"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "In ASCII, uppercase 'A' is 65 and uppercase 'Z' is 90.", "topic": "C/C++"}, {"id": "pdf6-142", "question": "*(&num) is equivalent to writing", "options": ["&num", "*num", "num", "0"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "&num takes the address of num, and *(...) dereferences that address, so *(&num) just gives back num itself.", "topic": "C/C++"}, {"id": "pdf6-143", "question": "Which of the following is the address operator?", "options": ["@", "#", "&", "%"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "The & symbol is C's address-of operator, used to obtain a variable's memory address.", "topic": "C/C++"}, {"id": "pdf6-144", "question": "In the template <class T> declaration, what is T stands for", "options": ["a generic data type", "an arbitrary class", "a class defined earlier", "none of the above"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "In a C++ template declaration like template<class T>, T is a placeholder for a generic data type that gets substituted with a concrete type at compile time.", "topic": "C/C++"}, {"id": "pdf6-145", "question": "There\u2019s a notion of _______ and _______. A subject is allowed to temporarily reduce her level or set of compartments from (L, C) \u2192 (L \u2018 , C\u2019 )", "options": ["Maximum security level, Current security level", "Current security level, Audit security level", "Temporary security level , Current security level", "Audit security level, Maximum security level"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "In multilevel security models, a subject has a maximum (clearance) security level and can temporarily operate at a lower current security level, per the low-water-mark / current-level concept.", "topic": "Information Security"}, {"id": "pdf6-146", "question": "The implements Multi\u2013Lateral security by adding compartments", "options": ["Biba\u2019s model", "Integrity Policies", "Bell\u2013LaPadula model", "Low Water Mark"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "The Bell-LaPadula model adds compartments (categories) alongside hierarchical levels to implement multilateral (need-to-know) security.", "topic": "Information Security"}, {"id": "pdf6-147", "question": "The model does not give users power to alter access control in the system manifested in a principle called tranquility", "options": ["Bell\u2013LaPadula model", "Biba model", "Low Water Mark model", "Ring model"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Bell-LaPadula enforces the tranquility principle, meaning subjects cannot alter access control labels/levels themselves while the system is running.", "topic": "Information Security"}, {"id": "pdf6-148", "question": "The Bell\u2013LaPadula model leverages mandatory _____", "options": ["Access control", "Kernel control", "System control", "Privacy control"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Bell-LaPadula is a mandatory access control (MAC) model, where access decisions are governed by system-enforced security labels rather than owner discretion.", "topic": "Information Security"}, {"id": "pdf6-149", "question": "The _______ requires that a subject S can read an object O only if S dom O and any DAC permits it (\u201cread down\u201d)", "options": ["Simple Security Condition", "Complex security condition", "*-Property", "Multi lateral security"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "This describes the Simple Security Condition (ss-property) of Bell-LaPadula, the \"no read up\" rule: a subject can only read an object at or below its own level.", "topic": "Information Security"}, {"id": "pdf6-150", "question": "Lipners model combines _____ and _____ models", "options": ["Biba model , Bell\u2013LaPadula model", "Low Water Mark model , Biba Model", "Low Water Mark model, Ring Policy model", "Ring Policy model, Bell\u2013LaPadula model"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Lipner's integrity model combines Bell-LaPadula (confidentiality) with the Biba model (integrity) to address both concerns together.", "topic": "Information Security"}, {"id": "pdf6-151", "question": "In MAC Tuples ,Process can write object when: Object MAC range (lr, hr); process MAC label pl", "options": ["\u2140 pl (lr, hr)", "pl U (lr, hr)", "pl (lr, hr) \u2208", "pl dom hr"], "correct": 3, "original_marked": null, "matches_original": false, "confidence": "low", "reasoning": "The question text and options are badly garbled by OCR, but the intended rule is that a process can write an object only if its MAC label pl falls within the object's range (lr, hr), i.e. pl \u2208 (lr, hr).", "topic": "Information Security"}, {"id": "pdf6-152", "question": "In clark Wilson model IVPs must ensure that all the _______ are in valid state when the IVP is run", "options": ["Unconstrained data items", "Constrained data items", "Transforamtion data items", "Integrity verification data items"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "In the Clark-Wilson model, Integrity Verification Procedures (IVPs) check that all Constrained Data Items (CDIs) are in a valid state before/when they run.", "topic": "Information Security"}, {"id": "pdf6-153", "question": "In clark Wilson model a proper_______ log files to be maintained", "options": ["Active", "Data", "Audit", "Internal"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Clark-Wilson requires a proper audit log of all transactions that change CDIs, so the sequence of actions can be reconstructed later.", "topic": "Information Security"}, {"id": "pdf6-154", "question": "In Biba Model A subjects can only read an object o if", "options": ["Is > Io", "LO > LS", "Is \u2264 Io", "LO > LS"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Biba's simple integrity (no-read-down) property says a subject can read an object only if the subject's integrity level is less than or equal to the object's, i.e. i(s) \u2264 i(o).", "topic": "Information Security"}, {"id": "pdf6-155", "question": "In _____ , each subject S and object O is assigned an integrity level in I", "options": ["Biba\u2019s model", "Bell\u2013LaPadula", "Low Water Mark", "Integrity Policies"], "correct": 1, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "Assigning every subject and object an integrity level in a lattice I is exactly how Biba's model is defined; Bell-LaPadula instead assigns security/classification levels for confidentiality, not integrity levels, so the marked answer is wrong.", "topic": "Information Security"}, {"id": "pdf6-156", "question": "If there is an information path from O 1\u2208O to O n+1\u2208O, then enforcement of the low-water-mark policy requires that _____ for all i>n", "options": ["i(O n) > i(O)", "i(O n-1) \u2260i(O 1)", "i(O n-1) \u2265(O 1)", "i(O n+1) \u2264i(O 1)"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Under the low-water-mark policy, each read lowers a subject's effective integrity to the minimum of what it has seen, so along an information-flow path from o1 to on+1, the final object's integrity level i(on+1) must be \u2264 i(o1).", "topic": "Information Security"}, {"id": "pdf6-157", "question": "If (s,o,a) \u2208 b and access is in alter mode, then fC(s) \u2264 fO(o) ; also, if subject s has access to object o in alter mode, then fO(o\u2019) \u2264 fO(o) for all objects o\u2019 accessed by s in observe mode", "options": ["Simple Security (ss)-Property", "Discretionary Simple (ds)-Property", "\u2217-Property (star property)", "Discretionary Security (ds)-Property"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "This is the standard Bell-LaPadula *-property: it constrains a subject's write (alter) access relative to its read (observe) access so information can't leak to a lower level.", "topic": "Information Security"}, {"id": "pdf6-158", "question": "Access permissions defined through an access _____ and _____.", "options": ["Control matrix, Security levels", "Control level, Access level", "Control matrix, Access level", "Security , Permission"], "correct": 1, "original_marked": 3, "matches_original": false, "confidence": "high", "reasoning": "Bell-LaPadula is a hybrid model: access permissions come from a discretionary access control matrix plus mandatory security levels, not from a 'control matrix and access level' as marked.", "topic": "Information Security"}, {"id": "pdf6-159", "question": "Access must be permitted by the access control matrix: if (s,o,a) \u2208 b, then a \u2208 Mso", "options": ["Simple Security (ss)-Property", "Discretionary Security (ds)-Property", "Security Property (sp)", "Discretionary Simple (ds)-Property"], "correct": 2, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "The rule 'if (s,o,a)\u2208b then a\u2208Mso' is the definition of the Discretionary Security (ds)-property, which ties access to entries in the access control matrix; the ss-property instead governs read access based on classification levels.", "topic": "Information Security"}, {"id": "pdf6-160", "question": "A system has _____ when subjects or objects levels and compartments do not change in a way that violates a given security policy.", "options": ["Weak Tranquility", "Tranquility", "Normal Operation", "Unclassified level"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Weak tranquility permits subject/object levels to change during operation as long as the change never violates the security policy.", "topic": "Information Security"}, {"id": "pdf6-161", "question": "_____means that when a system is in use, subjects and objects levels and compartments do not change", "options": ["Weak Tranquility", "Tranquility", "Normal Operation", "Unclassified Level"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "(Strict) tranquility means security levels of subjects and objects do not change at all while the system is in use.", "topic": "Information Security"}, {"id": "pdf6-162", "question": "________ means ensuring timely and reliable access to and the use of information.", "options": ["Integrity", "Availability", "Confidentiality", "Threat intelligence"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Availability, one of the CIA triad pillars, is defined as ensuring timely and reliable access to and use of information/systems.", "topic": "Information Security"}, {"id": "pdf6-163", "question": "________ includes activities to protect the usability, reliability, integrity and safety of the network", "options": ["Disaster security", "Information security", "Network security", "Application security"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Network security is the set of activities designed to protect the usability, reliability, integrity, and safety of a network and its data.", "topic": "Information Security"}, {"id": "pdf6-164", "question": "________ includes activities to protect the usability, reliability, integrity and safety of the network", "options": ["Disaster security", "Information security", "Network security", "Application security"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Duplicate of the previous question: network security protects the usability, reliability, integrity, and safety of the network.", "topic": "Information Security"}, {"id": "pdf6-165", "question": "Which operator is used to insert the data into file?", "options": [">>", "<<", "<", "none"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The stream insertion operator << is used to insert/write data into an output file stream in C++.", "topic": "C/C++"}, {"id": "pdf6-166", "question": "Use of Big oh notation (O) notation?", "options": ["To Specify Worst case complexity", "To specify Best case complexity", "To specify average case complexity", "None"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Big-O notation is conventionally taught and used to express an algorithm's worst-case (upper bound) time or space complexity.", "topic": "DSA"}, {"id": "pdf6-167", "question": "Which of the following are parts of any organisation given by Mintzberg?", "options": ["Operating core", "Strategic apex", "Middle line", "All of the above"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Mintzberg's organizational model lists the operating core, strategic apex, and middle line (plus technostructure and support staff) as parts of any organization, so all three listed options are correct.", "topic": "Management"}, {"id": "pdf6-168", "question": "______ is a set of autonomous units, each typically machine bureaucracies, coordinated by a central headquarters.", "options": ["Divisional structure", "Professional bureaucracy", "Adhocracy", "None of the above."], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Mintzberg's divisionalized form consists of quasi-autonomous units, each often a machine bureaucracy, coordinated by a central headquarters.", "topic": "Management"}, {"id": "pdf6-169", "question": "Which of the following is not true of the span of control?", "options": ["The average span of control affects the number of managers.", "Geographical separation of staff influences the span that can be coped with.", "High spans of control are found in supervision of line production.", "The technical content of jobs has little effect on the required span of control of supervisors."], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "The technical/complexity content of a job strongly affects the appropriate span of control (more complex work needs a narrower span), so the claim that it has 'little effect' is the false statement.", "topic": "Management"}, {"id": "pdf6-170", "question": "Which one of the following statements most accurately describes the nature of an ethical issue in business?", "options": ["Ethical issues can be resolved if you do what you think is right.", "Ethical issues can be resolved by following the guidance of religious beliefs.", "Ethical issues are difficult because all the choices may do some harm.", "Ethical issues are difficult because the results of a decision are hard to predict."], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Ethical issues in business are difficult largely because the consequences of a decision are hard to foresee, making it hard to judge which choice is truly 'right'.", "topic": "Business Ethics"}, {"id": "pdf6-171", "question": "Which of the following statements is false about the behavioural theories of leadership?", "options": ["Consideration is people-oriented", "Production-orientation has little concern for people", "High initiating structure leaders do not set deadlines .", "Employee-centred leader behaviour focuses on people."], "correct": 3, "original_marked": null, "matches_original": false, "confidence": "high", "reasoning": "Initiating structure is precisely the task-oriented leader behavior that includes setting deadlines, schedules, and defining roles, so the claim that high initiating-structure leaders 'do not set deadlines' is the false statement; the source PDF left this one unmarked.", "topic": "Management"}, {"id": "pdf6-172", "question": "There are several practical steps that managers can take to improve the level of socially responsible behaviour in their company. Which of the following is the least likely to work?", "options": ["Publishing a statement of ethical policy in a booklet for staff.", "Creating a system of ethical reporting which is widely accessible on their website.", "Leading by example.", "Creating ethical structures."], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "low", "reasoning": "The source marks 'leading by example' as least likely to work, though most management literature actually treats it as one of the most effective steps; deferring to the source answer since the intended textbook reasoning (e.g. it lacks formal accountability compared to written policies/structures) can't be independently confirmed.", "topic": "Business Ethics"}, {"id": "pdf6-173", "question": "The number of persons which can be effectively supervised by a single executive or departmental head should be limited to _______ in an average firm.", "options": ["six", "ten", "fourteen", "twenty"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The classical span-of-control principle (Urwick) holds that a manager can effectively supervise about six subordinates whose work is interrelated.", "topic": "Management"}, {"id": "pdf6-174", "question": "The managerial grid used the behavioural dimensions \"concern for people\" and ________", "options": ["\"Concern for integrity\"", "\"Concern for profit\"", "\"Concern for environment\"", "\"Concern for production\""], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "The Blake-Mouton managerial grid plots leadership style on two axes: 'concern for people' and 'concern for production'.", "topic": "Management"}, {"id": "pdf6-175", "question": "The following phrase is used to describe a leader:", "options": ["relies on control strategies", "challenges the status quo", "uses traditional influence", "acts with established culture"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "In the classic leader-vs-manager distinction (Bennis/Zaleznik style), a leader challenges the status quo while a manager accepts and administers it.", "topic": "Management"}, {"id": "pdf6-176", "question": "The following is not a principle of organisation.", "options": ["Principle of exception", "Principle of balance", "Principle of complexity", "Principle of co-ordination"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Standard principles of organisation include exception, balance, and co-ordination; 'complexity' is not one \u2014 organisations actually strive for simplicity, not complexity.", "topic": "Management"}, {"id": "pdf6-177", "question": "Responsibility always flows from", "options": ["Superior to subordinate", "Subordinate to superior", "Both from the superior to the subordinate, and from the subordinate to the superior", "None of the answers is correct"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Authority flows downward from superior to subordinate, but responsibility (accountability for performing the assigned task) flows upward from subordinate to superior.", "topic": "Management"}, {"id": "pdf6-178", "question": "Leadership which enlists the help of subordinates as a group to solve problems is:", "options": ["Situational", "Laissez-faire", "participative", "employee-oriented"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Participative leadership involves subordinates as a group in decision-making and problem-solving, unlike autocratic, laissez-faire, or purely situational styles.", "topic": "Management"}, {"id": "pdf6-179", "question": "In a line organisation, the business activities are divided into following three types.", "options": ["Accounts, Production, Sales", "Production, Quality, Sales", "Production, Quality, Maintenance", "Production, Maintenance, Sales"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "In a classic line organisation, activities are split into the three core functions of Accounts, Production, and Sales, confirmed by standard commerce MCQ references (e.g., ICAI/CPT study material).", "topic": "Management"}, {"id": "pdf6-180", "question": "_______________ builds trust among individuals and in business relationships, which validates and promotes confidence in business relationships.", "options": ["Ethical conduct", "Social responsibility", "Ethical responsibility", "Business ethics"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "It is the actual practice of ethical conduct (not just the study of business ethics or general social responsibility) that builds trust and confidence in business relationships.", "topic": "Business Ethics"}, {"id": "pdf6-181", "question": "____ dependent on template parameter?", "options": ["base class", "abstract class", "method", "None of the mentioned"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A 'dependent base class' is a C++ template concept where a base class depends on a template parameter, which is why the compiler cannot resolve its members without a 'this->' or 'typename' qualifier until instantiation.", "topic": "C/C++"}, {"id": "pdf7-001", "question": "What is the output of this program? #include < iostream > #include < string > using namespace std; template < typename T > void print_mydata(T output) { cout << output << endl; } int main() { double d = 5.5; string s(\"Hello World\"); print_mydata( d ); print_mydata( s ); return 0; }", "options": ["5.5\u00c2 Hello World", "5.5", "Hello World", "none of the mentioned"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "print_mydata<double> outputs 5.5 and print_mydata<string> outputs Hello World, each followed by endl, so the program prints 5.5 then Hello World on separate lines.", "topic": "C/C++"}, {"id": "pdf7-002", "question": "Non-type template allows how many legal parameters?", "options": ["1", "2", "3", "4"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A non-type template parameter can legally be an integral/enum constant, a pointer, a reference, or a pointer-to-member \u2014 four kinds in total.", "topic": "C/C++"}, {"id": "pdf7-003", "question": "Is overloading of the function templates allowed in C++?", "options": ["Yes", "No", "May Be", "Can't Say"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "C++ allows function templates to be overloaded with other function templates or ordinary functions, just like regular function overloading.", "topic": "C/C++"}, {"id": "pdf7-004", "question": "The query to add a unique constraint using alter table command on name column in the proctor table is proctor(id number,name varchar2(10),numberofstudents number, address varchar2(10));", "options": ["alter table proctor constraint proctor_name_uk unique(name);", "alter table proctor add constraint proctor_name_uk unique;", "alter table proctor add constraint proctor_name_uk unique(name);", "alter table proctor add proctor_name_uk unique(name);"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "The correct Oracle syntax to name a unique constraint on a column is ALTER TABLE ... ADD CONSTRAINT <name> UNIQUE(column);.", "topic": "DBMS"}, {"id": "pdf7-005", "question": "The query to add a check constraint using alter table command on numberofstudents column in the proctor table such that the number of students is between 1 and 20 is proctor(id number,name varchar2(10),numberofstudents number, address varchar2(10));", "options": ["alter table proctor add proctor_numberofstudents_ck check(numberofstudents>=1 and numberofstudents<=20);", "alter table proctor add constraint proctor_numberofstudents_ck check(numberofstudents>=1 and numberofstudents<=20);", "alter table proctor add proctor_numberofstudents_ck check(numberofstudents>1 and numberofstudents<20);", "alter proctor add constraint proctor_numberofstudents_ck check(numberofstudents>=1 and numberofstudents<=20);"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A CHECK constraint enforcing an inclusive range of 1 to 20 needs >= and <=, added with ADD CONSTRAINT ... CHECK(...).", "topic": "DBMS"}, {"id": "pdf7-006", "question": "Select transitive dependency from the following", "options": ["x-->y then wy-->z", "X--> YZ then X-->Y , X--> Z", "X-->Y , Y-->Z then X-->Z", "X-->Y then XZ--> YZ"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Transitive dependency is defined as: if X->Y and Y->Z hold (and Y does not determine X), then X->Z holds transitively.", "topic": "DBMS"}, {"id": "pdf7-007", "question": "Select the query to add not null constraint on the numberofstudents column in the proctor table proctor(id number,name varchar2(10),numberofstudents number, address varchar2(10));", "options": ["alter table add constraint proctor_numberofstudent_nn not null;", "alter table proctor add constraint proctor_numberofstudent_nn not null;", "alter table proctor modify numberofstudents number constraint proctor_numberofstudents_nn not null;", "alter table proctor modify numberofstudents constraint proctor_numberofstudents_nn not null;"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Oracle requires MODIFY (not ADD) to attach a NOT NULL constraint to an existing column, and the taught form restates the datatype: MODIFY numberofstudents number CONSTRAINT ... NOT NULL.", "topic": "DBMS"}, {"id": "pdf7-008", "question": "Select the query that establishes the foreign key constraint between the given two tables . Here proctor id is a foreign key in the student table student(regno number, name varchar2(10), address varchar2(10), proctorid number); proctor(proctorid number, proctorname varchar2(10))", "options": ["alter table student add constraint foreign key references proctor(proctorid);", "alter table student add constraint student_proctorid_fr foreign key references proctor(proctorid);", "alter table student add constraint student_proctorid_fr foreign key(proctorid) references student(proctorid);", "alter table student add constraint student_proctorid_fr foreign key(proctorid) references proctor(proctorid);"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A foreign key must name the local column and reference the correct parent table and column: FOREIGN KEY(proctorid) REFERENCES proctor(proctorid).", "topic": "DBMS"}, {"id": "pdf7-009", "question": "Identify the normal for the given relational schema employee (id, name, projectid, projectname, projectlocation) . An employee can work on multiple projects.", "options": ["employee relation is in first normal form", "employee relation is in third normal form", "employee relation is in second normal form", "None of the options are true"], "correct": 1, "original_marked": 4, "matches_original": false, "confidence": "high", "reasoning": "name depends only on id, and projectname/projectlocation depend only on projectid, which are partial dependencies on the composite key (id, projectid) \u2014 so the relation is only in 1NF (not 2NF or 3NF), making statement 1 the true one, not 'none of the options'.", "topic": "DBMS"}, {"id": "pdf7-010", "question": "Foreign keys can be established", "options": ["only at the column level", "only at the table level", "Either at the table level or at the column level", "All the given options are wrong"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Foreign keys can be declared inline on a column (column-level) or as a separate table-level constraint clause \u2014 both are valid SQL.", "topic": "DBMS"}, {"id": "pdf7-011", "question": "For any relation R(pqrs) the set of FD's are F= {pq-->r, q-->s}. If pq is the key for the relation then", "options": ["R is in third normal form", "R is in second normal form", "R is in Boyce Codd normal form", "none of the options are true"], "correct": 4, "original_marked": 3, "matches_original": false, "confidence": "high", "reasoning": "q->s is a partial dependency because q is a proper subset of the key pq and s is a non-prime attribute, so R already violates 2NF and therefore can't be in 3NF or BCNF \u2014 none of the listed options hold.", "topic": "DBMS"}, {"id": "pdf7-012", "question": "For a relation R(ABC) with functional dependencies f={A-->B, B-->C,C-->A) is in", "options": ["second normal form", "third normal form", "Boyce Codd normal form", "All the options are correct"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "A->B->C->A forms a cycle, so each of A, B, C individually determines all attributes and is a candidate key; since every FD's left side is a superkey, R is in BCNF.", "topic": "DBMS"}, {"id": "pdf7-013", "question": "F+ for the set of functional dependencies F = {A-->B,B-->C} is", "options": ["{A-->A,B-->B,C-->C,A-->B, B-->C,A-->C }", "{A-->B, B-->C,AB-->C }", "{A-->A,B-->B,C-->C B-->C,A-->C }", "{A-->A,B-->B,C-->C}"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Reflexivity gives the trivial X->X dependencies, and transitivity on A->B and B->C gives A->C, matching the listed closure.", "topic": "DBMS"}, {"id": "pdf7-014", "question": "Consider the following schemas Product (productid varchar2(10), productname varchar2(10), product_price number,manufacturing_date date, vendorId varchar2(10)) Vendor (vendorId varchar2(10), vendorname varchar2(10), location varchar2(10)) The SQL query to establish check constraint on the location column on location column in the vendor table such that location accepts only US or UK is", "options": ["alter table vendor add constraint vendor_location_ck check(location in ('US','UK'));", "alter table vendor add constraint vendor_location_ck check(location = 'US' or location ='UK');", "Both the given SQL queries are correct", "Only one of the given SQL query is correct"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "CHECK(location IN ('US','UK')) and CHECK(location='US' OR location='UK') are logically and syntactically equivalent, so both queries work correctly.", "topic": "DBMS"}, {"id": "pdf7-015", "question": "Consider the following schemas Product (productid varchar2(10), productname varchar2(10), product_price number,manufacturing_date date, vendorId varchar2(10)) Vendor (vendorId varchar2(10) ,vendorname varchar2(10) ,location varchar2(10)) The SQL query to establish vendorid as the foreign key in the product table is", "options": ["alter table product add constraint foreign key(vendorId) references vendor(vendorId);", "alter table product add constraint product_vendorid_fr foreign key references vendor(vendorId);", "alter table vendor add constraint product_vendorid_fr", "foreign key(vendorId) references vendor(vendorId);"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "low", "reasoning": "The options for this question appear split/garbled by PDF text extraction (option 3 and option 4 read like one statement broken across two lines), so the intended correct query can't be reliably reconstructed from the given choices.", "topic": "DBMS"}, {"id": "pdf7-016", "question": "Consider the following schemas Product (productid varchar2(10) ,productname varchar2(10), product_price number,manufacturing_date date, vendorId varchar2(10)) Vendor (vendorId varchar2(10) ,vendorname varchar2(10) ,location varchar2(10)) The SQL query to establish default price as 100 in the product_price column in the product table is", "options": ["alter table product add constraint price default 100;", "alter table product modify product_price number default 100;", "alter table vendor add price default 100;", "alter table product add constraint price default 100;"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A column default is set with ALTER TABLE ... MODIFY column datatype DEFAULT value; 'ADD CONSTRAINT ... default' is not valid syntax for defaults.", "topic": "DBMS"}, {"id": "pdf7-017", "question": "A-->A according to rule of", "options": ["Reflexivity", "Transitivity", "Union", "Decomposition"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A->A is a trivial dependency produced directly by Armstrong's reflexivity axiom.", "topic": "DBMS"}, {"id": "pdf7-018", "question": "A table is in second normal form if", "options": ["It is in first normal form and has no partial key dependencies", "It is not having multivalued attributes", "It\u2019s partial composite key functionally determines an attribute", "None of the given options are true"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "2NF is defined as 1NF plus no partial dependency of a non-prime attribute on part of a composite candidate key.", "topic": "DBMS"}, {"id": "pdf7-019", "question": "A relation R(ABC) has all attributes to be prime attributes. The highest normal form satisfied by R is", "options": ["BCNF", "Third Normal Form", "Fourth Normal Form", "None of the given options are true"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "When every attribute is prime, no non-prime attribute exists to be transitively dependent, so 3NF is always satisfied \u2014 but BCNF can still fail if some determinant isn't a superkey, so 3NF is the highest form guaranteed.", "topic": "DBMS"}, {"id": "pdf7-020", "question": "A relation R which is having a non-prime attribute transitively dependent on the key is not in", "options": ["Boyce Codd normal form", "Third normal Form", "Fourth Normal Form", "Any of the given Normal Forms"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A transitive dependency of a non-prime attribute on the key violates 3NF, and failing 3NF automatically means failing the stricter BCNF and 4NF too.", "topic": "DBMS"}, {"id": "pdf7-021", "question": "Which of the following problem is undecidable?", "options": ["Membership problem for CFL", "Membership problem for regular sets", "Membership problem for CSL", "Membership problem for type 0 languages"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Membership is decidable for regular, context-free, and context-sensitive languages, but undecidable in general for type-0 (recursively enumerable) languages.", "topic": "TOC"}, {"id": "pdf7-022", "question": "Recursive languages are", "options": ["A proper super set of CFL", "Always recognized by PDA", "Are also called type 0 languages", "Always recognized by FSA"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The hierarchy regular \u2282 CFL \u2282 recursive \u2282 RE means recursive languages strictly and properly contain all context-free languages.", "topic": "TOC"}, {"id": "pdf7-023", "question": "Recursive enumerable languages are not closed under", "options": ["Union", "Homomorphism", "Complementation", "Concatenation"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Recursively enumerable languages are closed under union, concatenation, and homomorphism, but not under complementation.", "topic": "TOC"}, {"id": "pdf7-024", "question": "The statement \u201c A Turing machine cannot solve halting problem\u201d is", "options": ["True", "False", "Still an open problem", "Cannot say"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The undecidability of the halting problem is a proven result \u2014 no Turing machine can decide in general whether an arbitrary TM halts on arbitrary input.", "topic": "TOC"}, {"id": "pdf7-025", "question": "Every non-deterministic TM can be simulated by a deterministic TM", "options": ["True", "False", "Some times", "None of the choices."], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Nondeterministic and deterministic Turing machines are equivalent in computational power; any NTM can be simulated by a DTM (with possible exponential slowdown).", "topic": "TOC"}, {"id": "pdf7-026", "question": "Context-sensitive languages can be recognized by", "options": ["Deterministic PDA", "Non-deterministic PDA", "Linear bounded automaton", "Finite state automaton"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Context-sensitive languages are exactly the languages recognized by linear bounded automata (LBA), a PDA is too weak (only recognizes context-free languages) and an FSA only recognizes regular languages.", "topic": "TOC"}, {"id": "pdf7-027", "question": "A multi-head TM can be simulated by a single head TM", "options": ["True", "False", "Some times", "None of the choices."], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A multi-head Turing machine has the same computational power as a single-head TM because a single head can simulate multiple heads by tracking their positions on an expanded tape alphabet.", "topic": "TOC"}, {"id": "pdf7-028", "question": "To determine whether the stream object is currently associated with a file ___ member function is used", "options": ["is_open", "Buf", "String", "None of the above"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "is_open() is the standard C++ fstream member function that returns true if the stream is currently associated with an open file.", "topic": "C/C++"}, {"id": "pdf7-029", "question": "void main() { struct books{ float st1; char st2[6]; }*ptr; printf(\"%d\",sizeof(ptr)); }", "options": ["5", "6", "8", "10"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "ptr is declared as a pointer to a struct, so sizeof(ptr) only measures the pointer itself (not the struct it points to), which is 8 bytes on a typical 64-bit compiler.", "topic": "C/C++"}, {"id": "pdf7-030", "question": "which of the following is the correct way of declaring a float pointer variable:", "options": ["float ptr;", "float **ptr;", "*float ptr;", "float *ptr;"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A pointer to float is declared by placing the * next to the variable name after the base type, i.e. \"float *ptr;\".", "topic": "C/C++"}, {"id": "pdf7-031", "question": "What is the size of a C structure?", "options": ["C structure is always 128 bytes.", "Size of C structure is the total bytes of all elements of structure.", "Size of C structure is the size element. of largest", "Size of C structure is the size element. of smallest"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The standard textbook rule taught for structure size is that it's the sum of the sizes of all its members (padding/alignment aside, which most intro courses ignore) \u2014 unlike a union, which takes the size of its largest member.", "topic": "C/C++"}, {"id": "pdf7-032", "question": "What is actually passed if you pass a structure variable to a function?", "options": ["Copy of structure variable", "Reference of structure variable", "Starting address of structure variable", "Ending address of structure variable"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "C passes arguments by value by default, so passing a structure to a function passes a full copy of it, not a reference or address.", "topic": "C/C++"}, {"id": "pdf7-033", "question": "void main() { printf(\u201c%d %d\u201d, sizeof(int *), sizeof(int **)); }", "options": ["2 0", "0 2", "2 2(if 16 bit)", "2 4 \u2014none match since\u2013 5. Compiler gives = 8,8(64 bit)"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "low", "reasoning": "sizeof(int*) and sizeof(int**) are always equal to each other since all pointer types have the same size on a given system (2 bytes on a classic 16-bit compiler like Turbo C); the option wording here is garbled, making this one genuinely hard to verify cleanly.", "topic": "C/C++"}, {"id": "pdf7-034", "question": "void main() { int i=3, *f, **g; f=&I; g=&f; printf(\u201c%d %d %d\u201d, *f, **g, *(*g)); }", "options": ["4 4 4", "0 0 0", "3 3 3", "4 3 3"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "f points to i (value 3), g points to f, so *f = 3, and **g = *(*g) = *f = 3 as well \u2014 all three printed values are 3.", "topic": "C/C++"}, {"id": "pdf7-035", "question": "void main() { int a[]={1, 2, 3,4}, *p; p=a; ++*p; printf(\u201c%d\u201d, *p); }", "options": ["2", "1", "3", "4"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "p points to a[0] which is 1; ++*p increments the value pointed to (not the pointer), making a[0] equal to 2, which is then printed.", "topic": "C/C++"}, {"id": "pdf7-036", "question": "void main() { int *pt, q=20; pt=&q; *pt+=1; printf(\u201c%d,%d\u201d,*pt,q) }", "options": ["20, 20", "20, 21", "21, 20", "21, 21"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "pt points to q; *pt+=1 increments q through the pointer, so both *pt and q become 21.", "topic": "C/C++"}, {"id": "pdf7-037", "question": "void main() { char st1=\u201dqwty\u201d; char st2[]=\u201dqwty\u201d; printf(\u201c%d %d %d\u201d, sizeof(st1),sizeof(s2t),sizeof(\u201cqwty\u201d)) }", "options": ["2 5 5", "2 4 4", "8 5 5 (if it is char* st1)", "2 4 5"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "As the option notes, if st1 is a char pointer, sizeof(st1) is the pointer size (8 on 64-bit), while st2 is a char array holding \"qwty\"+null terminator (5 bytes), same as the string literal itself.", "topic": "C/C++"}, {"id": "pdf7-038", "question": "void main() { char fast, *faster, *fastest; printf(\u201c%d..%d\u201d, sizeof(faster),sizeof(fastest)) }", "options": ["4..2", "2..2", "4..4", "2..4"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "faster and fastest are both char pointers, and all pointer types have the same size on a given system (4 bytes on a 32-bit compiler), so the two sizeof results must be equal.", "topic": "C/C++"}, {"id": "pdf7-039", "question": "void main() { char *pt=NULL; char *p=0; if(pt) printf(\u201cPT\u201d); else printf(\u201cNullvlauept\u201d); if(p) printf(\u201cP\u201d); else printf(\u201cNullvlauep\u201d); }", "options": ["PT P", "Nullvlauept P", "PT Nullvlauep", "Nullvlauept Nullvlauep"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Both pt and p are null pointers (NULL and 0 are equivalent), so both if-conditions are false and both else branches execute, printing \"Nullvlauept\" then \"Nullvlauep\".", "topic": "C/C++"}, {"id": "pdf7-040", "question": "void main() { char *pt; pt=\u201dWorld\u201d; printf(\u201c%cn\u201d, *&*pt); }", "options": ["World", "Some address will be printed", "Wn", "W"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "*&*pt just dereferences pt, giving the character 'W'; the format string \"%cn\" prints that character followed by the literal letter n, giving \"Wn\".", "topic": "C/C++"}, {"id": "pdf7-041", "question": "void main() { char *f=\u201dHello\u201d; printf(f) }", "options": ["Hello", "H", "Hello followed by garbage value", "Garbage value"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "printf(f) uses f (\"Hello\") directly as the format string; since it contains no format specifiers, it just prints \"Hello\" as-is.", "topic": "C/C++"}, {"id": "pdf7-042", "question": "void main() { char *f; printf(\u201c%d %d\u201d, sizeof(*f),sizeof(f)) }", "options": ["1 1", "1 2", "2 1", "2 2"], "correct": 2, "original_marked": 3, "matches_original": false, "confidence": "high", "reasoning": "*f dereferences a char pointer to a char, and sizeof(char) is always 1 byte, while sizeof(f) is the pointer size (2 bytes on a classic 16-bit compiler) \u2014 so the answer must be \"1 2\", not \"2 1\" as marked, since a pointer can never be smaller than a char.", "topic": "C/C++"}, {"id": "pdf7-043", "question": "void main() { struct books{ int pages; char str[4]; }b; printf(\"%d\",sizeof(b)); }", "options": ["5", "6", "7", "8"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "An int (4 bytes) plus a char[4] (4 bytes) totals 8 bytes with no extra padding needed since char[4] is already aligned to a 4-byte boundary.", "topic": "C/C++"}, {"id": "pdf7-044", "question": "void main() { struct paint{ int type; int color; }p1, p2; p1.type=1; p1.color=5; if(sizeof(p1)==sizeof(p2)) { printf(\"SAME\"); } else { printf(\"DIFFERENT\"); } return 0; }", "options": ["Garbage value", "DIFFERENT", "Compiler error", "SAME"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "p1 and p2 are both declared as the same struct type, so sizeof always returns the same value for both regardless of the values stored in their members, printing SAME.", "topic": "C/C++"}, {"id": "pdf7-045", "question": "void main() { struct laptop { int cost; char brand[10]; }; struct laptop L1={5000,\"ACER\"}; struct laptop L2={6000,\"IBM\"}; printf(\"Name=%s\",strcat(L1.brand,L2.brand)); }", "options": ["ACERIBM", "IBM ACER", "ACER IBM", "IBMACER"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "strcat appends L2.brand (\"IBM\") onto the end of L1.brand (\"ACER\"), and there's enough room in the 10-byte array, producing \"ACERIBM\".", "topic": "C/C++"}, {"id": "pdf7-046", "question": "void main() { sturct tree { int q,w; }; struct tree t1={10}; printf(\u201c%d\u201d, t1.w); printf(\u201c%d\u201d, t1.q); }", "options": ["0 0", "10 0", "0 10", "10 10"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "t1={10} initializes only the first member q to 10; the second member w, left unspecified, is zero-initialized, so t1.w prints 0 and t1.q prints 10, giving \"0 10\".", "topic": "C/C++"}, {"id": "pdf7-047", "question": "void main() { sturct ship { char paint[10]; }b1,b2; strcpy(b1.paint,\u201dRED\u201d); printf(\u201c%s\u201d, b1.paint); b2=b1; strcpy(b2.paint,\u201dYELLOW\u201d); printf(\u201c%s\u201d, b1.paint); }", "options": ["YELLOW RED", "RED YELLOW", "YELLOW YELLOW", "RED RED"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "b2=b1 copies the struct by value, so b1 and b2.paint are independent arrays afterward; changing b2.paint to YELLOW does not affect b1.paint, which stays \"RED\" both times it's printed.", "topic": "C/C++"}, {"id": "pdf7-048", "question": "void main() { sturct bus { int sz; char type[10]; }b1,b2; b1.sz=20; b2=b1; printf(\u201cb2=%d\u201d, b2.sz); }", "options": ["boat2=0", "boat2=-1", "boat2=20", "boat2=some garbage value"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "b2=b1 performs a full struct copy (value semantics), so b2.sz picks up b1's value of 20.", "topic": "C/C++"}, {"id": "pdf7-049", "question": "The address operator & cannot act on", "options": ["R-values and Arithmetic expressions", "Local variables", "Global variables", "Member of a structure"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The & operator requires an lvalue with a storage location; it cannot be applied to r-values or the results of arithmetic expressions, since those don't have addresses of their own.", "topic": "C/C++"}, {"id": "pdf7-050", "question": "The statement int **a;", "options": ["is illegal", "is legal but meaningless", "pointer to pointer variable", "pointer variable"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "int **a; declares a which holds the address of an int pointer \u2014 i.e., a pointer to a pointer variable.", "topic": "C/C++"}, {"id": "pdf7-051", "question": "Select the valid statement about C structure.", "options": ["Structure elements are stored on random free memory locations", "Structure elements are stored in register memory locations", "Structure elements are stored in contiguous memory locations", "Structure elements are stored in detached memory locations"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "C structure members are stored in contiguous memory locations (possibly with padding for alignment), which is the standard textbook answer.", "topic": "C/C++"}, {"id": "pdf7-052", "question": "function(){ int i=1, s=1; while(S<=n) { i++; s=s+i; printf(\u201chello\u201d) } } What is the time complexity of the given function()?", "options": ["O(n)", "O(n^2)", "O(\u221an)", "O(nlogn)"], "correct": 3, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "s grows roughly as i\u00b2/2 with each pass, so the loop only needs about \u221a(2n) iterations before s exceeds n \u2014 this is the classic O(\u221an) loop pattern, not O(n).", "topic": "DSA"}, {"id": "pdf7-053", "question": "Function(){ int I,j,k; for(i=n/2;i<=n;i++) for(j=1;j<=n;j=2*j) for(k=1;k<=n;k=k*2) printf(\u201cHello\u201d); } What is the time complexity of the given function()?", "options": ["O(n* (Log2 n)2)", "O(n* (Log2 n))", "O(n2* (Log2 n))", "O(n3)"], "correct": 1, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "The outer loop runs O(n) times (i++ from n/2 to n), while the middle and inner loops each double their counter, giving O(log n) iterations apiece; multiplying three independent nested loops gives O(n\u00b7(log n)\u00b2).", "topic": "DSA"}, {"id": "pdf7-054", "question": "Comment on the following pointer declaration. int *ptr, p;", "options": ["ptr and p, both are pointers to integer.", "ptr is a pointer to integer, p is not.", "ptr is pointer to integer, p may or may not be.", "ptr and p both are not pointers to integer."], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "In 'int *ptr, p;' the * binds only to ptr, so ptr is a pointer to int while p is declared as a plain int.", "topic": "C/C++"}, {"id": "pdf7-055", "question": "Choose the correct statement about C structure.", "options": ["Structure members cannot be initialized at the time of declaration", "Structure elements can be initialized at the time of declaration.", "Only integer members of structure can be initialized at the time of declaration", "Only float members of structure can be initialized at the time of declaration"], "correct": 2, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "C structures can absolutely be initialized at the point of declaration, e.g. struct Point p = {1, 2}; the marked option states the opposite of the true fact.", "topic": "C/C++"}, {"id": "pdf7-056", "question": "struct node { int i; float j; }; struct node *s[10];", "options": ["An array, each element of which is a pointer to a structure of type node", "A structure of 2 fields, each field being a pointer to an array of 10", "A structure of 3 fields: an integer, a float, and an array of 10 elements", "An array, each element of which is a structure of type node"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "struct node *s[10] declares s as an array of 10 pointers, each pointing to a struct node \u2014 read right-to-left: array of pointers to struct, not pointer to array.", "topic": "C/C++"}, {"id": "pdf7-057", "question": "You have a class A network address 10.0.0.0 with 40 subnets, but are required to add 60 new subnets very soon. You would like to still allow for the largest possible number of host IDs per subnet. Which subnet mask should you assign?", "options": ["255.240.0.0", "255.248.0.0", "255.252.0.0", "255.254.0.0"], "correct": 4, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "You need at least 40+60=100 subnets, which requires borrowing 7 bits (2^7=128 \u2265 100); using the fewest bits that satisfy this maximizes remaining host bits, giving mask 255.254.0.0 \u2014 255.240.0.0 only yields 16 subnets, which isn't enough.", "topic": "CN"}, {"id": "pdf7-058", "question": "Which of the transport layer protocols is connectionless?", "options": ["UDP", "TCP", "FTP", "Nvt"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "UDP is connectionless; TCP is connection-oriented, and FTP/Telnet (NVT) run over TCP.", "topic": "CN"}, {"id": "pdf7-059", "question": "Which of the following uses network address translation?", "options": ["Routers", "Network adapter drivers", "Hubs", "Windows 95"], "correct": 1, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "NAT is implemented on routers/gateway devices sitting between a private network and the public internet; network adapter drivers, hubs, and Windows 95 by itself don't perform address translation.", "topic": "CN"}, {"id": "pdf7-060", "question": "Which of the following pieces of information can be found in the IP header?", "options": ["Source address of the IP packet", "Destination address for the IP packet", "Sequence number of the IP packet", "Both Source address of the IP packet and Destination address for the IP packet only \u2013more proper ans\u2013 IP version, source IP address, destination IP address, time-to-live"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "The IP header carries source and destination addresses (plus version, TTL, etc.); sequence numbers belong to the TCP header, not IP.", "topic": "CN"}, {"id": "pdf7-061", "question": "Which layer of the OSI reference model has service point addressing Select one:", "options": ["session layer", "physical layer", "transport layer", "data link layer"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Service-point (port) addressing is added at the transport layer so data reaches the correct process on the destination host.", "topic": "CN"}, {"id": "pdf7-062", "question": "WHICH LAYER LINKS THE NETWORK SUPPORT LAYERS AND USER SUPPORT LAYERS?", "options": ["SESSION LAYER", "DATA LINK LAYER", "TRANSPORT LAYER", "NETWORK LAYER"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "In the OSI model, the transport layer is the layer that links the lower network-support layers to the upper user-support layers.", "topic": "CN"}, {"id": "pdf7-063", "question": "WHICH ADDRESS IDENTIFIES A PROCESS ON A HOST?", "options": ["PHYSICAL ADDRESS", "LOGICAL ADDRESS", "PORT ADDRESS", "SPECIFIC ADDRESS"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "A port address identifies a specific process running on a host, as opposed to a physical (MAC) or logical (IP) address which identify the NIC/host.", "topic": "CN"}, {"id": "pdf7-064", "question": "What is the default subnet mask for a class C network?", "options": ["127.0.0.1", "255.0.0.0", "255.255.0.0", "255.255.255.0"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Class C addresses reserve the first three octets for the network portion, giving the default mask 255.255.255.0.", "topic": "CN"}, {"id": "pdf7-065", "question": "We also don't want our undeliverable packets to hop around forever. What feature/flag limits the life of an IP packet on the network?", "options": ["Time to Live counter", "Subnet Mask", "Header Checksum", "Wackamole field"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The IP header's Time-to-Live field is decremented at every router hop, and the packet is discarded once it reaches zero, preventing packets from looping forever.", "topic": "CN"}, {"id": "pdf7-066", "question": "The standard suit of protocols used by the Internet, Intranets, extranets and some other networks.", "options": ["Protocol", "TCP/IP", "Open system", "Internet work processor"], "correct": 2, "original_marked": 4, "matches_original": false, "confidence": "high", "reasoning": "TCP/IP is literally the name of the standard protocol suite used across the Internet, intranets, and extranets; 'Internetwork processor' is not a real networking term.", "topic": "CN"}, {"id": "pdf7-067", "question": "THE 4 BYTE IP ADDRESS CONSISTS OF....", "options": ["NETWORK ADDRESS", "HOST ADDRESS", "NETWORK BOTH ADDRESS and HOST ADDRESS", "MAC ADDRESS"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "A 4-byte IPv4 address is split into a network portion and a host portion, so it consists of both.", "topic": "CN"}, {"id": "pdf7-068", "question": "TCP/IP ................. layer corresponds to the OSI models to three layers.", "options": ["Application", "Presentation", "Session", "Transport"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The TCP/IP application layer combines the functions the OSI model splits across its session, presentation, and application layers.", "topic": "CN"}, {"id": "pdf7-069", "question": "State the following statement is true or false. (i) In class B addresses a total of more than 1 billion addresses can be formed. (ii)Class E addresses are reserved for future or experimental use.", "options": ["True, False", "True, True", "False, True", "False, False"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Class B spans 128.0.0.0-191.255.255.255, roughly 2^30 (~1.07 billion) addresses, so statement (i) is true; Class E is indeed reserved for experimental/future use, so (ii) is true too.", "topic": "CN"}, {"id": "pdf7-070", "question": "Propagation time of data packets is calculated using Select one:", "options": ["transmission time + delay", "queuing time + processing delay", "distance/propagation speed", "message size/bandwidth"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Propagation time is distance divided by the signal's propagation speed through the medium, distinct from transmission time (which depends on message size/bandwidth).", "topic": "CN"}, {"id": "pdf7-071", "question": "Leaky bucket algorithm works in", "options": ["Transport layer", "Network layer", "Data link layer", "Physical layer"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Leaky bucket (and token bucket) are traffic-shaping/congestion-control algorithms, which standard networking texts (e.g., Forouzan) place at the network layer.", "topic": "CN"}, {"id": "pdf7-072", "question": "If there are N routers from source to destination, total end to end delay in sending packet P (L->number of bits in the packet R-> transmission rate)", "options": ["N", "(N*L)/R", "(2N*L)/R", "L/R"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "With N hops each store-and-forwarding an L-bit packet at rate R, the standard textbook end-to-end transmission delay (ignoring propagation/queuing) is (N\u00b7L)/R.", "topic": "CN"}, {"id": "pdf7-073", "question": "ICMP IS PRIMARILY USED FOR.....", "options": ["ERROR AND DIAGNOSTIC FUNCTIONS", "ADDRESSING", "FORWARDING", "REVERSING"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "ICMP reports errors and provides diagnostic functions (e.g., ping, destination-unreachable messages); it does not handle addressing or forwarding.", "topic": "CN"}, {"id": "pdf7-074", "question": "How many bits internet address is assigned to each host on a TCP/IP internet which is used in all information exchange with the host?", "options": ["16 bits", "32 bits", "48 bits", "64 bits"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "IPv4 addresses used to identify hosts on a TCP/IP internet are 32 bits long.", "topic": "CN"}, {"id": "pdf7-075", "question": "End-to-end connectivity is provided from host-to-host in:", "options": ["Network layer", "Session layer", "Transport layer", ". Data link layer"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The network layer delivers packets from the source host to the destination host (host-to-host), while the transport layer handles process-to-process delivery.", "topic": "CN"}, {"id": "pdf7-076", "question": "A SUBSET OF A NETWORK THAT INCLUDES ALL THE ROUTERS BUT CONTAINS NO LOOPS IS CALLED....", "options": ["SPANNING TREE", "SPIDER STRUCTURE", "SPIDER TREE", "ACYCLIC TREE"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A spanning tree of a network includes every router (node) but has no loops/cycles, by definition.", "topic": "CN"}, {"id": "pdf7-077", "question": "................... address use 8 bits for the <network> and 24 bits for the <host> portion of the IP address.", "options": ["Class A", "Class B", "Class C", "Class D"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Class A addresses use the first 8 bits (first octet) for the network portion and the remaining 24 bits for the host portion.", "topic": "CN"}, {"id": "pdf7-078", "question": "............. addresses are reserved for multicasting.", "options": ["Class B", "Class C", "Class D", "Class E"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Class D addresses (224.0.0.0-239.255.255.255) are reserved for multicast group addressing.", "topic": "CN"}, {"id": "pdf7-079", "question": "Which of the following algorithm shows better best-case complexity?", "options": ["Quick sort", "Insertion sort", "Merge sort", "Selection sort"], "correct": 2, "original_marked": 4, "matches_original": false, "confidence": "high", "reasoning": "Insertion sort has the best best-case complexity at O(n) when the array is already sorted; selection sort is always O(n^2) regardless of input order, so it cannot be the answer.", "topic": "DSA"}, {"id": "pdf7-080", "question": "What is the minimum complexity to perform sorting on an array of n elements?", "options": ["O(n logn)", "O(n)", "O(n+logn)", "O(logn)"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Comparison-based sorting has a proven lower bound of O(n log n), which is why algorithms like merge sort and heap sort achieve this optimal complexity.", "topic": "DSA"}, {"id": "pdf7-081", "question": "Which of the following is not a limitation of the binary search algorithms?", "options": ["must use a sorted array", "requirement of the sorted array is expensive when a lot of insertion and deletions are needed", "there must be a mechanism to access the middle element directly", "the binary search algorithm is not efficient when the data elements are more than 1500"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "The '1500 elements' cutoff is not a real property of binary search - it remains O(log n) efficient regardless of size, unlike the other three which are genuine limitations (needs sorted, random-access data and is costly to keep sorted under frequent insert/delete).", "topic": "DSA"}, {"id": "pdf7-082", "question": "The condition signals the binary search is unsuccessful is,", "options": ["END<BEG+2", "END>BEG", "END<BEG", "END=BEG"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Binary search terminates unsuccessfully once the low pointer crosses the high pointer, i.e. when END < BEG.", "topic": "DSA"}, {"id": "pdf7-083", "question": "Assume that the available memory space is very less. Which of the following sorting algorithm is not suitable for performing the sorting of a large amount of data elements.", "options": ["Bubble sort", "Insertion sort", "Merge sort", "Selection sort"], "correct": 3, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "Merge sort needs O(n) extra auxiliary space for merging, making it unsuitable under tight memory constraints; bubble, insertion, and selection sort are all in-place with O(1) extra space.", "topic": "DSA"}, {"id": "pdf7-084", "question": "Selection sort is suitable when,", "options": ["If even number of elements are there in the list", "If odd number of elements are there in the list", "If number of elements in the list is small", "If nymber of elements in the list is large"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Selection sort's O(n^2) behavior makes it acceptable only for small lists where its simplicity and low overhead outweigh its poor scaling.", "topic": "DSA"}, {"id": "pdf7-085", "question": "The algorithm which works based on the intervals between the elements of the array is,", "options": ["Bubble sort", "Insertion sort", "Shell sort", "Selection sort"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Shell sort compares and swaps elements separated by a decreasing 'gap' (interval) sequence before finishing with a final pass of gap 1.", "topic": "DSA"}, {"id": "pdf7-086", "question": "1. A minimum state DFA accepting the language L={w/w belongs {0,1}*} number of 0s and 1s in w are divisible by 3 and 5, respectively} has", "options": ["15", "9", "7", "8"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Tracking count mod 3 and count mod 5 simultaneously requires a product automaton of 3*5 = 15 states.", "topic": "TOC"}, {"id": "pdf7-087", "question": "The clark Wilson model addressess _______ requirments for commercial applications", "options": ["Data Integrity", "Data Privacy", "Confidentiality", "Threat Intelligence"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The Clark-Wilson model is an integrity-focused security model designed for commercial data integrity requirements, not confidentiality.", "topic": "Information Security"}, {"id": "pdf7-088", "question": "Which of the following attacks would compromise the integrity of system information?", "options": ["Denial-of-service", "Smurf", "SQL Injection", "Fraggle"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "SQL injection lets an attacker modify or corrupt stored data, directly compromising integrity, whereas DoS/Smurf/Fraggle attacks target availability.", "topic": "Information Security"}, {"id": "pdf7-089", "question": "In clark Wilson model CDIs can only be manipulated by_______", "options": ["Integrity procedure", "Transforamtion procedure", "Unconstrained data procedure", "Integrity verfication procedure"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "In the Clark-Wilson model, Constrained Data Items (CDIs) can only be modified through Transformation Procedures (TPs), which enforce integrity rules.", "topic": "Information Security"}, {"id": "pdf7-090", "question": "Consider the following schemas Product (productid varchar2(10), productname varchar2(10), product_price number, manufacturing_date date, vendorId varchar2(10)) Vendor (vendorId varchar2(10), vendorname varchar2(10), location varchar2(10)) The SQL query to establish vendorid as the primary key in the vendor table is", "options": ["a. alter table vendor add constraint vendor_vendorid_pr primary key (vendorid);", "a. alter table vendor add constraint primary key (vendorid);", "a. alter table vendor add constraint vendor_vendorid_pr primary key ;", "a. alter table vendor constraint vendor_vendorid_pr primary key (vendorid);"], "correct": 1, "original_marked": null, "matches_original": false, "confidence": "high", "reasoning": "The correct syntax names the constraint and specifies the column: 'ALTER TABLE vendor ADD CONSTRAINT vendor_vendorid_pr PRIMARY KEY (vendorid);'; the other options omit the constraint name, the column list, or the required ADD keyword.", "topic": "DBMS"}, {"id": "pdf7-091", "question": "The clause to set the foreign key field to null in the child table on deletion of the corresponding parent key in the parent table is", "options": ["On Delete Cascade", "On Delete Restrict", "On Delete Update", "On Delete Set Null"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "ON DELETE SET NULL sets the referencing foreign key column(s) in child rows to NULL when the referenced parent row is deleted.", "topic": "DBMS"}, {"id": "pdf7-092", "question": "The clause to automatically delete the entire rows in the child table on deletion of the Parent key in the parent table is", "options": ["On Delete Set Null", "On Delete Cascade", "On Delete Update", "All the given options are wrong"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "ON DELETE CASCADE automatically deletes child rows whose foreign key references a deleted parent row.", "topic": "DBMS"}, {"id": "pdf7-093", "question": "F = {AB-->C,C-->A} , A closure is", "options": ["CA", "C", "A", "ABC"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "low", "reasoning": "The question text appears to have dropped a 'B' (likely meant 'AB closure'): computing AB+ under F={AB->C, C->A} gives {A,B,C}=ABC, matching the marked answer; taken literally as just A's closure it would be {A} instead, so this is flagged as ambiguous.", "topic": "DBMS"}, {"id": "pdf7-094", "question": "Which if the functional dependencies is not true in a real world scenario", "options": ["registrationnumber --> name", "pincode --> district", "personname-->city", "country-->capital"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "A person's name does not uniquely determine their city in the real world (many people share names and live in different cities), so personname-->city is not a valid functional dependency, unlike the unique-identifier-based ones listed.", "topic": "DBMS"}, {"id": "pdf7-095", "question": "The relational schema in fourth normal form should not have", "options": ["Multi Valued Dependencies", "Transitive Dependencies", "Partial Key Dependencies", "Should not have any of the given dependencies"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Fourth normal form (4NF) eliminates non-trivial multi-valued dependencies that BCNF does not address.", "topic": "DBMS"}, {"id": "pdf7-096", "question": "A Foreign Key", "options": ["should always be a primary key in the Parent Table", "should always be a unique key in the Parent Table", "can be either a primary key or a unique key in the Parent Table", "All the given options are wrong"], "correct": 3, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "A foreign key must reference a column with either a PRIMARY KEY or a UNIQUE constraint in the parent table, per SQL standard and vendor documentation (e.g. MySQL, SQL Server) - it is not required to always be the primary key.", "topic": "DBMS"}, {"id": "pdf7-097", "question": "__________ mode of addressing is a form of implied addressing:", "options": ["Stack", "Array", "Queue", "Binary"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Stack addressing is implied/implicit addressing because the operand's location (top of stack) is implicit in the instruction, no explicit address is given.", "topic": "CAO"}, {"id": "pdf7-098", "question": "Definition of a language L with alphabet {a} is given as following. L= { a^nk | k > 0, and n is a positive integer constant} What is the minimum number of states needed in a DFA to recognize L?", "options": ["k+1", "n+1", "2^n+1", "2^k+1"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Recognizing multiples of n requires a cycle of n states tracking length mod n, plus one extra distinct start state so the empty string (0 symbols) is not wrongly accepted, giving n+1 states total.", "topic": "TOC"}, {"id": "pdf7-099", "question": "Which of the following relations is correct, when comparing the worst-case complexity?", "options": ["insertion=quick <selection", "quick =insertion=selec tion", "insertion<selec tion<quick", "none of the above"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "In the worst case, quicksort, insertion sort, and selection sort are all O(n^2), so their worst-case complexities are equal.", "topic": "DSA"}, {"id": "pdf7-100", "question": "Which is more suitable (DFS or BFS) if the solution is far from the starting node?", "options": ["DFS", "BFS"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "DFS dives deep along a path first, making it more suitable when the solution is far from the start node, whereas BFS explores level by level and is better suited for shallow solutions.", "topic": "DSA"}, {"id": "pdf7-101", "question": "Which is more suitable (DFS or BFS) if the solution is closer to the starting node?", "options": ["DFS", "BFS"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "BFS explores level by level, so it reaches a solution close to the start node faster than DFS, which can dive deep down an unrelated branch first.", "topic": "DSA"}, {"id": "pdf7-102", "question": "What is the status of the array after the first iteration of quick sort for the given array of elements:5,7,10,12,2,8", "options": ["5,7,10,12,2,8", "2,5,10,12,7,8", "2,7,10,12,5,8", "5,7,10,2,8,12"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Taking 5 (first element) as pivot and swapping elements in from both ends, the first partition pass places 5 correctly and yields 2,5,10,12,7,8.", "topic": "DSA"}, {"id": "pdf7-103", "question": "What is the status of an array after the first iteration of bubble sort for the given array of elements:5,7,10,12,2,8", "options": ["5,7,10,12,2,8", "2,5,10,12,7,8", "2,7,10,12,5,8", "5,7,10,2,8,12"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "One left-to-right pass of adjacent comparisons only triggers swaps at (12,2) and then (12,8), giving 5,7,10,2,8,12 after the first bubble sort pass.", "topic": "DSA"}, {"id": "pdf7-104", "question": "Quick sort algorithms are not following the divide and conquer type of algorithm strategy?", "options": ["True", "False"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Quicksort partitions the array around a pivot and recursively sorts each half, which is exactly divide-and-conquer, so the statement is false.", "topic": "DSA"}, {"id": "pdf7-105", "question": "Merge sort algorithms are following the divide and conquer type of algorithm strategy?", "options": ["True", "False"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Merge sort splits the array in half, recursively sorts each half, then merges them back \u2014 the textbook definition of divide-and-conquer.", "topic": "DSA"}, {"id": "pdf7-106", "question": "What is the status of the array after the first iteration of insertion sort for the given array of elements:5,7,10,12,2,8", "options": ["5,7,10,12,2,8", "2,5,10,12,7,8", "2,7,10,12,5,8", "5,7,10,2,8,12"], "correct": 1, "original_marked": 3, "matches_original": false, "confidence": "high", "reasoning": "In insertion sort the first iteration only compares a[1]=7 to a[0]=5; since 7>5 nothing shifts, so the array stays 5,7,10,12,2,8 unchanged. Option 3 (2,7,10,12,5,8) is actually what you'd get from a selection-sort first pass (swap min to front), not insertion sort.", "topic": "DSA"}, {"id": "pdf7-107", "question": "Insertion sort algorithms are following the divide and conquer type of algorithm strategy?", "options": ["True", "False"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Insertion sort builds the sorted array incrementally one element at a time; it doesn't split the problem into independent subproblems, so it is not divide-and-conquer.", "topic": "DSA"}, {"id": "pdf7-108", "question": "Finite automata recognizes --------grammars", "options": ["Type-1", "Type-2", "Type-3", "Type-0"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "In the Chomsky hierarchy, finite automata correspond exactly to Type-3 (regular) grammars.", "topic": "TOC"}, {"id": "pdf7-109", "question": "1. The lexical analysis for a modern language such as Java needs The power of which one of the following machine models in a necessary and sufficient sense?", "options": ["A. Finite state automata", "B. Deterministic pushdown automata", "C. Non-deterministi c pushdown automata", "D. Turing machine"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Lexical analysis (tokenizing) is defined by regular expressions, which are exactly the power of finite state automata \u2014 no more, no less is needed.", "topic": "TOC"}, {"id": "pdf7-110", "question": "When FA M is given which recognizes language L and reverse of L is found by using M then there can be ___________Final states", "options": ["2", "3", "only one", "any number"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Reversing an automaton swaps the roles of start and final states: the old (single) start state becomes the new unique final state, so there can only be one final state.", "topic": "TOC"}, {"id": "pdf7-111", "question": "The number of states in minimum DFA corresponding to the language (00+10)*100 is", "options": ["4", "3", "6", "5"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Building the NFA for (00+10)*100 and applying subset construction gives 6 reachable, pairwise-distinguishable DFA states (including the trap/dead state needed for completeness).", "topic": "TOC"}, {"id": "pdf7-112", "question": "Minimal dfa where number of 0\u2019s are divisible by 2 and number of 1\u2019s divisible by 3", "options": ["5", "6", "8", "10"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The count-of-0s-mod-2 automaton needs 2 states and the count-of-1s-mod-3 automaton needs 3 states; their product (cross) construction gives the minimal 2x3=6-state DFA.", "topic": "TOC"}, {"id": "pdf7-113", "question": "Consider the regular language L = (111 + 11111)*. The minimum number of states in any DFA accepting the language is", "options": ["3", "5", "8", "9"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "This is a classic GATE result: valid string lengths are sums of 3s and 5s, requiring 9 states (4 non-final tracking progress plus 5 final states) in the minimal DFA.", "topic": "TOC"}, {"id": "pdf7-114", "question": "When there are infinite distinguishable strings then there cannot be a -------------", "options": ["automata", "finite automata", "regular expression", "both finite automata and regular expression"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "low", "reasoning": "By Myhill-Nerode, infinitely many pairwise-distinguishable strings means the language isn't regular, so strictly neither a finite automaton nor a regular expression can exist for it \u2014 the question's single-option phrasing is a bit imprecise here.", "topic": "TOC"}, {"id": "pdf7-115", "question": "_______ means preserving the authorized restriction on the access and disclosure, including means for protecting personal privacy and proprietary information.", "options": ["Availability", "Integrity", "Confidentiality", "Threat intelligence"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "This is the standard NIST/FIPS definition of confidentiality: restricting access and disclosure to authorized parties to protect privacy and proprietary data.", "topic": "Information Security"}, {"id": "pdf7-116", "question": "You fail to back up your files and then drop your laptop breaking it into many small pieces. You have just failed to address which aspect of the CIA Triad?", "options": ["Confidentiality", "Integrity", "Availability", "Authentication"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Without a backup, destroying the only copy of the data means authorized users can no longer access it when needed \u2014 that's a failure of availability, not confidentiality or integrity.", "topic": "Information Security"}, {"id": "pdf7-117", "question": "Assume that you are having account in xyz bank with the e- banking facility. During your online transaction, you have tried to carry out multiple transactions where the bank web server denies your request to carry out the transaction. Identify the missing element of the Information security provided to the system", "options": ["Confidentiality", "Authenticity", "Availability", "integrity"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "low", "reasoning": "The scenario is ambiguous between availability (server can't process the request) and authenticity (server can't verify who is making repeated requests); deferring to the source's marked answer of authenticity.", "topic": "Information Security"}, {"id": "pdf7-118", "question": "Which of the following policy includes both end-users and management on how should they respond to security", "options": ["Technical security policies", "Administrative security policies", "Control policies", "None of the mentioned"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "low", "reasoning": "The question and its option wording (\"Control policies\") don't map cleanly onto standard security-policy categories (technical/administrative/physical), so the intended answer is ambiguous; deferring to the source's marked option.", "topic": "Information Security"}, {"id": "pdf7-119", "question": "Which of the following policy that an organization has to check how the availability of data is made online 24/7?", "options": ["Contingency Planning Policy", "Backup Policy", "Retention Policy", "Data Classification Policy"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A Contingency Planning Policy covers disaster recovery and business continuity, which is exactly what ensures data/services stay available around the clock.", "topic": "Information Security"}, {"id": "pdf7-120", "question": "One of my workstations has gone down and my entire network has gone down. Which topology am I using?", "options": ["Bus", "Star", "Ring", "Mesh"], "correct": 3, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "In a (simple) ring topology, data passes sequentially through every node, so one failed workstation breaks the loop and takes down the whole network; in a bus topology a single workstation failure does not normally affect the shared backbone.", "topic": "CN"}, {"id": "pdf7-121", "question": "1) Which of the following networks is LEAST likely to be a WAN?", "options": ["The Internet", "A school network", "A network of bank cash dispensers", "Intranet"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A school network is typically confined to one campus/building (a LAN), while the Internet, ATM networks, and many intranets span wide geographic areas, making the school network least likely to be a WAN.", "topic": "CN"}, {"id": "pdf7-122", "question": "1) Which of the following is NOT a network protocol?", "options": ["UDP", "TCP", "LAN", "SMTP"], "correct": 3, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "LAN is a type of network, not a protocol; UDP, TCP, and SMTP are all genuine network/transport/application protocols, so LAN is the odd one out (the source's marked answer of TCP is incorrect since TCP is definitely a protocol).", "topic": "CN"}, {"id": "pdf7-123", "question": "1) Which type of network needs 'terminators' to function correctly?", "options": ["Bus", "Star", "Ring", "Tree"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Bus topology needs terminating resistors at each end of the shared cable to absorb signals and prevent reflection/interference.", "topic": "CN"}, {"id": "pdf7-124", "question": "1) What type of network is this?", "options": ["Ring", "Bus", "star", "mesh"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "low", "reasoning": "This question includes a diagram \u2014 see the image above and verify the answer visually; not independently fact-checked.", "topic": "CN", "diagram": "pdf7_p37_y467.png"}, {"id": "pdf7-125", "question": "1) What is the fastest type of network connection?", "options": ["Ethernet", "Mobile data", "Fiber optics", "WiFi"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Fiber optic connections transmit data as light and offer far higher bandwidth and speed than Ethernet copper, mobile data, or WiFi.", "topic": "CN"}, {"id": "pdf7-126", "question": "1) What is Metropolitan Area Network?", "options": ["Interconnection of several local area networks by bridging with a backbone line", "Interconnection of several local area networks without bridging with a backbone line", "Interconnection of several wireless local area networks by bridging with a backbone line", "Interconnection of several wireless local area networks by bridging with a coaxial cable"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A MAN connects multiple LANs across a city-sized area using a backbone line, which is bigger than a LAN but smaller than a WAN.", "topic": "CN"}, {"id": "pdf7-127", "question": "What is an advantage of a LAN?", "options": ["a. You can save money by sharing peripherals like printers.", "It is limited to a small area.", "a. Can cover near infinite geographical distance.", "a. Expensive to set up."], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A key LAN advantage is sharing expensive peripherals like printers among many users to cut costs; the other options describe LAN limitations or disadvantages, not advantages.", "topic": "CN"}, {"id": "pdf7-128", "question": "1) What type of network is this?", "options": ["Ring", "Bus", "Star", "Mesh"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "low", "reasoning": "This question includes a diagram \u2014 see the image above and verify the answer visually; not independently fact-checked.", "topic": "CN", "diagram": "pdf7_p39_y72.png"}, {"id": "pdf7-129", "question": "1. Which of the following is not a member of the class?", "options": ["Static function", "Friend function", "Const function", "Virtual function"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A friend function is declared by a class to access its private/protected members, but it is not itself a member function \u2014 unlike static, const, or virtual functions.", "topic": "OOPS"}, {"id": "pdf7-130", "question": "1. Consider the finite automation in the following figure. What is the set of reachable states for the input string 0011?", "options": ["{q0, q1, q2}", "{q0, q1}", "{q0, q1, q2, q3}", "{q3}"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "This question includes a diagram \u2014 see the image above and verify the answer visually; not independently fact-checked.", "topic": "TOC", "diagram": "pdf7_p39_y392.png"}, {"id": "pdf7-131", "question": "The statement \u201c computable functions can be identified with a class of partial recursive functions\u201d is from", "options": ["Rice theorem", "Church- Turing thesis", "Parikh mapping theorem", "Pumping lemma"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The Church-Turing thesis states that every effectively computable function is a partial recursive function (equivalently, Turing-computable).", "topic": "TOC"}, {"id": "pdf7-132", "question": "Post systems is equivalent to", "options": ["Turing machine", "Lambda calculus", "Godel incompletene ss theorem", "All the choices"], "correct": 1, "original_marked": null, "matches_original": false, "confidence": "high", "reasoning": "Emil Post's canonical (Post) systems were proven to have exactly the same computational power as Turing machines, both computing the class of partial recursive functions.", "topic": "TOC"}, {"id": "pdf7-133", "question": "1. Medium term schedulers reduce the degree of multiprogramming by ________", "options": ["Interrupt", "Swapping", "Terminating", "Thread"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The medium-term scheduler reduces the degree of multiprogramming by swapping processes out of (and later back into) main memory.", "topic": "OS"}, {"id": "pdf7-134", "question": "1. Single inheritance, Multiple inheritance, and Aggregation comes under _______", "options": ["Modularity", "Typing", "Hierarchy", "None of the mentioned"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "In the classic OOP design elements (abstraction, encapsulation, modularity, hierarchy), inheritance and aggregation define structural rankings between classes and fall under 'Hierarchy'.", "topic": "OOPS"}, {"id": "pdf7-135", "question": "1. Which of the following statements is false? A. If a language is regular it can always be accepted by a finite state automaton B. The union of two regular languages is regular C. The intersection of regular languages is regular D. The power of NFA is more than the power of a DFA", "options": ["A", "B", "C", "D"], "correct": 4, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "NFAs and DFAs are equivalent in computational power (every NFA converts to an equivalent DFA), so statement D is false, not B \u2014 union and intersection are both valid closure properties of regular languages.", "topic": "TOC"}, {"id": "pdf7-136", "question": "1. Which of the following is the transition function of a NFA?", "options": ["Q x \u2211 --> Q", "Q x \u2211 --> 2^Q", "Q x \u2211 --> 2^Q-1", "Q x \u2211 U {epsilon}--> 2^Q"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "An NFA's transition function maps a state and input symbol to a set of possible next states: \u03b4: Q \u00d7 \u03a3 \u2192 2^Q.", "topic": "TOC"}, {"id": "pdf7-137", "question": "What is the minimum number of states in deterministic finite automata (DFA) for string starting with ba2 and ending with \u2018a\u2019 over alphabet {a, b}?", "options": ["10", "9", "8", "6"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "low", "reasoning": "The question text ('ba2') appears garbled in this extraction, making the intended language ambiguous, so the source's marked answer is kept without independent verification.", "topic": "TOC"}, {"id": "pdf7-138", "question": "1. The password to the admins account=\u201dadministrator\u201d. The total number of states required to make a password-pass system using DFA would be __________", "options": ["14 states", "13 states", "12 states", "A password pass system cannot be created using DFA"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "For a password of length n with no repeating substrings, a DFA needs n+1 states (one per matched-prefix length, plus the start); 'administrator' has 13 letters, giving 14 states.", "topic": "TOC"}, {"id": "pdf7-139", "question": "1. The number of states required by a Finite State Machine, to simulate the behaviour of a computer with a memory capable of storing 'm' words, each of length 'n' bits is?", "options": ["2^(mn)", "2^m2^n", "m+n", "2mn"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A memory of m words of n bits each has 2^(mn) possible total bit configurations, so a finite state machine needs 2^(mn) states to represent every configuration.", "topic": "TOC"}, {"id": "pdf7-140", "question": "1. The number of states in a minimal deterministic finite automaton corresponding to the language L = {a^n | n=4 } is:", "options": ["3", "4", "5", "6"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Counting a's from 0 up to 3 needs four non-accepting states, plus one accepting state that loops on further a's once the threshold is reached, giving 5 states total.", "topic": "TOC"}, {"id": "pdf7-141", "question": "1. The language acceptance of a DFA is given as:", "options": ["{w \u03f5 \u2211^* | \u03b4^*(q0,w) \u03f5 F}", "{w \u03f5 \u2211 | \u03b4^*(q0,w) \u03f5 F}", "{w \u03f5 \u2211^* | \u03b4(q0,w) \u03f5 F}", "{w \u03f5 \u2211 | \u03b4(q0,w) \u03f5 F}"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A DFA accepts string w exactly when the extended transition function \u03b4* run from q0 on w lands in an accepting state, over all strings in \u03a3*.", "topic": "TOC"}, {"id": "pdf7-142", "question": "1. The difference between number of states with regular expression (a + b) and (a + b) * is:", "options": ["1", "2", "3", "0"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Building minimal automata for (a+b) and (a+b)*, the two constructions differ by exactly one state.", "topic": "TOC"}, {"id": "pdf7-143", "question": "1. Let w be any string of length n in {a, b}*. Consider \u2018L\u2019 be the set of all strings ending with at least n a\u2019s. What is the minimum number of states in non deterministic finite automata that accept \u2018L\u2019?", "options": ["n+3", "n+1", "n", "2n"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "An NFA can nondeterministically guess where the final run of a's begins: one self-looping state to skip any prefix, then a chain of n states verifying the last n symbols are all 'a', for n+1 states total.", "topic": "TOC"}, {"id": "pdf7-144", "question": "1. Let N be an NFA with n states. Let k be the number of states of a minimal DFA which is equivalent to N. Which one of the following is necessarily true?", "options": ["K \u2265 2n", "K \u2265 n", "K \u2264 n2", "K \u2264 2n"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "By the subset construction, a minimal DFA equivalent to an n-state NFA has at most 2^n states, so k \u2264 2^n is the statement that must always hold.", "topic": "TOC"}, {"id": "pdf7-145", "question": "1. Given an arbitrary non-deterministic finite automaton (NFA) with N states, the maximum number of states in an equivalent minimized DFA is at least", "options": ["N2", "2^N", "2N", "N!"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The subset construction shows converting an N-state NFA to an equivalent minimal DFA can require up to 2^N states in the worst case, and this bound is tight.", "topic": "TOC"}, {"id": "pdf7-146", "question": "1. Given an arbitrary non-deterministic finite automaton (NFA) with N states, the maximum number of states in an equivalent minimized DFA is at least.", "options": ["N^2", "2^N", "N!", "2N"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Same as the subset-construction bound: converting an N-state NFA to a DFA can require up to 2^N states in the worst case, and this bound is tight.", "topic": "TOC"}, {"id": "pdf7-147", "question": "For a machine to surpass all the letters of alphabet excluding vowels, how many number of states in DFA would be required?", "options": ["3", "2", "22", "27"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Recognizing strings made only of consonants needs a non-accepting start state, an accepting state for 'all consonants read so far', and a dead state once a vowel appears \u2014 3 states total.", "topic": "TOC"}, {"id": "pdf7-148", "question": "1. For a DFA accepting binary numbers whose decimal equivalent is divisible by 4, what are all the possible remainders?", "options": ["0", "0,2", "0,2,4", "0,1,2,3"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A DFA tracking a binary number's value mod 4 cycles through four possible remainder states \u2014 0, 1, 2, and 3 \u2014 as it processes arbitrary binary strings.", "topic": "TOC"}, {"id": "pdf7-149", "question": "1. Finite state machine are not able to recognize Palindromes because:", "options": ["Finite automata cannot deterministically find the midpoint", "Finite automata cannot remember arbitarily large amount of data", "Even if the mid point is known, it cannot find whether the second half matches the first", "All of the mentioned"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A finite automaton has fixed, finite memory, so it can't locate a string's midpoint, can't store the first half to compare later, and can't verify a match even if the midpoint were known \u2014 all three limitations apply.", "topic": "TOC"}, {"id": "pdf7-150", "question": "1. Definition of a language L with alphabet {a} is given as following. L= {a^(nk) | k > 0, and n is a positive integer constant} What is the minimum number of states needed in a DFA to recognize L?", "options": ["k+1", "n+1", "2^(n+1)", "2^(k+1)"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "This is a modular counting DFA: n states track length mod n, plus one extra distinguishable start state so the empty string (k=0, excluded since k>0) isn't wrongly accepted, giving n+1 states.", "topic": "TOC"}, {"id": "pdf7-151", "question": "1. Consider the language L given by the regular expression (a + b) *b(a +b) over the alphabet {a, b}. The smallest number of states needed in a deterministic finite-state automaton (DFA) accepting L is ______:", "options": ["3", "4", "5", "6"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The language requires the second-to-last symbol to be 'b'; tracking the last two symbols needs exactly 4 distinguishable states (2^2), confirmed by Myhill-Nerode analysis \u2014 all 4 states are pairwise distinguishable and no fewer suffice.", "topic": "TOC"}, {"id": "pdf7-152", "question": "1. Consider the following moves: \u03b4(A,1) = B, \u03b4(A,0) = A \u03b4(B,(0,1))= C \u03b4(C,0) = A (Initial state =A) Applying the string= 011001, the automata will be in which of the states?", "options": ["A", "C", "B", "Invalid String"], "correct": 3, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "Tracing the transitions step by step on '011001': A-0->A-1->B-1->C-0->A-0->A-1->B, so the automaton ends in state B, not A.", "topic": "TOC"}, {"id": "pdf7-153", "question": "1. Basic limitation of FSM is that it", "options": ["A. cannot remember arbitrary large amount of information", "B. sometimes fails to recognize grammars that are regular", "C. sometimes recognizes grammars are not regular", "D. None of these"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "An FSM has only a finite number of states, so it cannot remember unbounded information (e.g., it can't count arbitrarily high or match nested constructs), which is why languages like {a^n b^n} aren't regular.", "topic": "TOC"}, {"id": "pdf7-154", "question": ".....means persons authorized have access to receive or use information, documents", "options": ["Confidentiality", "Integrity", "Authentication", "Availability"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Availability is the security property ensuring authorized users can access and use information/resources when they need to, matching the given definition.", "topic": "Information Security"}, {"id": "pdf7-155", "question": ".....is concerned with the prevention of improper or unauthorized modification of information", "options": ["Confidentiality", "Integrity", "Authentication", "Availability"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Integrity is specifically about preventing improper or unauthorized modification of data, as opposed to confidentiality (disclosure) or availability (access).", "topic": "Information Security"}, {"id": "pdf7-156", "question": "........... is the machine to recognize the context sensitive languages", "options": ["FA", "NFA", "Moore machine", "LBA"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Linear Bounded Automata (LBA) are the machines equivalent in power to context-sensitive grammars, so they recognize exactly the context-sensitive languages.", "topic": "TOC"}, {"id": "pdf7-157", "question": ".... used to ensures the security of telecommunications confidentiality and integrity", "options": ["AppSec", "ComSec", "IdAM", "VPN"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "ComSec (Communications Security) refers specifically to measures that protect the confidentiality and integrity of telecommunications.", "topic": "Information Security"}, {"id": "pdf7-158", "question": "... virus is unable to scan but the anti-virus", "options": ["Cavity Virus", "Prepending Virus", "Appending Virus", "Stealth Virus"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A stealth virus actively hides its presence and modifications (e.g., intercepting system calls) so that antivirus scans fail to detect the infection.", "topic": "Information Security"}, {"id": "pdf7-159", "question": ". Which of the following is /are the functions of the operating system? i) Sharing hardware among users. ii) Allowing users to share data among themselves. iii) Recovering from errors. iv) Preventing users from interfering with one another. v) Scheduling resources among users.", "options": ["i, ii, iii and iv only", "ii, iii, iv and v only", "i, iii, iv and v only", "All i, ii, iii, iv and v"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "All five listed items (sharing hardware, sharing data, error recovery, protecting users from each other, and scheduling resources) are standard textbook functions of an operating system.", "topic": "OS"}, {"id": "pdf7-160", "question": ". State True or False. i) In spooling high-speed device like a disk is interposed between a running program and low-speed device in Input/output. ii) By using spooling for example instead of writing directly to a printer, outputs are written to the disk.", "options": ["i-True, ii-False", "i-True, ii-True", "i-False, ii-True", "i-False, ii-True"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Spooling by definition interposes a fast disk buffer between a running program and a slow I/O device (like a printer), and output meant for the device is first written to disk \u2014 both statements are true.", "topic": "OS"}, {"id": "pdf7-161", "question": "------is a global communications hub that connects data from all across the world.", "options": ["WWW", "HTTP", "FTTP", "HTML"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Among the given options, the WWW (World Wide Web) is the one commonly described as the global system/hub connecting information across the world, unlike HTTP (a protocol) or HTML (a markup language).", "topic": "CN"}, {"id": "pdf7-162", "question": "---- a context free grammar to generate expression with balanced parenthesis.", "options": ["S-->(S)| \u0190", "S-->(S)", "S-->S| \u0190", "S-->S"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "S -> (S) | \u03b5 is the standard base grammar for generating nested/balanced parenthesis expressions; the other options either never terminate (no epsilon base case) or only ever produce the empty string.", "topic": "TOC"}, {"id": "pdf7-163", "question": "(i). Virtual function overloading is not a syntax error. (ii). Virtual function overloading might not achieve polymorphism concept Which of the above statement(s) are true?", "options": ["Only (i)", "Only (ii)", "Both (i) and (ii)", "Neither (i) nor (ii)"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "Statement (i) is clearly true \u2014 overloading a virtual function is legal C++ and not a syntax error \u2014 but statement (ii) is worded ambiguously (the word 'might' could make it technically true too), so the intended answer is uncertain without more context on the source's intended reasoning.", "topic": "OOPS"}, {"id": "pdf7-164", "question": "(a+b)(cd)*(a+b) denotes the following set", "options": ["{a(cd)^nb|n>=1}", "{a(cd)^n>=1}U{b(cd)^n|n>=1}", "{a(cd)^na|n>=0}U{a(cd)^nb|n>=0}U{b(cd)^na|n>=0}U{b(cd)^nb|n> =0}", "{ac^nd^nb|n>=1}"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "The regex picks one symbol from {a,b}, then n>=0 repetitions of 'cd', then one more symbol from {a,b}, giving all four combinations a...a, a...b, b...a, b...b \u2014 exactly option 3.", "topic": "TOC"}, {"id": "pdf7-165", "question": "Which statement is NOT CORRECT?", "options": ["In a database approach, the maintenance of data and metadata is easier", "In a database approach, applications do not have their own files, but all applications access the same version of the data by interfacing with the DBMS", "In a database approach, there is typically less storage needed compared to the file approach", "In a database approach, the data definitions or metadata are stored in the applications accessing the data."], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "In the database approach, metadata/data definitions are stored centrally in the DBMS's data dictionary, not scattered inside individual applications \u2014 that decentralized storage of metadata is a hallmark of the older file-based approach.", "topic": "DBMS"}, {"id": "pdf7-166", "question": "Which of the following is correct about class and structure?", "options": ["A class can have member functions while a structure cannot.", "class data members are public by default while that of the structure are private.", "Pointer to structure or classes cannot be declared.", "class data members are private by default while that of a structure are public by default"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "In C++, a class's members are private by default while a struct's members are public by default; both can have member functions and pointers to either can be declared, so the other options are false.", "topic": "C/C++"}, {"id": "pdf7-167", "question": "Which of the following adopts a top-down approach?", "options": ["Object-Oriented Programming", "Procedural Programming", "Pure - Object-Oriented Programming", "none"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Procedural/structured programming follows a top-down design where a problem is broken into functions step by step, whereas OOP is generally considered a bottom-up approach built from objects upward.", "topic": "OOPS"}, {"id": "pdf7-168", "question": "What happens if the base and the derived class contain a definition of a function with the same prototype?", "options": ["The compiler reports an error on compilation.", "The only base class function will get called irrespective of the object", "Only derived class function will get called irrespective of the object.", "The base class object will call the base class function and the derived class object will call the derived class function."], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "When base and derived classes define a function with the same prototype (and it isn't resolved via virtual dispatch through a base pointer/reference), each object invokes its own class's version \u2014 a base object calls the base version and a derived object calls the derived version.", "topic": "OOPS"}, {"id": "pdf8-001", "question": "What does overriding a method mean? .", "options": ["Changing the number and/or type of parameters of a method", "Changing the return type of a method.", "Writing a method in the child class that has the same header as a method in the parent", "Implementing an abstract method."], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Overriding means the child class provides a new implementation for a method with the exact same signature/header as one in the parent class.", "topic": "OOPS"}, {"id": "pdf8-002", "question": "In a mechanistic structure, there is______________.", "options": ["high formalisation.", "low formalisation.", "no formalisation.", "cross-functional formalisation."], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Mechanistic structures are rigid and bureaucratic, characterized by high formalisation (many written rules and procedures), unlike flexible organic structures.", "topic": "Management"}, {"id": "pdf8-003", "question": "In ________, we combine signals from different sources to fit into a larger bandwidth.", "options": ["line coding", "block coding", "spread spectrum", "none of the above"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "This is the textbook definition of spread spectrum: signals from multiple sources are combined and spread to share a wider bandwidth, mainly for security and resistance to jamming.", "topic": "CN"}, {"id": "pdf8-004", "question": "If an organisation is getting a new network they will need to think about existing systems to integrate. Which of the below would NOT be a reason for this", "options": ["Less maintenance", "a. More often networks are not developed from scratch but need to fit in with existing systems", "It must support any peripherals already in use, e.g. bar code readers, printers, etc", "They will want the system to fit in with existing pcs to save money where possible"], "correct": 1, "original_marked": 3, "matches_original": false, "confidence": "low", "reasoning": "\"Less maintenance\" is a general benefit, not a reason tied to fitting a new network with existing systems, whereas the other three options all directly concern compatibility with existing infrastructure; the option text formatting (stray \"a.\") suggests possible OCR/transcription issues affecting option order.", "topic": "CN"}, {"id": "pdf8-005", "question": "If (s,o,a) \u2208 b and access is in observe mode, then fS(s) \u2265 fO(o).", "options": ["Simple Security (ss)-Property", "Discretionary Security (ds)-Property", "Security Property (sp)", "Discretionary Simple (ds)-Property"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "This is the Bell-LaPadula Simple Security (no-read-up) Property: a subject can observe an object only if the subject's clearance is at least the object's classification.", "topic": "Information Security"}, {"id": "pdf8-006", "question": "How many classes can be defined in a single program", "options": ["Only 1", "Only 100", "Only 999", "As many as you want"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "There is no language-imposed limit on the number of classes you can define in a program; you can define as many as you need.", "topic": "OOPS"}, {"id": "pdf8-007", "question": "Create a rectangle object with a width of 5 and a height of 12.", "options": ["Rectangle r = new Rectangle(5,10)", "Rectangle r = new Rectangle(5,12)", "Student r = new Student(5,12)", "Student r = new Rectangle(5,12)"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The width (5) and height (12) must be passed in that order to the Rectangle constructor, matching \"Rectangle r = new Rectangle(5,12)\".", "topic": "OOPS"}, {"id": "pdf8-008", "question": "An _________ is an instance or of a copy of a class.", "options": ["Class", "Object", "Attribute"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "An object is a concrete instance created from a class blueprint.", "topic": "OOPS"}, {"id": "pdf8-009", "question": "A software object's behavior is exposed through ___.", "options": ["methods", "encapsulation", "abstraction", "inheritance"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "An object's behavior (what it can do) is exposed to other code through its methods.", "topic": "OOPS"}, {"id": "pdf8-010", "question": "A Lecturer is an Employee.\" This statement can best describe which object orientation concept?", "options": ["Polymorphism", "Inheritance", "Encapsulation", "Generalization"], "correct": 2, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "\"A Lecturer is an Employee\" is a classic \"is-a\" relationship, which describes inheritance (a subclass specializing a superclass); it does not describe polymorphism, which is about one interface having many implementations.", "topic": "OOPS"}, {"id": "pdf8-011", "question": "A collection of methods with no implementation is called an ___.", "options": ["block code", "comment", "interface", "blueprint"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "An interface is a collection of method signatures with no implementation, which implementing classes must define.", "topic": "OOPS"}, {"id": "pdf8-012", "question": "___________ is responsible for gathering and recording the requirements, agreements, and decisions made in every workshop.", "options": ["Executive Sponsor", "Visionary", "Scribe", "Project Manager"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "In requirements workshops, the Scribe's role is to record requirements, agreements, and decisions as they are made.", "topic": "Software Engineering"}, {"id": "pdf8-013", "question": "_____ solution requires reasoning built on knowledge and experience", "options": ["Algorithmic Solution", "Heuristic Solution", "Random Solution", "None of these"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A heuristic solution relies on rules of thumb, judgment, and experience rather than a guaranteed step-by-step procedure, unlike an algorithmic solution.", "topic": "DSA"}, {"id": "pdf8-014", "question": "When a class becomes a friend of another class they are additionally getting access", "options": ["to:Private", "Protected", "Public", "None of the above"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A friend class/function gains access to the private (and protected) members of the class that declared it as a friend, which it otherwise couldn't access.", "topic": "C/C++"}, {"id": "pdf8-015", "question": "What does the word virtual do when placed in front of a member function in C++?", "options": ["Forces derived classes to define the function to compile.", "Allows derived classes, not required, to define the function.", "Do not place the function in the text segment if it is not called.", "None of the above."], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Declaring a member function virtual allows (but does not force) derived classes to override it; only a pure virtual function (=0) forces derived classes to implement it.", "topic": "C/C++"}, {"id": "pdf8-016", "question": "Assume that all the elements of the array, which is to be sorted is not known before. But, the array should always be maintained as sorted array. Which of the following algorithm is suitable in this situation?", "options": ["Insertion", "Extraction", "Selection", "Distribution"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Inserting each new element into its correct position while keeping the array sorted at all times is exactly what insertion sort does, making it suited for online/incremental sorting.", "topic": "DSA"}, {"id": "pdf8-017", "question": "RAD Software process model stands for _____ .", "options": ["Rapid Application Development.", "Relative Application Development", "Rapid Application Design", "Recent Application Development."], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "RAD stands for Rapid Application Development, a software process model emphasizing fast, iterative delivery.", "topic": "Software Engineering"}, {"id": "pdf8-018", "question": "Which among the following is false, for a member function of a class", "options": ["All member functions must be defined", "Member functions can be defined inside or outside the class body", "Member functions need not be declared inside the class definition", "Member functions can be made friend to another class using the friend keyword"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "In C++, every member function must be declared inside the class body; only its definition (body) may optionally appear outside using the scope resolution operator, so the claim that declaration inside the class is unnecessary is false.", "topic": "C/C++"}, {"id": "pdf8-019", "question": "The following undirected graph: The number of minimum-weight spanning trees of the graph is ___________.", "options": ["3", "4", "5", "2"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "This question includes a diagram \u2014 see the image above and verify the answer visually; not independently fact-checked.", "topic": "DSA", "diagram": "pdf8_p5_y500.png"}, {"id": "pdf8-020", "question": "Where an object of a class gets stored?", "options": ["Heap", "Stack", "Disk", "File"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Objects are allocated dynamically on the heap (while local references/variables live on the stack).", "topic": "OOPS"}, {"id": "pdf8-021", "question": "The function of MUA in email is", "options": ["Formats message", "Listing mails", "Exchanges message", "Formats message"], "correct": 1, "original_marked": 3, "matches_original": false, "confidence": "high", "reasoning": "The Mail User Agent (MUA) prepares/formats messages for sending or reading (composing, creating the envelope); actually exchanging/transferring mail between hosts is the job of the Mail Transfer Agent (MTA), so \"Formats message\" is correct, not \"Exchanges message\" (note the option list also has a duplicated \"Formats message\" entry, likely a transcription artifact).", "topic": "CN"}, {"id": "pdf8-022", "question": "The dynamic update occurs when", "options": ["Server boots", "New browser installed", "Windows client created", "DHCP server renews"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "DNS dynamic update is commonly triggered when a DHCP client's lease is renewed, causing the DHCP/DNS system to refresh the associated resource records.", "topic": "CN"}, {"id": "pdf8-023", "question": "Determines the protocol which dynamically updating name server records", "options": ["RFC 2136", "RFC 2316", "RFC 2613", "RFC 2163"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "RFC 2136 defines the Dynamic Updates in the Domain Name System (DNS UPDATE) protocol.", "topic": "CN"}, {"id": "pdf8-024", "question": "Which of the following is a root level label in the domain name system?", "options": ["stc", "museum", "bizz", "ong"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "\".museum\" is a real generic top-level domain; \"stc\", \"bizz\", and \"ong\" are not valid TLDs (note the real one is \".biz\", not \"bizz\").", "topic": "CN"}, {"id": "pdf8-025", "question": "Active directory is mainly supported by", "options": ["Dynamic DNS", "DNS", "DHCP", "Domain server"], "correct": 2, "original_marked": 4, "matches_original": false, "confidence": "low", "reasoning": "Active Directory fundamentally depends on DNS (it uses DNS to locate domain controllers via SRV records, often with dynamic updates); \"Domain server\" is not a standard supporting technology, so it's an unlikely correct choice, though DNS vs. Dynamic DNS is a close call.", "topic": "CN"}, {"id": "pdf8-026", "question": "A Client Echoes a character but only after a full line in which telnet mode?", "options": ["Server", "Command", "Character", "Default"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "In Telnet's Default (half-duplex) mode the client echoes typed characters locally on screen but only transmits the completed line to the server at once.", "topic": "CN"}, {"id": "pdf8-027", "question": "Hardware Devices like a router, switch, camera and other IoT based devices remotely manage command-line interface communication using", "options": ["File transfer protocol", "Routing protocol", "Wired LAN", "Telnet Protocol"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Telnet provides a text-based, remote command-line interface used to manage routers, switches, cameras and other IoT/network devices.", "topic": "CN"}, {"id": "pdf8-028", "question": "If you face an issue in establishing a web page in any browser and that issue cannot even be resolved by switching over pages then the reason for it is", "options": ["DNS cache not cleared", "DNS not updated", "DNS host is slow", "DNS controllers in trouble"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "The question is vaguely worded; among the options, a stale/unclear DNS cache is the closest plausible explanation for a persistent page-load failure that switching pages doesn't fix, but this isn't a clean fact-checkable claim.", "topic": "CN"}, {"id": "pdf8-029", "question": "Which one of the following is not the process of Deadlock Recovery?", "options": ["Killing a process", "Rollback to the previous state", "Selecting a Victim", "Delaying the process"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Deadlock recovery techniques are process termination (killing a process) and resource preemption (selecting a victim, rollback); delaying a process is a prevention/avoidance idea, not a recovery technique.", "topic": "OS"}, {"id": "pdf8-030", "question": "To make a process as an orphan, which process needs to delay (sleep()) its execution? The parent process or the child process?", "options": ["parent to sleep for a while, child terminates", "child to sleep for a while, parent terminates", "parent and child both normal execution", "parent and child both to sleep for a while"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A process becomes an orphan when its parent terminates before it does, so to demonstrate this the child sleeps for a while so the parent can finish (terminate) first.", "topic": "OS"}, {"id": "pdf8-031", "question": "Ensuring that processes release the resources if they are not able to acquire the resources requested violates ______________condition for deadlock", "options": ["Mutual exclusion", "Hold and Wait", "Circular Wait", "No Preemption"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Hold-and-wait means a process holds resources while waiting for more; forcing processes to release held resources when they can't get new ones directly breaks this condition.", "topic": "OS"}, {"id": "pdf8-032", "question": "A system has two processes and three identical resources. Each process needs a maximum of two resources to complete. Is deadlock inevitable?", "options": ["Yes", "No"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "With 2 processes each needing at most 2 of 3 identical resources, at least one process can always obtain its full requirement, so deadlock cannot occur (classic safe-allocation example).", "topic": "OS"}, {"id": "pdf8-033", "question": "_________ memory management scheme will produce largest fragment", "options": ["Best Fit", "Worst Fit", "First Fit", "None of the given choices"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Worst Fit allocates from the largest available hole, so it leaves behind the largest leftover fragment compared to Best Fit or First Fit.", "topic": "OS"}, {"id": "pdf8-034", "question": "#include<stdio.h> #include<math.h> void power(int parameter) { printf(\"%d\", parameter*parameter); } main(){ int value=4; printf(\"%d \", (int)(pow(value,2))); power(value); }", "options": ["16 16", "16", "2", "Error"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "pow(4,2) cast to int prints \"16 \" (with trailing space from the format string), then power(4) prints 4*4=\"16\", giving combined output \"16 16\".", "topic": "C/C++"}, {"id": "pdf8-035", "question": "\"A Student object has some attributes such as name, ID, telephone number, CGPA, and email address. This information is bound to that particular Student object. Some of this information can be accessed while some might be restricted.\" This statement refers to which object-oriented concept?", "options": ["Encapsulation", "Inheritance", "Polymorphism", "Specialization"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Bundling an object's data together and controlling access to it (some visible, some restricted) is the definition of encapsulation.", "topic": "OOPS"}, {"id": "pdf8-036", "question": "In DFD the symbol used to refer the external entity", "options": ["Rectangle Rectangle", "Ellipse", "Diamond", "Circle"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "In standard DFD notation, a rectangle/square represents an external entity, a circle represents a process, and open-ended rectangles represent data stores.", "topic": "Software Engineering"}, {"id": "pdf8-037", "question": "Overview of the software systems is given by", "options": ["Component Diagram", "Deployment Diagram", "Package Diagram", "Class Diagram"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "low", "reasoning": "This is genuinely debatable between Class Diagram (structural overview of the system) and Package Diagram (high-level grouping overview); deferring to the source's marked answer of Class Diagram.", "topic": "Software Engineering"}, {"id": "pdf8-038", "question": "DFD stands for", "options": ["d Data Flow Diagram", "Dependent Flow diagram", "Decomposition Flow Diagram", "Decision Flow Diagram"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "DFD stands for Data Flow Diagram.", "topic": "Software Engineering"}, {"id": "pdf8-039", "question": "1. A DFD is normally levelled as", "options": ["it is a good idea in design", "it is easier to read and understand a number of smaller DFDs than one large DFD", "it is recommended by many experts", "it is easy to do it"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "DFDs are leveled (broken into levels like 0, 1, 2...) because a set of smaller, focused DFDs is easier to read and understand than one large complex diagram.", "topic": "Software Engineering"}, {"id": "pdf8-040", "question": "The weak entity set can be converted to the strong entity set by", "options": ["Generalisation", "Aggregation", "Composition", "Adding appropriate attributes"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A weak entity depends on an identifying relationship because it lacks its own key; adding appropriate attributes to give it a full primary key converts it into a strong entity.", "topic": "DBMS"}, {"id": "pdf8-041", "question": "Not a Component of DFD", "options": ["Attributes", "Entities", "Process", "Data Flow"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "DFD components are external entities, processes, data flows, and data stores; attributes belong to ER diagrams, not DFDs.", "topic": "Software Engineering"}, {"id": "pdf8-042", "question": "The process in DFD is represented as", "options": ["Data Flow", "Data Store", "External Entity", "Bubble Symbol"], "correct": 4, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "A process in a DFD is drawn as a circle/bubble (the \"bubble symbol\"), not as a data flow; the source's marked answer appears to be an error.", "topic": "Software Engineering"}, {"id": "pdf8-043", "question": "Name, Age, Date of Birth ,Mail id are examples of", "options": ["Entities", "Attributes", "Relationship", "Descriptors"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Name, Age, Date of Birth, and Mail ID are properties that describe an entity, which is exactly what attributes are.", "topic": "DBMS"}, {"id": "pdf8-044", "question": "Ellipse in ER diagram represents", "options": ["Attributes", "Entities", "Weak Set", "Strong Set"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "In ER diagram notation, an ellipse/oval represents an attribute of an entity.", "topic": "DBMS"}, {"id": "pdf8-045", "question": "How many views of software can a UML diagram be represented", "options": ["3", "4", "5", "6"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "low", "reasoning": "Sources disagree on the exact count of UML \"views\" (commonly cited as 4, 5, or the 4+1 model), so this is ambiguous; deferring to the source's marked answer of 4.", "topic": "Software Engineering"}, {"id": "pdf8-046", "question": "ER diagram follows", "options": ["Left-Right Strategy", "Right-Left Strategy", "Top Down Approach", "Bottom up Approach"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "ER modeling is typically done top-down: starting from high-level entities and relationships and progressively refining details like attributes and keys.", "topic": "DBMS"}, {"id": "pdf8-047", "question": "Context Diagram is also known as", "options": ["Level 2 DFD", "Level 1 DFD", "Level 3 DFD", "Level 0 DFD"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "The context diagram is the highest-level DFD showing the whole system as a single process, which is defined as Level 0 DFD.", "topic": "Software Engineering"}, {"id": "pdf8-048", "question": "the intersection of a CFL and regular language", "options": ["need not be regular", "need not be context free", "is always regular", "is always CFL"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Context-free languages are closed under intersection with regular languages, so the intersection of a CFL and a regular language is always a CFL.", "topic": "TOC"}, {"id": "pdf8-049", "question": "Syntax of any high level language is defined with", "options": ["CFG", "CNF", "GNF", "log n"], "correct": 1, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "The syntax of high-level programming languages is formally defined using Context-Free Grammar (CFG), not Chomsky Normal Form (CNF), which is just a restricted normal form of CFG used for parsing algorithms.", "topic": "TOC"}, {"id": "pdf8-050", "question": "PDA can recognise", "options": ["any grammar", "only CFG", "only regular grammar", "any unambiguous grammar"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A pushdown automaton (PDA) is the machine model that exactly recognizes context-free grammars/languages.", "topic": "TOC"}, {"id": "pdf8-051", "question": "Left linear grammars are ....... of CFG", "options": ["subset", "super set", "power set", "null"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Left-linear grammars generate exactly the regular languages, and every regular language is also context-free, so left-linear grammars form a subset of CFGs.", "topic": "TOC"}, {"id": "pdf8-052", "question": "L={anbncn/n=1,2,3.....}is an example of a language that is", "options": ["Context free", "not context free", "not context free but whose complement is CF", "context free but whose complement is CF"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "L={a^n b^n c^n} fails the CFL pumping lemma so it is not context-free, but a classic construction (union of languages that are each context-free) shows its complement is context-free.", "topic": "TOC"}, {"id": "pdf8-053", "question": "L=0", "options": ["L is regular but not 0", "L is context free but not regular", "L is not context free", "null"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "low", "reasoning": "The question text ('L=0') and its options are garbled/incomplete from the source extraction, so the intended question can't be reliably reconstructed; deferring to the source's marked answer.", "topic": "TOC"}, {"id": "pdf8-054", "question": "if r and s are two regular expressions then expression r+s is also.............", "options": ["Regular expression", "Regular Laguage", "Regular set", "c and b"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The union of two regular expressions r and s, written r+s, is itself a regular expression by the recursive definition of regular expressions.", "topic": "TOC"}, {"id": "pdf8-055", "question": "if G is CFG and w is a string of length l in L(G), how long is a derivation of w in G, if G is Chomsky normal form?", "options": ["2 l", "2l +1", "2l-1", "l"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "For a grammar in Chomsky Normal Form, deriving a terminal string of length l always takes exactly 2l-1 derivation steps (l-1 steps to build l nonterminals, then l steps to replace each with a terminal).", "topic": "TOC"}, {"id": "pdf8-056", "question": "if a grammar has different LMD or RMD, then it is..........", "options": ["ambiguous grammar, un ambiguous grammar", "un ambiguous grammar, ambiguous grammar", "ambiguous grammar, ambiguous grammar", "ambiguous grammar"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A grammar that produces more than one leftmost or rightmost derivation for the same string is, by definition, an ambiguous grammar.", "topic": "TOC"}, {"id": "pdf8-057", "question": "if a grammar has different LMD or RMD, then it is..........", "options": ["ambiguous grammar, un ambiguous grammar", "un ambiguous grammar, ambiguous grammar", "ambiguous grammar, ambiguous grammar", "ambiguous grammar"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A grammar that produces more than one leftmost or rightmost derivation for the same string is, by definition, an ambiguous grammar.", "topic": "TOC"}, {"id": "pdf8-058", "question": "Every language defined by a FA is a ......Language", "options": ["Regular", "irregular", "Regular set", "c and b"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "By definition, the set of strings accepted by a finite automaton is exactly a regular language.", "topic": "TOC"}, {"id": "pdf8-059", "question": "Every context free language is context sensitive language", "options": ["True", "False", "nothing", "True and False"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The Chomsky hierarchy nests Type-3 (regular) inside Type-2 (context-free) inside Type-1 (context-sensitive) languages, so every context-free language is also context-sensitive.", "topic": "TOC"}, {"id": "pdf8-060", "question": "Elimination of null productions results in simplified grammar with no unit productions and useless symbol", "options": ["True", "False", "nothing", "True and False"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Grammar simplification requires three separate steps (removing null productions, removing unit productions, and removing useless symbols); eliminating null productions alone does not remove the other two.", "topic": "TOC"}, {"id": "pdf8-061", "question": "Elimination of null productions results in simplified grammar with no unit productions and useless symbol", "options": ["True", "False", "nothing", "True and False"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Grammar simplification requires three separate steps (removing null productions, removing unit productions, and removing useless symbols); eliminating null productions alone does not remove the other two.", "topic": "TOC"}, {"id": "pdf8-062", "question": "Context free languages are described by type---------grammars", "options": ["Type 1", "Type 2", "Type 3", "Type 4"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "In the Chomsky hierarchy, context-free languages are generated by Type 2 grammars.", "topic": "TOC"}, {"id": "pdf8-063", "question": "CFG's are........... of CSG", "options": ["subset", "super set", "power set", "null"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Every context-free grammar can be converted into an equivalent context-sensitive grammar, so CFLs are a proper subset of context-sensitive languages.", "topic": "TOC"}, {"id": "pdf8-064", "question": "Applying pumping lemma we can show that all languages are not regular", "options": ["True", "False", "0*", "c and a"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "The pumping lemma is the standard tool for proving a specific language is not regular; the statement's wording ('all languages') is imprecise, but the source marks this True and the underlying technique is sound.", "topic": "TOC"}, {"id": "pdf8-065", "question": "All grammars are expressed in ----- form", "options": ["4 tuple", "5 tuple", "CFG", "Context free"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A formal grammar is defined as a 4-tuple (N, T, P, S): nonterminals, terminals, productions, and start symbol.", "topic": "TOC"}, {"id": "pdf8-066", "question": "Aliasing in the context free programming languages refer to", "options": ["Multiple variables having the same memory location", "Multiple variables having the same memory value", "Multiple variables having the same memory identifier", "null"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Aliasing occurs when two or more variable names refer to the same memory location, so changing one affects the other.", "topic": "C/C++"}, {"id": "pdf8-067", "question": "A non terminal is useless if it is", "options": ["Not derive any terminals", "derive terminal", "derive Non terminal", "a and c"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A nonterminal is useless if no terminal string can ever be derived from it (or it is unreachable from the start symbol), since it can never contribute to the generated language.", "topic": "TOC"}, {"id": "pdf8-068", "question": "A context free grammar is ambiguous if", "options": ["the grammar contains useless non-terminals", "it produces more than one parse tree for the same sentence", "some production has two non-terminals side by side on the right-hand side"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A CFG is ambiguous exactly when some string in its language has more than one distinct parse tree (equivalently, more than one leftmost derivation).", "topic": "TOC"}, {"id": "pdf8-069", "question": "......languages are used define the lexical structure of the programming language", "options": ["Regular expression", "Regular Laguage", "Regular set", "C and B"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Compilers use regular expressions to specify token patterns (identifiers, numbers, keywords), which defines a programming language's lexical structure.", "topic": "TOC"}, {"id": "pdf8-070", "question": ".------------ language are the subset of context free languages.", "options": ["regular grammar", "regular", "CNF", "GNF"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Regular languages are a proper subset of context-free languages in the Chomsky hierarchy.", "topic": "TOC"}, {"id": "pdf8-071", "question": ".------------ language are the subset of context free languages.", "options": ["regular grammar", "regular", "CNF", "GNF"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Regular languages are a proper subset of context-free languages in the Chomsky hierarchy.", "topic": "TOC"}, {"id": "pdf8-072", "question": "Any string of terminal that can be generated by the following CFG S-->XY, X-->ax/bx/a, Y-->ya/yb/a", "options": ["has atleast one b", "should end in a 'a'", "has no", "context free but whose complement is CF \u2013Correct\u2013 Has atleast 2 a\u2019s"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "X always derives a string ending in 'a' and Y always derives a string starting with 'a', so every string generated by S contains at least two a's (one from the end of X, one from the start of Y).", "topic": "TOC"}, {"id": "pdf8-073", "question": "MSD stand for", "options": ["Most significant digit", "Many significant digit", "Both a and b", "None of these"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "MSD is the standard abbreviation for Most Significant Digit, the digit with the highest place value in a number.", "topic": "CAO"}, {"id": "pdf8-074", "question": "In the base\u2013register addressing the register reference may be :", "options": ["Implicit", "Explicit", "Both", "None"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Depending on the instruction set design, the base register used in base-register addressing can be named explicitly in the instruction or implied implicitly by the architecture, so both forms occur.", "topic": "CAO"}, {"id": "pdf8-075", "question": "How many types of unconditional jumps used in program control are follows", "options": ["1", "2", "3", "4"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "low", "reasoning": "The wording of this question is unclear about which classification of program-control/jump instructions it refers to, so this defers to the source's marked answer rather than a confident independent count.", "topic": "CAO"}, {"id": "pdf8-076", "question": "Which operation is used to shift the content of an operand to one or more bits to provide necessary variation:", "options": ["Logical and bit manipulation", "Shift manipulation", "Circular manipulation", "None of these"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "\"Shift manipulation\" is the standard operation used to move the bits of an operand left/right to produce positional variation; the other options aren't standard classifications for this.", "topic": "CAO"}, {"id": "pdf8-077", "question": "20.The final addressing mode that we consider is :", "options": ["Immediate addressing", "Direct addressing", "Register addressing", "Stack addressing"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "In the common textbook list of addressing modes (immediate, direct, indirect, register, register indirect, displacement), stack addressing is presented last, making it the \"final\" mode covered.", "topic": "CAO"}, {"id": "pdf8-078", "question": "Which system was used extensively by early mini computers:", "options": ["Decimal number", "Octal number", "Hexadecimal number", "Binary number"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Early minicomputers (e.g., the PDP-8) used word sizes that split evenly into 3-bit groups, so octal was the natural, widely-used shorthand for their binary content.", "topic": "CAO"}, {"id": "pdf8-079", "question": "Which part is not physically indicated in the register:", "options": ["Binary", "Decimal", "Octal", "None of these"], "correct": 1, "original_marked": 3, "matches_original": false, "confidence": "low", "reasoning": "The classic textbook line is that \"the binary point in a register is not physically indicated\" (its position is only implied); the question stem appears to be missing the word \"point,\" so among the given options \"Binary\" fits the original fact better than \"Octal.\"", "topic": "CAO"}, {"id": "pdf8-080", "question": "In the case of a right arithmetic shift the sign bit values are shifted to the :", "options": ["Left", "Right", "Up", "Down"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "In an arithmetic right shift, the sign bit is retained and copied into the vacated leftmost position while the bits shift toward the right, preserving the number's sign.", "topic": "CAO"}, {"id": "pdf8-081", "question": "of a number from another can be accomplished by adding the complement of the subtrahend to the minuend:", "options": ["Subtraction", "Multiply", "Divide", "All of these"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Subtraction is performed digitally by adding the complement (e.g., 2's complement) of the subtrahend to the minuend, avoiding the need for a separate subtractor circuit.", "topic": "CAO"}, {"id": "pdf8-082", "question": "Which carry is similar to rotate without carry operations:", "options": ["Rotate carry", "Rotate through carry", "Both", "None"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A plain circular \"rotate\" (sometimes labeled \"rotate carry\") is the same operation as \"rotate without carry\" \u2014 bits wrap around within the register itself, unlike \"rotate through carry,\" which folds the carry flag into the rotation loop.", "topic": "CAO"}, {"id": "pdf8-083", "question": "Counting in hex, each digit can be increment from :", "options": ["0 to F", "0 TO H", "0 TO G", "O TO J"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Hexadecimal digits run 0-9 and then A-F, so each digit increments from 0 up through F (15 in decimal).", "topic": "CAO"}, {"id": "pdf8-084", "question": "How many types of addition in the 2\u2019s complement system:", "options": ["3", "4", "5", "6"], "correct": 2, "original_marked": 1, "matches_original": false, "confidence": "low", "reasoning": "Addition of two n-bit numbers in 2's complement is classically split into four cases by sign/magnitude combination (both positive, both negative, positive with larger magnitude, negative with larger magnitude), not three, though the exact count intended by this source is uncertain.", "topic": "CAO"}, {"id": "pdf8-085", "question": "Which number are used extensively in microprocessor work:", "options": ["Octal", "Hexadecimal", "Both", "None of these"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Hexadecimal is the standard shorthand for binary data in microprocessor work because each hex digit maps cleanly onto a 4-bit nibble.", "topic": "CAO"}, {"id": "pdf8-086", "question": "In which addressing the operand is actually present in instruction:", "options": ["Immediate addressing", "Direct addressing", "Register addressing", "None of the above"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Immediate addressing is defined by the operand's actual value being encoded directly in the instruction, with no memory reference required.", "topic": "CAO"}, {"id": "pdf8-087", "question": "Which types of register holds a single vector containing at least two read ports and one write ports:", "options": ["Data system", "Data base", "Memory", "Vector register"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A vector register is built to hold an entire vector of operands and provides the multiple read/write ports needed for parallel vector operations.", "topic": "CAO"}, {"id": "pdf8-088", "question": "In program control the instruction is set for the statement in a:", "options": ["Parallel", "Sequence", "Both", "None"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Program-control instructions normally execute in sequence, one after another, unless a branch or jump changes the flow.", "topic": "CAO"}, {"id": "pdf8-089", "question": "19.In which mode the main memory location holds the EA of the operand:", "options": ["Immediate addressing", "Direct addressing", "Register addressing", "Indirect addressing"], "correct": 4, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "It's indirect addressing, not direct addressing, where the memory location referenced by the instruction holds the effective address (EA) of the operand \u2014 that extra level of indirection is exactly what distinguishes it from direct addressing.", "topic": "CAO"}, {"id": "pdf8-090", "question": "A binary number with 4 bits is called a ____", "options": ["Bit", "Bytes", "Nibble", "None of these"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "A 4-bit binary number is called a nibble, i.e., half of an 8-bit byte.", "topic": "CAO"}, {"id": "pdf8-091", "question": "In any system, there is an ordered set of symbols also known as :", "options": ["Digital", "Digit", "Both", "None of these"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "An ordered set of symbols used to represent numbers in a system is called its digits (e.g., 0-9 for the decimal system).", "topic": "CAO"}, {"id": "pdf8-092", "question": "Which algorithm is used to find GCD of two integers:", "options": ["Multiplication algorithm", "Division algorithm", "Addition Algorithm", "Simple algorithm \u2013According to google\u2013 Euclidean Algorithm"], "correct": 4, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "The Euclidean algorithm (repeated division/modulo) is the standard, well-known method for computing the GCD of two integers, not a multiplication algorithm.", "topic": "DSA"}, {"id": "pdf8-093", "question": "Which are unconditional jumps used in program control are follows:", "options": ["Short jump", "Near jump", "Far jump", "All of these"], "correct": 4, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "Short, near, and far jumps are all variants of the unconditional JMP instruction, differing only in address range or segment, so \"All of these\" is the more complete answer.", "topic": "CAO"}, {"id": "pdf8-094", "question": "Which operation use one operand or unary operations:", "options": ["Arithmetic", "Logical", "Both", "None"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "low", "reasoning": "Both arithmetic operations (e.g., increment, negate) and logical operations (NOT) have single-operand forms, so it's genuinely ambiguous which one this source intends without more context.", "topic": "CAO"}, {"id": "pdf8-095", "question": "Which is used to speed-up the processing:", "options": ["Pipeline", "Vector processing", "Both", "None"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "Both pipelining and vector processing are techniques used to speed up processing in high-performance computers, so the single intended answer isn't fully clear from the question text alone.", "topic": "CAO"}, {"id": "pdf8-096", "question": "21.Which is a method of decomposing a sequential process into sub operations:", "options": ["Pipeline", "CISC", "RISC", "Database"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "This is the standard definition of pipelining: decomposing a sequential process into sub-operations, each executed in its own dedicated pipeline segment.", "topic": "CAO"}, {"id": "pdf8-097", "question": "decompositions R1(AC),R2(AB) with the function dependency FThe ={C->A,A->B} is", "options": ["Lossless", "Lossy", "Neither Lossless or Lossy", "All the given options are wrong"], "correct": 1, "original_marked": 3, "matches_original": false, "confidence": "high", "reasoning": "The intersection of R1(A,C) and R2(A,B) is {A}; since A\u2192B holds, A is a superkey of R2, which satisfies the lossless-join test (R1\u2229R2 \u2192 R2) \u2014 so this decomposition is lossless, not neither.", "topic": "DBMS"}, {"id": "pdf8-098", "question": "Non additive join property on a relation R holds if", "options": ["the natural join of all decompositions of R != R", "the natural join of all decompositions of R = R", "the decomposition is lossy", "None of the given options are correct"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The non-additive (lossless) join property holds exactly when the natural join of the decomposed relations reconstructs the original relation R.", "topic": "DBMS"}, {"id": "pdf8-099", "question": "A prime attribute is an attribute that is part of a", "options": ["A Primary Key", "A Candidate Key", "A Composite Key", "All the give options are correct"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A prime attribute is defined as any attribute that belongs to at least one candidate key of the relation.", "topic": "DBMS"}, {"id": "pdf8-100", "question": "A multivalued dependency X multi determines y is trivial if", "options": ["Y is a subset of X", "X is a subset of Y", "X Union Y equals R", "Y is a subset of X and X Union Y equals R"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A multivalued dependency X \u2192\u2192 Y is trivial if Y is a subset of X (or, separately, if X\u222aY = R) \u2014 these are two independent sufficient conditions, not a conjunction, so requiring both at once would be incorrect.", "topic": "DBMS"}, {"id": "pdf8-101", "question": "A Foreign Key Column", "options": ["cannot hold null values", "can hold null or duplicate values", "cannot hold duplicate values", "All the given options are wrong"], "correct": 2, "original_marked": 4, "matches_original": false, "confidence": "high", "reasoning": "A foreign key column is allowed to contain both null values and duplicate values, so option 2 is correct \u2014 'all options are wrong' is itself wrong.", "topic": "DBMS"}, {"id": "pdf8-102", "question": "When 2 or more bits in a data unit has been changed during the transmission, the error is called", "options": ["Random error", "Burst error", "Inverted error", "None of the mentioned"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A burst error is defined as two or more bits changing during transmission, as opposed to a single-bit error affecting only one bit.", "topic": "CN"}, {"id": "pdf8-103", "question": "What is the minimum hamming distance of this coding scheme d (00000, 10011)?", "options": ["1", "2", "3", "4"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Hamming distance is the count of differing bit positions; XOR(00000, 10011) = 10011, which has three 1s, so the distance is 3.", "topic": "CN"}, {"id": "pdf8-104", "question": "To guarantee the detection of up to S errors in all cases, the minimum hamming distance in a block code must be", "options": ["S", "S+1", "S-1", "0"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "To guarantee detection of up to s errors, the minimum Hamming distance of the code must be s+1.", "topic": "CN"}, {"id": "pdf8-105", "question": "To detect or correct errors, we send extra bits with data is known as", "options": ["Redundancy", "Correction", "Detection", "Authentication"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "The extra bits added to data for error detection/correction are called redundant bits, and the technique is called redundancy.", "topic": "CN"}, {"id": "pdf8-106", "question": "The stop and wait protocol uses the link of", "options": ["Modulation", "Full duplex", "Half duplex", "De modulation"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "Stop-and-wait is classically depicted over a half-duplex link since the sender transmits one frame and then waits for an acknowledgment before sending the next.", "topic": "CN"}, {"id": "pdf8-107", "question": "In Go-Back-N ARQ, if 4 is the number of bits for the sequence number, then the maximum size of the send window must be _____.", "options": ["15", "16", "31", "1"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "With m=4 bits for the sequence number, the maximum Go-Back-N send window size is 2^m - 1 = 15.", "topic": "CN"}, {"id": "pdf8-108", "question": "In a cyclic code, generator polynomial is actually the", "options": ["Multiplier", "Divisor", "Polynomial", "Quotient"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "In cyclic codes, the generator polynomial is the divisor used to compute the CRC remainder that gets appended to the data.", "topic": "CN"}, {"id": "pdf8-109", "question": "Which of the following is not an advantage of trees?", "options": ["a) Hierarchical structure", "b) Faster search", "c) Router algorithms", "d) Undo/Redo operations in a notepad"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Undo/redo functionality is classically implemented using a stack, not a tree; hierarchical structure, fast search, and routing algorithms are genuine tree advantages.", "topic": "DSA"}, {"id": "pdf8-110", "question": "The number of edges from the root to the node is called __________ of the tree.", "options": ["Height", "Depth", "Length", "Width"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "The depth of a node is defined as the number of edges on the path from the root to that node.", "topic": "DSA"}, {"id": "pdf8-111", "question": "In a full binary tree if number of internal nodes is I, then number of nodes N are?", "options": ["a) N = 2*I", "b) N = I + 1", "c) N = I \u2013 1", "d) N = 2*I + 1"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "In a full binary tree with I internal nodes and I+1 leaves, the total node count is N = 2I + 1.", "topic": "DSA"}, {"id": "pdf8-112", "question": "In a full binary tree if number of internal nodes is I, then number of leaves L are?", "options": ["a) L = 2*I", "b) L = I + 1", "c) L = I \u2013 1", "d) L = 2*I \u2013 1"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "In a full binary tree, the number of leaves equals the number of internal nodes plus one: L = I + 1.", "topic": "DSA"}, {"id": "pdf8-113", "question": ". Which of the following is incorrect with respect to binary trees?", "options": ["a) Let T be a binary tree. For every k \u2265 0, there are no more than 2k nodes in level k", "b) Let T be a binary tree with \u03bb levels. Then T has no more than 2\u03bb \u2013 1 nodes", "c) Let T be a binary tree with N nodes. Then the number of levels is at least ceil(log (N + 1))", "d) Let T be a binary tree with N nodes. Then the number of levels is at least floor(log (N + 1))"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "The correct lower bound on levels for N nodes is ceil(log2(N+1)), not floor(log2(N+1)), so statement (d) is the incorrect one.", "topic": "DSA"}, {"id": "pdf8-114", "question": "In addressing modes instruction has primarily how many components", "options": ["1", "2", "3", "4"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "An instruction is primarily made up of two components: the opcode (operation to perform) and the operand/address field it acts on.", "topic": "CAO"}, {"id": "pdf8-115", "question": "Select is referred to as a ________ operator", "options": ["Binary", "Unary", "Ternary", "All of the above"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "SELECT (restrict) in relational algebra operates on a single relation, which makes it a unary operator.", "topic": "DBMS"}, {"id": "pdf8-116", "question": "__________ combines all rows from two tables, excluding duplicate rows", "options": ["Intersect", "Difference", "Union", "None of the above"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "UNION combines all rows from two union-compatible tables while automatically eliminating duplicate rows.", "topic": "DBMS"}, {"id": "pdf8-117", "question": "Which of the following statements is not correct?", "options": ["Relational algebra is a set of operations on relational databases that allow retrieval of data", "The data in relational tables are of limited value unless the data can be manipulated to generate useful information", "Relational algebra defines the theoretical way of manipulating table contents using relational operators", "Relational algebra is not the basis for implementing and optimizing queries in the query processing and optimization modules"], "correct": 4, "original_marked": 2, "matches_original": false, "confidence": "high", "reasoning": "Relational algebra IS the theoretical basis used for implementing and optimizing queries in RDBMS query processing modules, so statement (d), which denies this, is the incorrect one \u2014 not (b), which is a true statement about data needing manipulation to be useful.", "topic": "DBMS"}, {"id": "pdf8-118", "question": "The ___ operator provides a not functionality", "options": ["difference", "intersection", "projection", "none of the above"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Set difference (A - B) returns tuples in A that are not in B, effectively giving NOT-style filtering functionality.", "topic": "DBMS"}, {"id": "pdf8-119", "question": "Which of the following statements is correct?", "options": ["An outer join only returns matched records from the tables that are being joined", "In an inner join, the matched pairs would be retained, and any unmatched values in the other table would be left null", "An equijoin, links tables on the basis of a non-equally condition that compares specified columns of each table", "The operation of eliminating columns in a table is called a project operation"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Projection is the operation that eliminates (removes) columns from a table, keeping only the specified attributes; the other statements mischaracterize inner/outer joins and equijoins.", "topic": "DBMS"}, {"id": "pdf8-120", "question": "A _____ is a tree data structure that corresponds to a relational algebra expression", "options": ["Entree", "Query Tree", "Sub tree", "None of the above"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "A query tree is a tree data structure whose leaves are the relations and whose internal nodes are relational algebra operators, directly corresponding to a relational algebra expression.", "topic": "DBMS"}, {"id": "pdf8-121", "question": "Which of the following statement is not correct?", "options": ["Relational algebra is a formal declarative query language", "Relational algebra is procedural in nature.", "Queries in relational algebra are composed using a collection of operators", "The relational algebra operations can be of arbitrary complexity"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "Relational algebra is procedural (it specifies how to get the result), not declarative \u2014 SQL is the declarative language \u2014 so statement (a) is the incorrect one.", "topic": "DBMS"}, {"id": "pdf8-122", "question": "is a variable that holds a A _________ relation.", "options": ["relvar", "table", "database", "none of the above"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "A relvar (relation variable) is a named variable whose value is a relation, distinguishing it from the relation value itself.", "topic": "DBMS"}, {"id": "pdf8-123", "question": "___ operates on pairs of relations and is, therefore, called binary operations", "options": ["", "", "Cartesian Product", ""], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "low", "reasoning": "Some answer options are images not captured in this text extraction \u2014 not independently fact-checked.", "topic": "DBMS", "option_images": ["pdf8_p34_y472_opt1.png", "pdf8_p34_y472_opt2.png", null, "pdf8_p34_y472_opt4.png"]}, {"id": "pdf8-124", "question": "Which of the following statement is correct?", "options": ["By using intersection, multiple queries can be put together and their output merged", "Grouping facilitates the combination of values based on a common reference", "The result of projection is the rows common to the rows produced by the individual queries.", "Restrict returns rows after combining two tables."], "correct": 2, "original_marked": 4, "matches_original": false, "confidence": "high", "reasoning": "Grouping (as in SQL GROUP BY) combines rows into groups that share a common attribute value, which matches statement (b); the other statements incorrectly describe intersection, projection, and restrict.", "topic": "DBMS"}, {"id": "pdf8-125", "question": "____ takes place at execution time", "options": ["Dynamic Query Optimization", "", "", ""], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "Some answer options are images not captured in this text extraction \u2014 not independently fact-checked.", "topic": "DBMS", "option_images": [null, "pdf8_p35_y324_opt2.png", "pdf8_p35_y324_opt3.png", "pdf8_p35_y324_opt4.png"]}, {"id": "pdf8-126", "question": "Which of the following statement is not correct?", "options": ["Automatic query optimization means the DBMS finds the most cost-effective access path without user intervention.", "Manual query optimization requires, that the optimization be selected and scheduled by the end user or programmer.", "A statistically based query optimization algorithm uses statistical information about the database.", "A role-based query optimization algorithm is based on a set of user-defined rules to determine the best query access strategy. 5."], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "The definition given for automatic query optimization matches the standard textbook definition (DBMS finds the most cost-effective access path without user intervention), so it reads as true; option 4 looks like an OCR-mangled 'rule-based optimizer' definition, making the intended 'not correct' statement unclear, so we defer to the source's marked answer.", "topic": "DBMS"}, {"id": "pdf8-127", "question": "A ____ uses sophisticated algorithms based on statistics about the objects being accessed to determine the best approach to execute a query", "options": ["", "Cost Based Optimizer", "", ""], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "low", "reasoning": "Some answer options are images not captured in this text extraction \u2014 not independently fact-checked.", "topic": "DBMS", "option_images": ["pdf8_p36_y382_opt1.png", null, "pdf8_p36_y382_opt3.png", "pdf8_p36_y382_opt4.png"]}, {"id": "pdf8-128", "question": "Which of the following statement is correct?", "options": ["Query optimization algorithm cannot be evaluated on the basis of its operation mode or the timing of its optimization", "The optimizer process organises the concurrent execution of SQL requests", "Query optimization is the central activity during the parsing phase in query processing", "Most SQL performance optimization techniques are not DBMS-specific and therefore are easily portable"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "In standard query-processing models, query optimization is carried out as part of the parsing phase; the other statements are false since optimization algorithms are commonly classified by operation mode/timing, optimizers don't manage concurrent SQL execution, and most SQL tuning techniques are DBMS-specific and not portable.", "topic": "DBMS"}, {"id": "pdf8-129", "question": "__ consists of selecting a strategy from a list of candidates that is closest to optimal", "options": ["Global Query Optimization", "", "", ""], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "Some answer options are images not captured in this text extraction \u2014 not independently fact-checked.", "topic": "DBMS", "option_images": [null, "pdf8_p37_y355_opt2.png", "pdf8_p37_y355_opt3.png", "pdf8_p37_y355_opt4.png"]}, {"id": "pdf8-130", "question": "Which of the following statement is not correct?", "options": ["A drawback of cost-based optimization is the cost of optimization itself", "Generation of expressions is only part of the query-optimization process since each operation in the expression can be implemented with different algorithms.", "The commutavity and associativity of join operations are important for join reordering in query optimization", "Query optimization cannot be performed by treating materialized views just like regular relations"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Materialized views can in fact be treated like regular relations during query optimization, so the statement claiming this cannot be done is the incorrect one; the other statements about cost-based optimization drawbacks, expression generation, and join reordering are all accurate.", "topic": "DBMS"}, {"id": "pdf8-131", "question": "Complex queries may have subexpressions repeated in different parts of the query, which can be similarly exploited to reduce query evaluation cost. Such optimization is known as ____", "options": ["Multiquery Optimization", "", "", ""], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "Some answer options are images not captured in this text extraction \u2014 not independently fact-checked.", "topic": "DBMS", "option_images": [null, "pdf8_p38_y334_opt2.png", "pdf8_p38_y334_opt3.png", "pdf8_p38_y334_opt4.png"]}, {"id": "pdf8-132", "question": "In ____, a query is optimized without being provided specific values for its parameters.", "options": ["", "Parametric Query Optimization.", "", ""], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "low", "reasoning": "Some answer options are images not captured in this text extraction \u2014 not independently fact-checked.", "topic": "DBMS", "option_images": ["pdf8_p39_y72_opt1.png", null, "pdf8_p39_y72_opt3.png", "pdf8_p39_y72_opt4.png"]}, {"id": "pdf8-133", "question": "The activity of choosing an efficient execution strategy for processing a query is known as", "options": ["", "", "", "Query Optimization"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "low", "reasoning": "Some answer options are images not captured in this text extraction \u2014 not independently fact-checked.", "topic": "DBMS", "option_images": ["pdf8_p39_y361_opt1.png", "pdf8_p39_y361_opt2.png", "pdf8_p39_y361_opt3.png", null]}, {"id": "pdf8-134", "question": "__ is based on constraints specified on the database schema to reduce the search space", "options": ["", "", "Semantic query optimization", ""], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "low", "reasoning": "Some answer options are images not captured in this text extraction \u2014 not independently fact-checked.", "topic": "DBMS", "option_images": ["pdf8_p40_y72_opt1.png", "pdf8_p40_y72_opt2.png", null, "pdf8_p40_y72_opt4.png"]}, {"id": "pdf8-135", "question": "___ ensures that the data moves from one consistent state to another; this activity includes the synchronization of local and remote transactions as well as transactions across multiple distributed segments.", "options": ["", "Transaction Management", "", ""], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "low", "reasoning": "Some answer options are images not captured in this text extraction \u2014 not independently fact-checked.", "topic": "DBMS", "option_images": ["pdf8_p40_y299_opt1.png", null, "pdf8_p40_y299_opt3.png", "pdf8_p40_y299_opt4.png"]}, {"id": "pdf8-136", "question": "Which of the following is correct?", "options": ["", "a transaction is a logical unit of work that must be either entirely completed or aborted; intermediate states are acceptable.", "", ""], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "low", "reasoning": "Some answer options are images not captured in this text extraction \u2014 not independently fact-checked.", "topic": "DBMS", "option_images": ["pdf8_p41_y72_opt1.png", null, "pdf8_p41_y72_opt3.png", "pdf8_p41_y72_opt4.png"]}, {"id": "pdf8-137", "question": "Ensures that once the changes are commited, they cannot be undone or lost, even in the event of a system failure", "options": ["Durability", "", "", ""], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "Some answer options are images not captured in this text extraction \u2014 not independently fact-checked.", "topic": "DBMS", "diagram": "pdf8_p41_y366.png", "option_images": [null, "pdf8_p41_y366_opt2.png", "pdf8_p41_y366_opt3.png", "pdf8_p41_y366_opt4.png"]}, {"id": "pdf8-138", "question": "A \u2014-- statement is reached, in which case all changes are aborted and the database must be restored to its previous consistent state.", "options": ["", "Rollback", "", ""], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "low", "reasoning": "Some answer options are images not captured in this text extraction \u2014 not independently fact-checked.", "topic": "DBMS", "diagram": "pdf8_p42_y72.png", "option_images": ["pdf8_p42_y72_opt1.png", null, "pdf8_p42_y72_opt3.png", "pdf8_p42_y72_opt4.png"]}, {"id": "pdf8-139", "question": "Which of the following statement is not correct?", "options": ["Serializability ensures that the schedule for the concurrent execution of the transactions yields consistent results", "", "", ""], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "Some answer options are images not captured in this text extraction \u2014 not independently fact-checked.", "topic": "DBMS", "option_images": [null, "pdf8_p42_y312_opt2.png", "pdf8_p42_y312_opt3.png", "pdf8_p42_y312_opt4.png"]}, {"id": "pdf8-140", "question": "Information residing in__________ does not usually survive system crashes.", "options": ["Volatile storage", "", "", ""], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "Some answer options are images not captured in this text extraction \u2014 not independently fact-checked.", "topic": "DBMS", "option_images": [null, "pdf8_p43_y72_opt2.png", "pdf8_p43_y72_opt3.png", "pdf8_p43_y72_opt4.png"]}, {"id": "pdf8-141", "question": "Which of the following statements is not correct?", "options": ["", "A transaction is committed , after the final statement has been executed", "", ""], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "low", "reasoning": "Some answer options are images not captured in this text extraction \u2014 not independently fact-checked.", "topic": "DBMS", "option_images": ["pdf8_p43_y281_opt1.png", null, "pdf8_p43_y281_opt3.png", "pdf8_p43_y281_opt4.png"]}, {"id": "pdf8-142", "question": "The DBMS component that ensures atomicity and durability is", "options": ["", "", "Recovery manager"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "low", "reasoning": "Some answer options are images not captured in this text extraction \u2014 not independently fact-checked.", "topic": "DBMS", "option_images": ["pdf8_p43_y526_opt1.png", "pdf8_p43_y526_opt2.png", null]}, {"id": "pdf8-143", "question": "In a DBMS transaction subsystem, _____ is responsible for the efficient transfer of data between disk storage and main memory", "options": ["buffer manager", "", "", ""], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "Some answer options are images not captured in this text extraction \u2014 not independently fact-checked.", "topic": "DBMS", "option_images": [null, "pdf8_p44_y117_opt2.png", "pdf8_p44_y117_opt3.png", "pdf8_p44_y117_opt4.png"]}, {"id": "pdf8-144", "question": "Which of the following statements is correct?", "options": ["", "", "", "It is the responsibility of both the DBMS and the application developers to ensure consistency."], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "low", "reasoning": "Some answer options are images not captured in this text extraction \u2014 not independently fact-checked.", "topic": "DBMS", "option_images": ["pdf8_p44_y344_opt1.png", "pdf8_p44_y344_opt2.png", "pdf8_p44_y344_opt3.png", null]}, {"id": "pdf8-145", "question": "Context-sensitive languages (CSLs) are closed under i) Union ii) intersection iii) complementation iv) concatenation", "options": ["(i) and (iii) only", "(ii) and (iv) only", "(i), (ii) and (iii) only", "(i), (ii) , (iii) and (iv)"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Context-sensitive languages are closed under union, intersection, complementation, and concatenation (as well as Kleene star and reversal), so all four listed operations preserve context-sensitivity.", "topic": "TOC"}, {"id": "pdf8-146", "question": "Let L1\u2019 be a recursive language and let L2\u2019 be a recursively enumerable language which is not recursive. Which one of the following is TRUE?", "options": ["L1 is recursive, L2 is recursively enumerable", "L1 is recursively enumerable and L2 is recursive", "L1 is recursive, L2 is not recursively enumerable", "L1 and L2 are recursively enumerable"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "This is a classic closure result: recursive languages are closed under complementation, so L1's complement stays recursive, while an r.e.-but-not-recursive language's complement can never be r.e. (that would force it to be recursive) \u2014 the extraction appears to have dropped the complement marks on L1/L2, but the intended textbook answer is unambiguous.", "topic": "TOC", "diagram": "pdf8_p45_y245.png"}, {"id": "pdf8-147", "question": "The complement of the universal language Lu\u2019 is", "options": ["Recursively enumerable", "Not recursively enumerable", "Recursively enumerable but not recursive", "Recursive"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Lu (the universal/acceptance language) is recursively enumerable but not recursive; since a language and its complement are both r.e. only when the language is recursive, the complement of Lu cannot be recursively enumerable at all.", "topic": "TOC", "diagram": "pdf8_p45_y466.png"}, {"id": "pdf8-148", "question": "The complement of the diagonal language L\u2019 is", "options": ["Recursively enumerable", "Not recursively enumerable", "Recursively enumerable but not recursive", "Recursive"], "correct": 3, "original_marked": 3, "matches_original": true, "confidence": "high", "reasoning": "The diagonal language Ld is not r.e., but its complement can be recognized by decoding a string's index i, extracting machine Mi, and simulating Mi on that string (accepting if Mi accepts) \u2014 making the complement r.e.; it can't also be recursive, since that would make Ld recursive (and hence r.e.) too, a contradiction.", "topic": "TOC", "diagram": "pdf8_p46_y72.png"}, {"id": "pdf8-149", "question": "The following grammar G=(N, T, P, S), where N=(S, A, B, C, D, E), T ={a,b,c} P= {S\u2192ABCD, BCD \u2192 DE, D\u2192aD, D\u2192a, E\u2192bE} is of", "options": ["Type 3", "Type 2 but not of type 3", "Type 1 but not of type 2", "Type 0 but not of type 1"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "The rule BCD\u2192DE has a right-hand side (length 2) shorter than its left-hand side (length 3), violating the non-contracting requirement for context-sensitive (Type 1) grammars, so despite other rules looking regular, the grammar as a whole is only unrestricted, i.e. Type 0 but not Type 1.", "topic": "TOC"}, {"id": "pdf8-150", "question": "Let L and L\u2019 be a language and its complement. Which one of the following possibilities will not", "options": ["L and L' are recursive", "L is recursively enumerable but not recursive L' is not recursively enumerable.", "L and L' are not recursively enumerable", "L and L' are not recursively enumerable but not recursive."], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "If both a language and its complement were recursively enumerable, the language would have to be recursive (a standard closure theorem), so a language and its complement being 'r.e. but not recursive' at the same time can never happen; the other combinations (both recursive, one r.e./one not r.e., or both not r.e.) are all realizable.", "topic": "TOC"}, {"id": "pdf8-151", "question": "The encoding of the Turing machine with transitions \u03b4(q1,0) = (q2, 1, R) \u03b4(q2, 0) (q3,0, R) \u03b4(q3, B)= (q2,1,L) is hold?", "options": ["1110101001001001100101000101001 1000100010010010111", "11101010010010011001010010100 11000100010010010111", "1110101001001001100101000101001 100010001001010111", "1110101001001001100101000101001 10010010010010111"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "The transition text is OCR-garbled and the four binary strings differ only in small details that depend on the exact encoding convention (state/symbol/direction separators) used by the source, which isn't recoverable from the extracted text \u2014 deferring to the marked answer.", "topic": "TOC"}, {"id": "pdf8-152", "question": "Let L1 be a regular language and L2 a deterministic CFL, L3 is recursively enumerable but not recursive. Which one of the following statements is FALSE?", "options": ["L1\u2229L2 is a DCFL", "L3\u2229L1 is recursive", "L1U L2 is context-free", "L1\u2229L2\u2229L3 is recursively enumerable"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "DCFLs are closed under intersection with regular languages and CFLs are closed under union, so those hold; L1\u2229L2\u2229L3 stays recursively enumerable since RE is closed under intersection. But L3\u2229L1 need not be recursive \u2014 if L1 = \u03a3*, then L3\u2229L1 = L3, which is not recursive \u2014 so that's the false statement.", "topic": "TOC"}, {"id": "pdf8-153", "question": "Which one of the following is the strongest correct statement about a finite language L over a finite alphabet \u03a3?", "options": ["L is undecidable", "L is recursive", "L is a CSL", "L is a regular set"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "Any finite language is trivially a regular set (finite union of single strings accepted by a DFA), which is the strongest/most specific true classification \u2014 it implies recursive, decidable, and CSL, but those are weaker statements.", "topic": "TOC"}, {"id": "pdf8-154", "question": "Let \u03a3 be a finite alphabet. For a set A\u2286\u03a3*, define cycle A = {yx | xy \u2208A}, permute A = {y | there exists x \u2208A, for every a \u2208\u03a3, na(x) = na(y)} For example, if \u03a3 = {a, b, c} and A = {aaabc), then cycle A = {aaabc, aabca, abcaa, bcaaa, caaab}, permute A = {aaabc, aabca, abcaa, bcaaa, caaab, aabac, abaca, bacaa,acaab, caaba, abaac, bacaa , aacab, acaba, cabaa, abaac, baaca , aacab, acaba, cabaa, baaac, aaacb, aacba, acbaa, cbaaa}. Which of the following propositions is true?", "options": ["For all A \u2e26\u03a3*, if A is regular, then so is cycle A.", "For all A \u2e26\u03a3 *, if A is regular, then so is permute A.", "For all A \u2e26 \u03a3 *, if A is context-free, then so is cycle A.", "For all A \u2e26\u03a3 *, if A is context-free, then so is permute A."], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "low", "reasoning": "Regular languages are closed under the cyclic-shift 'cycle' operation, making option 1 true, but Oshiba's theorem shows context-free languages are also closed under cyclic shift, so option 3 is equally true \u2014 the question has two technically correct options, so this defers to the source's marked answer.", "topic": "TOC"}, {"id": "pdf8-155", "question": "Consider the following statements: I) Recursive languages are closed under complementation II) Recursive enumerable languages are closed under union III) Recursive enumerable languages are closed under complementation Which of the above statements are TRUE?", "options": ["I only", "I and II", "I and III", "II and III"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Recursive languages are closed under complementation and RE languages are closed under union \u2014 both standard closure properties \u2014 but RE languages are NOT closed under complementation (that would make every RE language recursive), so only I and II are true.", "topic": "TOC"}, {"id": "pdf8-156", "question": "Consider a language L for which there exists a Turing machine (TM), T, that accepts every word in L and either rejects or loops for every word that is not in L. The language is", "options": ["NP hard", "NP complete", "Recursive", "Recursively enumerable"], "correct": 4, "original_marked": 4, "matches_original": true, "confidence": "high", "reasoning": "A TM that accepts every string of L but may reject or loop forever on non-members (i.e., isn't guaranteed to halt on all inputs) is exactly the definition of recursively enumerable, not necessarily recursive.", "topic": "TOC"}, {"id": "pdf8-157", "question": "Consider the languages L\u2081= {a^n.b^m.c^m / n, m\u22651} and L\u2082= {a^n.b^n.c^m / n,m \u22651 } Which one of the following statements is TRUE?", "options": ["L1U L2 is a CSL", "L1 \u2229 L2 is a CFL", "L1 and L1 are CSL", "L1 \u2229 L2 is a CSL"], "correct": 4, "original_marked": 1, "matches_original": false, "confidence": "high", "reasoning": "L1\u2229L2 = {a^n b^n c^n : n\u22651}, the classic language that is context-sensitive but provably not context-free (this mirrors GATE CS 2005 Q55); since L1 and L2 are each context-free (so is their union), the statement that specifically flags L1\u2229L2 as a CSL is the one testing that insight, not the marked option about the union.", "topic": "TOC"}, {"id": "pdf8-158", "question": "A context-free language L = {wwR / w\u2208{a,c}* can be accepted by", "options": ["DPDA", "NPDA", "DFA", "NFA"], "correct": 2, "original_marked": 2, "matches_original": true, "confidence": "high", "reasoning": "Even-length palindromes {wwR} with no middle marker can't be recognized deterministically because a PDA can't know in advance where the midpoint is to switch from pushing to popping, so it needs a nondeterministic PDA (it's still context-free, just not deterministic).", "topic": "TOC"}, {"id": "pdf8-159", "question": "Which of the following languages over {a,b,c} is deterministic PDA?", "options": ["wbwR { / w \u2208{a, c}* }", "wwR { / w \u2208{a, b, c}* }", "anbncn { / n \u22651 }", "{ w / w is a palindrome over {a, b, c} }"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "wbwR has an explicit middle marker 'b', so a PDA deterministically knows exactly when to stop pushing and start popping, making it a DCFL \u2014 the other options (plain wwR, palindromes, or a^nb^ncn which isn't even context-free) lack that marker or aren't CFL at all.", "topic": "TOC"}, {"id": "pdf8-160", "question": "Which of the following languages over {a,b,c} is deterministic PDA?", "options": ["wbwR { / w \u2208{a, c}* }", "wwR { / w \u2208{a, b, c}* }", "anbncn { / n \u22651 }", "{ w / w is a palindrome over {a, b, c} }"], "correct": 1, "original_marked": 1, "matches_original": true, "confidence": "high", "reasoning": "wbwR has an explicit middle marker 'b', so a PDA deterministically knows exactly when to stop pushing and start popping, making it a DCFL \u2014 the other options (plain wwR, palindromes, or a^nb^ncn which isn't even context-free) lack that marker or aren't CFL at all.", "topic": "TOC"}];
